pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps heavily.
    // A residual gap is "dead" if it cannot hold even the smallest plausible item (1..=20).
    if post_residual > 0 && post_residual < 20 {
        score += 60.0 + (20 - post_residual) as f64 * 2.0;
    }

    // Penalize gaps that cannot fit the next item (lookahead k=2), forcing a new bin later.
    if next_item_size > 0 && post_residual < next_item_size as f64 {
        score += 25.0 + (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // Reward tight fits: post_residual == 0 is perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // rather than spreading items out.
    score += open_bins_count as f64 * 1.5;

    // Slight reward for bins with residual below mean (denser bins).
    score -= (mean_residual - post_residual as f64) * 0.1;

    // Prefer bins whose residual is close to the item size (tight fit coupling).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: small classes of dead space are penalized.
    let cls = post_residual % 10;
    if post_residual > 0 {
        // Penalize residuals that are too small to ever be useful again
        // (below the minimum conceivable item size class).
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        }
        // Modulo-10 class shaping: residuals matching common item-size classes
        // (multiples of 10) are favored since future items often align.
        if cls == 0 {
            score -= 8.0;
        } else if cls == 5 {
            score -= 3.0;
        } else {
            score += (cls as f64) * 0.6;
        }
        // Integer-division threshold: residual usable by at least a mid item (>=25)
        let usable_quotient = post_residual / 25;
        score -= usable_quotient as f64 * 6.0;
    } else {
        // Perfect fill: strongly reward.
        score -= 100.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + (next_item_size as f64) * 0.2;
        // Extra reward if post-residual is an exact harmonic multiple of next item.
        if post_residual % next_item_size.max(1) == 0 && post_residual == next_item_size {
            score -= 12.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here: penalize proportionally to wasted fraction.
        score += 5.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: mild bias so a new bin is chosen only when
    // open bins have genuinely bad fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 20.0 * (1.0 - progress) - open_bins_count as f64 * 1.5;
        // If current item nearly fills a fresh bin, opening is attractive.
        if item_size * 2 >= bin_capacity {
            score -= 15.0;
        }
    }

    // Prefer tighter bins overall relative to mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Late-stream consolidation: reward filling existing bins as stream ends near.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 && bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (fragmentation)
    if post_residual < item_size.min(10) && post_residual > 0 {
        score += 40.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Last chance: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Lookahead: if next item fits in post residual, reward; else penalize
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
        } else {
            score += (next_item_size as f64) * 0.15;
        }
    }

    // Time horizon: later in stream, prefer consolidating into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 15.0;

    // Global state: many open bins -> discourage spreading; compare residual to mean
    score += (bin_residual as f64 - mean_residual) * 0.3;
    if open_bins_count > 8 {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        // baseline cost of opening a bin, reduced when current bins are fragmented
        let frag = mean_residual / bin_capacity as f64;
        score = 30.0 + frag * 40.0 - (fitting_bins_count as f64) * 5.0;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 25.0; // large next item: fresh bin useful
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly unusable.
    let pr = post_residual as f64;
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 45.0 - 3.0 * pr; // hard penalty for unusable slivers
        } else if post_residual <= 20 {
            score += 12.0 - 0.4 * pr;
        }
        // Perfect fit bonus
        if post_residual == 0 {
            score -= 60.0;
        }
    }

    // Reward tight fits relative to bin fill ratio
    let fill = (bin_residual - post_residual) as f64 / cap;
    score -= 25.0 * fill * fill;

    // Last-chance bin before opening a new bin: strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: discourage scattering across many bins
    score += 0.9 * open_bins_count as f64;

    // Lookahead: if next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual && post_residual > 0 {
            let nxt = next_item_size as f64;
            let ratio = nxt / pr;
            score -= 20.0 * ratio * (1.0 - (ratio - 1.0).abs().min(1.0));
        }
        // If next item won't fit anywhere else, keep residual flexible
        if next_item_size > post_residual && post_residual < next_item_size {
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // New-bin candidate: only attractive when current bin would leave bad dead space
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin, modulated by stream progress
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 0.5 * cap + 30.0 * progress;
        if item_size as f64 / cap > 0.7 {
            score -= 15.0; // large items fine in fresh bins
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild deviation from mean residual: prefer bins below mean (tighter bins)
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (unusable for future items) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 + (10 - post_residual) as f64 / 10.0);
    } else if post_residual > 10 && post_residual <= 20 {
        score += 15.0; // moderate penalty for small-ish gaps
    }

    // Reward very tight fits (almost exact packing).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins with residuals below the mean (compact bins first).
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.2;

    // Lookahead: if next item fits exactly in the post-residual, bonus.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 {
        score -= 25.0;
    }
    // Penalize leaving a gap just above the next item (awkward dead space).
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 8 {
        score += 12.0;
    }

    // New-bin candidate: baseline cost, decreasing pressure as stream progresses.
    if bin_residual == bin_capacity {
        score = 55.0 - (step_index as f64 / total_items.max(1) as f64) * 20.0;
        // If nothing else fits well, allow the new bin.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item (1..100 range, but realistically >=10) are pure waste.
    let min_item = 10.0f64;
    if (post_residual as f64) < min_item && post_residual > 0 {
        // Unusable sliver: harsh penalty proportional to how close to zero.
        score += 60.0 * (1.0 - (post_residual as f64) / min_item);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize leaving a gap that is large enough to be useful but
    // awkwardly sized relative to the lookahead item.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            // This bin can also host the next item: favorable.
            score -= 15.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            // Next item won't fit here; residual may become dead space.
            score += 8.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless the
    // fit is genuinely good.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only bin that fits, using it avoids
    // opening a new bin for a potentially awkward item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when current fit is poor
    // (large post_residual) or open bins are numerous/congested.
    if bin_residual == bin_capacity {
        // Base cost of opening a fresh bin; cheap when item is large or
        // existing bins are nearly full.
        let poor_fit = (post_residual as f64) > 45.0;
        let congestion = mean_residual < 20.0;
        if poor_fit || congestion || fitting_bins_count == 0 {
            score -= 20.0 + 0.5 * open_bins_count as f64;
        } else {
            score += 45.0; // prefer placing into an existing reasonable bin
        }
    }

    // Mild alignment reward: residual close to mean_residual keeps bin
    // population homogeneous and flexible.
    score -= 0.15 * (post_residual as f64 - mean_residual).abs().max(0.0).min(30.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot fit a typical next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 * (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 {
        // Reward leaving room exactly for the lookahead item.
        score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer fuller bins relative to the fleet's mean residual.
    score += 0.35 * (mean_residual - bin_residual as f64);

    // Mild penalty for spreading across many open bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: only attractive when the item barely fits anywhere
    // or open bins would waste a lot of space.
    if bin_residual == bin_capacity {
        let waste_if_forced = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 30.0 * waste_if_forced - 10.0 * (1.0 - progress);
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 6.0; // room to pair with lookahead item in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are
    // permanently unusable, so penalize them quadratically.
    let min_item = 1u32; // sizes 1..100; treat 1 as floor for dead-space definition
    if post_residual < 10 {
        // effectively unusable gap -> heavy penalty
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Perfect fit gets a strong bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last chance: only this bin fits -> strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize placing into a bin when many bins fit the item (save flexible bins)
    if fitting_bins_count > 1 && bin_residual != bin_capacity {
        score += 6.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Open bins pressure: discourage scattering across many bins mid-stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (2.0 + 4.0 * progress);

    // Lookahead: if next item fits the post-residual, reward leaving that gap
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // gap that next item cannot use: mild penalty
        score += 8.0;
    }

    // New-bin candidate handling: attractive early, or when open bins fit poorly
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        // prefer new bin if existing fits leave worse residuals
        if mean_gap > post_residual as f64 {
            score -= 25.0;
        } else {
            score += 20.0 + 30.0 * (1.0 - progress);
        }
    }

    // Slight preference for bins below mean residual (balance loads)
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;

    // Base: post residual, lightly normalized
    let mut score = pr / cap;

    // Smooth non-linear coupling: small post_residuals are penalized quadratically
    // (dead space), large post_residuals mildly rewarded (keeps bin usable).
    let x = pr / cap; // in [0,1]
    score += 0.8 * (1.0 - x) * (1.0 - x) * (1.0 - x); // cubic penalty for tight fits

    // Progress coupling: early in the stream, prefer spreading into new bins;
    // later, pack tightly. Smooth via a polynomial ramp.
    let urgency = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += urgency * 0.6 * x; // reward residual more as stream progresses
    score -= (1.0 - urgency) * 0.3 * x; // early: less penalty for tight fits

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 1.5;
    } else if fitting_bins_count > 1 {
        // mild competition bonus scaled by scarcity
        score -= 0.3 / fitting_bins_count as f64;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = (pr - nxt) / cap;
            score -= 0.7 * (1.0 - fit_quality * fit_quality);
        } else {
            // next item won't fit here; penalize leaving residual close to next size
            score += 0.2 * (1.0 - (pr - nxt).abs() / cap);
        }
    }

    // Discourage fragmenting when many bins are already open and mean residual is low
    let mr = mean_residual / cap;
    score += 0.25 * (1.0 - mr) * (open_bins_count as f64).sqrt() * 0.1;

    // New-bin candidate: make it attractive only when open bins are nearly full
    if is_new_bin {
        score -= 0.5 * urgency;
        score += 0.4 * (1.0 - urgency);
        // penalize new bin if plenty of aggregate space exists
        score += 0.3 * mr * (open_bins_count as f64 / (1.0 + open_bins_count as f64));
    }

    // Tie-break: prefer bins whose residual is close to item size (smooth kernel)
    let tightness = (bin_residual as f64 - item_size as f64) / cap;
    score += 0.15 * tightness * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold any
    // future item (min item size 1, but practically gaps < ~12 are weak)
    // are costly. Penalize small-but-nonzero post_residual heavily.
    if post_residual > 0 && post_residual < 12 {
        score += 45.0 * (1.0 - post_residual as f64 / 12.0);
    }
    // Perfect fit is golden.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits relative to the bin's free space (high fill ratio).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio;

    // Dead-space penalty scaled by how unusable the leftover gap is
    // relative to the next item's size: if next item cannot use the gap,
    // this placement wastes it.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 15.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
        // If the next item fits exactly in the post-residual, reward.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Open-bin pressure: discourage scattering across many bins early,
    // encourage consolidating when few bins are open.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bonus: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mean-residual coupling: prefer bins whose residual deviates below
    // the mean (tighter bins) when the mean is high.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate handling: an empty bin is a fallback. Only make
    // it attractive when no open bin offers a decent fit (large residual
    // gap) or when bin pressure is low. Penalize opening new bins when
    // the item would fit reasonably in an existing bin.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 18.0;
        // As the stream progresses, opening new bins becomes cheaper
        // (fewer future chances to consolidate).
        let progress = step_index as f64 / total_items as f64;
        score -= 10.0 * progress;
        // If many bins are open, spreading is fine.
        score -= open_bins_count as f64 * 0.5;
        // If next item is large and this item is small, keep flexibility.
        if next_item_size > item_size && next_item_size > 0 {
            score -= 6.0;
        }
    }

    // Slight late-stream tightening: waste matters more near the end.
    let progress = step_index as f64 / total_items as f64;
    score += post_residual as f64 * 0.25 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;
    let mut score = pr * (1.0 + 0.03 * (pr / cap) * (pr / cap));

    // Progress-driven tightness
    let tightness = 1.0 + 2.4 * progress * progress + 2.2 * progress * progress * progress;
    score *= tightness;

    // Lookahead: penalize bins that can't host the next item, reward chained fits
    if nx > 0.0 {
        if pr < nx {
            let gap = nx - pr;
            score += gap * (2.0 + 6.0 * (1.0 - progress));
        } else {
            let chain_gap = pr - nx;
            let slack = chain_gap / cap;
            if chain_gap <= 40.0 {
                score -= 6.0 + 0.1 * chain_gap;
            }
            if slack < 0.04 {
                score -= 8.0 * (1.0 - slack * 25.0) * (1.0 + progress);
            }
            let chain = 1.0 - slack.min(1.0);
            score -= 5.0 + 4.0 * (nx / cap) + 9.0 * chain * (1.0 - progress);
        }
    }

    // Dead-space penalty (quadratic, progress-coupled)
    let dead_ratio = (pr / cap).max(0.0);
    score += 10.0 * dead_ratio * dead_ratio * cap * (0.45 + progress);
    // Mid-range residual penalty for dead space control
    if dead_ratio > 0.25 && dead_ratio < 0.6 {
        score += 4.5 * (dead_ratio - 0.25) * (0.5 + progress);
    }

    // Scarcity handling
    if fitting_bins_count == 1 {
        score -= 14.0 + 12.0 * progress;
    } else if fitting_bins_count == 2 {
        score -= 4.0 + 3.0 * progress;
    }

    // NEW-BIN CANDIDATE scoring
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let item_frac = (it / cap).min(1.0);
        let mut nb = cap * (1.35 + 1.1 * progress);
        nb -= 26.0 * scarcity * (1.0 - progress);
        nb -= 18.0 * item_frac * (1.0 - progress);
        if nx >= 0.5 * cap {
            nb -= 12.0 * progress + 6.0 * (1.0 - progress);
        }
        nb += 15.0 * progress * (1.0 - item_frac);
        if it >= cap - 1.0 {
            nb -= 30.0;
        }
        if nx > 0.0 && cap - it >= nx {
            nb -= 10.0 + 0.1 * (cap - it - nx);
        }
        if fitting_bins_count <= 2 {
            nb += 20.0 + 10.0 * (1.0 - progress);
        }
        // Discourage new bins when mean residual across open bins still
        // comfortably exceeds the next item (reuse potential)
        if nx > 0.0 && mean_residual > nx + 8.0 && progress < 0.7 {
            nb += 8.0 * ((mean_residual - nx) / cap).min(0.5) * cap * 0.1;
        }
        // Stronger reuse pressure late in stream
        if mean_residual >= it && progress > 0.5 {
            nb += 6.0 + 8.0 * progress;
        }
        score = nb;
    } else {
        let fill_ratio = 1.0 - res / cap;
        let waste = pr / cap;

        // Near-perfect fit bonuses
        if waste < 0.08 {
            score -= 48.0 * (1.0 - progress) * (0.08 - waste);
        }
        if fill_ratio > 0.65 {
            score -= 4.5 * (fill_ratio - 0.65) * 10.0 * (0.4 + progress);
        }
        if nx > 0.0 && nx <= pr && pr > 0.0 {
            let gap = (pr - nx) / cap;
            if gap < 0.03 {
                score -= 7.0 * (1.0 - gap * 33.0);
            }
        }

        // Tiny residual penalties (avoid stranding slivers)
        if pr > 0.0 && pr < 4.0 {
            score += 6.0 * (4.0 - pr) * (1.0 - progress);
        }
        if pr > 0.0 && pr < 10.0 {
            score += 40.0 * (1.0 - 0.5 * progress);
        }
        if pr == 0.0 {
            score -= 60.0;
        } else if pr <= 5.0 {
            score -= 30.0 * (1.0 - 0.4 * progress);
        }
        if nx > 0.0 && pr > 0.0 && pr < nx {
            score += 6.0;
        }

        // Balance vs mean residual with quadratic deviation
        let dev = mean_residual - res;
        score += 0.08 * dev;
        score += 0.01 * dev * dev;
        if dev > -5.0 && dev < 15.0 && pr > 0.0 {
            score -= 4.0;
        }

        // Exact chain fit bonus
        let tight_fit = (pr == 0.0) || (nx > 0.0 && pr == nx);
        if tight_fit {
            score -= 10.0 * (0.3 + progress);
        }

        // Reward bins whose post-residual still fits next item with small slack
        if nx > 0.0 && pr >= nx {
            let room = pr - nx;
            if room < 0.06 * cap {
                score -= 6.0 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
            }
        }

        // Crowding bonus
        score -= 0.4 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let prn = pr / bin_capacity as f64;
    let poly = prn * prn * (0.5 + 2.0 * progress) + prn * (1.0 - progress) * 3.0;
    score += poly * 10.0;

    // Reward tight fits more strongly as the stream progresses.
    let tightness = 1.0 - prn;
    score -= tightness * tightness * (20.0 + 30.0 * progress);

    // Last-chance bin bonus (smoothly weighted).
    if fitting_bins_count == 1 {
        score -= 25.0 + 25.0 * progress;
    }

    // Penalize bins far below mean residual (dead space creation), scaled by open count.
    let mean_gap = mean_residual - pr;
    score += 0.5 * mean_gap * (1.0 + (open_bins_count as f64).sqrt()) * (0.3 + 0.7 * progress);

    // Lookahead: favor bins leaving room for the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = (pr - nx as f64).abs();
        score += 0.2 * fit_next;
        if pr >= nx {
            score -= 5.0;
        }
    }

    // Mild penalty for opening a new bin when good fits exist.
    if bin_residual == bin_capacity {
        score += 8.0 + 40.0 * (1.0 - progress) + 2.0 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space, amplified for large items.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= (post_residual as f64).powi(2) / bin_capacity as f64 * (0.5 + fill_ratio);

    // Last-chance bonus: strongly favor the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0 + 0.5 * item_size as f64;
    }

    // Many open bins: discourage fragmenting further; prefer consolidating into fuller bins.
    score += open_bins_count as f64 * 0.35;

    // Global pressure: when mean residual is low, preserve bins with large residuals
    // for future large items; when mean residual is high, prefer using spacious bins.
    if mean_residual > 0.0 {
        let dev = bin_residual as f64 - mean_residual;
        if post_residual < 10 {
            // Dead space creation: unusable slivers are costly.
            score += 25.0;
        } else if post_residual < 20 {
            score += 8.0;
        }
        // Penalize consuming a bin whose residual far exceeds the average
        // (it may be the only one able to host a big future item).
        score += 0.15 * dev.max(0.0);
        // Slight reward for using below-average-residual bins (already fragmented).
        score -= 0.05 * (-dev).max(0.0);
    }

    // Lookahead: if the next item would fit exactly into the post-residual,
    // reward this placement (chain fit). If next item is large and this bin
    // is one of few with big residual, penalize consuming it.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 40.0;
        } else if next_item_size as i64 - post_residual as i64 == 0 {
            score -= 40.0;
        } else if (next_item_size as f64 - post_residual as f64).abs() <= 3.0 {
            score -= 15.0;
        }
        if next_item_size > post_residual && post_residual >= item_size && bin_residual > 60 {
            score += 5.0; // keeping big residual may help next item elsewhere anyway
        }
        if next_item_size <= post_residual && post_residual - next_item_size < 5 {
            score -= 20.0;
        }
    }

    // Time horizon: early in the stream, be conservative with new bins;
    // late in the stream, allow tighter packing to dominate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * progress;

    // New-bin candidate (empty bin): only attractive when item is large and
    // no open bin fits well, or when open-bin population is huge.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 > 0.7 * bin_capacity as f64;
        if big_item || open_bins_count > 12 {
            score -= 10.0 + 0.3 * item_size as f64;
        } else {
            score += 55.0; // prefer existing bins for small/medium items
        }
    }

    score
}

