    // Harmonic class of post_residual: residues modulo 10 (capacity/10).
    let residue_class = (post_residual % 10) as f64;
    // Integer-division threshold: how many "capacity/10 slots" remain.
    let slots = (post_residual / 10) as f64;

    // Penalize small unusable remainders: post_residual in 1..10 is dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 - residue_class * 2.0;
    }
    // Reward perfectly closed bins.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward post_residual that is a harmonic fraction of capacity
    // (25, 50, 75, 100): these are reusable "clean" states.
    let clean = post_residual == 25 || post_residual == 50 || post_residual == 75 || post_residual == 100;
    if clean {
        score -= 12.0;
    }

    // Lookahead coupling: if next item fits exactly into the post residual,
    // strongly reward; if next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            let fit_frac = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * fit_frac;
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 8.0 * (1.0 - miss / cap).min(1.0);
        }
        // Harmonic class match: next item's decade matches post residual decade.
        if (next_item_size / 10) == (post_residual / 10) && post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless post residual would be tiny.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a fresh bin when decent fits exist,
    // but allow it when the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        score = cap - item_size as f64; // baseline: full residual after placement
        if item_frac > 0.5 {
            score -= 10.0;
        }
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    // Mild drift toward tightness as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    // Tie-break: prefer bins whose residual deviates from mean (diversity).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (smallest possible item = 1, but practically
    // small gaps < ~15) are "dead space" -> heavy penalty.
    if post_residual > 0 && post_residual < 15 {
        score += 60.0 - (post_residual as f64) * 2.0; // small gap => up to +58
    }
    // Medium gaps are mildly risky too (next item may not match).
    if post_residual >= 15 && post_residual < 30 {
        score += 12.0 - (post_residual as f64) * 0.3;
    }

    // Reward tight fits: fraction of the bin consumed by this item.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Open-bin pressure: with many open bins, prefer reusing existing bins
    // to avoid fragmentation; with few bins, packing tightly matters less.
    let progress = step_index as f64 / total_items as f64;
    let pressure = (open_bins_count as f64).sqrt() * (1.0 + progress);
    score += pressure * 2.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into the post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect pairing
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit in the gap -> gap likely becomes dead space
            score += 8.0;
        }
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is relatively full already -> prefer filling nearly-full bins.
    let residual_f = post_residual as f64;
    if mean_residual > 0.0 {
        let deviation = (mean_residual - residual_f) / mean_residual;
        score -= 6.0 * deviation;
    }

    // New-bin candidate (empty bin): penalize so it is only chosen when all
    // open bins would create bad dead space.
    if bin_residual == bin_capacity {
        score += 35.0 + 3.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheap.
        score -= 25.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base tightness: strongly reward small post_residual (tight fit).
    score = post_residual as f64 * 1.0;

    // 2-step lookahead: if next item fits exactly into post_residual, huge reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: bin fully consumed by next item
        } else if next_item_size <= post_residual {
            // next item fits, but leaves more waste: reward proportional to how well it chains
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 40.0 - 0.5 * chain_waste;
        } else {
            // next item will NOT fit here: penalize leaving awkward space
            score += 8.0 + 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (denser bins),
    // so their remaining space is small and structured.
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): make it unattractive by default, but attractive
    // when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // nothing else fits: opening a new bin is correct
            score -= 100.0;
        } else {
            // discourage opening a new bin when alternatives exist
            score += 45.0 + 0.2 * item_size as f64;
        }
    }

    // Early in stream, be slightly more willing to open bins (build diverse residuals);
    // late in stream, consolidate to avoid leftover waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress);
    } else {
        score -= 10.0 * progress;
    }

    // Penalize creating dead space below the minimum item size (unusable gap).
    // With unknown distribution assume min size 1, so only zero residual is "perfect".
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny unusable slivers are wasteful
    }
    if post_residual == 0 {
        score -= 15.0; // perfectly closed bin
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post residual), with non-linear penalty.
    let tight = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tight * tight;

    // Lookahead: reward if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leaving medium dead space
            score += 8.0;
        }
    } else {
        // Last item: just minimize waste
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Global state: if mean residual across open bins is high, prefer reusing bins.
    score -= 0.15 * mean_residual;

    // Many open bins: discourage opening yet another bin.
    score += 0.5 * open_bins_count as f64;

    // Time horizon: early in the stream, be more conservative (favor packing
    // into existing bins); late in the stream, waste matters less.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 5.0;

    // New-bin candidate handling: empty bin gets a base handicap so it is only
    // chosen when all open bins score poorly (large post residual / dead space).
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when existing bins are mostly full
        // (low mean residual) or few bins can fit the item.
        let scarcity = 1.0 - (fitting_bins_count as f64) / (open_bins_count.max(1) as f64 + 1.0);
        score += 45.0 - 40.0 * scarcity - 0.2 * mean_residual;
        // Late in the stream, opening fresh bins is cheaper.
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / (total_items.max(1) as f64)).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with polynomial shaping
    let mut score = norm_pr * norm_pr * 40.0 + norm_pr * 10.0;

    // Smooth coupling of post_residual with stream progress:
    // early on, larger post_residual is tolerable; late, penalize dead space more
    let progress_coupling = 1.0 + 2.5 * progress * progress;
    score *= progress_coupling;

    // Non-linear interaction: post_residual relative to mean residual of open bins
    let mean_norm = mean_residual / cap;
    let interaction = (norm_pr - mean_norm) * (1.0 + progress);
    score += interaction * 12.0;

    // Perfect fit bonus (smooth, non-piecewise)
    let fit_quality = 1.0 - (pr / cap).powf(2.0);
    score -= fit_quality * (item_size as f64 / cap) * 15.0;

    // Lookahead: reward leaving space that fits the next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = if pr >= nxt { 1.0 } else { 0.0 }.min(1.0);
        let slack = (pr - nxt).max(0.0) / cap;
        score -= fits_next * (1.0 - slack) * 8.0 * (1.0 + progress);
        score += slack * 6.0;
    }

    // Last-chance bin: strongly favor using it (avoid opening new bin)
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * progress;
    }

    // Mild pressure to consolidate when many bins are open
    let open_pressure = (open_bins_count as f64 / (1.0 + (total_items as f64).sqrt())).min(2.0);
    score += norm_pr * open_pressure * 4.0;

    // New-bin candidate handling: make an empty bin attractive only when
    // current residuals are all poor (large post_residual would be created)
    if bin_residual == bin_capacity {
        let penalty = 25.0 * (1.0 - progress * 0.3);
        score = penalty + norm_pr * 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of post_residual (integer division on capacity fractions) ----
    // Class 0: post_residual == 0  -> perfect fit, huge reward
    // Class 1: post_residual in 1..=10   -> near-perfect, dead space small
    // Class 2: post_residual in 11..=30  -> awkward zone, penalize
    // Class 3: post_residual in 31..=60  -> still reusable for mid items
    // Class 4: post_residual > 60        -> large residual, fine
    let cls: u32 = if post_residual == 0 { 0 }
        else if post_residual <= 10 { 1 }
        else if post_residual <= 30 { 2 }
        else if post_residual <= 60 { 3 }
        else { 4 };

    match cls {
        0 => score -= 500.0,
        1 => score -= 120.0,
        2 => score += 60.0, // awkward dead space
        3 => score += 10.0,
        _ => score -= 20.0,
    }

    // ---- Harmonic compatibility: does next_item_size divide/match post_residual classes? ----
    if next_item_size > 0 {
        let nxt = next_item_size;
        if nxt == post_residual {
            score -= 200.0; // next item exactly fills this bin
        } else if post_residual >= nxt {
            // next item fits here too: reward tight chaining
            let gap = post_residual - nxt;
            if gap <= 10 { score -= 80.0; }
            else if gap <= 30 { score -= 20.0; }
            else { score += 5.0; }
        } else {
            // next item cannot use this residual
            score += (post_residual as f64) * 0.15;
        }
    }

    // ---- Last-chance bin: strongly favor using the only fitting bin ----
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if existing bins fit poorly
        // (large post_residual elsewhere) or many bins already open.
        let poor_fit_elsewhere = mean_residual - (item_size as f64);
        let base = 250.0;
        let pressure = if fitting_bins_count == 0 { 0.0 } else {
            (poor_fit_elsewhere.max(0.0)) * 2.0 + (open_bins_count as f64) * 3.0
        };
        score += base - pressure;
        // slight decay over stream: early on prefer consolidating
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 40.0;
    }

    // ---- Tie-break with mean residual: prefer bins tighter than average ----
    score += (mean_residual - bin_residual as f64) * 0.5;

    // ---- Modulo harmonic bonus: residuals in multiples of 10 pair well with typical items ----
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any plausible item (1..100)
    // are worthless. Penalize unusable gaps hard.
    if post_residual < 10 {
        score += 60.0; // dead space: nothing can ever go there
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward tight fits: small post_residual relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items as f64;
    let pressure = (open_bins_count as f64 / (1.0 + progress * 10.0)).min(10.0);
    score += 2.0 * pressure;

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0; // next item won't chain here
    }

    // Prefer bins with below-mean residual (close out emptier bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    }

    // New-bin candidate (empty bin): apply opening cost, scaled by how many
    // existing bins could fit and how poor the best existing fit would be.
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * fitting_bins_count as f64;
        if post_residual < 10 {
            score += 100.0; // never open a bin for an item leaving dead space? (post=cap-item)
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Near-perfect match: next item fits with small slack.
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Reward proportionally when slack is tiny (next item nearly fills bin).
        if slack <= 10.0 {
            score -= 30.0 - 2.5 * slack;
        } else {
            // Mild reward for leaving room usable by the next item.
            score -= 5.0 * (next_item_size as f64 / post_residual as f64);
        }
    }
    // Penalize next item NOT fitting the resulting residual (forces future bin use).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0 + 0.15 * (next_item_size - post_residual) as f64;
    }

    // Dead space penalty: residuals too small for the minimum item size are waste.
    if post_residual < 1 {
        score += 100.0; // safety, shouldn't happen
    } else if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Compare against mean residual across open bins: prefer bins tighter than average.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 0.5 {
            score -= 6.0 * (0.5 - rel);
        } else if rel > 1.5 {
            score += 4.0 * (rel - 1.5);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible (huge dead space).
    if fitting_bins_count == 1 && post_residual >= 1 {
        score -= 12.0;
        if post_residual < 10 {
            score -= 10.0; // still better to use it than open a new bin
        }
    }

    // New-bin candidate (pristine empty bin): only attractive if no open bin gives
    // a decent fit; make it moderately unattractive by default so fragmentation
    // is consumed first.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.85; // 85.0 baseline
        // If stream is early, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 5.0 * (1.0 - progress);
        // If many bins open already, discourage opening more.
        score += 0.5 * open_bins_count as f64;
    }

    // Late in the stream: tighten packing further, avoid spreading.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post residual), scaled.
    let mut score = post;

    // Waste penalty: dead space that is too small for typical future items.
    let dead_zone = 20.0;
    if post > 0.0 && post < dead_zone {
        score += (dead_zone - post) * 1.5;
    } else if post == 0.0 {
        score -= 25.0; // perfect fit reward
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack_after_next = post - nxt;
            score -= 10.0 * (1.0 - slack_after_next / cap);
        } else {
            score += 4.0; // next item won't fit here; slight penalty
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Global state: many open bins with high mean residual -> consolidate.
    let consolidation = (open_bins_count as f64).ln() * mean_residual / cap;
    score -= 8.0 * consolidation;

    // Time horizon: early on, allow opening new bins; late, pack tightly.
    let time_pressure = t * t;
    score += (1.0 - time_pressure) * 6.0;   // early: mild penalty on all (favors new bin less strongly)
    score -= time_pressure * 12.0 * (resid / cap); // late: favor fullest bins

    // New-bin candidate handling: empty bin should only win when no good fit exists.
    if bin_residual == bin_capacity {
        // Penalize new bin; penalty shrinks when existing fits are poor or none.
        let poor_fit = if fitting_bins_count <= 1 { 0.0 } else { 1.0 };
        let fit_quality = 1.0 - (item / cap); // big items leave little waste anyway
        score += 20.0 * poor_fit - 10.0 * (1.0 - fit_quality) * (1.0 - t);
        // If item is large, a fresh bin is fine.
        if item > 0.6 * cap {
            score -= 15.0;
        }
    }

    // Fragmentation guard: avoid leaving residual just above next item when bin nearly full.
    if next_item_size > 0 && post > 0.0 && post < next_item_size as f64 && post < 10.0 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let fit = item_size as f64;

    // Base: reward tight fits (low post_residual), non-linearly.
    let mut score = pr * (1.0 + 0.02 * (pr / cap) * (pr / cap));

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; late, demand tight packing.
    let tightness = 1.0 + 2.0 * progress * progress + 2.0 * progress * progress * progress;
    score *= tightness;

    // Dead-space penalty: residual too small for any plausible item (1..100).
    let dead = if pr > 0.0 { ((pr - 1.0) / cap).max(0.0) } else { 0.0 };
    score += 8.0 * dead * dead * cap;

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * progress;
    }

    // Lookahead: reward leaving space that still fits the next item.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 + 4.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 3.0 * progress;
    }

    // New-bin candidate: mildly penalize opening a bin unless residual is huge
    // or the stream is early and bin count is low.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        score = cap as f64 * (1.5 + progress) - 20.0 * scarcity * (1.0 - progress);
    }

    // Slight preference toward bins below mean residual (consolidate waste).
    score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space by
    // capacity fractions (eighths). Residuals in "small" classes are more
    // likely to be filled by future items; large awkward classes get penalized.
    let eighth = bin_capacity / 8;
    let class = (post_residual / eighth) as f64; // 0..=8 integer division class
    score -= class * 3.0; // reward bins whose leftover falls in a low class (tight fit)

    // Modulo arithmetic: residuals divisible by common item sizes (10, 20, 25, 50)
    // are "harmonic" and easier to fill later.
    let mut harmonic_bonus = 0.0f64;
    for m in [10u32, 20u32, 25u32, 50u32] {
        if post_residual % m == 0 {
            harmonic_bonus += 4.0;
        }
    }
    score -= harmonic_bonus;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize dead space in awkward classes: leftover that no plausible item
    // (1..=80) can pair with efficiently. If post_residual < 10 nothing fits.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let rem2 = post_residual - next_item_size;
            // prefer chains leaving small, harmonic remainders
            score -= 15.0;
            if rem2 < 10 {
                score += 10.0; // creates dead space after the lookahead
            }
            if rem2 % 10 == 0 {
                score -= 5.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): make it a mid-range
    // fallback. It should win only when all fits are bad (large post_residual
    // class or heavy dead-space penalties above).
    if bin_residual == bin_capacity {
        // baseline competitive score: an empty bin leaves residual = capacity
        score = cap * 0.85 + mean_residual * 0.1;
        // early in the stream, opening bins is cheap; later, prefer filling
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // many open bins: discourage spreading
        score += open_bins_count as f64 * 0.5;
    }

    // Mild tie-break toward bins below mean residual (keeps balance).
    if (post_residual as f64) < mean_residual {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strict dead-space avoidance archetype with open-bin pressure.

    let mut score = post_residual as f64;

    // --- Dead-space penalty: residuals below the minimum item size (1) are
    // never truly "dead" here, but small residuals that cannot host the
    // lookahead item are wasted. Penalize unusable gaps harshly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 0.25 * (next_item_size - post_residual) as f64;
    }

    // --- Perfect-fit reward: leaving exactly zero residual is ideal.
    if post_residual == 0 {
        score -= 10.0;
    }

    // --- Tight-fit reward: prefer bins where the item fills a large fraction.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill_ratio;

    // --- Lookahead harmony: if the next item fits the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = next_item_size as f64 / post_residual as f64;
        score -= 4.0 * next_fit;
    }

    // --- Open-bin pressure: discourage spreading across many bins; when many
    // bins are open, slightly favor consolidating into existing ones, and
    // penalize opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.05 + 0.10 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: pay the pressure tax plus a base cost so that it
        // only wins when all existing fits are genuinely bad.
        score += pressure + 5.0;
    } else {
        // Existing bins get a mild discount that grows with pressure.
        score -= 0.5 * pressure;
    }

    // --- Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // --- Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already fragmented; using it is fine, but avoid leaving it worse.
    let dev = mean_residual - post_residual as f64;
    score += 0.05 * dev.max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
