    // Progress-aware pressure: late in the stream, prefer tighter fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - pr / cap);

    // Prefer bins already below mean residual (balance avoidance of fragmentation).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: make it moderately unattractive unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 15.0;
