    // Waste discrimination: near-perfect fills heavily rewarded.
    let waste = pr / cap;
    if waste < 0.05 {
        score -= 6.0 * (0.05 - waste) * 20.0 * (1.0 - progress);
    }
    if waste > 0.6 {
        score += 4.0 * (waste - 0.6) * 10.0 * progress;
    }

    // NEW-BIN CANDIDATE: decide whether opening a fresh bin is worthwhile.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let tight_new = 1.0 - (item / cap).min(1.0);
        score = cap * (1.6 + progress)
            - 18.0 * scarcity * (1.0 - progress)
            - 25.0 * (1.0 - tight_new) * (1.0 - progress)
            + 35.0 * waste * progress;
        // If next item is large, a fresh bin with room is attractive.
        if nxt > 0.0 && nxt >= 0.5 * cap {
            score -= 12.0 * progress;
        }
        // Never open a new bin if the item fits snugly somewhere (implicit via high base).
        if fitting_bins_count >= 1 && item >= 0.8 * cap {
            score += 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest future item (size >= 1, but practically small gaps
    // below ~10 are near-useless) are heavily penalized.
    let dead_zone = 10.0f64;
    if (post_residual as f64) < dead_zone {
        // Quadratic penalty inside the dead zone: smaller leftover = worse.
        score += (dead_zone - post_residual as f64) * (dead_zone - post_residual as f64) * 4.0;
    }

    // Reward tight fits (small but nonzero post_residual is good only if
    // it stays usable); a perfect fit (0) is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize bins whose residual is already tight relative to capacity
    // (fragmented bins), scaled by how close post_residual is to dead zone.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score += tightness * tightness * 8.0;

    // Last-chance pressure: if this is the only fitting bin, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new
    // ones (penalize the empty-bin candidate implicitly via residual
    // reasoning) and encourage filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open.
        score += 10.0 + pressure * 2.0;
    } else {
        // Existing bin: reward slightly under pressure.
        score -= pressure * 0.3;
    }

    // Lookahead coupling: if the next item fits exactly in the post
    // residual, reward this placement strongly (creates a perfect follow-up).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.2;
        } else {
            // Next item cannot use the leftover: penalize proportionally
            // to how much dead space this creates for the lookahead.
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (i.e., tighter than average) to consolidate space.
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

