    // Penalize unusable dead space: post_residual too small for the smallest
    // plausible future item (assume items >= 1, but weight by dead-space size).
    if post_residual > 0 {
        let dead = post_residual as f64;
        score += 0.15 * dead;
        // Extra penalty if dead space is in the awkward small-but-nonzero zone.
        if dead < 10.0 {
            score += 25.0 * (10.0 - dead) / 10.0;
        }
    }

    // 2-step lookahead: reward bins where the next item also fits the residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect chaining: next item exactly fills remaining space.
            if slack == 0.0 {
                score -= 80.0;
            } else {
                score -= 30.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
