            let over = (next_item_size - post_residual) as f64;
            score += 0.3 * over.min(50.0);
        }
    }

    // Compare against mean residual: prefer bins whose residual is below mean
    // (consume the fuller bins first, keep spacious bins for large items).
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: make an empty bin attractive only when the
    // item is large relative to capacity or open bins are numerous.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
        // Default: new bin is moderately unattractive...
        score += 35.0;
        // ...but becomes attractive for big items or when bins are scarce.
        score -= 50.0 * frac * frac;
        score -= 20.0 / (1.0 + pressure);
    }

    // Slight preference to fill bins earlier in the stream (keep flexibility).
    score += 5.0 * (1.0 - step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
