            let pair_waste = cap - it - nx;
            if pair_waste >= 0.0 && pair_waste < 0.05 * cap {
                nb += 7.0 * (1.0 - pair_waste / (0.05 * cap)) * (1.0 - progress);
            }
        }
        if progress > 0.75 && fitting_bins_count > 0 && mean_residual >= it {
            nb += 5.5 + 4.5 * progress;
        }
