pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let x = post / cap; // normalized post residual

    // Base: penalize wasted space quadratically (dead space grows costly)
    let mut score = x * x * cap;

    // Smooth coupling with stream progress: later in stream, dead space is worse
    score += 12.0 * x * x * (progress * progress) * cap;

    // Lookahead synergy: reward residual that still fits the next item smoothly
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        let fit = next_item_size as f64 / cap;
        score -= 10.0 * (1.0 - x) * fit * (1.0 - progress);
    }

    // Penalize leaving residuals that are too small to be useful (smooth ramp)
    let small = (1.0 - x).min(0.2) / 0.2; // peaks when x near 1 (nearly full) -> actually reward near-full
    score -= 6.0 * small * x;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 - x);
    }

    // Mild penalty for spreading across many open bins when mean residual is high
    score += 0.05 * (open_bins_count as f64) * ((mean_residual - post).abs() / cap);

    // Reward tight fits relative to item size
    score -= 8.0 * (item_size as f64 / cap) * (1.0 - x);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover into residue classes mod 10
    let class = post_residual % 10;
    // Residues that pair well with common item sizes (1..100) get rewarded
    match class {
        0 => score -= 12.0,          // perfectly closed bin
        2 | 3 | 5 | 7 => score -= 6.0, // prime-ish / common small complements
        1 | 4 | 6 => score -= 2.0,
        _ => score += 4.0,           // 8, 9 awkward dead space
    }

    // Integer-division thresholds on post_residual: how many "half-capacity" units remain
    let half_units = post_residual / (bin_capacity / 2);
    score += half_units as f64 * 8.0; // large leftovers are fine, small fragments penalized
    // Penalize the awkward middle band (post_residual just above half capacity)
    if post_residual > bin_capacity / 2 && post_residual <= (bin_capacity * 3) / 5 {
        score += 6.0;
    }

    // Capacity-fraction coupling: item size relative to capacity
    let frac = item_size as f64 / bin_capacity as f64;
    if frac > 0.5 {
        score -= 5.0; // big items: prefer placing them somewhere rather than fragmenting
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // harmonic match: next item leaves a small, well-classed remainder
            let nxt_class = (post_residual - next_item_size) % 10;
            if nxt_class == 0 { score -= 10.0; }
            else if nxt_class <= 3 { score -= 4.0; }
            score += (post_residual - next_item_size) as f64 * 0.05;
        } else {
            score += 3.0; // next item cannot follow here
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Many open bins: discourage spreading; few open bins: encourage tight packing
    score += (open_bins_count as f64) * 0.3;
    score -= (mean_residual - post_residual as f64) * 0.1;

    // Stream progression: later in stream, be more tolerant of imperfect fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score += 10.0 + (fitting_bins_count as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never host the smallest
    // plausible item are pure waste — penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Moderate penalty for small-but-usable gaps that few future items fit.
    if post_residual > 0 && post_residual < 25 {
        score += 18.0;
    }

    // Reward near-perfect packing.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bins pressure: when many bins are open, prefer consolidating into
    // existing bins (penalize opening new ones / spreading).
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: empty bin should only win when existing
    // placements would create severe dead space.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if the residual barely misses the next item (dead space risk).
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Slight preference for tighter bins (low residual before placement).
    score += (bin_residual as f64 - post_residual as f64) * 0.1;

    score
}

