            nb -= 5.5 * (1.0 - (cap - it - nx) / (0.03 * cap));
        }
        if it > 0.85 * cap && progress > 0.3 {
            nb -= 9.0 * progress;
        }
        if it < 0.2 * cap && progress < 0.3 && open_bins_count < 6 {
            nb += 7.0 * (1.0 - progress);
        }
        if nx > 0.0 && progress > 0.6 && mean_residual > 0.45 * cap {
            nb += 6.0 * (1.0 - progress) * (mean_residual / cap - 0.45) * 10.0;
        }
        score = nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
