pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;

    let mut score = pr * (1.0 + 0.03 * (pr / cap) * (pr / cap));

    let tightness = 1.0 + 2.6 * progress * progress + 2.4 * progress * progress * progress;
    score *= tightness;

    // Fine-grained residual fitting: strong penalty for tiny leftovers
    let waste = pr / cap;
    if waste < 0.08 && pr > 0.0 {
        score -= 46.0 * (1.0 - progress) * (0.08 - waste);
    }
    if pr > 0.0 && pr < 10.0 {
        score += 41.0 * (1.0 - 0.5 * progress);
    }
    if pr == 0 {
        score -= 62.0;
    } else if pr <= 5 {
        score -= 31.0 * (1.0 - 0.4 * progress);
    }
    if pr > 0.0 && pr < 4.0 {
        score += 6.5 * (4.0 - pr) * (1.0 - progress);
    }

    // Lookahead anticipation with chained fits
    if nx > 0.0 {
        if pr < nx {
            let gap = nx - pr;
            score += gap * (2.0 + 6.5 * (1.0 - progress));
            if gap <= 3.0 {
                score -= 9.0 * (1.0 - progress);
            }
        } else {
            let chain_gap = pr - nx;
            let slack = chain_gap / cap;
            if chain_gap <= 40.0 {
                score -= 6.5 + 0.11 * chain_gap;
            }
            if slack < 0.04 {
                score -= 8.5 * (1.0 - slack * 25.0) * (1.0 + progress);
            }
            let chain = 1.0 - slack.min(1.0);
            score -= 5.0 + 4.0 * (nx / cap) + 9.5 * chain * (1.0 - progress);
            if chain_gap < 0.06 * cap {
                score -= 6.5 * (1.0 - chain_gap / (0.06 * cap)) * (0.5 + progress);
            }
            if chain_gap < 0.02 * cap {
                score -= 4.0 * (1.0 - chain_gap / (0.02 * cap)) * (0.4 + progress);
            }
        }
    }

    // Dead-space penalty, amplified when leftover is unusable for next item
    let dead_ratio = (pr / cap).max(0.0);
    let unusable = if nx > 0.0 && pr > 0.0 && pr < nx { 1.0 } else { 0.55 };
    score += (10.5 + 3.2 * progress) * dead_ratio * dead_ratio * cap * (0.45 + progress) * unusable;

    if bin_residual < bin_capacity {
        let dev = mean_residual - res;
        score += 0.085 * dev;
        if dev > -5.0 && dev < 15.0 && pr > 0.0 {
            score -= 4.2;
        }
        let fill_ratio = 1.0 - res / cap;
        if fill_ratio > 0.65 {
            score -= 4.8 * (fill_ratio - 0.65) * 10.0 * (0.4 + progress);
        }
        if nx > 0.0 && pr > 0.0 && pr < nx {
            score += 6.5 + 2.2 * progress;
        }
        let tight_fit = pr == 0 || (nx > 0.0 && pr == nx);
        if tight_fit {
            score -= 10.5 * (0.3 + progress);
        }
        if waste > 0.14 && waste < 0.34 {
