pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches
    // the next item size exactly (perfect chain fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot follow in this bin: penalize proportionally to waste.
        score += 0.35 * (next_item_size as f64 - post_residual as f64);
    }

    // Perfect fill is always excellent.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize dead space below the minimum plausible item size (1..=100 range,
    // treat <10 as likely dead) relative to capacity.
    if post_residual < 10 {
        score += 0.6 * (10 - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (compact packing).
    score += 0.15 * (post_residual as f64 - mean_residual);

    // Early in the stream, be more willing to open fresh bins (score new-bin
    // candidate generously later; keep it slightly attractive early).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

