            nb -= 6.5 + 8.5 * progress;
        }
        if nx > 0.0 && mean_residual > nx + 8.0 && progress < 0.7 {
            nb += 8.5 * ((mean_residual - nx) / cap).min(0.5) * cap * 0.1;
        }
        if mean_residual >= it && progress > 0.5 {
            nb += 6.5 + 8.5 * progress;
        }
        if nx > it && mean_residual >= nx && progress < 0.6 {
            nb += 10.0 * (1.0 - progress);
        }
        if nx > 0.0 && mean_residual < nx && progress < 0.5 {
            nb -= 0.56 * (nx - mean_residual);
        }
        if nx > 0.0 && mean_residual >= it + nx && progress < 0.6 {
            nb -= 5.5 * (1.0 - progress) * ((mean_residual - it - nx) / cap).min(0.3) * 10.0;
        }
        if it > 0.85 * cap && progress > 0.3 {
            nb -= 9.0 * progress;
        }
        if nx > 0.0 && mean_residual > nx {
            let excess = mean_residual - nx;
            if excess < 0.05 * cap && progress < 0.55 {
                nb += 5.0 * (1.0 - excess / (0.05 * cap)) * (1.0 - progress);
            }
        }
        if fitting_bins_count == 0 && progress > 0.25 {
            nb += 9.0 + 7.0 * progress;
        }
        if nx > 0.0 && it + nx > cap && mean_residual >= nx {
            nb += 6.0 * (1.0 - progress);
        }
        if progress > 0.75 && fitting_bins_count > 0 && mean_residual >= it {
            nb += 5.5 + 4.5 * progress;
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_left = mean_residual - it;
            if best_left >= nx && (best_left - nx) < 12.0 {
                nb += 4.0 * (1.0 - (best_left - nx) / 12.0) * (0.5 + progress);
            }
        }
        if it < 0.2 * cap && progress < 0.3 && open_bins_count < 6 {
            nb += 7.0 * (1.0 - progress);
        }
        if nx > 0.0 && progress > 0.6 && mean_residual > 0.45 * cap {
            nb += 6.0 * (1.0 - progress) * (mean_residual / cap - 0.45) * 10.0;
        }
        if it > 0.55 * cap && it < 0.85 * cap && nx > 0.0 && it + nx <= cap {
            nb -= 4.0 * (1.0 - progress);
        }
        score = nb;
    } else {
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize dead space relative to smallest plausible item
        let dead = post_residual as f64;
        score += 0.15 * dead;
        // Tight fit bonus: fraction of bin used
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 40.0 * fit_ratio * fit_ratio;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else {
            score += 10.0;
        }
        // Penalize leaving a gap just below the next item (near-miss dead space)
        let gap = post_residual as f64 - next_item_size as f64;
        if gap < 0.0 && gap > -8.0 {
            score += 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer opening a new bin only when fits are poor
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; cheaper early, costlier late
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 70.0 + 40.0 * progress;
        // If the item fits poorly everywhere, opening a new bin looks better
        if fitting_bins_count == 1 {
            let waste = (bin_residual - item_size) as f64;
            if waste > 40.0 {
                score -= 45.0;
            }
        }
        // Many open bins with high mean residual => prefer existing bins
        score += 0.5 * mean_residual;
        if open_bins_count > 8 {
            score += 15.0;
        }
    }

    // Global pressure: when many bins are open, tighten selection
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Time-horizon modulation: late in stream, prioritize filling bins tightly
    if total_items > 0 {
        let t = step_index as f64 / total_items as f64;
        score -= 20.0 * t * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;

    // Base: post residual, lightly normalized
    let mut score = pr / cap;

    // Smooth non-linear coupling: small post_residuals are penalized quadratically
    // (dead space), large post_residuals mildly rewarded (keeps bin usable).
    let x = pr / cap; // in [0,1]
    score += 0.8 * (1.0 - x) * (1.0 - x) * (1.0 - x); // cubic penalty for tight fits

    // Progress coupling: early in the stream, prefer spreading into new bins;
    // later, pack tightly. Smooth via a polynomial ramp.
    let urgency = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += urgency * 0.6 * x; // reward residual more as stream progresses
    score -= (1.0 - urgency) * 0.3 * x; // early: less penalty for tight fits

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 1.5;
    } else if fitting_bins_count > 1 {
        // mild competition bonus scaled by scarcity
        score -= 0.3 / fitting_bins_count as f64;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = (pr - nxt) / cap;
            score -= 0.7 * (1.0 - fit_quality * fit_quality);
        } else {
            // next item won't fit here; penalize leaving residual close to next size
            score += 0.2 * (1.0 - (pr - nxt).abs() / cap);
        }
    }

    // Discourage fragmenting when many bins are already open and mean residual is low
    let mr = mean_residual / cap;
    score += 0.25 * (1.0 - mr) * (open_bins_count as f64).sqrt() * 0.1;

    // New-bin candidate: make it attractive only when open bins are nearly full
    if is_new_bin {
        score -= 0.5 * urgency;
        score += 0.4 * (1.0 - urgency);
        // penalize new bin if plenty of aggregate space exists
        score += 0.3 * mr * (open_bins_count as f64 / (1.0 + open_bins_count as f64));
    }

    // Tie-break: prefer bins whose residual is close to item size (smooth kernel)
    let tightness = (bin_residual as f64 - item_size as f64) / cap;
    score += 0.15 * tightness * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo 10: prefer residuals that are
    // multiples of 10 (usable by typical item sizes), penalize odd/prime-ish dead space.
    let r_mod = post_residual % 10;
    score += match r_mod {
        0 => -8.0,
        1 | 3 | 7 | 9 => 6.0,
        5 => 2.0,
        _ => 0.0,
    };

    // Fractional capacity class of post_residual (integer division thresholds)
    let quarter = bin_capacity / 4;
    if post_residual < quarter {
        score += 12.0; // tiny dead space
    } else if post_residual < bin_capacity / 2 {
        score -= 2.0;
    } else if post_residual < 3 * quarter {
        score -= 5.0;
    } else {
        score -= 4.0;
    }

    // Reward when next item exactly fills post_residual (perfect harmonic pair)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let pair_mod = (post_residual - next_item_size) % 10;
            if pair_mod == 0 {
                score -= 10.0;
            }
            score += (post_residual - next_item_size) as f64 * 0.15;
        } else {
            score += 3.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: neutral-ish, penalize slightly so it's only chosen
    // when open bins have terrible fits.
    if bin_residual == bin_capacity {
        score += 20.0 + (open_bins_count as f64).sqrt() * 2.0;
        if post_residual as f64 > mean_residual + 30.0 {
            score -= 10.0;
        }
    }

    // Late in the stream, tighten packing (avoid opening new bins)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 {
        score += 6.0 * progress;
    }

    // Mean residual coupling: prefer bins far from the mean (keeps diversity)
    let dev = (post_residual as f64 - mean_residual).abs();
    score -= dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: minimize wasted space, but treat "unusable" gaps harshly.
    // A gap is unusable if it cannot fit the next item (or the smallest plausible item).
    let min_useful = if next_item_size > 0 { next_item_size.min(item_size) } else { item_size };
    if post_residual > 0 && post_residual < min_useful {
        // Dead space: gap too small for anything useful -> heavy penalty.
        score += 60.0 + (min_useful - post_residual) as f64 * 2.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit reward: fraction of residual consumed.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Lookahead coupling: if the next item exactly fits the post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Leaving room for the next item is mildly good.
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open bins pressure: with many open bins, prefer consolidating into existing bins
    // (penalize opening new bins implicitly by rewarding existing-bin usage).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - 0.5 * progress);

    // New-bin candidate: only attractive when it beats dead-space creation.
    if bin_residual == bin_capacity {
        // Neutral baseline; slight penalty scaled by how many bins already exist,
        // so we only open new bins when open-bin fits are poor.
        score += 10.0 + 0.5 * open_bins_count as f64;
        // If the current item is large relative to mean residual, opening fresh is fine.
        if item_size as f64 > mean_residual {
            score -= 15.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is above average (larger bins)
    // when the item is large, to preserve small bins for small items.
    if item_size as f64 > mean_residual {
        score += 3.0 * (mean_residual - bin_residual as f64).abs() * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
