pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / (bin_capacity as f64)) * (1.0 - diff / (bin_capacity as f64));
        // Perfect two-item closure: bin fully used by current + next item.
        if post_residual == next_item_size {
            score -= 50.0;
        }
        // Penalize leaving residual that no plausible item can use (dead space).
        if post_residual > 0 && next_item_size > post_residual {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 40.0;
    }

    // Prefer bins whose residual is close to the item (tight fit relative to mean state).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 10.0 * tightness * tightness;

    // Reward filling bins below the mean residual (consolidating waste).
    if (post_residual as f64) < mean_residual {
        score -= 5.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;
    } else {
        score += 3.0 * ((post_residual as f64) - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin offers a decent fit
    // or the stream is early (keeping bins clean for future large items).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let decent_fit_exists = fitting_bins_count > 0 && (bin_residual - item_size) as f64 <= mean_residual + 10.0;
        if decent_fit_exists {
            score += 35.0; // discourage opening new bin when decent fit exists
        }
        score -= 15.0 * (1.0 - progress); // early stream: fresh bins slightly favored
        score -= (post_residual as f64) * 0.3; // empty bin has max residual; offset base term
    }

    // Slight preference for bins with less residual overall (fill fuller bins first).
    score += 0.1 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
