pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;
    let x = pr / cap;
    let is_new_bin = (res - cap).abs() < 1e-9;

    if is_new_bin {
        // New-bin candidate: strong penalty unless clearly beneficial
        let item_frac = (it / cap).min(1.0);
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let mut nb = cap * (1.30 + 1.10 * progress);
        nb -= 25.0 * scarcity * (1.0 - progress);
        nb -= 18.0 * item_frac * (1.0 - progress);
        if nx >= 0.5 * cap { nb -= 12.0 * progress + 6.0 * (1.0 - progress); }
        nb += 14.0 * progress * (1.0 - item_frac);
        if it >= cap - 1.0 { nb -= 30.0; }
        if nx > 0.0 && cap - it >= nx { nb -= 10.0 + 0.1 * (cap - it - nx); }
        if fitting_bins_count <= 2 { nb += 20.0 + 10.0 * (1.0 - progress); }
        if fitting_bins_count >= 4 { nb -= 6.0 + 8.0 * progress; }
        if nx > 0.0 && mean_residual > nx + 8.0 && progress < 0.7 {
            nb += 8.0 * ((mean_residual - nx) / cap).min(0.5) * cap * 0.1;
        }
        if mean_residual >= it && progress > 0.5 { nb += 6.0 + 8.0 * progress; }
        if nx > it && mean_residual >= nx && progress < 0.6 { nb += 9.0 * (1.0 - progress); }
        if progress > 0.75 && fitting_bins_count > 0 && mean_residual >= it { nb += 5.0 + 4.0 * progress; }
        if it < 0.2 * cap && progress < 0.3 && open_bins_count < 6 { nb += 7.0 * (1.0 - progress); }
        return nb;
    }

    // Base: post residual with mild convexity
    let mut score = pr * (1.0 + 0.03 * x * x);
    score *= 1.0 + 2.2 * progress * progress;

    // Strong dead-space penalty when residual is unusable for the next item
    if nx > 0.0 && pr > 0.0 && pr < nx {
        score += 6.0 + 2.2 * progress;
        if nx - pr <= 3.0 { score -= 9.0 * (1.0 - progress); }
    }

    // Perfect fills are excellent
    if pr == 0.0 { score -= 60.0; }
    else if pr <= 5.0 { score -= 30.0 * (1.0 - 0.4 * progress); }

    // Small residual band: near-perfect fits rewarded
    if x > 0.0 && x < 0.12 {
        score -= 9.0 * (1.0 - x / 0.12) * (0.4 + progress);
    }
    // Mid-range waste penalized increasingly with progress
    if x > 0.12 && x < 0.3 {
        score += 4.0 * (x - 0.12) * (0.5 + progress);
    }

    // Lookahead: reward when next item fits with small leftover
    if nx > 0.0 && pr >= nx {
