    if fitting_bins_count == 1 {
        score -= 1.5;
    } else if fitting_bins_count > 3 && x < 0.12 {
        score -= 5.0 * (1.0 - x * 8.0) * (0.5 + progress);
    }

    // Pull toward mean residual (diversity tie-break)
    let dev = mean_residual - res;
    score += 0.08 * dev;

    // Mild open-bin fragmentation cost
    score -= 0.4 * (open_bins_count as f64).ln().max(0.0);

    // Tightness kernel
    let tightness = (res - it) / cap;
    score += 0.12 * tightness * tightness;

