            if rem < 0.02 * cap {
                score -= 5.0 * (1.0 - rem / (0.02 * cap)) * (0.4 + progress);
            }
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

