        if pr > 0.0 && (res - pr).abs() < 0.05 * cap {
            score -= 2.0 * (1.0 - (res - pr).abs() / (0.05 * cap));
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

