            nb -= 5.0 * (1.0 - (cap - it - nx) / (0.08 * cap)) * (0.5 + progress);
        }
        // NEW: opening a fresh bin is wasteful when the mean open residual can
        // still absorb the item with a usable remainder for the next item.
