        // NEW: two-item lookahead — if the new bin's leftover after this item
        // cannot host nx but some open bin's post-fit residual can, opening
        // strands both nx and the leftover; penalize when that stranded space
        // would be near-perfectly usable elsewhere.
        if nx > 0.0 && cap - it < nx && fitting_bins_count >= 1 {
            let best_post = (mean_residual - it).max(0.0);
            if best_post >= nx {
                let stranded = cap - it;
