            }
        }
        // NEW: if the new bin's post residual exactly equals nx (perfect chain),
        // opening it is nearly free of dead space; reward strongly.
        if nx > 0.0 && (cap - it) == nx {
            nb -= 9.0 * (0.5 + progress);
        }
        score = nb;
    } else {
        let fill_ratio = 1.0 - res / cap;
        let waste = pr / cap;
        if waste < 0.08 {
