        if nx > 0.0 && pr > 0.0 && pr < nx && fitting_bins_count >= 2 && mean_residual >= it + pr {
            score -= 2.8 * (1.0 - pr / nx) * (0.5 + progress);
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

