            let closeness = 1.0 - pr / nx;
            score += 3.0 * closeness * closeness * (0.6 + progress);
        }
        if nx > 0.0 && pr > nx && (pr - nx) <= 0.04 * cap {
            score -= 3.2 * (1.0 - (pr - nx) / (0.04 * cap)) * (1.0 - progress);
        }
        if nx > 0.0 && pr > nx && (pr - nx) > 0.04 * cap && (pr - nx) < 0.18 * cap {
            score -= 2.2 * (1.0 - ((pr - nx) / (0.18 * cap))) * (0.3 + progress);
        }
        // MUTATION: residual variance control — prefer bins whose post-residual
        // stays close to the fleet mean so remaining space stays uniformly usable.
        let dev2 = pr - mean_residual;
        if pr > 0.0 && dev2 > 0.1 * cap {
            score += 3.0 * ((dev2 - 0.1 * cap) / cap).min(0.5) * (0.5 + progress) * 10.0;
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * 1.0;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward if next item fits in post_residual (chain placement)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0 + 0.5 * next_item_size as f64;
        } else {
            // penalize leaving residual that nothing useful can use
            let waste = post_residual as f64;
            if waste < 10.0 {
                score += 5.0; // small dead space
            } else if waste < next_item_size as f64 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Global state: when many bins are open with large mean residual,
    // prefer filling existing bins over opening new ones
    let pressure = mean_residual / bin_capacity as f64;
    score -= pressure * 20.0;

    // Penalize opening a new bin when open bins could fit (handled by
    // comparing against new-bin candidate whose post_residual is large).
    // New-bin candidate gets a mild time-dependent penalty so early on we
    // consolidate, later we allow spreading.
    let t = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 50.0 + 100.0 * (1.0 - t);
        // but if mean residual is tiny (bins nearly full), new bin is fine
        score -= (bin_capacity as f64 - mean_residual).max(0.0);
    }

    // Reward using bins with small residual more aggressively late in stream
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.1 * (0.5 + t);

    // Slight bonus when few fitting bins exist (scarcity)
    if fitting_bins_count <= 2 && bin_residual >= item_size {
        score -= 10.0;
    }

    score
}

