        if pr > 0.0 && nx > 0.0 && pr < 0.5 * nx && progress > 0.3 {
            score += 3.5 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
        }
        if waste > 0.3 && pr > nx && progress < 0.5 {
            score += 3.0 * (waste - 0.3) * 10.0 * (1.0 - progress);
        }
        if fill_ratio > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
            score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
        }
        if waste > 0.35 && progress > 0.55 && nx > 0.0 && pr >= nx {
            score -= 4.5 * ((pr - nx) / cap).min(0.2) * 5.0 * progress;
        }
        // Two-step lookahead: residual that chains nx plus a small follow-up
        // margin keeps flexibility; reward moderately.
        if nx > 0.0 && pr > nx && (pr - nx) > 0.04 * cap && (pr - nx) < 0.18 * cap {
            score -= 2.2 * (1.0 - ((pr - nx) / (0.18 * cap))) * (0.3 + progress);
        }
        if fitting_bins_count == 1 {
            score -= 14.0 + 12.0 * progress;
        } else if fitting_bins_count == 2 {
            score -= 4.0 + 3.0 * progress;
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: post-residual cost, with non-linear (quadratic) penalty on wasted space.
    let mut score = pr + (pr / cap) * (pr / cap) * 30.0;

    // Smooth stream-progress coupling: early on, tight fits matter more (build dense bins);
    // later, slightly relax to keep many bins flexible.
    let tightness = 1.0 + 0.8 * (1.0 - progress) * (1.0 - progress);
    score *= tightness;

    // Non-linear interaction: reward filling the bin (small pr) more strongly as progress grows.
    score -= 25.0 * progress * (1.0 - pr / cap) * (1.0 - pr / cap);

    // Lookahead coupling: penalize leaving residual that neither fits nor matches next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        score += 8.0 * (gap / cap) * (gap / cap);
        // Reward leaving exactly enough room for the next item (smooth trough).
        score -= 10.0 * (-((pr - nx) * (pr - nx)) / (2.0 * 25.0)).exp();
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - progress * 0.5);
    }

    // New-bin candidate: penalize opening a fresh bin unless it's genuinely attractive.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln().max(0.0);
        score += 55.0 - 20.0 * (it / cap) - 15.0 * progress - 6.0 * openness;
    } else {
        // Mild preference for bins with residuals near the mean (balance spread).
        score += 4.0 * ((bin_residual as f64 - mean_residual) / cap).abs();
    }

    // Smooth small-scale regularizer.
    score += 0.01 * (pr * pr) / (cap * cap) * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
