            score -= 4.0 * (1.0 - (pr - nx) / (0.09 * cap)) * progress;
        }
        if pr > 0.0 && nx > 0.0 && pr < nx && (nx - pr) > 0.1 * cap && waste > 0.25 {
            score += 5.0 * (waste - 0.25) * 10.0 * (0.4 + progress);
        }
        if pr > 0.0 && nx > 0.0 && pr < 0.5 * nx && progress > 0.3 {
            score += 3.5 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
        }
        if waste > 0.3 && pr > nx && progress < 0.5 {
            score += 3.0 * (waste - 0.3) * 10.0 * (1.0 - progress);
        }
        if fill_ratio > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
            score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
        }
        if waste > 0.35 && progress > 0.55 && nx > 0.0 && pr >= nx {
            score -= 4.5 * ((pr - nx) / cap).min(0.2) * 5.0 * progress;
        }
        if nx > 0.0 && pr > 0.0 && pr < nx {
            let closeness = 1.0 - pr / nx;
            score += 3.0 * closeness * closeness * (0.6 + progress);
        }
        if nx > 0.0 && pr > nx && (pr - nx) <= 0.04 * cap {
            score -= 3.2 * (1.0 - (pr - nx) / (0.04 * cap)) * (1.0 - progress);
        }
        if nx > 0.0 && pr > nx && (pr - nx) > 0.04 * cap && (pr - nx) < 0.18 * cap {
            score -= 2.2 * (1.0 - ((pr - nx) / (0.18 * cap))) * (0.3 + progress);
        }
        // NEW: prefer bins whose post-residual stays close to the pooled mean
        // — reduces residual variance and preserves balanced flexibility.
        if pr > 0.0 {
            let dv = (pr - mean_residual).abs();
            if dv < 0.05 * cap {
                score -= 2.0 * (1.0 - dv / (0.05 * cap)) * (0.3 + progress);
            } else if dv > 0.25 * cap {
                score += 1.8 * ((dv - 0.25 * cap) / cap).min(0.3) * 10.0 * progress;
            }
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction band does the leftover fall in?
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let pr = post_residual;
    let class_penalty: f64 = if pr == 0 {
        -30.0 // perfect closure
    } else if pr < eighth {
        -12.0 // tiny dead space, nearly closed
    } else if pr < quarter {
        6.0 // awkward small gap
    } else if pr < quarter * 2 {
        0.0
    } else if pr < quarter * 3 {
        -4.0 // still roomy, half+ usable
    } else {
        -8.0 // large residual, very reusable
    };
    score += class_penalty;

    // Modulo-16 harmony: does post_residual align with common size residues?
    let m = pr % 16;
    if m == 0 {
        score -= 5.0;
    } else if m <= 4 {
        score += 2.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            let npr = pr - next_item_size;
            // harmonic check on the double-remainder
            if npr % 8 == 0 {
                score -= 8.0;
            }
            score += npr as f64 * 0.3;
        } else {
            // next item cannot use this leftover: leftover becomes dead space risk
            score += (pr as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bins are fragmented
    // (high mean residual relative to next item) or we're early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = if next_item_size > 0 {
            (mean_residual - next_item_size as f64).max(0.0) / cap
        } else {
            mean_residual / cap
        };
        score = cap * (1.0 - 0.4 * progress) - 20.0 * fragmentation;
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    // Mild preference for tighter bins overall (waste-avoidance).
    score += (bin_residual as f64 - mean_residual) * 0.1;

    score
}

