        if avg_fragmentation < item_size as f64 * 1.5 {
            // Open bins are large enough; discourage new bin.
            score += 6.0;
        }
        // Early in the stream, opening bins is cheaper (build a pool).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0 * (1.0 - progress);
    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    let pressure = open_bins_count as f64 * mean_residual / (bin_capacity as f64);
    if bin_residual != bin_capacity {
        score -= 3.0 * pressure / (open_bins_count.max(1) as f64);
    }

    // Time horizon: late in the stream, prioritize compactness (avoid stranded residual).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 4.0 * progress * tightness;

    // Slight preference for bins whose residual is close to item size (perfect fit shaping).
    let fit_gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 3.0 * fit_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
