        // ignore is stranded capacity; penalize its share of the bin.
        if nx > 0.0 && pr > 0.0 && pr < nx && waste > 0.06 {
            score += 55.0 * (waste - 0.06) * (0.7 + progress);
        }
        // NEW: residual just below nx but reachable by the item after it
        // (common small sizes) — soften the penalty slightly.
        if nx > 0.0 && pr > 0.0 && pr < nx && nx - pr <= 8.0 && pr >= 4.0 {
            score -= 3.0 * (1.0 - (nx - pr) / 8.0) * (1.0 - progress);
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // plausible future item are "dead". Penalize them super-linearly.
    if post_residual > 0 {
        // smallest item is 1, but small gaps (< ~20) are hard to reuse
        let dead_threshold = 20.0f64;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 2.5;
        }
        // exact fit is a perfect placement: strong reward
        if post_residual == 0 {
            score -= 30.0;
        }
    }

    // Reward tight fits relative to the residual before placement.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 12.0;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement is ideal; reward it. If next item cannot fit into
    // post_residual but would fit a fresh bin, slightly prefer conserving
    // large residuals.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    } else {
        // last item: prefer filling a bin completely
        score -= fit_ratio * 20.0;
    }

    // Open-bin pressure: discourage scattering across many bins when
    // open_bins_count is large, but allow opening new bins early in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).powf(0.7) * (0.4 + 0.6 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new one (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + fit_ratio * 10.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already fragmented; prefer dumping items there (use up the worst
    // bins first, keep clean bins for future items).
    let dev = mean_residual - bin_residual as f64;
    score -= dev * 0.3;

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when the current fit is poor (large post_residual on
    // a nearly empty residual would mean item is small relative to nothing).
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, scaled by how many bins are open
        score += 18.0 + 2.0 * open_bins_count as f64;
        // but if placing in an existing bin would leave a big awkward gap,
        // the empty bin becomes relatively better (score above already lower
        // for bad fits via post_residual penalty).
        if post_residual == 0 {
            score -= 10.0; // exact fit in fresh bin still fine
        }
    }

    score
}

