                score += 2.8 * (spread - 0.22).min(0.3) * 10.0 * progress;
            }
        }
        // MUTATION: awkward dead zone — post-residual just below next item
        // wastes the chain; scale penalty with how close it is to nx.
        if nx > 0.0 && pr > 0.0 && pr < nx {
            let miss = 1.0 - pr / nx;
            score += 1.8 * miss * (0.5 + progress) * (nx / cap).min(0.5);
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

