pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: perfect match of post_residual with next item is gold.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Exact fit for the next item -> huge reward
        if diff < 0.5 {
            score -= 200.0;
        } else if post_residual as f64 >= nxt {
            // Next item still fits: reward proportional to how tight the match is
            score -= 60.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize dead space scaled by leftover gap
            score += 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving below-average residual wastes capacity elsewhere.
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless current bins are bad fits.
    if bin_residual == bin_capacity {
        score += 120.0 + 0.5 * open_bins_count as f64;
        // If next item is large, an empty bin is more valuable.
        if next_item_size > 50 {
            score -= 80.0;
        }
    }

    // Slight preference to keep tight fits early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress) * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

