        // leaves an awkward sliver that can't hold nx, discourage opening it.
        if nx > 0.0 && cap - it > 0.0 && cap - it < nx {
            nb += 4.5 * (1.0 - progress) * ((nx - (cap - it)) / cap).min(0.3) * 10.0;
        }
        // NEW: reward opening a fresh bin when it can exactly chain the next
        // item with a tight margin (perfect two-item packing ahead).
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin < 0.15 * cap {
                nb -= 6.0 * (1.0 - margin / (0.15 * cap)) * (0.6 + 0.4 * progress);
            }
        }
        // NEW: late-stream small items should avoid spawning new bins when the
        // mean residual can still absorb them — dead-space control.
        if item_frac < 0.35 && progress > 0.45 && mean_residual >= it + 4.0 {
            nb += 8.0 * progress * (1.0 - item_frac / 0.35);
        }
        // NEW: when many bins remain open but poorly utilized, opening yet
        // another fresh bin fragments residual space; penalize mildly.
        if open_bins_count > 8 && mean_residual > 0.3 * cap && item_frac < 0.5 {
            nb += 4.0 * ((open_bins_count as f64 - 8.0).min(6.0) / 6.0) * (1.0 - progress);
        }
        score = nb;
    } else {
        let fill_ratio = 1.0 - res / cap;
        let waste = pr / cap;
        if waste < 0.08 {
            score -= 48.0 * (1.0 - progress) * (0.08 - waste);
        }
        if fill_ratio > 0.65 {
            score -= 4.8 * (fill_ratio - 0.65) * 10.0 * (0.4 + progress);
        }
        if nx > 0.0 && nx <= pr && pr > 0.0 {
            let gap = (pr - nx) / cap;
            if gap < 0.03 {
                score -= 7.5 * (1.0 - gap * 33.0);
            }
        }
        if pr > 0.0 && pr < 10.0 {
            score += 41.0 * (1.0 - 0.5 * progress);
        }
        if pr == 0.0 {
            score -= 62.0;
        } else if pr <= 5.0 {
            score -= 31.0 * (1.0 - 0.4 * progress);
        }
        if nx > 0.0 && pr > 0.0 && pr < nx {
            score += 6.5 + 2.2 * progress;
            if nx - pr <= 3.0 {
                score -= 9.0 * (1.0 - progress);
            }
        }
        let dev = mean_residual - res;
        score += 0.085 * dev;
        if dev > -5.0 && dev < 15.0 && pr > 0.0 {
            score -= 4.2;
        }
        let tight_fit = (pr == 0.0) || (nx > 0.0 && pr == nx);
        if tight_fit {
            score -= 10.5 * (0.3 + progress);
        }
        if nx > 0.0 && pr >= nx {
            let room = pr - nx;
            if room < 0.06 * cap {
                score -= 6.5 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if waste > 0.14 && waste < 0.34 {
            score += 13.0 * (waste - 0.14) * (0.6 + 0.8 * progress);
        }
        if fitting_bins_count > 3 && waste < 0.12 {
            score -= 5.5 * (1.0 - waste * 8.0) * (0.5 + progress);
        }
        if nx > 0.0 && pr > 0.0 && pr > nx && (pr - nx) < 0.02 * cap {
            score -= 4.0 * (1.0 - (pr - nx) / (0.02 * cap)) * (0.4 + progress);
        }
        if pr > 0.0 && (pr as f64).sqrt() < 2.6 {
            score -= 3.5 * (1.0 - progress);
        }
        if waste > 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.09 * cap && progress > 0.4 {
            score -= 4.0 * (1.0 - (pr - nx) / (0.09 * cap)) * progress;
        }
        if pr > 0.0 && nx > 0.0 && pr < nx && (nx - pr) > 0.1 * cap && waste > 0.25 {
            score += 5.0 * (waste - 0.25) * 10.0 * (0.4 + progress);
        }
        if pr > 0.0 && nx > 0.0 && pr < 0.5 * nx && progress > 0.3 {
            score += 3.5 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
        }
        if waste > 0.3 && pr > nx && progress < 0.5 {
            score += 3.0 * (waste - 0.3) * 10.0 * (1.0 - progress);
        }
        if fill_ratio > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
            score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
        }
        if waste > 0.35 && progress > 0.55 && nx > 0.0 && pr >= nx {
            score -= 4.5 * ((pr - nx) / cap).min(0.2) * 5.0 * progress;
        }
        if nx > 0.0 && pr > 0.0 && pr < nx {
            let closeness = 1.0 - pr / nx;
            score += 3.0 * closeness * closeness * (0.6 + progress);
        }
        if nx > 0.0 && pr > nx && (pr - nx) <= 0.04 * cap {
            score -= 3.2 * (1.0 - (pr - nx) / (0.04 * cap)) * (1.0 - progress);
        }
        if nx > 0.0 && pr > nx && (pr - nx) > 0.04 * cap && (pr - nx) < 0.18 * cap {
            score -= 2.2 * (1.0 - ((pr - nx) / (0.18 * cap))) * (0.3 + progress);
        }
        // NEW: bins whose residual sits well below the current item's size
        // class are nearly dead — mild penalty scaled by how far below.
        if pr > 0.0 && it > 0.0 && pr < it * 0.5 && waste > 0.05 {
            score += 2.5 * (1.0 - pr / (it * 0.5)) * (0.4 + progress);
        }
        // NEW: residual-space compaction — prefer bins whose post-residual is
        // close to the mean residual (keeps remaining space homogeneous and
        // reusable by upcoming items), reducing fragmented dead space.
        if pr > 0.0 {
            let dev2 = ((pr - mean_residual) / cap).abs();
            if dev2 < 0.1 {
                score -= 3.0 * (1.0 - dev2 / 0.1) * (0.3 + 0.7 * progress);
            }
        }
        // NEW: when few bins can fit the item, strongly prefer the one whose
        // post-residual is closest to a multiple of the next item size —
        // preserves chainability of the residual space.
        if nx > 0.0 && pr > nx && fitting_bins_count <= 2 {
            let m = (pr % nx.max(1.0)) / nx.max(1.0);
            if m < 0.08 {
                score -= 4.5 * (1.0 - m / 0.08) * (0.4 + progress);
            }
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize very small dead space that becomes unusable (< 10).
    if post_residual < 10 {
        score -= 25.0; // actually desirable: bin fully exploited
    } else if post_residual < 20 {
        score += 6.0; // awkward dead zone
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize unless item is huge or fits are poor.
    if bin_residual == bin_capacity {
        let tightness = fit_ratio;
        score += 35.0;
        score -= 30.0 * tightness; // big items justify a fresh bin
        if next_item_size > 0 && next_item_size as f64 + item_size as f64 <= bin_capacity as f64 {
            score -= 12.0; // new bin can host the pair
        }
        // Late in stream, prefer consolidation into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 15.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else if next_item_size > bin_residual {
            // next item cannot fit here anyway; mild bonus for using this bin now
            score -= 5.0;
        }
    }

    // Global pressure: many open bins with low mean residual -> consolidate.
    if open_bins_count > 2 {
        let pressure = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).ln();
        score += 4.0 * pressure;
    }

    // Prefer bins already below mean residual (concentrate usage).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Time horizon: early stream, keep bins tidy; late stream, pack aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { (step_index as f64 / total_items as f64).clamp(0.0, 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;
    let is_new_bin = (res - cap).abs() < 1e-9;
    let waste = pr / cap;

    if is_new_bin {
        // New-bin candidate: open only when open bins are nearly saturated
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let item_frac = (it / cap).min(1.0);
        let mut nb = cap * (1.30 + 1.05 * progress);
        nb -= 24.0 * scarcity * (1.0 - progress);
        nb -= 18.0 * item_frac * (1.0 - progress);
        if nx >= 0.5 * cap {
            nb -= 10.0 * progress + 5.0 * (1.0 - progress);
        }
        nb += 14.0 * progress * (1.0 - item_frac);
        if it >= cap - 1.0 {
            nb -= 30.0;
        }
        // fresh bin chains next item tightly -> good lookahead
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin < 0.15 * cap {
                nb -= 6.5 * (1.0 - margin / (0.15 * cap)) * (0.6 + 0.4 * progress);
            }
        }
        // fresh bin leaves sliver that can't hold next item -> discourage
        if nx > 0.0 && cap - it > 0.0 && cap - it < nx {
            nb += 4.5 * (1.0 - progress) * ((nx - (cap - it)) / cap).min(0.3) * 10.0;
        }
        if fitting_bins_count <= 2 {
            nb += 20.0 + 9.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 4 {
            nb -= 6.0 + 8.0 * progress;
        }
        if mean_residual >= it && progress > 0.5 {
            nb += 6.0 + 8.0 * progress;
        }
        if nx > it && mean_residual >= nx && progress < 0.6 {
            nb += 9.0 * (1.0 - progress);
        }
        if progress > 0.85 && mean_residual < 0.15 * cap {
            nb += 7.0 * progress * (1.0 - mean_residual / (0.15 * cap));
        }
        if it < 0.2 * cap && progress < 0.3 && open_bins_count < 6 {
            nb += 6.5 * (1.0 - progress);
        }
        return nb;
    }

    // Existing-bin scoring: strongly penalize dead space, reward tight fits
    let mut score = pr * (1.0 + 0.03 * waste * waste);
    score *= 1.0 + 2.4 * progress * progress + 2.2 * progress * progress * progress;

    // Dead-space quadratic penalty, stronger when residual can't hold next item
    let unusable = if nx > 0.0 && pr > 0.0 && pr < nx { 1.0 } else { 0.55 };
    score += (10.0 + 3.0 * progress) * waste * waste * cap * (0.45 + progress) * unusable;

    // Near-perfect fit reward
    if waste > 0.0 && waste < 0.12 {
        score -= 9.0 * (1.0 - waste / 0.12) * (0.4 + progress);
    }
    // Awkward mid-band waste
    if waste > 0.12 && waste < 0.3 {
        score += 4.0 * (waste - 0.12) * (0.5 + progress);
    }
    // Residual just below next item size: nearly-dead space
    if pr > 0.0 && nx > 0.0 && pr < nx && (nx - pr) <= 0.04 * cap {
        score += 3.5 * (1.0 - (nx - pr) / (0.04 * cap)) * (0.5 + progress);
    }
    // Tiny residuals are dead
    if pr == 0.0 {
        score -= 60.0;
    } else if pr <= 5.0 {
        score -= 30.0 * (1.0 - 0.4 * progress);
    } else if pr < 10.0 {
        score += 38.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: next item fits with tight chain
    if nx > 0.0 {
        if pr >= nx {
            let chain_gap = pr - nx;
            let slack = chain_gap / cap;
            if chain_gap <= 40.0 {
                score -= 6.0 + 0.1 * chain_gap;
            }
            if slack < 0.04 {
                score -= 8.0 * (1.0 - slack * 25.0) * (1.0 + progress);
            }
            let chain = 1.0 - slack.min(1.0);
            score -= 4.5 + 3.5 * (nx / cap) + 8.5 * chain * (1.0 - progress);
        } else {
            let gap = nx - pr;
            score += gap * (2.0 + 6.0 * (1.0 - progress));
            let closeness = 1.0 - pr / nx;
            score += 3.0 * closeness * closeness * (0.6 + progress);
        }
    }

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 1.5;
    } else if fitting_bins_count > 1 {
        score -= 0.3 / fitting_bins_count as f64;
    }

    // Fill ratio bonus for well-filled bins
    let fill_ratio = 1.0 - res / cap;
    if fill_ratio > 0.65 {
        score -= 4.5 * (fill_ratio - 0.65) * 10.0 * (0.4 + progress);
    }

    // Deviation from mean residual: prefer typical bins
    let dev = mean_residual - res;
    score += 0.08 * dev;
    if dev > -5.0 && dev < 15.0 && pr > 0.0 {
        score -= 4.0;
    }

    // Mild open-bin count pressure
    score -= 0.35 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: quadratic penalty on wasted space, modulated by stream progress
    let mut score = x * (1.0 - 0.5 * progress) + 2.0 * x * x * (0.5 + progress);

    // Smooth interaction: tight fits are increasingly valuable as stream progresses
    let tightness = 1.0 - x;
    score -= tightness * tightness * (0.5 + 1.5 * progress);

    // Penalize bins whose residual deviates strongly from the mean residual (smooth coupling)
    let dev = (pr - mean_residual) / cap;
    score += 0.3 * dev * dev * (1.0 - progress);

    // Last-chance bonus: strongly favor the only fitting bin, scaled by progress
    if fitting_bins_count == 1 {
        score -= 3.0 * (0.4 + 0.6 * progress);
    }

    // Lookahead: reward leaving room for the next item (smooth margin term)
    if next_item_size > 0 {
        let gap = (pr as f64 - next_item_size as f64) / cap;
        if gap >= 0.0 {
            score -= 0.8 * gap * (1.0 - gap) * (0.5 + progress);
        } else {
            score += 0.5 * gap * gap;
        }
    }

    // Mild pressure against proliferating bins late in the stream
    score += 0.05 * open_bins_count as f64 * x * progress;

    // New-bin candidate: neutral-to-slightly-punished early, more punished late
    if bin_residual == bin_capacity {
        score += 0.4 + 1.2 * progress;
    }

    score
}

