        }
        if pr > 0.0 && pr < 10.0 {
            score += 41.0 * (1.0 - 0.5 * progress);
        }
        if pr == 0.0 {
            score -= 62.0;
        } else if pr <= 5.0 {
            score -= 31.0 * (1.0 - 0.4 * progress);
        }
        if nx > 0.0 && pr > 0.0 && pr < nx {
            if nx - pr <= 3.0 {
                score -= 9.0 * (1.0 - progress);
            }
            if nx - pr > 0.1 * cap && waste > 0.25 {
                score += 5.0 * (waste - 0.25) * 10.0 * (0.4 + progress);
            }
        }
        let dev = mean_residual - res;
        score += 0.085 * dev;
        if dev > -5.0 && dev < 15.0 && pr > 0.0 {
            score -= 4.2;
        }
        let tight_fit = (pr == 0.0) || (nx > 0.0 && pr == nx);
        if tight_fit {
            score -= 10.5 * (0.3 + progress);
        }
        if nx > 0.0 && pr >= nx {
            let room = pr - nx;
            if room < 0.06 * cap {
                score -= 6.5 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
            }
            if room <= 0.04 * cap {
                score -= 3.2 * (1.0 - room / (0.04 * cap)) * (1.0 - progress);
            } else if room < 0.18 * cap {
                score -= 2.2 * (1.0 - room / (0.18 * cap)) * (0.3 + progress);
