        }
        // NEW: reward bins whose post-residual chains tightly with the
        // item after next (two-step lookahead) — reduces dead space.
        if nx > 0.0 && pr > nx && (pr - nx) > 0.04 * cap && (pr - nx) < 0.18 * cap {
