pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are
    // permanently unusable, so penalize them quadratically.
    let min_item = 1u32; // sizes 1..100; treat 1 as floor for dead-space definition
    if post_residual < 10 {
        // effectively unusable gap -> heavy penalty
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Perfect fit gets a strong bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last chance: only this bin fits -> strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize placing into a bin when many bins fit the item (save flexible bins)
    if fitting_bins_count > 1 && bin_residual != bin_capacity {
        score += 6.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Open bins pressure: discourage scattering across many bins mid-stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (2.0 + 4.0 * progress);

    // Lookahead: if next item fits the post-residual, reward leaving that gap
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // gap that next item cannot use: mild penalty
        score += 8.0;
    }

    // New-bin candidate handling: attractive early, or when open bins fit poorly
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        // prefer new bin if existing fits leave worse residuals
        if mean_gap > post_residual as f64 {
            score -= 25.0;
        } else {
            score += 20.0 + 30.0 * (1.0 - progress);
        }
    }

    // Slight preference for bins below mean residual (balance loads)
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (small post_residual).
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * (bin_capacity as f64);

    // 2-step lookahead: reward if the next item exactly fits the post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain: next item closes this bin
        } else if next_item_size <= post_residual {
            // next item fits: the smaller the leftover after that, the better
            let chain_leftover = post_residual - next_item_size;
            score -= 20.0 * (1.0 - chain_leftover as f64 / post_residual as f64);
        } else {
            // next item does NOT fit here: penalize leaving dead space that
            // the lookahead cannot use, scaled by how badly it misses
            let miss = (next_item_size - post_residual) as f64;
            score += 0.3 * miss.min(30.0);
        }
    }

    // Relative-to-mean coupling: bins with residual far above the mean are
    // wasteful targets unless the fit is very tight.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.2 * (pr - mean_residual);
    } else {
        score -= 0.1 * (mean_residual - pr);
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a good fit. Penalize the fresh bin by default, but
    // reduce the penalty late in the stream or when many bins are open
    // (fragmentation likely) so a clean bin can win over terrible fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 60.0; // default: worse than any decent fit
        new_bin_score -= 15.0 * progress;
        new_bin_score -= (open_bins_count as f64).min(10.0);
        // If the item is large, a fresh bin guarantees a good residual.
        if item_size > bin_capacity / 2 {
            new_bin_score -= 10.0;
        }
        // If no open bin can fit the item at all, the new bin is the only option.
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0;
        }
        return new_bin_score;
    }

    // Mild penalty for very loose fits (large item in nearly empty bin wastes
    // capacity that smaller future items could have used).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio < 0.35 {
        score += 8.0 * (0.35 - fill_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
