        if nx > 0.0 && pr > 0.0 && pr < nx {
            score += 6.0 + 2.0 * progress;
            if nx - pr <= 3.0 { score -= 8.5 * (1.0 - progress); }
            let closeness = 1.0 - pr / nx;
            score += 3.0 * closeness * closeness * (0.6 + progress);
        }

        // Deviation from mean residual
        let dev = mean_residual - res;
        score += 0.08 * dev;
        if dev > -5.0 && dev < 15.0 && pr > 0.0 { score -= 4.0; }

        // Scarcity of fitting bins
        if fitting_bins_count == 1 { score -= 4.0 + 3.0 * progress; }
        else if fitting_bins_count > 3 && waste < 0.12 {
            score -= 5.0 * (1.0 - waste * 8.0) * (0.5 + progress);
        }

        // Fragmentation control: many open bins, low mean residual
        score += 0.35 * (1.0 - mean_residual / cap) * (open_bins_count as f64).ln().max(0.0);
        score -= 0.4 * (open_bins_count as f64).ln().max(0.0);

        // Mid-range waste band penalty
        if waste > 0.14 && waste < 0.34 {
            score += 12.0 * (waste - 0.14) * (0.6 + 0.8 * progress);
        }
        if waste > 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.09 * cap && progress > 0.4 {
            score -= 3.5 * (1.0 - (pr - nx) / (0.09 * cap)) * progress;
        }
        // High fill with usable room for next item
        if fill_ratio > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
            score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
        }
        if waste > 0.35 && progress > 0.55 && nx > 0.0 && pr >= nx {
            score -= 4.0 * ((pr - nx) / cap).min(0.2) * 5.0 * progress;
        }
        // Near-perfect chain fits
        if nx > 0.0 && pr > nx && (pr - nx) <= 0.04 * cap {
            score -= 3.0 * (1.0 - (pr - nx) / (0.04 * cap)) * (1.0 - progress);
        }
        score
    }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let fit_ratio = item_size as f64 / bin_capacity as f64;
    let post_norm = post_residual as f64 / bin_capacity as f64;

    // Tight fits are excellent: reward strongly (subtract).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 30.0 * (11.0 - post_residual as f64);
    } else {
        // Non-linear penalty for awkward mid-size dead space.
        let dead = if post_norm < 0.5 { post_norm * 2.0 } else { post_norm };
        score += 10.0 * dead * dead;
    }

    // Favor bins whose residual is close to the item (best-fit flavor).
    score += 0.5 * (bin_residual as f64 - item_size as f64);

    // Lookahead: if next item fits in the post residual, this is a great pairing.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 + 0.2 * next_item_size as f64;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            // Next item would have fit now but not after this placement: mild penalty.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Many open bins with slack: encourage consolidation into existing bins.
    if open_bins_count > 2 {
        let slack = (mean_residual - post_norm * bin_capacity as f64).abs();
        score += 0.05 * open_bins_count as f64 + 0.02 * slack;
    }

    // New-bin candidate handling: default penalty so we prefer reusing bins,
    // but allow opening a new bin when the fit in existing bins is bad
    // (large post residual = unusable leftover) or late in the stream with big items.
    if is_new_bin {
        let bad_fit_elsewhere = post_norm > 0.45 && fit_ratio > 0.4;
        let late_big = progress > 0.7 && fit_ratio > 0.5;
        let mut new_bin_score = 40.0; // base penalty
        if bad_fit_elsewhere { new_bin_score -= 20.0; }
        if late_big { new_bin_score -= 15.0; }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            new_bin_score -= 5.0; // fresh bin can host a follow-up item
        }
        score = new_bin_score + post_residual as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;
    let waste = pr / cap;
    let mut score = pr * (1.0 + 0.03 * waste * waste);

    let tightness = 1.0 + 2.5 * progress * progress + 2.3 * progress * progress * progress;
    score *= tightness;

    // COMBINED: dead-space quadratic penalty (from best) fused into base score
    let dead_ratio = (pr / cap).max(0.0);
    let unusable = if nx > 0.0 && pr > 0.0 && pr < nx { 1.0 } else { 0.55 };
    score += (10.5 + 3.2 * progress) * dead_ratio * dead_ratio * cap * (0.45 + progress) * unusable;
    if dead_ratio > 0.0 && dead_ratio < 0.12 {
        score -= 9.0 * (1.0 - dead_ratio / 0.12) * (0.4 + progress);
    }

    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let item_frac = (it / cap).min(1.0);
        let mut nb = cap * (1.35 + 1.15 * progress);
        nb -= 26.0 * scarcity * (1.0 - progress);
        nb -= 19.0 * item_frac * (1.0 - progress);
        if nx >= 0.5 * cap {
            nb -= 12.0 * progress + 6.0 * (1.0 - progress);
        }
        nb += 15.0 * progress * (1.0 - item_frac);
        if it >= cap - 1.0 {
            nb -= 32.0;
        }
        if nx > 0.0 && cap - it >= nx {
            nb -= 10.5 + 0.11 * (cap - it - nx);
        }
        if nx > 0.0 {
            let r1 = cap - it;
            if r1 >= nx && (r1 - nx) < 6.0 && (r1 - nx) > 0.0 {
                nb += 8.5 * (1.0 - progress);
            }
        }
        if fitting_bins_count <= 2 {
            nb += 21.0 + 10.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 4 {
            nb -= 6.5 + 8.5 * progress;
        }
        if nx > 0.0 && mean_residual > nx + 8.0 && progress < 0.7 {
            nb += 8.5 * ((mean_residual - nx) / cap).min(0.5) * cap * 0.1;
        }
        if mean_residual >= it && progress > 0.5 {
            nb += 6.5 + 8.5 * progress;
        }
        if nx > it && mean_residual >= nx && progress < 0.6 {
            nb += 10.0 * (1.0 - progress);
        }
        if nx > 0.0 && mean_residual >= it + nx && progress < 0.6 {
            nb -= 5.5 * (1.0 - progress) * ((mean_residual - it - nx) / cap).min(0.3) * 10.0;
        }
        if it > 0.85 * cap && progress > 0.3 {
            nb -= 9.0 * progress;
        }
        if nx > 0.0 && mean_residual > nx {
            let excess = mean_residual - nx;
            if excess < 0.05 * cap && progress < 0.55 {
                nb += 5.0 * (1.0 - excess / (0.05 * cap)) * (1.0 - progress);
            }
        }
        if fitting_bins_count == 0 && progress > 0.25 {
            nb += 9.0 + 7.0 * progress;
        }
        if nx > 0.0 && it + nx > cap && mean_residual >= nx {
            nb += 6.0 * (1.0 - progress);
        }
        if progress > 0.75 && fitting_bins_count > 0 && mean_residual >= it {
            nb += 5.5 + 4.5 * progress;
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_left = mean_residual - it;
            if best_left >= nx && (best_left - nx) < 12.0 {
                nb += 4.0 * (1.0 - (best_left - nx) / 12.0) * (0.5 + progress);
            }
        }
        if it < 0.2 * cap && progress < 0.3 && open_bins_count < 6 {
            nb += 7.0 * (1.0 - progress);
        }
        if item_frac > 0.6 && nx > 0.0 && cap >= it + nx && cap - it - nx < 0.03 * cap {
            nb -= 5.5 * (1.0 - (cap - it - nx) / (0.03 * cap));
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_pr = (mean_residual - it).max(0.0);
            if best_pr > 0.0 && best_pr < 0.06 * cap && (cap - it) >= nx {
                nb -= 7.0 * (1.0 - best_pr / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if progress > 0.85 && mean_residual < 0.15 * cap {
            nb += 7.0 * progress * (1.0 - mean_residual / (0.15 * cap));
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_post = (mean_residual - it).max(0.0);
            if best_post >= nx && best_post - nx > 0.18 * cap && progress > 0.35 {
                nb -= 6.0 * ((best_post - nx) / cap).min(0.4) * (0.4 + progress);
            }
        }
        if item_frac > 0.45 && item_frac < 0.75 && progress > 0.5 {
            nb -= 5.0 * (item_frac - 0.45) * progress;
        }
        if fitting_bins_count >= 2 && mean_residual < 0.25 * cap && progress > 0.6 {
            nb += 6.0 * (1.0 - mean_residual / (0.25 * cap)) * progress;
        }
        if fitting_bins_count >= 3 && mean_residual - it >= nx && progress > 0.5 {
            nb += 4.5 * progress * (1.0 - ((mean_residual - it - nx) / cap).min(1.0));
        }
        if open_bins_count > 10 && progress < 0.35 && item_frac < 0.3 {
            nb += 6.0 * (1.0 - progress) * (1.0 - item_frac / 0.3);
        }
        if nx > 0.0 {
            let r1 = cap - it;
            if r1 < nx && r1 > 0.0 {
                nb += (1.0 + 2.0 * progress) * (nx - r1) * 0.55;
            }
            if r1 >= nx && (r1 - nx) > 0.25 * cap && progress > 0.45 {
                nb += 4.5 * ((r1 - nx) / cap).min(0.5) * progress;
            }
        }
        if nx > 0.0 && cap >= it + nx && (cap - it - nx) < 0.08 * cap && progress > 0.3 {
            nb -= 5.0 * (1.0 - (cap - it - nx) / (0.08 * cap)) * (0.5 + progress);
        }
        // COMBINED from best: fragmented open-bin pool discourages new bins
        if open_bins_count > 6 && mean_residual > 0.4 * cap && progress < 0.6 {
            nb += 5.0 * ((mean_residual - 0.4 * cap) / cap) * (1.0 - progress) * ((open_bins_count as f64 - 6.0).min(8.0) / 8.0);
        }
        // COMBINED: tight two-item chain in fresh bin
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin < 0.15 * cap {
                nb -= 6.0 * (1.0 - margin / (0.15 * cap)) * (0.6 + 0.4 * progress);
            }
        }
        score = nb;
    } else {
        // Fine-grained residual fitting with lookahead anticipation
        let fill_ratio = 1.0 - res / cap;
        if waste < 0.08 {
            score -= 48.0 * (1.0 - progress) * (0.08 - waste);
        }
        if fill_ratio > 0.65 {
            score -= 4.8 * (fill_ratio - 0.65) * 10.0 * (0.4 + progress);
        }
        if nx > 0.0 && nx <= pr && pr > 0.0 {
            let gap = (pr - nx) / cap;
            if gap < 0.03 {
                score -= 7.5 * (1.0 - gap * 33.0);
            }
            if gap <= 0.04 {
                score -= 3.2 * (1.0 - gap / 0.04) * (1.0 - progress);
            }
            let chain = 1.0 - gap.min(1.0);
            score -= 5.0 + 4.0 * (nx / cap) + 9.5 * chain * (1.0 - progress);
        }
        if pr > 0.0 && pr < 10.0 {
            score += 41.0 * (1.0 - 0.5 * progress);
        }
        if pr == 0.0 {
            score -= 62.0;
        } else if pr <= 5.0 {
            score -= 31.0 * (1.0 - 0.4 * progress);
        }
        if nx > 0.0 && pr > 0.0 && pr < nx {
            let gap = nx - pr;
            score += gap * (2.0 + 6.5 * (1.0 - progress));
            if gap <= 3.0 {
                score -= 9.0 * (1.0 - progress);
            }
            let closeness = 1.0 - pr / nx;
            score += 3.0 * closeness * closeness * (0.6 + progress);
        }
        let dev = mean_residual - res;
        score += 0.085 * dev;
        if dev > -5.0 && dev < 15.0 && pr > 0.0 {
            score -= 4.2;
        }
        let tight_fit = (pr == 0.0) || (nx > 0.0 && pr == nx);
        if tight_fit {
            score -= 10.5 * (0.3 + progress);
        }
        if nx > 0.0 && pr >= nx {
            let room = pr - nx;
            if room < 0.06 * cap {
                score -= 6.5 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if waste > 0.14 && waste < 0.34 {
            score += 13.0 * (waste - 0.14) * (0.6 + 0.8 * progress);
        }
        if fitting_bins_count > 3 && waste < 0.12 {
            score -= 5.5 * (1.0 - waste * 8.0) * (0.5 + progress);
        }
        if nx > 0.0 && pr > 0.0 && pr > nx && (pr - nx) < 0.02 * cap {
            score -= 4.0 * (1.0 - (pr - nx) / (0.02 * cap)) * (0.4 + progress);
        }
        if pr > 0.0 && (pr as f64).sqrt() < 2.6 {
            score -= 3.5 * (1.0 - progress);
        }
        if waste > 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.09 * cap && progress > 0.4 {
            score -= 4.0 * (1.0 - (pr - nx) / (0.09 * cap)) * progress;
        }
        if pr > 0.0 && nx > 0.0 && pr < nx && (nx - pr) > 0.1 * cap && waste > 0.25 {
            score += 5.0 * (waste - 0.25) * 10.0 * (0.4 + progress);
        }
        if pr > 0.0 && nx > 0.0 && pr < 0.5 * nx && progress > 0.3 {
            score += 3.5 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
        }
        if waste > 0.3 && pr > nx && progress < 0.5 {
            score += 3.0 * (waste - 0.3) * 10.0 * (1.0 - progress);
        }
        if fill_ratio > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
            score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
        }
        if waste > 0.35 && progress > 0.55 && nx > 0.0 && pr >= nx {
            score -= 4.5 * ((pr - nx) / cap).min(0.2) * 5.0 * progress;
        }
        // Scarcity: prefer using existing bins when few can fit
        if fitting_bins_count == 1 {
            score -= 14.0 + 12.0 * progress;
        } else if fitting_bins_count == 2 {
            score -= 4.0 + 3.0 * progress;
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64 / cap;
    let it = item_size as f64 / cap;

    // Base: penalize post residual, with non-linear (quadratic/cubic) shaping
    let mut score = pr * (1.0 + 2.0 * pr * pr);

    // Smooth coupling: residual penalty relaxes as stream progresses
    score *= 1.0 - 0.5 * progress;

    // Reward tight fits (small post_residual) more strongly later in stream
    score -= (1.0 - pr).powi(3) * (1.0 + progress) * 10.0;

    // Penalize dead space that cannot fit a plausible next item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        if pr < nx && pr > 0.0 {
            score += (nx - pr) * 15.0 * (1.0 - progress);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 10.0 * progress;
    }

    // Mild penalty for spreading across too many open bins
    score += open_bins_count as f64 * 0.05 * pr;

    // Coupling with mean residual: prefer bins deviating from mean when tight
    score += (mean_residual - bin_residual as f64).abs() / cap * 2.0 * (1.0 - it);

    // New-bin candidate: neutral-ish baseline, penalized unless current bin fit is bad
    if bin_residual == bin_capacity {
        score = 8.0 + 12.0 * progress + 0.5 * open_bins_count as f64;
        if fitting_bins_count == 1 {
            score += 30.0; // discourage opening new bin when only one fits
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but reward "usable" residuals.
    // Harmonic classes: residuals divisible by small classes (5,10,20) are more
    // likely to host future items drawn from an unknown integer distribution.
    if post_residual > 0 {
        let pr = post_residual;
        if pr % 10 == 0 {
            score -= 6.0;                       // perfect harmonic class
        } else if pr % 5 == 0 {
            score -= 3.0;
        } else if pr % 20 == 0 {
            score -= 7.0;
        }
        // Dead-space penalty: residuals below the minimum plausible item size
        // (small classes) are near-unusable.
        if pr < 5 {
            score += 12.0;
        } else if pr < 10 {
            score += 6.0;
        }
        // Integer-division threshold ladder: residuals in [10,30] are prime
        // targets for medium items; [31,60] for large ones.
        let class = pr / 10; // 0..=10
        score -= (class as f64) * 0.8;      // mildly prefer larger leftovers
        // Non-linear coupling: penalize the awkward band 60..70 (fits few sizes)
        if pr >= 60 && pr < 70 {
            score += 4.0;
        }
    } else {
        score -= 10.0; // perfect fill
    }

    // Lookahead: if the next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            // partial compatibility, scaled by how much slack remains
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / bin_capacity as f64);
            if post_residual % next_item_size.max(1) == 0 {
                score -= 3.0; // harmonic divisibility with lookahead
            }
        } else {
            // next item won't fit here: slight penalty for wasting lookahead
            score += 2.0;
        }
    } else {
        // last item of the stream: any residual is pure waste
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 14.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // are genuinely poor hosts. Penalize the empty bin by its would-be waste
    // (capacity - item_size), plus a mild inertia term scaled by stream progress.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += waste * 0.6;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 3.0 * (1.0 - progress);           // early stream: prefer reusing
        score += (open_bins_count.min(20) as f64) * 0.4; // many open bins: reuse them
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0; // fresh bin can host the lookahead too
        }
    }

    // Contextual coupling with mean residual: if this bin is far below the mean,
    // it is the "emptiest" — using it consolidates open bins.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= diff.min(50.0) * 0.15;
    } else {
        score += (-diff).min(50.0) * 0.10;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item are pure waste — penalize them heavily.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // overflow guard; shouldn't happen for valid fits
    }
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 12.0; // tiny unusable gap
    } else if post_residual < 20 {
        score += 18.0; // small gap, likely dead space
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score -= 25.0 / (1.0 + tightness);
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, avoid fragmenting further;
    // with few open bins, prefer spreading to keep flexibility.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += pressure * post_residual as f64 * 0.5;
    score -= pressure * 5.0 * (fitting_bins_count as f64).recip().min(1.0);

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when
    // the item fits poorly everywhere (large post_residual in existing bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let threshold = 25.0 + 25.0 * (1.0 - progress);
        if post_residual as f64 > threshold {
            score -= 45.0; // fresh bin is attractive for big items
        } else {
            score += 30.0; // discourage opening bins for easy fits
        }
    }

    // Lookahead: if next item could use the post_residual, reward leaving it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 {
        score += 8.0; // next item won't fit the leftover — dead space risk
    }

    // Mean residual coupling: bins far below the mean residual are good
    // consolidation targets.
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;
    let urgency = progress * progress * (3.0 - 2.0 * progress);
    let is_new_bin = res >= cap - 0.5;

    // ---- Existing-bin score (borrowed tight-packing structure) ----
    let mut score = pr * (1.0 + 0.03 * (pr / cap) * (pr / cap));
    let tightness = 1.0 + 2.6 * urgency * urgency + 2.4 * urgency * urgency * urgency;
    score *= tightness;

    // Lookahead chain logic
    if nx > 0.0 {
        if pr < nx {
            let gap = nx - pr;
            score += gap * (2.0 + 6.5 * (1.0 - progress));
            if gap <= 0.04 * cap {
                score += 3.5 * (1.0 - gap / (0.04 * cap)) * (0.5 + progress);
            }
        } else {
            let chain_gap = pr - nx;
            let slack = chain_gap / cap;
            if chain_gap <= 42.0 {
                score -= 6.5 + 0.11 * chain_gap;
            }
            if slack < 0.04 {
                score -= 8.5 * (1.0 - slack * 25.0) * (1.0 + progress);
            }
            let chain = 1.0 - slack.min(1.0);
            score -= 5.0 + 4.0 * (nx / cap) + 9.5 * chain * (1.0 - progress);
        }
    }

    // Dead-space penalty, scaled by unusability
    let dead_ratio = (pr / cap).max(0.0);
    let unusable = if nx > 0.0 && pr > 0.0 && pr < nx { 1.0 } else { 0.55 };
    score += (10.5 + 3.2 * progress) * dead_ratio * dead_ratio * cap * (0.45 + progress) * unusable;

    // Sweet-spot: near-perfect fits
    if dead_ratio > 0.0 && dead_ratio < 0.12 {
        score -= 9.0 * (1.0 - dead_ratio / 0.12) * (0.4 + progress);
    }
    if pr == 0.0 {
        score -= 62.0;
    } else if pr <= 5.0 {
        score -= 31.0 * (1.0 - 0.4 * progress);
    }

    // Scarcity bonus
    if fitting_bins_count == 1 {
        score -= 1.5 + 2.5 * progress;
    } else if fitting_bins_count > 1 {
        score -= 0.3 / fitting_bins_count as f64;
    }

    // Mean-residual deviation pull (favors bins near the packable frontier)
    let dev = mean_residual - res;
    score += 0.085 * dev;
    if dev > -5.0 && dev < 15.0 && pr > 0.0 {
        score -= 4.2;
    }

    // Room-for-next bonus
    if nx > 0.0 && pr >= nx {
        let room = pr - nx;
        if room < 0.06 * cap {
            score -= 6.5 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
        }
    }

    // Mid-range waste penalty
    if dead_ratio > 0.14 && dead_ratio < 0.34 {
        score += 13.0 * (dead_ratio - 0.14) * (0.6 + 0.8 * progress);
    }

    score -= 0.42 * (open_bins_count as f64).ln().max(0.0);

    // ---- New-bin candidate ----
    if is_new_bin {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let item_frac = (it / cap).min(1.0);
        let mut nb = cap * (1.35 + 1.15 * progress);
        nb -= 26.0 * scarcity * (1.0 - progress);
        nb -= 19.0 * item_frac * (1.0 - progress);
        if nx >= 0.5 * cap {
            nb -= 12.0 * progress + 6.0 * (1.0 - progress);
        }
        nb += 15.0 * progress * (1.0 - item_frac);
        if it >= cap - 1.0 {
            nb -= 32.0;
        }
        if nx > 0.0 && cap - it >= nx {
            nb -= 10.5 + 0.11 * (cap - it - nx);
