            nb += 8.5 * ((mean_residual - nx) / cap).min(0.5) * cap * 0.1;
        }
        if mean_residual >= it && progress > 0.5 {
            nb += 6.5 + 8.5 * progress;
        }
        if nx > it && mean_residual >= nx && progress < 0.6 {
            nb += 10.0 * (1.0 - progress);
        }
        if nx > 0.0 && mean_residual >= it + nx && progress < 0.6 {
            nb -= 5.5 * (1.0 - progress) * ((mean_residual - it - nx) / cap).min(0.3) * 10.0;
        }
        if it > 0.85 * cap && progress > 0.3 {
            nb -= 9.0 * progress;
        }
        if fitting_bins_count == 0 && progress > 0.25 {
            nb += 9.0 + 7.0 * progress;
        }
        if nx > 0.0 && it + nx > cap && mean_residual >= nx {
            nb += 6.0 * (1.0 - progress);
        }
        if progress > 0.75 && fitting_bins_count > 0 && mean_residual >= it {
            nb += 5.5 + 4.5 * progress;
        }
        if it < 0.2 * cap && progress < 0.3 && open_bins_count < 6 {
            nb += 7.0 * (1.0 - progress);
        }
        if open_bins_count > 10 && progress < 0.35 && item_frac < 0.3 {
            nb += 6.0 * (1.0 - progress) * (1.0 - item_frac / 0.3);
        }
        if nx > 0.0 && cap >= it + nx && (cap - it - nx) < 0.08 * cap && progress > 0.3 {
            nb -= 5.0 * (1.0 - (cap - it - nx) / (0.08 * cap)) * (0.5 + progress);
        }
        if item_frac < 0.15 && progress > 0.55 && fitting_bins_count >= 1 {
            nb += 6.0 * progress * (1.0 - item_frac / 0.15);
        }
        // Mutation: aggregate-space guard — don't open bins when mean residual is generous
        nb += 0.35 * (mean_residual / cap).min(1.0) * (open_bins_count as f64).sqrt() * 2.0;
        score = nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> chain fills exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Next item fits too, but leaves a new gap; penalize leftover gap size.
            let gap = (post_residual - next_item_size) as f64;
            score -= 10.0 - gap * 0.15;
        }
        // If next item cannot fit, this bin's residual is likely dead space.
        if post_residual < next_item_size && post_residual > 0 {
            score += (post_residual as f64) * 0.3;
        }
    } else {
        // Last item: prefer minimal residual.
        score += 5.0;
    }

    // Exact fit of current item.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize creating small unusable slivers (dead space below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score -= (mean_residual - post_residual as f64) * 0.2;

    // Late in the stream, prefer closing bins (fewer open bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.05 * progress;

    // Slight bias toward using existing bins over opening new ones.
    if bin_residual == bin_capacity {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly favor bins whose post residual is small.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that no future item (10..80 range) can fill well.
    if post_residual > 0 && post_residual < 10 {
        score -= 12.0; // perfectly dead small gap is fine if unavoidable
    } else if post_residual >= 10 {
        // residual that still fits typical items is reusable
        score -= 8.0;
    } else {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            score += 5.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is expensive unless the item fits
    // poorly everywhere. Penalize the empty-bin candidate moderately.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.3 * open_bins_count as f64;
        // But late in the stream, waste in old bins matters less; allow new bins more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress;
        // If mean residual is large, open bins have slack; discourage new bin.
        score += 0.15 * mean_residual;
        // If item is large relative to capacity, a fresh bin is actually good.
        if item_size > bin_capacity / 2 {
            score -= 18.0;
        }
    }

    // Slight preference for bins below mean residual (balance load, keep big gaps open).
    if bin_residual != bin_capacity {
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Time horizon: early in stream, keep bins flexible (avoid tiny residuals);
    // late in stream, greedily minimize post_residual.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.10 * post_residual as f64;
    score -= progress * 0.10 * post_residual as f64;

    score
}

