            score -= 2.8 * (1.0 - (pr - nx) / (0.5 * nx)) * progress;
        }
        // Scarcity: prefer using existing bins when few can fit
        if fitting_bins_count == 1 {
            score -= 14.0 + 12.0 * progress;
        } else if fitting_bins_count == 2 {
            score -= 4.0 + 3.0 * progress;
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 3.0 * progress * (1.0 - progress));
    score += 8.0 * poly;
    // Reward tight fits more aggressively as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (10.0 + 20.0 * progress);
    // Penalize dead space relative to mean residual
    score += 0.15 * (pr - mean_residual).abs() * (1.0 + progress);
    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }
    // Lookahead: favor bins whose post residual fits next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0 * (1.0 - progress);
        } else {
            score += 3.0 * (1.0 - norm_pr);
        }
    }
    // Penalize opening new bins when open bins exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 20.0 + 30.0 * progress * (1.0 - progress);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;
    let mut score = pr * (1.0 + 0.03 * (pr / cap) * (pr / cap));

    let tightness = 1.0 + 2.5 * progress * progress + 2.3 * progress * progress * progress;
    score *= tightness;

    if nx > 0.0 {
        if pr < nx {
            let gap = nx - pr;
            score += gap * (2.0 + 6.2 * (1.0 - progress));
        } else {
            let chain_gap = pr - nx;
            let slack = chain_gap / cap;
            if chain_gap <= 41.0 {
                score -= 6.2 + 0.105 * chain_gap;
            }
            if slack < 0.04 {
                score -= 8.2 * (1.0 - slack * 25.0) * (1.0 + progress);
            }
            let chain = 1.0 - slack.min(1.0);
            score -= 5.0 + 4.0 * (nx / cap) + 9.2 * chain * (1.0 - progress);
        }
    }

    // Dead-space penalty with lookahead-aware "unusable" weighting
    let dead_ratio = (pr / cap).max(0.0);
    let unusable = if nx > 0.0 && pr > 0.0 && pr < nx { 1.0 } else { 0.55 };
    score += (10.2 + 3.0 * progress) * dead_ratio * dead_ratio * cap * (0.45 + progress) * unusable;
    if dead_ratio > 0.25 && dead_ratio < 0.6 {
        score += 4.5 * (dead_ratio - 0.25) * (0.5 + progress);
    }
    // Reward very small residuals (near-perfect compaction)
    if dead_ratio > 0.0 && dead_ratio < 0.12 {
        score -= 9.0 * (1.0 - dead_ratio / 0.12) * (0.4 + progress);
    }

    if fitting_bins_count == 1 {
        score -= 14.0 + 12.0 * progress;
    } else if fitting_bins_count == 2 {
        score -= 4.0 + 3.0 * progress;
    }

    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let item_frac = (it / cap).min(1.0);
        let mut nb = cap * (1.35 + 1.12 * progress);
        nb -= 26.0 * scarcity * (1.0 - progress);
        nb -= 18.5 * item_frac * (1.0 - progress);
        if nx >= 0.5 * cap {
            nb -= 12.0 * progress + 6.0 * (1.0 - progress);
        }
        nb += 15.0 * progress * (1.0 - item_frac);
        if it >= cap - 1.0 {
            nb -= 31.0;
        }
        if nx > 0.0 && cap - it >= nx {
            nb -= 10.2 + 0.105 * (cap - it - nx);
        }
        if fitting_bins_count <= 2 {
            nb += 20.5 + 10.0 * (1.0 - progress);
        }
        if nx > 0.0 && mean_residual > nx + 8.0 && progress < 0.7 {
            nb += 8.2 * ((mean_residual - nx) / cap).min(0.5) * cap * 0.1;
