        if nx > 0.0 && cap >= it + nx && (cap - it - nx) < 0.08 * cap && progress > 0.3 {
            nb -= 5.0 * (1.0 - (cap - it - nx) / (0.08 * cap)) * (0.5 + progress);
        }
        if mean_residual >= it + nx && progress < 0.6 {
            nb -= 5.5 * (1.0 - progress) * ((mean_residual - it - nx) / cap).min(0.3) * 10.0;
        }
        if progress > 0.75 && fitting_bins_count > 0 && mean_residual >= it {
            nb += 5.5 + 4.5 * progress;
        }
        score = nb;
    } else {
        let fill_ratio = 1.0 - res / cap;
        let waste = pr / cap;

        if waste < 0.08 {
            score -= 48.0 * (1.0 - progress) * (0.08 - waste);
        }
        if fill_ratio > 0.65 {
            score -= 4.6 * (fill_ratio - 0.65) * 10.0 * (0.4 + progress);
        }
        if nx > 0.0 && nx <= pr && pr > 0.0 {
            let gap = (pr - nx) / cap;
            if gap < 0.03 {
                score -= 7.2 * (1.0 - gap * 33.0);
            }
        }

        if pr > 0.0 && pr < 10.0 {
            score += 40.0 * (1.0 - 0.5 * progress);
        }
        if pr == 0.0 {
            score -= 61.0;
        } else if pr <= 5.0 {
            score -= 30.0 * (1.0 - 0.4 * progress);
        }
        if nx > 0.0 && pr > 0.0 && pr < nx {
            score += 6.2 + 2.0 * progress;
            if nx - pr <= 3.0 {
                score -= 9.0 * (1.0 - progress);
            }
        }

        let dev = mean_residual - res;
        score += 0.082 * dev;
        if dev > -5.0 && dev < 15.0 && pr > 0.0 {
            score -= 4.1;
        }

        let tight_fit = (pr == 0.0) || (nx > 0.0 && pr == nx);
        if tight_fit {
            score -= 10.2 * (0.3 + progress);
        }

        if nx > 0.0 && pr >= nx {
            let room = pr - nx;
            if room < 0.06 * cap {
                score -= 6.2 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
            }
        }

        // Mid-range waste penalty (dead space control)
        if waste > 0.14 && waste < 0.34 {
            score += 13.0 * (waste - 0.14) * (0.6 + 0.8 * progress);
        }
        // Prefer bins that still fit next item when waste is low
        if fitting_bins_count > 3 && waste < 0.12 {
            score -= 5.5 * (1.0 - waste * 8.0) * (0.5 + progress);
        }
        // Near-exact chain fit
        if nx > 0.0 && pr > nx && (pr - nx) < 0.02 * cap {
            score -= 4.0 * (1.0 - (pr - nx) / (0.02 * cap)) * (0.4 + progress);
        }
        // Small residual slivers are hard to reuse
        if pr > 0.0 && (pr as f64).sqrt() < 2.6 {
            score -= 3.5 * (1.0 - progress);
        }
        if waste > 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.09 * cap && progress > 0.4 {
            score -= 4.0 * (1.0 - (pr - nx) / (0.09 * cap)) * progress;
        }
        if pr > 0.0 && nx > 0.0 && pr < 0.5 * nx && progress > 0.3 {
            score += 3.5 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
        }
        if fill_ratio > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
            score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
        }
        if nx > 0.0 && pr > nx && (pr - nx) <= 0.04 * cap {
            score -= 3.2 * (1.0 - (pr - nx) / (0.04 * cap)) * (1.0 - progress);
        }

        score -= 0.41 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction band does it fall in?
    // Residuals divisible by large powers/classes are more "usable" by future items.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Reward exact harmonic fits: post_residual in {0, 10, 20, 25, 50} are ideal states.
    let harmonic = pr == 0 || pr == 10 || pr == 20 || pr == 25 || pr == 50;
    if harmonic {
        score -= 12.0;
    }

    // Dead-space penalty: tiny unusable residuals (1..=9) are wasted capacity.
    if pr > 0 && pr < 10 {
        score += 18.0;
    }

    // Modulo-10 classes: residuals that are multiples of 10 pair well with
    // item sizes drawn from wide ranges; odd/prime residuals are awkward.
    if pr % 10 == 0 && pr > 0 {
        score -= 5.0;
    } else if pr % 10 != 0 && pr > 0 {
        score += 3.0;
    }

    // Integer-division threshold on post_residual: quarter-capacity bands.
    let quarter = (bin_capacity / 4) as f64;
    if (pr as f64) < quarter {
        // Bin nearly full: good, but only if the leftover is still reachable.
        score -= 4.0;
        if pr > 0 && next_item_size > pr {
            score += 10.0; // leftover can't host the lookahead item: dead end
        }
    } else if (pr as f64) < quarter * 2.0 {
        score -= 1.0;
    } else {
        // Leaving more than half a bin: wasteful unless bin was already empty.
        if bin_residual != bin_capacity {
            score += 6.0;
        }
    }

    // Lookahead coupling: harmonic match between post_residual and next item.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0; // perfect chain fit
        } else if pr >= next_item_size && (pr - next_item_size) % 10 == 0 {
            score -= 8.0; // chain leaves another harmonic residual
        } else if pr >= next_item_size && (pr - next_item_size) < 10 && pr != next_item_size {
            score += 7.0; // chain creates sub-10 dead space
        }
    }

    // Last-chance bin: strongly prefer using the final fitting bin over opening new.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: opening a bin is only attractive when no good harmonic
    // state exists among open bins (mean residual already fragmented).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        if fitting_bins_count > 0 {
            // Prefer existing bins unless they're all badly fragmented.
            let fragmentation = (mean_residual / cap).abs();
            if fragmentation < 0.35 {
                score += 25.0;
            } else {
                score += 8.0;
            }
        } else {
            score -= 10.0;
        }
        // Late in the stream, consolidating is better than spawning bins.
        score += progress * 10.0;
        // If the lookahead item also fits a fresh 100, new bin chains well.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0;
        }
    }

    // Mild pressure to prefer fuller bins when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item
    // (1..10) are pure waste; penalize them heavily and progressively.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Awkward gap: only small items can use it, mild penalty.
        score += (20 - post_residual) as f64 * 2.0;
    }

    // Perfect fit bonus: exact fill or leaving room exactly for the next item.
    if post_residual == 0 {
        score -= 50.0;
    } else if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward gaps that can still host the lookahead item.
        score -= 10.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a
    // new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + (post_residual as f64).min(20.0);
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; a brand-new empty bin (residual == capacity) is
    // penalized so it only wins when all fits create dead space.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 3.0;
        // Late in the stream, new bins are even less desirable.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Mild tie-break: prefer bins whose residual is already below average
    // (tighter bins), keeping looser bins for larger future items.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    score
}

