pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Two-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            let gap = post_residual as f64 - next;
            // Reward tight 2-step chains (post_residual == next_item_size => perfect chain)
            if gap < 1.0 {
                score -= 400.0;
            } else if gap <= 10.0 {
                score -= 150.0 * (1.0 - gap / 10.0);
            } else {
                score -= 50.0 * (1.0 - (gap / post_residual as f64).min(1.0));
            }
        } else {
            // Next item cannot use this bin's leftover: penalize dead space
            score += 60.0 * (1.0 - post_residual as f64 / next);
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    if mean_residual > 0.0 {
        let rel = (bin_residual as f64 - mean_residual) / mean_residual;
        score += 30.0 * rel.max(-2.0).min(2.0);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize new-bin candidate unless current bins are bad fits
    if bin_residual == bin_capacity {
        score += 120.0 + 2.0 * open_bins_count as f64;
        // But allow opening when next item would chain into a fresh bin
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 80.0;
        }
    }

    // Late-stream: be less picky, close out bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 50.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 5.0;
        }
        // Perfect chain: item + next item exactly fills this bin.
        if item_size + next_item_size == bin_residual {
            score -= 20.0;
        }
    }

    // New-bin candidate logic: opening a bin is attractive early or when
    // existing bins would leave very poor fits, but wasteful when many
    // bins are already open with slack capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_slack = mean_residual / (bin_capacity as f64).max(1.0);
        let mut new_bin_score = 25.0;
        // Early stream: opening is cheap; late stream: prefer consolidation.
        new_bin_score += 20.0 * progress;
        // Many open bins with slack: discourage opening another.
        new_bin_score += 0.8 * open_bins_count as f64 * avg_slack;
        // Poor fits elsewhere (large mean residual wasted): encourage opening.
        new_bin_score -= 15.0 * avg_slack;
        // Big items early benefit from fresh bins.
        if item_size > bin_capacity / 2 && progress < 0.3 {
            new_bin_score -= 10.0;
        }
        score = new_bin_score + post_residual as f64;
    }

    // Mild global pressure: when many bins are open, favor filling existing ones.
    score += 0.15 * open_bins_count as f64 * (bin_residual != bin_capacity) as i32 as f64;

    // Slight time decay on residual penalty: later in stream, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 2.0;

    score
}

