            score += 3.5 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
        }
        if waste > 0.3 && pr > nx && progress < 0.5 {
            score += 3.0 * (waste - 0.3) * 10.0 * (1.0 - progress);
        }
        if fill_ratio > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
            score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
        }
        if waste > 0.35 && progress > 0.55 && nx > 0.0 && pr >= nx {
            score -= 4.5 * ((pr - nx) / cap).min(0.2) * 5.0 * progress;
        }
        if fitting_bins_count == 1 {
            score -= 14.0 + 12.0 * progress;
        } else if fitting_bins_count == 2 {
            score -= 4.0 + 3.0 * progress;
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer small post residual (tight fit), with smooth non-linear shaping
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post residual with stream progress:
    // early on, mildly prefer leaving moderate space (flexibility);
    // late in the stream, punish large residuals more strongly (dead space).
    let flex = x * (1.0 - x); // peaks at x = 0.5 (mid-size leftover)
    score -= 12.0 * flex * (1.0 - progress);           // early: reward mid residuals
    score += 20.0 * x * x * (0.5 + progress);          // late: quadratic penalty on big leftovers

    // Lookahead coupling: reward post residual that still fits the next item,
    // scaled by smooth progress-based urgency.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as u32 >= next_item_size {
            let room = (pr as u32 - next_item_size) as f64 / cap;
            score -= 6.0 * (1.0 - room * room) * (0.3 + 0.7 * progress);
        } else {
            // post residual too small for next item: dead space penalty, smooth in gap size
            let gap = (nx - pr) / cap;
            score += 8.0 * gap * gap * (1.0 + progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit would be terrible (smooth quadratic guard).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let bad = (x - 0.1).max(0.0);
        score -= 15.0 * (1.0 - bad * bad * 4.0).max(0.0);
    }

    // New-bin candidate: score relative to mean residual state; slightly discourage
    // proliferation when existing bins still have room, more so early in the stream.
    if bin_residual == bin_capacity {
        score += 4.0 + 0.05 * open_bins_count as f64 * (1.0 - progress) - 10.0 * (mean_residual / cap) * (1.0 - progress);
    }

    // Tie-breaking smooth coupling with item size: prefer placing larger items tightly.
    score -= (item_size as f64 / cap) * (pr as f64 / cap) * 4.0;

    score
}

