        } else if fitting_bins_count == 2 {
            score -= 4.0 + 3.0 * progress;
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "nice" residue classes (multiples of 10, 25, 50) are more reusable.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit, always reward strongly
    } else if pr % 50 == 0 {
        -25.0
    } else if pr % 25 == 0 {
        -18.0
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -6.0
    } else {
        8.0 // awkward residue: dead-space penalty
    };
    score += class_bonus;

    // Dead-space danger: small leftovers (<10) are nearly unusable.
    if pr > 0 && pr < 10 {
        score += 30.0;
    }

    // Lookahead coupling: does the leftover accommodate the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // Harmonic check: exact / coarse class match with next item
            let diff = pr - next_item_size;
            if diff == 0 {
                score -= 20.0;
            } else if diff % 10 == 0 {
                score -= 10.0;
            } else if diff < 10 {
                score += 10.0; // creates tiny dead space after next item
            } else {
                score -= 4.0;
            }
        } else {
            // next item won't fit here regardless; slight penalty for tight bin
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / bin_capacity as f64;
        // Base penalty so a fresh bin is chosen only for large items / poor fits.
        let mut nb = 45.0;
        nb += 40.0 * (1.0 - crowding); // crowded open bins -> cheaper to open new
        if item_size >= 60 {
            nb -= 25.0;
        }
        if open_bins_count == 0 {
            nb -= 100.0;
        }
        nb -= 10.0 * progress;
        score += nb;
    }

    // Mild preference for tighter bins overall.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Small exploration term keyed to stream position and open-bin count.
    score += 0.001 * ((step_index % 7) as f64) * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;

    let mut score = pr * (1.0 + 0.03 * (pr / cap) * (pr / cap));

    let tightness = 1.0 + 2.6 * progress * progress + 2.4 * progress * progress * progress;
    score *= tightness;

    if nx > 0.0 {
        if pr < nx {
            let gap = nx - pr;
            score += gap * (1.8 + 6.0 * (1.0 - progress));
            if gap <= 3.0 {
                score -= 9.0 * (1.0 - progress);
            }
            if gap <= 0.04 * cap {
                score += 3.5 * (1.0 - gap / (0.04 * cap)) * (0.5 + progress);
            }
        } else {
            let chain_gap = pr - nx;
            let slack = chain_gap / cap;
            if chain_gap <= 42.0 {
                score -= 6.5 + 0.11 * chain_gap;
            }
            if slack < 0.04 {
                score -= 8.5 * (1.0 - slack * 25.0) * (1.0 + progress);
            }
            let chain = 1.0 - slack.min(1.0);
            score -= 5.0 + 4.0 * (nx / cap) + 9.5 * chain * (1.0 - progress);
            if chain_gap > 0.04 * cap && chain_gap < 0.18 * cap {
                score -= 2.2 * (1.0 - chain_gap / (0.18 * cap)) * (0.3 + progress);
            }
        }
    }

    if pr == 0.0 {
        score -= 62.0;
    } else if pr <= 5.0 {
        score -= 31.0 * (1.0 - 0.4 * progress);
    } else if pr < 10.0 {
        score += 41.0 * (1.0 - 0.5 * progress);
    }

    let dead_ratio = (pr / cap).max(0.0);
    let unusable = if nx > 0.0 && pr > 0.0 && pr < nx { 1.0 } else { 0.55 };
    score += (10.5 + 3.2 * progress) * dead_ratio * dead_ratio * cap * (0.45 + progress) * unusable;
    if dead_ratio > 0.0 && dead_ratio < 0.12 {
        score -= 9.0 * (1.0 - dead_ratio / 0.12) * (0.4 + progress);
    }
    if dead_ratio > 0.12 && dead_ratio < 0.3 {
        score += 3.5 * (dead_ratio - 0.12) * (0.5 + progress);
    }

    if bin_residual < bin_capacity {
        let dev = mean_residual - res;
        score += 0.085 * dev;
        if dev > -5.0 && dev < 15.0 && pr > 0.0 {
            score -= 4.2;
        }
        let fill_ratio = 1.0 - res / cap;
        let waste = pr / cap;
        if waste < 0.08 {
            score -= 48.0 * (1.0 - progress) * (0.08 - waste);
        }
        if fill_ratio > 0.65 {
            score -= 4.8 * (fill_ratio - 0.65) * 10.0 * (0.4 + progress);
        }
        if waste > 0.14 && waste < 0.34 {
            score += 13.0 * (waste - 0.14) * (0.6 + 0.8 * progress);
        }
        if fitting_bins_count > 3 && waste < 0.12 {
            score -= 5.5 * (1.0 - waste * 8.0) * (0.5 + progress);
        }
        if nx > 0.0 && pr > 0.0 && pr >= nx {
            let room = pr - nx;
            if room < 0.06 * cap {
                score -= 6.5 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if nx > 0.0 && pr > 0.0 && pr < nx {
            let closeness = 1.0 - pr / nx;
            score += 3.0 * closeness * closeness * (0.6 + progress);
        }
        if fitting_bins_count == 1 {
            score -= 14.0 + 12.0 * progress;
        } else if fitting_bins_count == 2 {
            score -= 4.0 + 3.0 * progress;
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
        let tight_fit = (pr == 0.0) || (nx > 0.0 && pr == nx);
        if tight_fit {
            score -= 10.5 * (0.3 + progress);
        }
    }

    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let item_frac = (it / cap).min(1.0);
        let mut nb = cap * (1.35 + 1.15 * progress);
