pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 20.0;

    // Penalize wasted capacity relative to bin residual (dead space ratio).
    let waste_ratio = (bin_residual - post_residual) as f64 / bin_residual.max(1) as f64;
    score -= waste_ratio * 15.0;

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + (next_item_size as f64 / post_residual.max(1) as f64) * 10.0;
    } else if next_item_size > 0 {
        // Penalize leaving a gap that blocks the next item, scaled by gap size.
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score += gap * 0.3;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Crowding effect: many open bins -> prefer consolidating into existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln() * 2.0 * (0.5 + progress);

    // Global residual balance: prefer bins whose residual is near the mean (keeps pool uniform).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05 * (1.0 - progress);

    // Late in the stream, be more greedy about exact fills.
    if progress > 0.7 {
        score -= (bin_capacity - post_residual) as f64 * 0.05;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 6.0;
        // But a new bin is attractive if the item is huge and fits poorly elsewhere.
        if item_size > bin_capacity * 3 / 4 && fitting_bins_count <= 2 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 3.0;
        }
    }

    score
}

