pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, scaled by progress (late stream: value tight fits more)
    let mut score = pr * (1.0 + 0.5 * progress);

    // Non-linear polynomial coupling: quadratic waste penalty grows with progress
    score += 40.0 * progress * norm_pr * norm_pr;

    // Dead-space term: residuals too small for any future item (min size 1, but small slivers are useless)
    let dead = (20.0 - pr as f64).max(0.0) / 20.0;
    score += 30.0 * dead * dead * (0.5 + progress);

    // Perfect fit reward (smooth, polynomial)
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead coupling: if next item fits exactly into post_residual, reward
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 20.0 * (1.0 - gap / cap) * (1.0 - gap / cap);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening new bins when decent fits exist, more so early
    if bin_residual == bin_capacity {
        score += 10.0 + 40.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // but if existing bins would leave bad residuals, allow new bin
        let mean_gap = (mean_residual - item_size as f64).abs();
        if mean_gap > 30.0 {
            score -= 35.0 * progress;
        }
    }

    // Mean residual coupling: prefer bins near mean residual (keeps balance)
    score += 0.1 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: buckets by capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Penalize dead space that is too small to be useful for typical items.
    // Class boundaries: residual < 10 is nearly dead; < 25 is half-dead.
    if post_residual == 0 {
        score -= 30.0; // perfect fit, ideal
    } else if post_residual < 10 {
        score += 40.0; // dead space class: residual 1..9 useless
    } else if post_residual < 25 {
        score += 15.0; // awkward class
    } else if post_residual < 50 {
        score += 5.0;
    }

    // Modulo arithmetic on post_residual: residuals divisible by 10 align
    // with the coarse item grid, making future packing easier.
    let mod10 = post_residual % 10;
    if mod10 == 0 {
        score -= 8.0;
    } else if mod10 >= 5 {
        score += mod10 as f64 * 0.5;
    } else {
        score += (5 - mod10) as f64 * 0.3;
    }

    // Harmonic coupling with next item: if next item fits exactly in the
    // post-residual, strongly reward this bin (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // reward closeness of next item to post-residual
            let gap = (post_residual - next_item_size) as f64;
            score -= 10.0 / (1.0 + gap / 10.0);
        } else {
            // next item won't fit here; penalize large wasted residuals
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit would be terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + frac * 10.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer reusing open bins when their post-residual stays usable;
    // prefer a new bin when the item is huge relative to any residual.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, amortized by stream progress:
        // early on, opening bins is cheap (many future items to fill them);
        // late in the stream, prefer squeezing into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 30.0 * progress;

        // If item is large (>60), a fresh bin is naturally attractive.
        if item_size >= 60 {
            score -= 15.0;
        }
        // If many open bins already exist with high mean residual, opening
        // yet another bin fragments capacity; discourage.
        if open_bins_count > 3 && mean_residual > 30.0 {
            score += 10.0;
        }
    } else {
        // Reward tight fits into existing bins: small post_residual relative
        // to item size indicates good space utilization.
        let tightness = item_size as f64 / bin_residual.max(1) as f64;
        score -= 10.0 * tightness;
    }

    // Integer-division threshold: residual class by quarters of capacity.
    let quarter = post_residual / (bin_capacity / 4);
    score -= quarter as f64 * 2.0;

    // Mild global pressure: with many open bins, favor consolidation.
    score += open_bins_count as f64 * 0.3;

    score
}

