    // Lookahead chain scoring: reward bins whose post-residual chains tightly
    // into the next item; penalize dead slivers just below nx.
    if nx > 0.0 {
        if pr < nx && pr > 0.0 {
            let gap = nx - pr;
            score += gap * (2.0 + 6.5 * (1.0 - progress));
            let closeness = 1.0 - pr / nx;
            score += 3.0 * closeness * closeness * (0.6 + progress);
            if gap <= 3.0 {
                score -= 9.0 * (1.0 - progress);
            }
        } else if pr > 0.0 {
            let chain_gap = pr - nx;
            let slack = chain_gap / cap;
            if chain_gap <= 42.0 {
                score -= 6.5 + 0.11 * chain_gap;
            }
            if slack < 0.04 {
                score -= 8.5 * (1.0 - slack * 25.0) * (1.0 + progress);
