        if fitting_bins_count == 1 {
            score -= 14.0 + 12.0 * progress;
        } else if fitting_bins_count == 2 {
            score -= 4.0 + 3.0 * progress;
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item (1..100 range, but realistically >=10) are pure waste.
    let min_item = 10.0f64;
    if (post_residual as f64) < min_item && post_residual > 0 {
        // Unusable sliver: harsh penalty proportional to how close to zero.
        score += 60.0 * (1.0 - (post_residual as f64) / min_item);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize leaving a gap that is large enough to be useful but
    // awkwardly sized relative to the lookahead item.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            // This bin can also host the next item: favorable.
            score -= 15.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            // Next item won't fit here; residual may become dead space.
            score += 8.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless the
    // fit is genuinely good.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only bin that fits, using it avoids
    // opening a new bin for a potentially awkward item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when current fit is poor
    // (large post_residual) or open bins are numerous/congested.
    if bin_residual == bin_capacity {
        // Base cost of opening a fresh bin; cheap when item is large or
        // existing bins are nearly full.
        let poor_fit = (post_residual as f64) > 45.0;
        let congestion = mean_residual < 20.0;
        if poor_fit || congestion || fitting_bins_count == 0 {
            score -= 20.0 + 0.5 * open_bins_count as f64;
        } else {
            score += 45.0; // prefer placing into an existing reasonable bin
        }
    }

    // Mild alignment reward: residual close to mean_residual keeps bin
    // population homogeneous and flexible.
    score -= 0.15 * (post_residual as f64 - mean_residual).abs().max(0.0).min(30.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward when the next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0; // perfect two-step chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportional to how tight the chain is
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
            // penalize leaving awkward slack relative to mean residual
            if slack > mean_residual {
                score += 0.5 * (slack - mean_residual);
            }
        } else {
            // next item won't fit here: post residual likely dead space
            score += 10.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Prefer tighter bins overall (best-fit bias beyond raw post_residual)
    score += 0.3 * (bin_residual as f64 - post_residual as f64).signum()
        * ((item_size as f64) / 10.0);

    // Late in the stream, prefer using existing bins over opening new ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 20.0 * progress;
    } else {
        // new-bin candidate: penalize slightly unless post residual is large
        score += 15.0 * progress - 0.05 * post_residual as f64;
    }

    // Discard bins whose residual is too small to ever fit typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

