        // relative to the next item; prefer bins that keep chainable space.
        if nx > 0.0 {
            let r1 = cap - it;
            if r1 < nx && r1 > 0.0 {
                nb += (1.0 + 2.0 * progress) * (nx - r1) * 0.55;
            }
            if r1 >= nx && (r1 - nx) > 0.25 * cap && progress > 0.45 {
                nb += 4.5 * ((r1 - nx) / cap).min(0.5) * progress;
            }
        }
        // When mean residual is fragmented, opening a fresh bin that
        // chains it+nx tightly is attractive.
        if nx > 0.0 && cap >= it + nx && (cap - it - nx) < 0.08 * cap && progress > 0.3 {
            nb -= 5.0 * (1.0 - (cap - it - nx) / (0.08 * cap)) * (0.5 + progress);
        }
        // NEW: wider margin lookahead — a fresh bin that leaves margin in the
        // 8-15% band after it+nx is a good flexible host; reward it.
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin >= 0.08 * cap && margin < 0.15 * cap && progress > 0.25 {
                nb -= 4.5 * (1.0 - (margin - 0.08 * cap) / (0.07 * cap)) * (0.4 + progress);
            }
        }
        // NEW: when the next item cannot fit into any open bin's typical
        // residual (mean_residual < nx), a new bin hosting it+nx tightly is
        // strongly preferred over fragmenting.
        if nx > 0.0 && mean_residual < nx && cap >= it + nx && (cap - it - nx) < 0.12 * cap {
            nb -= 6.0 * (1.0 - (cap - it - nx) / (0.12 * cap)) * (0.5 + progress);
        }
