        // still have above-average room.
        if item_frac < 0.12 && progress > 0.5 && mean_residual > 0.3 * cap {
            nb += 7.0 * progress * (1.0 - item_frac / 0.12) * ((mean_residual - 0.3 * cap) / cap).min(1.0);
