    let mut score = post_residual as f64;

    // Strong reward if the next item fits exactly or well into the post residual (2-step lookahead).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect 2-step match is heavily favored.
            score -= 60.0 - slack * 0.5;
        } else {
            // Next item does not fit here; penalize if we leave large dead space.
            let dead = post_residual as f64;
            if dead > 0.0 && dead < next_item_size as f64 {
                score += dead * 0.4;
            }
        }
    }

    // Prefer bins with residual below mean residual (tight packing).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize waste when item fills bin nearly perfectly (small post residual is good).
    if post_residual == 0 {
        score -= 40.0;
    }

    // New-bin candidate: make it unattractive unless current bin fits poorly.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin, reduced when the item is large.
        score += 90.0 - (item_size as f64) * 0.5;
        // If next item is large and won't fit anywhere anyway, new bin is more acceptable.
        if next_item_size > 50 {
            score -= 15.0;
        }
    }

    // Late in stream: slightly discourage opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

