pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: waste is quadratic in leftover.
    score += 0.8 * (post_residual as f64 / bin_capacity as f64).powi(3) * bin_capacity as f64;

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to how far off.
            score += 0.15 * ((next_item_size - post_residual) as f64);
        }
    } else {
        // Last item: minimize leftover aggressively.
        score += 2.0 * post_residual as f64;
    }

    // Last-chance bin: if this is the only bin that can fit the item, favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when good fits exist elsewhere.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fit_quality = item_size as f64 / bin_capacity as f64;
        // New bins are better for large items late in the stream, worse for small items.
        score += 18.0 * (1.0 - fit_quality) * (0.5 + 0.5 * progress);
        if fitting_bins_count > 0 && post_residual > 40 {
            score += 15.0; // wasteful new bin with lots of room left elsewhere
        }
        if open_bins_count == 0 {
            score -= 50.0; // must open a bin
        }
    }

    // Global state coupling: prefer bins whose residual is above/below mean to balance.
    if bin_residual != bin_capacity {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev;
    }

    // Prefer filling bins that are already mostly full (small residual).
    score += 0.1 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: quadratic in normalized post-residual (favor small dead space)
    let mut score = x * x * 30.0 + x * 12.0;

    // Smooth interaction: post residual value scaled by progress
    score += pr * (0.5 + progress * 1.5) * 0.05;

    // Penalize waste relative to mean residual across open bins
    score += (pr - mean_residual).abs() * 0.08;

    // Last-chance bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - x);
    }

    // Lookahead: reward residual that can still host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 6.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 5.0 * (nx - pr) / cap;
        }
    }

    // Mild penalty for proliferating bins late in the stream
    score += (open_bins_count as f64).ln().max(0.0) * (0.5 + progress);

    // Prefer tight fits smoothly: coupling item size with residual
    let fill = 1.0 - x;
    score -= fill * fill * 8.0;

    // New-bin candidate: neutral-ish baseline so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score = 20.0 + 10.0 * progress;
    }

    score
}

