pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Leftovers in the "large half" class are
    // still broadly usable; tiny leftovers are dead space -> penalize hard.
    let cap = bin_capacity as f64;
    let half = cap / 2.0;
    let quarter = cap / 4.0;

    if post_residual as f64 > half {
        // Large residual class: reward tight packing into near-full bins less,
        // but a residual above half means this bin was loose anyway.
