        } else {
            // Next item will not fit: penalize proportionally to the gap.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless residual after is tiny anyway).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only open a new bin when existing residuals
    // are poor (mean residual low relative to item) or few bins are open.
    if bin_residual == bin_capacity {
        let poor_existing = if mean_residual > 0.0 {
            (item_size as f64 / mean_residual) > 0.85
        } else {
            true
        };
        if poor_existing && open_bins_count > 0 {
            score -= 5.0;
        } else {
            score += 25.0; // discourage needless bin proliferation
        }
    }

    // Early-stream exploration: keep bins open early to build packing options.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 {
        score += 3.0 * (1.0 - progress * 5.0);
    }

    // Mild preference for bins whose residual is close to the item (tight fit).
    score += (bin_residual - item_size) as f64 * 0.05;

    // Open-bins pressure: many open bins -> favor filling existing ones.
    score += open_bins_count as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
