            score += 3.0 * closeness * closeness * (0.6 + progress);
        }
        // Chain window: moderate room above next item
        if nx > 0.0 && pr > nx && (pr - nx) > 0.04 * cap && (pr - nx) < 0.18 * cap {
            score -= 2.2 * (1.0 - ((pr - nx) / (0.18 * cap))) * (0.3 + progress);
        }
        // Scarcity + moderate room
        if nx > 0.0 && pr >= nx && (pr - nx) > 0.06 * cap && (pr - nx) < 0.22 * cap && fitting_bins_count <= 2 {
            score -= 2.0 * (1.0 - ((pr - nx) / (0.22 * cap))) * (0.6 + progress);
        }
        // Early-stream: keep flexible space when next item fits
        if waste > 0.1 && waste < 0.2 && pr > 0.0 && nx > 0.0 && pr >= nx && progress < 0.45 {
            score += 1.8 * (1.0 - (pr - nx) / (0.12 * cap)) * (1.0 - progress);
        }

        // Crowding bonus
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
