            score -= 5.0 + 4.0 * (nx / cap) + 9.5 * (1.0 - (pr - nx) / cap).min(1.0) * (1.0 - progress);
            let chain_gap = pr - nx;
            if chain_gap >= 1.0 && chain_gap <= 42.0 {
                score -= 6.5 + 0.11 * chain_gap;
