}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { (step_index as f64 / total_items as f64).clamp(0.0, 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;
    let is_new_bin = (res - cap).abs() < 1e-9;

    // Base: post residual with quadratic amplification (borrowed from best)
    let mut score = pr * (1.0 + 0.03 * (pr / cap) * (pr / cap));

    // Tightness multiplier grows with progress
    let tightness = 1.0 + 2.6 * progress * progress + 2.4 * progress * progress * progress;
    score *= tightness;

    // Lookahead chain logic
    if nx > 0.0 {
        if pr < nx {
            let gap = nx - pr;
            score += gap * (2.0 + 6.5 * (1.0 - progress));
        } else {
            let chain_gap = pr - nx;
            let slack = chain_gap / cap;
            if chain_gap <= 42.0 {
                score -= 6.5 + 0.11 * chain_gap;
            }
            if slack < 0.04 {
                score -= 8.5 * (1.0 - slack * 25.0) * (1.0 + progress);
            }
            let chain = 1.0 - slack.min(1.0);
            score -= 5.0 + 4.0 * (nx / cap) + 9.5 * chain * (1.0 - progress);
        }
    }

    // Dead-space penalty scaled by unusability
    let dead_ratio = (pr / cap).max(0.0);
    let unusable = if nx > 0.0 && pr > 0.0 && pr < nx { 1.0 } else { 0.55 };
    score += (10.5 + 3.2 * progress) * dead_ratio * dead_ratio * cap * (0.45 + progress) * unusable;

    // Near-exact fit bonus
    if dead_ratio > 0.0 && dead_ratio < 0.12 {
        score -= 9.0 * (1.0 - dead_ratio / 0.12) * (0.4 + progress);
    }
    if nx > 0.0 && pr > 0.0 && pr < nx && (nx - pr) <= 0.04 * cap {
        score += 3.5 * (1.0 - (nx - pr) / (0.04 * cap)) * (0.5 + progress);
    }

    // Scarcity bonus for last fitting bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 4.0 + 2.0 * progress;
    } else if fitting_bins_count > 1 {
        score -= 0.3 / fitting_bins_count as f64;
    }

    // Exact fit: pr == 0 is ideal
    if pr == 0.0 {
        score -= 62.0;
    } else if pr <= 5.0 {
        score -= 31.0 * (1.0 - 0.4 * progress);
    }

    // Deviation from mean residual as mild tie-break
    let dev = mean_residual - res;
    score += 0.085 * dev;

    // Mild open-bin pressure
    score -= 0.42 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate gating (adapted from best heuristic)
    if is_new_bin {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let item_frac = (it / cap).min(1.0);
        let mut nb = cap * (1.35 + 1.15 * progress);
        nb -= 26.0 * scarcity * (1.0 - progress);
        nb -= 19.0 * item_frac * (1.0 - progress);
        if nx >= 0.5 * cap {
            nb -= 12.0 * progress + 6.0 * (1.0 - progress);
        }
        nb += 15.0 * progress * (1.0 - item_frac);
        if it >= cap - 1.0 {
            nb -= 32.0;
        }
        if nx > 0.0 && cap - it >= nx {
            nb -= 10.5 + 0.11 * (cap - it - nx);
        }
        if fitting_bins_count <= 2 {
            nb += 21.0 + 10.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 4 {
            nb -= 6.5 + 8.5 * progress;
        }
        if nx > 0.0 && mean_residual >= it + nx && progress < 0.6 {
            nb -= 5.5 * (1.0 - progress) * ((mean_residual - it - nx) / cap).min(0.3) * 10.0;
        }
        if it > 0.85 * cap && progress > 0.3 {
            nb -= 9.0 * progress;
        }
        if progress > 0.75 && fitting_bins_count > 0 && mean_residual >= it {
            nb += 5.5 + 4.5 * progress;
        }
        if it < 0.2 * cap && progress < 0.3 && open_bins_count < 6 {
            nb += 7.0 * (1.0 - progress);
        }
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin < 0.15 * cap {
                nb -= 6.0 * (1.0 - margin / (0.15 * cap)) * (0.6 + 0.4 * progress);
            }
        }
        score = nb;
    }

    score
}

