        if pr > 0.0 && nx > 0.0 && pr < nx && (nx - pr) > 0.1 * cap && waste > 0.25 {
            score += 5.0 * (waste - 0.25) * 10.0 * (0.4 + progress);
        }
        if pr > 0.0 && nx > 0.0 && pr < 0.5 * nx && progress > 0.3 {
            score += 3.5 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
        }
        if waste > 0.3 && pr > nx && progress < 0.5 {
            score += 3.0 * (waste - 0.3) * 10.0 * (1.0 - progress);
        }
        if fill_ratio > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
            score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
        }
        if waste > 0.35 && progress > 0.55 && nx > 0.0 && pr >= nx {
            score -= 4.5 * ((pr - nx) / cap).min(0.2) * 5.0 * progress;
        }
        if waste > 0.28 && fitting_bins_count > 2 && progress > 0.5 {
            score += 3.5 * (waste - 0.28) * 10.0 * progress;
        }
        if waste > 0.4 && pr > 0.0 && nx > 0.0 && pr < nx && progress > 0.6 {
            score += 4.0 * (waste - 0.4) * 10.0 * progress;
        }
        if nx > 0.0 && pr >= nx && (pr - nx) < 0.5 * nx && progress > 0.6 {
            score -= 2.8 * (1.0 - (pr - nx) / (0.5 * nx)) * progress;
        }
        if nx > 0.0 && pr >= nx && (pr - nx) > 0.06 * cap && (pr - nx) < 0.22 * cap && fitting_bins_count <= 2 {
            score -= 2.0 * (1.0 - ((pr - nx) / (0.22 * cap))) * (0.6 + progress);
        }
        if waste > 0.05 && waste < 0.14 && pr >= nx && progress > 0.5 {
            score -= 2.4 * (1.0 - (waste - 0.05) / 0.09) * progress;
        }
        if pr > 0.0 && it > 0.0 && pr < it * 0.5 && waste > 0.05 {
            score += 2.5 * (1.0 - pr / (it * 0.5)) * (0.4 + progress);
        }

        // Crowding bonus
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { (step_index as f64 / total_items as f64).clamp(0.0, 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;
    let is_new_bin = (res - cap).abs() < 1e-9;

    if is_new_bin {
        // New-bin candidate: mostly unattractive unless it enables a perfect chain
        let mut nb = cap * (1.3 + 1.1 * progress);
        let item_frac = (it / cap).min(1.0);
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        nb -= 24.0 * scarcity * (1.0 - progress);
        nb -= 18.0 * item_frac * (1.0 - progress);
        // Perfect two-item chain in a fresh bin
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin < 0.04 * cap { nb -= 10.0 * (1.0 - margin / (0.04 * cap)); }
        }
        if it >= cap - 1 { nb -= 30.0; }
        // Big item late: just open a bin
        if it > 0.85 * cap && progress > 0.3 { nb -= 9.0 * progress; }
        // Plenty of aggregate space elsewhere: keep new bin unattractive
        if mean_residual >= it { nb += 6.0 + 8.0 * progress; }
        if nx > it && mean_residual >= nx && progress < 0.6 { nb += 9.0 * (1.0 - progress); }
        // No fitting bin at all: must open
        if fitting_bins_count == 0 { nb -= 20.0 + 10.0 * progress; }
        if fitting_bins_count <= 2 { nb += 12.0 * (1.0 - progress); }
        if fitting_bins_count >= 4 { nb -= 6.0 + 7.0 * progress; }
        // Small items early: prefer consolidating into open bins
        if item_frac < 0.2 && progress < 0.3 && open_bins_count < 6 { nb += 6.0 * (1.0 - progress); }
        return nb;
    }

    // Open-bin scoring: strongly minimize post residual, reward perfect fills
    let waste = pr / cap;
    let mut score = pr * (1.0 + 0.03 * waste * waste);

    // Tightness ramp: later in stream, push harder for tight fits
    let tightness = 1.0 + 2.6 * progress * progress + 2.4 * progress * progress * progress;
    score *= tightness;

    // Perfect fill is the best outcome
    if pr == 0.0 {
        score -= 60.0 + 10.0 * progress;
    } else if pr <= 5.0 {
        score -= 28.0 * (1.0 - 0.4 * progress);
    } else if waste < 0.08 {
        score -= 30.0 * (1.0 - progress) * (0.08 - waste);
    }

    // Lookahead: chain next item into the residual
    if nx > 0.0 {
        if pr >= nx {
            let room = pr - nx;
            if room < 0.05 * cap {
                score -= 7.0 * (1.0 - room / (0.05 * cap)) * (0.5 + progress);
            } else if room < 0.2 * cap {
                score -= 3.0 * (1.0 - room / (0.2 * cap)) * (0.4 + progress);
            }
        } else {
            // next item won't fit: residual below next size is dead space
            let gap = nx - pr;
            score += 5.0 + 2.0 * progress;
            if gap <= 3.0 { score -= 8.0 * (1.0 - progress); }
            if waste > 0.25 { score += 4.0 * (waste - 0.25) * 10.0 * (0.4 + progress); }
        }
    }

    // Small unusable residual is worse than a filled bin
    if pr > 0.0 && pr < 10.0 { score += 30.0 * (1.0 - 0.5 * progress); }

    // Scarcity bonus: only fitting bin gets priority
    if fitting_bins_count == 1 {
        score -= 6.0;
    } else if fitting_bins_count > 1 {
        score -= 1.5 / fitting_bins_count as f64;
    }

    // Prefer bins whose residual is close to item size (smooth kernel)
    let t = (res - it) / cap;
    score += 1.2 * t * t;

    // Deviation from mean residual: mild consolidation pressure
    let dev = mean_residual - res;
    score += 0.08 * dev;

    // Many open bins with low mean residual: discourage leaving slack
    score += 0.02 * (open_bins_count as f64).ln().max(0.0) * waste * cap * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
