        }
        if waste > 0.14 && waste < 0.34 {
            score += 13.0 * (waste - 0.14) * (0.6 + 0.8 * progress);
        }
        if fitting_bins_count > 3 && waste < 0.12 {
            score -= 5.5 * (1.0 - waste * 8.0) * (0.5 + progress);
        }
        if nx > 0.0 && pr > 0.0 && pr > nx && (pr - nx) < 0.02 * cap {
            score -= 4.0 * (1.0 - (pr - nx) / (0.02 * cap)) * (0.4 + progress);
        }
        if pr > 0.0 && (pr as f64).sqrt() < 2.6 {
            score -= 3.5 * (1.0 - progress);
        }
        if waste > 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.09 * cap && progress > 0.4 {
            score -= 4.0 * (1.0 - (pr - nx) / (0.09 * cap)) * progress;
        }
        if pr > 0.0 && nx > 0.0 && pr < nx && (nx - pr) > 0.1 * cap && waste > 0.25 {
            score += 5.0 * (waste - 0.25) * 10.0 * (0.4 + progress);
        }
        if pr > 0.0 && nx > 0.0 && pr < 0.5 * nx && progress > 0.3 {
            score += 3.5 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
        }
        if waste > 0.3 && pr > nx && progress < 0.5 {
            score += 3.0 * (waste - 0.3) * 10.0 * (1.0 - progress);
        }
        if fill_ratio > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
            score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
        }
        if waste > 0.35 && progress > 0.55 && nx > 0.0 && pr >= nx {
            score -= 4.5 * ((pr - nx) / cap).min(0.2) * 5.0 * progress;
        }
        // NEW: prefer bins whose post-fit residual is chainable with next item
        if nx > 0.0 && pr > nx && (pr - nx) <= 0.04 * cap {
            score -= 3.2 * (1.0 - (pr - nx) / (0.04 * cap)) * (1.0 - progress);
        }
        if nx > 0.0 && pr > nx && (pr - nx) > 0.04 * cap && (pr - nx) < 0.18 * cap {
            score -= 2.2 * (1.0 - ((pr - nx) / (0.18 * cap))) * (0.3 + progress);
        }
        // NEW: penalize leaving residual below half the item in low waste
        if pr > 0.0 && it > 0.0 && pr < it * 0.5 && waste > 0.05 {
            score += 2.5 * (1.0 - pr / (it * 0.5)) * (0.4 + progress);
        }
        // NEW: moderate waste with chainable room is attractive
        if waste > 0.18 && waste < 0.4 && nx > 0.0 && pr >= nx && (pr - nx) < 0.12 * cap {
            score += 3.0 * (1.0 - (pr - nx) / (0.12 * cap)) * (0.5 + progress);
        }
        // NEW: late-stream moderate waste should be strongly penalized
        if waste > 0.28 && fitting_bins_count > 2 && progress > 0.5 {
            score += 3.5 * (waste - 0.28) * 10.0 * progress;
        }
        // NEW: very large waste with dead residual late — penalize more
        if waste > 0.4 && pr > 0.0 && nx > 0.0 && pr < nx && progress > 0.6 {
            score += 4.0 * (waste - 0.4) * 10.0 * progress;
        }
        // NEW: near-perfect chain (room within half of nx) late in stream
        if nx > 0.0 && pr >= nx && (pr - nx) < 0.5 * nx && progress > 0.6 {
            score -= 2.8 * (1.0 - (pr - nx) / (0.5 * nx)) * progress;
        }
        // Scarcity: prefer using existing bins when few can fit
        if fitting_bins_count == 1 {
            score -= 14.0 + 12.0 * progress;
        } else if fitting_bins_count == 2 {
            score -= 4.0 + 3.0 * progress;
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;

    let mut score = pr * (1.0 + 0.03 * (pr / cap) * (pr / cap));

    let tightness = 1.0 + 2.6 * progress * progress + 2.4 * progress * progress * progress;
    score *= tightness;

    if post_residual > 0 && post_residual < 10 {
        score += 41.0 * (1.0 - 0.5 * progress);
    }
    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual <= 5 {
        score -= 31.0 * (1.0 - 0.4 * progress);
    }

    // Lookahead: chained fits rewarded, blocking penalized
    if nx > 0.0 {
        if pr >= nx {
            let chain_gap = pr - nx;
            let slack = chain_gap / cap;
            if chain_gap <= 42.0 {
                score -= 6.5 + 0.11 * chain_gap;
            }
            if slack < 0.04 {
                score -= 8.5 * (1.0 - slack * 25.0) * (1.0 + progress);
            }
            // mid-gap chaining keeps residual useful for the stream
            if chain_gap > 0.04 * cap && chain_gap < 0.18 * cap {
                score -= 2.4 * (1.0 - (chain_gap / (0.18 * cap))) * (0.3 + progress);
            }
            let chain = 1.0 - slack.min(1.0);
            score -= 5.0 + 4.0 * (nx / cap) + 9.5 * chain * (1.0 - progress);
            if chain_gap < 0.06 * cap {
                score -= 6.5 * (1.0 - chain_gap / (0.06 * cap)) * (0.5 + progress);
            }
        } else {
            let gap = nx - pr;
            score += gap * (2.0 + 6.5 * (1.0 - progress));
            if gap <= 3.0 {
                score -= 9.0 * (1.0 - progress);
            }
            if gap <= 0.04 * cap {
                score += 3.5 * (1.0 - gap / (0.04 * cap)) * (0.5 + progress);
            }
            let closeness = 1.0 - pr / nx;
            score += 3.0 * closeness * closeness * (0.6 + progress);
        }
    }

    // Dead-space penalty with unusable weighting
    let dead_ratio = (pr / cap).max(0.0);
    let unusable = if nx > 0.0 && pr > 0.0 && pr < nx { 1.0 } else { 0.55 };
    score += (10.5 + 3.2 * progress) * dead_ratio * dead_ratio * cap * (0.45 + progress) * unusable;
    if dead_ratio > 0.0 && dead_ratio < 0.12 {
        score -= 9.0 * (1.0 - dead_ratio / 0.12) * (0.4 + progress);
    }
    if dead_ratio > 0.12 && dead_ratio < 0.3 {
        score += 3.5 * (dead_ratio - 0.12) * (0.5 + progress);
    }

    if bin_residual < bin_capacity {
        let dev = mean_residual - res;
        score += 0.085 * dev;
        if dev > -5.0 && dev < 15.0 && pr > 0.0 {
            score -= 4.2;
        }
        let fill_ratio = 1.0 - res / cap;
        let waste = pr / cap;
        if waste < 0.08 && pr > 0.0 {
            score -= 48.0 * (1.0 - progress) * (0.08 - waste);
        }
        if fill_ratio > 0.65 {
            score -= 4.8 * (fill_ratio - 0.65) * 10.0 * (0.4 + progress);
        }
        if fill_ratio > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
            score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
        }
        if waste > 0.14 && waste < 0.34 {
            score += 13.0 * (waste - 0.14) * (0.6 + 0.8 * progress);
        }
        if fitting_bins_count > 3 && waste < 0.12 {
            score -= 5.5 * (1.0 - waste * 8.0) * (0.5 + progress);
        }
        if nx > 0.0 && pr > 0.0 && pr < nx {
            score += 6.5 + 2.2 * progress;
        }
        let tight_fit = (pr == 0.0) || (nx > 0.0 && pr == nx);
        if tight_fit {
            score -= 10.5 * (0.3 + progress);
        }
        if fitting_bins_count == 1 {
            score -= 14.0 + 12.0 * progress;
        } else if fitting_bins_count == 2 {
            score -= 4.0 + 3.0 * progress;
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }

    // NEW-BIN CANDIDATE scoring
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let item_frac = (it / cap).min(1.0);
        let mut nb = cap * (1.35 + 1.15 * progress);
        nb -= 26.0 * scarcity * (1.0 - progress);
        nb -= 19.0 * item_frac * (1.0 - progress);
        if nx >= 0.5 * cap {
            nb -= 12.0 * progress + 6.0 * (1.0 - progress);
        }
        nb += 15.0 * progress * (1.0 - item_frac);
        if it >= cap - 1.0 {
            nb -= 32.0;
        }
        if nx > 0.0 && cap - it >= nx {
            nb -= 10.5 + 0.11 * (cap - it - nx);
        }
        if nx > 0.0 {
            let r1 = cap - it;
            if r1 >= nx && (r1 - nx) < 6.0 && (r1 - nx) > 0.0 {
                nb += 8.5 * (1.0 - progress);
            }
            if r1 < nx && r1 > 0.0 {
                nb += (1.0 + 2.0 * progress) * (nx - r1) * 0.55;
            }
            if r1 >= nx && (r1 - nx) > 0.25 * cap && progress > 0.45 {
                nb += 4.5 * ((r1 - nx) / cap).min(0.5) * progress;
            }
        }
        if fitting_bins_count <= 2 {
            nb += 21.0 + 10.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 4 {
            nb -= 6.5 + 8.5 * progress;
        }
        if nx > 0.0 && mean_residual > nx + 8.0 && progress < 0.7 {
            nb += 8.5 * ((mean_residual - nx) / cap).min(0.5) * cap * 0.1;
        }
        if mean_residual >= it && progress > 0.5 {
            nb += 6.5 + 8.5 * progress;
        }
        if nx > it && mean_residual >= nx && progress < 0.6 {
            nb += 10.0 * (1.0 - progress);
        }
        if nx > 0.0 && mean_residual >= it + nx && progress < 0.6 {
            nb -= 5.5 * (1.0 - progress) * ((mean_residual - it - nx) / cap).min(0.3) * 10.0;
        }
        if it > 0.85 * cap && progress > 0.3 {
            nb -= 9.0 * progress;
        }
        if nx > 0.0 && mean_residual > nx {
            let excess = mean_residual - nx;
            if excess < 0.05 * cap && progress < 0.55 {
                nb += 5.0 * (1.0 - excess / (0.05 * cap)) * (1.0 - progress);
            }
        }
        if fitting_bins_count == 0 && progress > 0.25 {
            nb += 9.0 + 7.0 * progress;
        }
        if nx > 0.0 && it + nx > cap && mean_residual >= nx {
            nb += 6.0 * (1.0 - progress);
        }
        if progress > 0.75 && fitting_bins_count > 0 && mean_residual >= it {
            nb += 5.5 + 4.5 * progress;
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_left = mean_residual - it;
            if best_left >= nx && (best_left - nx) < 12.0 {
                nb += 4.0 * (1.0 - (best_left - nx) / 12.0) * (0.5 + progress);
            }
        }
        if it < 0.2 * cap && progress < 0.3 && open_bins_count < 6 {
            nb += 7.0 * (1.0 - progress);
        }
        if item_frac > 0.6 && nx > 0.0 && cap >= it + nx && cap - it - nx < 0.03 * cap {
            nb -= 5.5 * (1.0 - (cap - it - nx) / (0.03 * cap));
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_pr = (mean_residual - it).max(0.0);
            if best_pr > 0.0 && best_pr < 0.06 * cap && (cap - it) >= nx {
                nb -= 7.0 * (1.0 - best_pr / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if progress > 0.85 && mean_residual < 0.15 * cap {
            nb += 7.0 * progress * (1.0 - mean_residual / (0.15 * cap));
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_post = (mean_residual - it).max(0.0);
            if best_post >= nx && best_post - nx > 0.18 * cap && progress > 0.35 {
                nb -= 6.0 * ((best_post - nx) / cap).min(0.4) * (0.4 + progress);
            }
        }
        if item_frac > 0.45 && item_frac < 0.75 && progress > 0.5 {
            nb -= 5.0 * (item_frac - 0.45) * progress;
        }
        if fitting_bins_count >= 2 && mean_residual < 0.25 * cap && progress > 0.6 {
            nb += 6.0 * (1.0 - mean_residual / (0.25 * cap)) * progress;
        }
        if fitting_bins_count >= 3 && mean_residual - it >= nx && progress > 0.5 {
            nb += 4.5 * progress * (1.0 - ((mean_residual - it - nx) / cap).min(1.0));
        }
        if open_bins_count > 10 && progress < 0.35 && item_frac < 0.3 {
            nb += 6.0 * (1.0 - progress) * (1.0 - item_frac / 0.3);
        }
        if open_bins_count > 6 && mean_residual > 0.4 * cap && progress < 0.6 {
            nb += 5.0 * ((mean_residual - 0.4 * cap) / cap) * (1.0 - progress) * ((open_bins_count as f64 - 6.0).min(8.0) / 8.0);
        }
        if item_frac < 0.15 && progress > 0.55 && fitting_bins_count >= 1 {
            nb += 6.0 * progress * (1.0 - item_frac / 0.15);
        }
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin < 0.15 * cap {
                nb -= 6.0 * (1.0 - margin / (0.15 * cap)) * (0.6 + 0.4 * progress);
            }
        }
        if nx > 0.0 && fitting_bins_count >= 1 && mean_residual - it >= nx {
            let leftover = mean_residual - it - nx;
            if leftover < 0.1 * cap && progress > 0.45 {
                nb -= 5.0 * (1.0 - leftover / (0.1 * cap)) * progress;
            }
        }
        if open_bins_count > 12 && progress > 0.6 && item_frac < 0.25 {
            nb += 5.0 * progress * (1.0 - item_frac / 0.25);
        }
        if nx > 0.0 && fitting_bins_count >= 1 && (cap - it) >= nx && (cap - it - nx) < 0.05 * cap && progress < 0.5 {
            nb -= 4.0 * (1.0 - (cap - it - nx) / (0.05 * cap)) * (1.0 - progress);
        }
        if fitting_bins_count == 1 && mean_residual >= it && (mean_residual - it) < 0.04 * cap && progress > 0.3 {
            nb -= 3.0 * (1.0 - (mean_residual - it) / (0.04 * cap)) * (0.5 + progress);
        }
        if open_bins_count > 8 && mean_residual < 0.1 * cap && progress > 0.5 {
            nb -= 4.0 * (1.0 - mean_residual / (0.1 * cap)) * progress;
        }
        score = nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: penalize unusable small gaps
    // (residual too small for the minimum plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Semi-dead space: mildly penalize.
        score += 15.0;
    }

    // Tight fit reward: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill;

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins over spreading; when few bins are open,
    // tolerate spreading (penalize new-bin usage less implicitly by
    // rewarding use of existing bins more).
    let pressure = (open_bins_count as f64).ln() + 1.0;
    if bin_residual != bin_capacity {
        score -= 8.0 * pressure;
    } else {
        // New empty bin candidate: penalize mildly unless it avoids dead space.
        score += 10.0 + 3.0 * pressure;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin for a poor fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item could fit into the post residual,
    // reward keeping this bin; otherwise penalize leaving a tempting gap.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Stream progression: late in the stream, be more conservative with
    // dead space since fewer opportunities remain to fill gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins whose residual is near the
    // mean to keep the pool of usable bins homogeneous.
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead matching: reward post_residual exactly matching next item ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step chain
        } else {
            let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
            // graded penalty grows with mismatch; small gaps still mildly rewarded
            score += gap * 0.45;
            if gap <= 5.0 {
                score -= 12.0;
            }
        }
        // avoid leaving residuals that no plausible item (min size 1..) can ever fill tightly
        if post_residual > 0 && post_residual < 10 && post_residual != next_item_size {
            score += 25.0; // tiny dead space
        }
    } else {
        // last item: prefer the fullest bin (smallest post residual) — already implicit
        score -= 10.0;
    }

    // --- relative-to-mean coupling: prefer bins tighter than the average ---
    let resid = post_residual as f64;
    if resid < mean_residual {
        score -= (mean_residual - resid) * 0.35;
    } else {
        score += (resid - mean_residual) * 0.55;
    }

    // --- last-chance bin: strongly favor using the only fitting bin ---
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // --- new-bin candidate handling ---
    if bin_residual == bin_capacity {
        // opening a new bin is only attractive when no open bin fits well,
        // i.e. when the item is large relative to typical residuals
        let tightness = mean_residual / bin_capacity as f64;
        let poor_fit = if next_item_size > 0 {
            (bin_residual as i64 - item_size as i64 - next_item_size as i64).unsigned_abs() as f64
        } else { 0.0 };
        score = (bin_capacity - item_size) as f64 // residual after placement in fresh bin
            + 18.0                                  // default cost of opening a bin
            + tightness * 20.0
            - poor_fit * 0.6;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 15.0; // fresh bin can also host the next item
        }
    }

    // --- mild progression pressure: as stream advances, consolidate more eagerly ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // prefer fewer open bins (encourage packing into existing bins)
    score += open_bins_count as f64 * 0.3;

    score
}

