    let it = item_size as f64;
    let nx = next_item_size as f64;

    let mut score = pr * (1.0 + 0.03 * (pr / cap) * (pr / cap));

    let tightness = 1.0 + 2.6 * progress * progress + 2.4 * progress * progress * progress;
    score *= tightness;

    if post_residual > 0 && post_residual < 10 {
        score += 41.0 * (1.0 - 0.5 * progress);
    } else if post_residual < item_size.min(20) {
        score += 8.0;
    }
    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual <= 5 {
        score -= 31.0 * (1.0 - 0.4 * progress);
    }

    // Lookahead: reward chained fits, penalize blocking the next item
    if nx > 0.0 {
        if pr >= nx {
            score -= 12.0 + 0.25 * nx;
            let chain_gap = pr - nx;
            if chain_gap >= 1.0 && chain_gap <= 42.0 {
                score -= 6.5 + 0.11 * chain_gap;
            }
            let slack = chain_gap / cap;
            if slack < 0.04 {
                score -= 8.5 * (1.0 - slack * 25.0) * (1.0 + progress);
            }
            // mid-gap chaining: residual after nx stays useful
            if chain_gap > 0.04 * cap && chain_gap < 0.18 * cap {
