        if open_bins_count > 6 && mean_residual > 0.4 * cap && progress < 0.6 {
            nb += 5.0 * ((mean_residual - 0.4 * cap) / cap) * (1.0 - progress) * ((open_bins_count as f64 - 6.0).min(8.0) / 8.0);
        }
        // tiny item late in stream should not trigger a fresh bin
        if item_frac < 0.15 && progress > 0.55 && fitting_bins_count >= 1 {
            nb += 6.0 * progress * (1.0 - item_frac / 0.15);
        }
        // NEW: fresh bin leaves margin after nx — discourage when tight margin possible
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin < 0.08 * cap {
                nb -= 5.5 * (1.0 - margin / (0.08 * cap)) * (0.5 + progress);
            }
        }
        // NEW: fresh bin whose leftover cannot fit nx is worse late in stream
        if nx > 0.0 && cap - it > 0.0 && cap - it < nx {
            nb += 4.5 * (1.0 - progress) * ((nx - (cap - it)) / cap).min(0.3) * 10.0;
        }
        score = nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + 0.8 * progress * norm_pr + 0.6 * (1.0 - progress) * norm_pr * norm_pr);

    let mut score = poly * cap;

    // Penalize near-empty bins late in the stream (waste of a fresh bin)
    score += 12.0 * progress * (norm_pr * norm_pr) * cap;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 10.0 * progress * (1.0 - norm_pr) * (1.0 - norm_pr) * cap;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - progress) * (next_item_size as f64 / cap);
    }

    // Slight penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // Dead-space penalty: residuals too small for typical items
    if pr > 0.0 && pr < 10.0 {
        score += 15.0 * (1.0 - pr / 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
