            nb += 5.0 * ((mean_residual - 0.4 * cap) / cap) * (1.0 - progress) * ((open_bins_count as f64 - 6.0).min(8.0) / 8.0);
        }
        // NEW: tiny items late — prefer existing bins
        if item_frac < 0.15 && progress > 0.55 && fitting_bins_count >= 1 {
            nb += 6.0 * progress * (1.0 - item_frac / 0.15);
        }
        score = nb;
    } else {
        // Fine-grained residual fitting with lookahead anticipation
        let fill_ratio = 1.0 - res / cap;
        if waste < 0.08 {
            score -= 48.0 * (1.0 - progress) * (0.08 - waste);
        }
        if fill_ratio > 0.65 {
            score -= 4.8 * (fill_ratio - 0.65) * 10.0 * (0.4 + progress);
        }
        if nx > 0.0 && nx <= pr && pr > 0.0 {
            let gap = (pr - nx) / cap;
            if gap < 0.03 {
                score -= 7.5 * (1.0 - gap * 33.0);
            }
            if gap <= 0.04 {
                score -= 3.2 * (1.0 - gap / 0.04) * (1.0 - progress);
            }
            let chain = 1.0 - gap.min(1.0);
            score -= 5.0 + 4.0 * (nx / cap) + 9.5 * chain * (1.0 - progress);
        }
        if pr > 0.0 && pr < 10.0 {
            score += 41.0 * (1.0 - 0.5 * progress);
        }
        if pr == 0.0 {
            score -= 62.0;
        } else if pr <= 5.0 {
            score -= 31.0 * (1.0 - 0.4 * progress);
        }
        if nx > 0.0 && pr > 0.0 && pr < nx {
            let gap = nx - pr;
            score += gap * (2.0 + 6.5 * (1.0 - progress));
            if gap <= 3.0 {
                score -= 9.0 * (1.0 - progress);
            }
            let closeness = 1.0 - pr / nx;
            score += 3.0 * closeness * closeness * (0.6 + progress);
        }
        let dev = mean_residual - res;
        score += 0.085 * dev;
        if dev > -5.0 && dev < 15.0 && pr > 0.0 {
            score -= 4.2;
        }
        let tight_fit = (pr == 0.0) || (nx > 0.0 && pr == nx);
        if tight_fit {
            score -= 10.5 * (0.3 + progress);
        }
        if nx > 0.0 && pr >= nx {
            let room = pr - nx;
            if room < 0.06 * cap {
                score -= 6.5 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if waste > 0.14 && waste < 0.34 {
            score += 13.0 * (waste - 0.14) * (0.6 + 0.8 * progress);
        }
        if fitting_bins_count > 3 && waste < 0.12 {
            score -= 5.5 * (1.0 - waste * 8.0) * (0.5 + progress);
        }
        if nx > 0.0 && pr > 0.0 && pr > nx && (pr - nx) < 0.02 * cap {
            score -= 4.0 * (1.0 - (pr - nx) / (0.02 * cap)) * (0.4 + progress);
        }
        if pr > 0.0 && (pr as f64).sqrt() < 2.6 {
            score -= 3.5 * (1.0 - progress);
        }
        if waste > 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.09 * cap && progress > 0.4 {
            score -= 4.0 * (1.0 - (pr - nx) / (0.09 * cap)) * progress;
        }
        if pr > 0.0 && nx > 0.0 && pr < nx && (nx - pr) > 0.1 * cap && waste > 0.25 {
            score += 5.0 * (waste - 0.25) * 10.0 * (0.4 + progress);
        }
        if pr > 0.0 && nx > 0.0 && pr < 0.5 * nx && progress > 0.3 {
            score += 3.5 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
        }
        if waste > 0.3 && pr > nx && progress < 0.5 {
            score += 3.0 * (waste - 0.3) * 10.0 * (1.0 - progress);
        }
        if fill_ratio > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
            score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
        }
        if waste > 0.35 && progress > 0.55 && nx > 0.0 && pr >= nx {
            score -= 4.5 * ((pr - nx) / cap).min(0.2) * 5.0 * progress;
        }
        // NEW: near-perfect chain margin (pr - nx just above 0) rewarded
        if nx > 0.0 && pr > nx && (pr - nx) > 0.04 * cap && (pr - nx) < 0.18 * cap {
            score -= 2.2 * (1.0 - ((pr - nx) / (0.18 * cap))) * (0.3 + progress);
        }
        // Scarcity: prefer using existing bins when few can fit
        if fitting_bins_count == 1 {
            score -= 14.0 + 12.0 * progress;
        } else if fitting_bins_count == 2 {
            score -= 4.0 + 3.0 * progress;
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect or near-perfect match with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // exact two-item fill
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 15.0 * (gap / bin_capacity as f64);
        }
    } else {
        // Last item: strongly prefer minimal post_residual.
        score *= 2.0;
    }

    // Penalize dead space relative to mean residual of open bins.
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Tight fit reward.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly unless current bin fit is bad.
    if bin_residual == bin_capacity {
        score += 30.0 - 25.0 * tightness;
    }

    // Late in stream: consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 1 {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio).powi(3);

    // Penalize dead space that cannot host the next item (lookahead).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 + 0.5 * (next_item_size - post_residual) as f64;
        } else {
            // Reward bins that can also host the lookahead item.
            score -= 8.0 * (post_residual as f64 / next_item_size as f64).min(3.0);
        }
    } else {
        // Last item: strongly prefer zero waste.
        score += 0.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize opening new bins mildly, more when many bins already fit.
        let mut penalty = 20.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            penalty += 15.0 * fitting_bins_count as f64;
        }
        // Early stream: slightly more willing to open bins (future flexibility).
        penalty -= 10.0 * (1.0 - progress);
        score += penalty.max(0.0);
    }

    // Prefer bins with residuals close to the item (minimize fragmentation).
    let gap = (bin_residual - item_size) as f64;
    score += 0.15 * gap;

    // Global state coupling: when mean residual is low, conserve tight bins.
    if mean_residual < item_size as f64 && !is_new_bin {
        score -= 6.0;
    }

    // Small item into large residual: discourage wasting space.
    if (item_size as f64) < 0.3 * bin_residual as f64 && !is_new_bin {
        score += 5.0;
    }

    score
}

