pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear waste coupling: penalize residual quadratically, more so late in the stream.
    let norm_post = post / cap;
    score += 6.0 * norm_post * norm_post * (0.5 + progress);

    // Perfect-fit reward: subtract to strongly prefer tight fits.
    if post == 0.0 {
        score -= 40.0;
    } else if post <= 10.0 {
        score -= 18.0 * (1.0 - post / 10.0);
    }

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward if next item fits into resulting residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 12.0 * (1.0 - nxt / post);
        } else {
            score += 4.0 * ((nxt - post) / cap);
        }
    }

    // New-bin candidate: penalize opening a bin, more when good fits exist and early on.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let fit_pressure = 1.0 / (fitting_bins_count as f64 + 1.0);
        score += 25.0 * (1.0 - progress) + 15.0 * fit_pressure;
        // But if residual is large and awkward, opening a new bin may be better:
        score -= 8.0 * (item_size as f64 / cap);
    }

    // Mild penalty for bins far below mean residual (keeps bins balanced).
    score += 2.0 * ((mean_residual - post) / cap).abs();

    // Prefer denser bin portfolios slightly.
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0) * norm_post;

    score
}

