        if fitting_bins_count == 1 {
            score -= 14.0 + 12.0 * progress;
        } else if fitting_bins_count == 2 {
            score -= 4.0 + 3.0 * progress;
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: modulo classes on capacity fractions
    let item_class = item_size / 10; // coarse class 0..=10
    let next_class = if next_item_size > 0 { next_item_size / 10 } else { 0 };

    // Reward tight fits: post_residual small means good packing
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space that is too small for the next item (unusable residue)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
        // Harmonic mismatch: post_residual class cannot host next class
        if post_residual / 10 < next_class {
            score += 8.0;
        }
    }

    // Reward when post_residual exactly matches next item size (perfect chaining)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Reward when post_residual can host next item with room to spare
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Last-chance bonus: only this bin fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Harmonic class complementarity: item class + next class near capacity class
    let pair_class = item_class + next_class;
    if pair_class == 10 {
        score -= 10.0; // item + next exactly fills a bin together
    } else if pair_class > 10 {
        score += 5.0; // pair overflows, expect splitting
    }

    // Penalize leaving odd small residues (harmonic dead zones: 1..9)
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // New-bin candidate handling: only open a new bin if existing fits are poor
    if bin_residual == bin_capacity {
        // Mildly prefer reusing a well-fitting open bin
        score += 4.0;
        // But if mean residual is small (bins nearly full), opening new bin is fine
        if mean_residual < item_size as f64 {
            score -= 8.0;
        }
        // Late in stream with many open bins, avoid bin proliferation
        if open_bins_count > 8 && mean_residual > 40.0 {
            score += 10.0;
        }
    }

    // Small progression coupling: encourage consolidation early, tighter fits later
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

