    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (gaps too small for typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }
    // Reward fits that leave room for the next item (lookahead k=2)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize gaps that cannot fit the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0;
    }
    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }
    // Open-bin pressure: fewer open bins -> prefer packing into existing bins
    score += open_bins_count as f64 * 0.5;
    // Slight preference for bins below mean residual (tighter bins first)
    score += (mean_residual - bin_residual as f64) * 0.1;
    // Prefer using bins with larger current fill (smaller residual)
    score += (bin_residual as f64) * 0.05;

    score
}

