        if nx > 0.0 && mean_residual > nx {
            let excess = mean_residual - nx;
            if excess < 0.05 * cap && progress < 0.55 {
                nb += 5.0 * (1.0 - excess / (0.05 * cap)) * (1.0 - progress);
            }
        }
        if fitting_bins_count == 0 && progress > 0.25 {
            nb += 9.0 + 7.0 * progress;
        }
        if nx > 0.0 && it + nx > cap && mean_residual >= nx {
            nb += 6.0 * (1.0 - progress);
        }
        if progress > 0.75 && fitting_bins_count > 0 && mean_residual >= it {
            nb += 5.5 + 4.5 * progress;
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_left = mean_residual - it;
            if best_left >= nx && (best_left - nx) < 12.0 {
                nb += 4.0 * (1.0 - (best_left - nx) / 12.0) * (0.5 + progress);
            }
        }
        if it < 0.2 * cap && progress < 0.3 && open_bins_count < 6 {
            nb += 7.0 * (1.0 - progress);
        }
        if item_frac > 0.6 && nx > 0.0 && cap >= it + nx && cap - it - nx < 0.03 * cap {
            nb -= 5.5 * (1.0 - (cap - it - nx) / (0.03 * cap));
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_pr = (mean_residual - it).max(0.0);
            if best_pr > 0.0 && best_pr < 0.06 * cap && (cap - it) >= nx {
                nb -= 7.0 * (1.0 - best_pr / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if progress > 0.85 && mean_residual < 0.15 * cap {
            nb += 7.0 * progress * (1.0 - mean_residual / (0.15 * cap));
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_post = (mean_residual - it).max(0.0);
            if best_post >= nx && best_post - nx > 0.18 * cap && progress > 0.35 {
                nb -= 6.0 * ((best_post - nx) / cap).min(0.4) * (0.4 + progress);
            }
        }
        if item_frac > 0.45 && item_frac < 0.75 && progress > 0.5 {
            nb -= 5.0 * (item_frac - 0.45) * progress;
        }
        if fitting_bins_count >= 2 && mean_residual < 0.25 * cap && progress > 0.6 {
            nb += 6.0 * (1.0 - mean_residual / (0.25 * cap)) * progress;
        }
        if fitting_bins_count >= 3 && mean_residual - it >= nx && progress > 0.5 {
            nb += 4.5 * progress * (1.0 - ((mean_residual - it - nx) / cap).min(1.0));
        }
        if open_bins_count > 10 && progress < 0.35 && item_frac < 0.3 {
            nb += 6.0 * (1.0 - progress) * (1.0 - item_frac / 0.3);
        }
        // dead sliver relative to next item; prefer chainable space
        if nx > 0.0 {
            let r1 = cap - it;
            if r1 < nx && r1 > 0.0 {
                nb += (1.0 + 2.0 * progress) * (nx - r1) * 0.55;
            }
            if r1 >= nx && (r1 - nx) > 0.25 * cap && progress > 0.45 {
                nb += 4.5 * ((r1 - nx) / cap).min(0.5) * progress;
            }
        }
        // fragmented mean residual: fresh bin chaining it+nx tightly is attractive
        if nx > 0.0 && cap >= it + nx && (cap - it - nx) < 0.08 * cap && progress > 0.3 {
            nb -= 5.0 * (1.0 - (cap - it - nx) / (0.08 * cap)) * (0.5 + progress);
        }
        // NEW: wide margin after chain is wasteful — moderate penalty
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin >= 0.08 * cap && margin < 0.2 * cap && progress > 0.25 {
                nb += 3.0 * ((margin - 0.08 * cap) / (0.12 * cap)).min(1.0) * (0.4 + progress);
            }
        }
        // NEW: when mean residual is large (fragmented), discourage new bins early
        if open_bins_count > 6 && mean_residual > 0.4 * cap && progress < 0.6 {
            nb += 5.0 * ((mean_residual - 0.4 * cap) / cap) * (1.0 - progress) * ((open_bins_count as f64 - 6.0).min(8.0) / 8.0);
        }
        // NEW: tiny items late — prefer existing bins strongly
        if item_frac < 0.15 && progress > 0.55 && fitting_bins_count >= 1 {
            nb += 6.0 * progress * (1.0 - item_frac / 0.15);
        }
        score = nb;
    } else {
        // Fine-grained residual fitting with lookahead anticipation
        let fill_ratio = 1.0 - res / cap;
        if waste < 0.08 {
            score -= 48.0 * (1.0 - progress) * (0.08 - waste);
        }
        if fill_ratio > 0.65 {
            score -= 4.8 * (fill_ratio - 0.65) * 10.0 * (0.4 + progress);
        }
        if nx > 0.0 && nx <= pr && pr > 0.0 {
            let gap = (pr - nx) / cap;
            if gap < 0.03 {
                score -= 7.5 * (1.0 - gap * 33.0);
            }
            if gap <= 0.04 {
                score -= 3.2 * (1.0 - gap / 0.04) * (1.0 - progress);
            }
            let chain = 1.0 - gap.min(1.0);
            score -= 5.0 + 4.0 * (nx / cap) + 9.5 * chain * (1.0 - progress);
        }
        if pr > 0.0 && pr < 10.0 {
            score += 41.0 * (1.0 - 0.5 * progress);
        }
        if pr == 0.0 {
            score -= 62.0;
        } else if pr <= 5.0 {
            score -= 31.0 * (1.0 - 0.4 * progress);
        }
        if nx > 0.0 && pr > 0.0 && pr < nx {
            let gap = nx - pr;
            score += gap * (2.0 + 6.5 * (1.0 - progress));
            if gap <= 3.0 {
                score -= 9.0 * (1.0 - progress);
            }
            // sharpened dead-space penalty: residual slightly below next item is worst
            let closeness = 1.0 - pr / nx;
            score += 3.0 * closeness * closeness * (0.6 + progress);
            // NEW: extend penalty band with scaled dead-ratio term
            let dead_ratio = (pr / cap).max(0.0);
            score += (10.5 + 3.2 * progress) * dead_ratio * dead_ratio * cap * (0.45 + progress);
        }
        let dev = mean_residual - res;
        score += 0.085 * dev;
        if dev > -5.0 && dev < 15.0 && pr > 0.0 {
            score -= 4.2;
        }
        let tight_fit = (pr == 0.0) || (nx > 0.0 && pr == nx);
        if tight_fit {
            score -= 10.5 * (0.3 + progress);
        }
        if nx > 0.0 && pr >= nx {
            let room = pr - nx;
            if room < 0.06 * cap {
                score -= 6.5 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if waste > 0.14 && waste < 0.34 {
            score += 13.0 * (waste - 0.14) * (0.6 + 0.8 * progress);
        }
        if fitting_bins_count > 3 && waste < 0.12 {
            score -= 5.5 * (1.0 - waste * 8.0) * (0.5 + progress);
        }
        if nx > 0.0 && pr > 0.0 && pr > nx && (pr - nx) < 0.02 * cap {
            score -= 4.0 * (1.0 - (pr - nx) / (0.02 * cap)) * (0.4 + progress);
        }
        if pr > 0.0 && (pr as f64).sqrt() < 2.6 {
            score -= 3.5 * (1.0 - progress);
        }
        if waste > 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.09 * cap && progress > 0.4 {
            score -= 4.0 * (1.0 - (pr - nx) / (0.09 * cap)) * progress;
        }
        if pr > 0.0 && nx > 0.0 && pr < nx && (nx - pr) > 0.1 * cap && waste > 0.25 {
            score += 5.0 * (waste - 0.25) * 10.0 * (0.4 + progress);
        }
        if pr > 0.0 && nx > 0.0 && pr < 0.5 * nx && progress > 0.3 {
            score += 3.5 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
        }
        if waste > 0.3 && pr > nx && progress < 0.5 {
            score += 3.0 * (waste - 0.3) * 10.0 * (1.0 - progress);
        }
        if fill_ratio > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
            score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
        }
        if waste > 0.35 && progress > 0.55 && nx > 0.0 && pr >= nx {
            score -= 4.5 * ((pr - nx) / cap).min(0.2) * 5.0 * progress;
        }
        // NEW: chain-gap shaping borrowed from lookahead: exact leftover just above nx
        if nx > 0.0 && pr > nx && (pr - nx) <= 0.04 * cap {
            score -= 3.2 * (1.0 - (pr - nx) / (0.04 * cap)) * (1.0 - progress);
        }
        if nx > 0.0 && pr > nx && (pr - nx) > 0.04 * cap && (pr - nx) < 0.18 * cap {
            score -= 2.2 * (1.0 - ((pr - nx) / (0.18 * cap))) * (0.3 + progress);
        }
        // NEW: prefer bins whose post-residual can chain with next item exactly
        if nx > 0.0 && pr >= nx && (pr - nx) < 0.5 * nx && progress > 0.6 {
            score -= 2.8 * (1.0 - (pr - nx) / (0.5 * nx)) * progress;
        }
        // Scarcity: prefer using existing bins when few can fit
        if fitting_bins_count == 1 {
            score -= 14.0 + 12.0 * progress;
        } else if fitting_bins_count == 2 {
            score -= 4.0 + 3.0 * progress;
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { (step_index as f64 / total_items as f64).clamp(0.0, 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;
    let is_new_bin = (res - cap).abs() < 1e-9;
    let urgency = progress * progress * (3.0 - 2.0 * progress);
    let x = pr / cap;

    if is_new_bin {
        // ---- New-bin candidate scoring (borrowed structure from best heuristic) ----
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let item_frac = (it / cap).min(1.0);
        let mut nb = cap * (1.35 + 1.15 * progress);
        nb -= 26.0 * scarcity * (1.0 - progress);
        nb -= 19.0 * item_frac * (1.0 - progress);
        if nx >= 0.5 * cap { nb -= 12.0 * progress + 6.0 * (1.0 - progress); }
        nb += 15.0 * progress * (1.0 - item_frac);
        if it >= cap - 1.0 { nb -= 32.0; }
        if nx > 0.0 && cap - it >= nx { nb -= 10.5 + 0.11 * (cap - it - nx); }
        if fitting_bins_count <= 2 { nb += 21.0 + 10.0 * (1.0 - progress); }
        if fitting_bins_count >= 4 { nb -= 6.5 + 8.5 * progress; }
        if nx > 0.0 && mean_residual > nx + 8.0 && progress < 0.7 {
            nb += 8.5 * ((mean_residual - nx) / cap).min(0.5) * cap * 0.1;
        }
        if mean_residual >= it && progress > 0.5 { nb += 6.5 + 8.5 * progress; }
        if nx > it && mean_residual >= nx && progress < 0.6 { nb += 10.0 * (1.0 - progress); }
        if it > 0.85 * cap && progress > 0.3 { nb -= 9.0 * progress; }
        if fitting_bins_count == 0 && progress > 0.25 { nb += 9.0 + 7.0 * progress; }
        if nx > 0.0 && it + nx > cap && mean_residual >= nx { nb += 6.0 * (1.0 - progress); }
        if progress > 0.75 && fitting_bins_count > 0 && mean_residual >= it { nb += 5.5 + 4.5 * progress; }
        if it < 0.2 * cap && progress < 0.3 && open_bins_count < 6 { nb += 7.0 * (1.0 - progress); }
        if nx > 0.0 && cap >= it + nx && (cap - it - nx) < 0.08 * cap && progress > 0.3 {
            nb -= 5.0 * (1.0 - (cap - it - nx) / (0.08 * cap)) * (0.5 + progress);
        }
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin < 0.15 * cap { nb -= 6.0 * (1.0 - margin / (0.15 * cap)) * (0.6 + 0.4 * progress); }
        }
        if open_bins_count > 12 && progress > 0.6 && item_frac < 0.25 {
            nb += 5.0 * progress * (1.0 - item_frac / 0.25);
        }
        return nb;
    }

    // ---- Existing-bin scoring: parent base + best-heuristic couplings ----
    let mut score = pr * (1.0 + 0.03 * x * x);

    // Tightness ramp with progress (stronger packing pressure later)
    let tightness = 1.0 + 2.6 * progress * progress + 2.4 * progress * progress * progress;
    score *= tightness;

    // Parent's cubic dead-space penalty, scaled up and progress-weighted
    score += (10.5 + 3.2 * progress) * (1.0 - x) * (1.0 - x) * (1.0 - x) * (0.45 + progress);

    // Exact / near-exact fit rewards
    if pr == 0.0 {
        score -= 62.0;
    } else if pr <= 5.0 {
        score -= 31.0 * (1.0 - 0.4 * progress);
    }
    if x > 0.0 && x < 0.12 {
        score -= 9.0 * (1.0 - x / 0.12) * (0.4 + progress);
    }
    if nx > 0.0 && pr == nx {
        score -= 10.5 * (0.3 + progress);
    }

    // Lookahead couplings
    if nx > 0.0 {
        if pr < nx {
            let gap = nx - pr;
            score += gap * (2.0 + 6.5 * (1.0 - progress));
            let closeness = 1.0 - pr / nx;
            score += 3.0 * closeness * closeness * (0.6 + progress);
            if nx - pr <= 3.0 { score -= 9.0 * (1.0 - progress); }
        } else {
            let chain_gap = pr - nx;
            let slack = chain_gap / cap;
            if chain_gap <= 42.0 { score -= 6.5 + 0.11 * chain_gap; }
            if slack < 0.04 { score -= 8.5 * (1.0 - slack * 25.0) * (1.0 + progress); }
            let chain = 1.0 - slack.min(1.0);
            score -= 5.0 + 4.0 * (nx / cap) + 9.5 * chain * (1.0 - progress);
        }
        if pr >= nx {
            let room = pr - nx;
            if room < 0.06 * cap {
                score -= 6.5 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
            }
        }
    }

    // Scarcity bonus: last fitting bin gets strong preference
    if fitting_bins_count == 1 {
        score -= 1.5;
    } else if fitting_bins_count > 1 {
        score -= 0.3 / fitting_bins_count as f64;
    }

    // Fragmentation guard: many open bins with low mean residual -> penalize waste
    let mr = (mean_residual / cap).min(1.0);
    score += 2.5 * (1.0 - mr) * (open_bins_count as f64).sqrt() * 0.1;
    score -= 0.42 * (open_bins_count as f64).ln().max(0.0);

    // Waste-band penalties (mid-range residuals are the big bin-wasters)
    if x > 0.14 && x < 0.34 {
        score += 13.0 * (x - 0.14) * (0.6 + 0.8 * progress);
    }
    if x > 0.3 && x < 0.5 && pr == (pr as u32) as f64 && it >= pr && pr > 0.0 && progress > 0.45 {
        score += 2.6 * (1.0 - pr / it.max(1.0)) * progress;
    }

    // Mean-residual deviation pull
    let dev = mean_residual - res;
    score += 0.085 * dev;
    if dev > -5.0 && dev < 15.0 && pr > 0.0 { score -= 4.2; }

    // High-fill preference
    let fill_ratio = 1.0 - res / cap;
    if fill_ratio > 0.65 {
        score -= 4.8 * (fill_ratio - 0.65) * 10.0 * (0.4 + progress);
    }

    // Tie-break smooth tightness kernel (parent, weakened)
    let t = (res - it) / cap;
    score += 0.08 * t * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space non-linearly: small leftovers are wasteful.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let dead = if pr < 10.0 { 60.0 } else if pr < 20.0 { 25.0 } else { 0.0 };
        score += dead;
        // Waste grows quadratically with leftover size relative to smallest possible item (1).
        score += (pr * pr) / (bin_capacity as f64);
    } else {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // next fits: leftover after next item; reward tight chains.
            let pr2 = post_residual - next_item_size;
            score -= 20.0 - (pr2 as f64) * 0.3;
        } else {
            // next item won't fit here: slight penalty proportional to gap.
            score += ((next_item_size - post_residual) as f64) * 0.1;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Prefer fuller bins: deviation from mean residual.
    let dev = (bin_residual as f64) - mean_residual;
    score += dev * 0.5;

    // Early in the stream, be more willing to open new bins (exploration);
    // later, consolidate tightly.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline so it wins only when fits are poor.
        score = 90.0 + (1.0 - t) * 30.0 + (open_bins_count as f64) * 0.5;
        // If the item would leave a tight residual, opening a new bin is bad.
        if post_residual <= 20 && item_size <= bin_capacity {
            score += 40.0;
        }
        // Lookahead synergy: fresh bin fits next item too.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 25.0;
        }
    } else {
        // Later in the stream, reward using existing bins more aggressively.
        score -= t * 15.0;
        // Many open bins: encourage consolidation into them.
        score -= (open_bins_count as f64).min(20.0) * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear (quadratic/cubic) shaping
    let mut score = 3.0 * norm_pr + 2.0 * norm_pr * norm_pr + 4.0 * norm_pr.powi(3);

    // Stream-progress coupling: later in stream, penalize waste more strongly
    score += progress * 6.0 * norm_pr * norm_pr;

    // Dead-space penalty: residuals too small to fit plausible future items
    let dead = if pr > 0.0 { (-norm_pr * 8.0).exp() } else { 0.0 };
    score += dead * (1.0 + 2.0 * progress);

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = if pr as f64 >= nx { 1.0 } else { 0.0 };
        let slack_match = 1.0 - ((pr as f64 - nx) / cap).abs();
        score -= 2.5 * fit_next * slack_match.max(0.0);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 4.0;
    }

    // Mild penalty when many bins are open and this bin is very full (fragmentation control)
    let open_norm = open_bins_count as f64;
    score += 0.3 * open_norm * norm_pr * norm_pr;

    // Mean-residual coupling: penalize bins far from the mean residual (balance)
    score += 0.5 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: make empty-bin attractive only when item is large relative to residual options
    if bin_residual == bin_capacity {
        let big = item_size as f64 / cap;
        score = 2.0 + 6.0 * big * (1.0 - progress) - 3.0 * big * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;

    let mut score = pr * (1.0 + 0.03 * (pr / cap) * (pr / cap));

    let tightness = 1.0 + 2.6 * progress * progress + 2.4 * progress * progress * progress;
    score *= tightness;

    if nx > 0.0 {
        if pr < nx {
            let gap = nx - pr;
            score += gap * (2.0 + 6.5 * (1.0 - progress));
            // near-miss relief: bin is nearly perfect for the pair
            if gap <= 3.0 {
                score -= 9.0 * (1.0 - progress);
            }
            // closeness shaping
            let closeness = 1.0 - pr / nx;
            score += 3.0 * closeness * closeness * (0.6 + progress);
            if gap <= 0.04 * cap {
                score += 3.5 * (1.0 - gap / (0.04 * cap)) * (0.5 + progress);
            }
            if gap > 0.1 * cap && pr / cap > 0.25 {
                score += 5.0 * (pr / cap - 0.25) * 10.0 * (0.4 + progress);
            }
        } else {
            let chain_gap = pr - nx;
            let slack = chain_gap / cap;
            if chain_gap <= 42.0 {
                score -= 6.5 + 0.11 * chain_gap;
            }
            if slack < 0.04 {
                score -= 8.5 * (1.0 - slack * 25.0) * (1.0 + progress);
            }
            let chain = 1.0 - slack.min(1.0);
            score -= 5.0 + 4.0 * (nx / cap) + 9.5 * chain * (1.0 - progress);
            if slack > 0.04 * 0.0 && slack < 0.06 {
                score -= 6.5 * (1.0 - slack / 0.06) * (0.5 + progress);
            }
            if slack > 0.06 && slack < 0.18 {
                score -= 2.2 * (1.0 - slack / 0.18) * (0.3 + progress);
            }
            if slack > 0.18 && slack < 0.22 && fitting_bins_count <= 2 {
                score -= 2.0 * (1.0 - slack / 0.22) * (0.6 + progress);
            }
        }
    }

    // Dead-space penalty, smooth, with unusable-space weighting
    let dead_ratio = (pr / cap).max(0.0);
    let unusable = if nx > 0.0 && pr > 0.0 && pr < nx { 1.0 } else { 0.55 };
    score += (10.5 + 3.2 * progress) * dead_ratio * dead_ratio * cap * (0.45 + progress) * unusable;
    if dead_ratio > 0.0 && dead_ratio < 0.12 {
        score -= 9.0 * (1.0 - dead_ratio / 0.12) * (0.4 + progress);
    }
    if dead_ratio > 0.12 && dead_ratio < 0.3 {
        score += 3.5 * (dead_ratio - 0.12) * (0.5 + progress);
    }

    if bin_residual < bin_capacity {
        let fill_ratio = 1.0 - res / cap;
        let waste = pr / cap;
        if waste < 0.08 && pr > 0.0 {
            score -= 48.0 * (1.0 - progress) * (0.08 - waste);
        }
        if fill_ratio > 0.65 {
            score -= 4.8 * (fill_ratio - 0.65) * 10.0 * (0.4 + progress);
        }
        if pr == 0.0 {
            score -= 62.0;
        } else if pr <= 5.0 {
            score -= 31.0 * (1.0 - 0.4 * progress);
        } else if pr < 10.0 {
            score += 41.0 * (1.0 - 0.5 * progress);
        }
        if pr > 0.0 && (pr as f64).sqrt() < 2.6 {
            score -= 3.5 * (1.0 - progress);
        }
        let dev = mean_residual - res;
        score += 0.085 * dev;
        if dev > -5.0 && dev < 15.0 && pr > 0.0 {
            score -= 4.2;
        }
        let tight_fit = (pr == 0.0) || (nx > 0.0 && pr == nx);
        if tight_fit {
            score -= 10.5 * (0.3 + progress);
        }
        if waste > 0.14 && waste < 0.34 {
            score += 13.0 * (waste - 0.14) * (0.6 + 0.8 * progress);
        }
        if fitting_bins_count > 3 && waste < 0.12 && waste > 0.0 {
            score -= 5.5 * (1.0 - waste * 8.0) * (0.5 + progress);
        }
        if waste > 0.05 && waste < 0.14 && pr >= nx && nx > 0.0 && progress > 0.5 {
            score -= 2.4 * (1.0 - (waste - 0.05) / 0.09) * progress;
        }
        // Scarcity: discourage opening new bins when few fit
        if fitting_bins_count == 1 {
            score -= 14.0 + 12.0 * progress;
        } else if fitting_bins_count == 2 {
            score -= 4.0 + 3.0 * progress;
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }

    // NEW-BIN CANDIDATE scoring
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let item_frac = (it / cap).min(1.0);
        let mut nb = cap * (1.35 + 1.15 * progress);
        nb -= 26.0 * scarcity * (1.0 - progress);
        nb -= 19.0 * item_frac * (1.0 - progress);
        if nx >= 0.5 * cap {
            nb -= 12.0 * progress + 6.0 * (1.0 - progress);
        }
        nb += 15.0 * progress * (1.0 - item_frac);
        if it >= cap - 1.0 {
            nb -= 32.0;
        }
        if nx > 0.0 && cap - it >= nx {
            nb -= 10.5 + 0.11 * (cap - it - nx);
        }
        if nx > 0.0 {
            let r1 = cap - it;
            if r1 >= nx && (r1 - nx) < 6.0 && (r1 - nx) > 0.0 {
                nb += 8.5 * (1.0 - progress);
            }
            if r1 < nx && r1 > 0.0 {
                nb += (1.0 + 2.0 * progress) * (nx - r1) * 0.55;
            }
            if r1 >= nx && (r1 - nx) > 0.25 * cap && progress > 0.45 {
                nb += 4.5 * ((r1 - nx) / cap).min(0.5) * progress;
            }
            if r1 < nx && r1 > 0.0 {
                nb += 4.5 * (1.0 - progress) * ((nx - r1) / cap).min(0.3) * 10.0;
            }
            if cap >= it + nx {
                let margin = cap - it - nx;
                if margin < 0.15 * cap {
                    nb -= 6.0 * (1.0 - margin / (0.15 * cap)) * (0.6 + 0.4 * progress);
                }
                if margin < 0.08 * cap && progress > 0.3 {
                    nb -= 5.0 * (1.0 - margin / (0.08 * cap)) * (0.5 + progress);
                }
            }
        }
        if fitting_bins_count <= 2 {
            nb += 21.0 + 10.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 4 {
            nb -= 6.5 + 8.5 * progress;
        }
        if nx > 0.0 && mean_residual > nx + 8.0 && progress < 0.7 {
            nb += 8.5 * ((mean_residual - nx) / cap).min(0.5) * cap * 0.1;
        }
        if mean_residual >= it && progress > 0.5 {
            nb += 6.5 + 8.5 * progress;
        }
        if nx > it && mean_residual >= nx && progress < 0.6 {
            nb += 10.0 * (1.0 - progress);
        }
        if nx > 0.0 && mean_residual >= it + nx && progress < 0.6 {
            nb -= 5.5 * (1.0 - progress) * ((mean_residual - it - nx) / cap).min(0.3) * 10.0;
        }
        if it > 0.85 * cap && progress > 0.3 {
            nb -= 9.0 * progress;
        }
        if nx > 0.0 && mean_residual > nx {
            let excess = mean_residual - nx;
            if excess < 0.05 * cap && progress < 0.55 {
                nb += 5.0 * (1.0 - excess / (0.05 * cap)) * (1.0 - progress);
            }
        }
        if fitting_bins_count == 0 && progress > 0.25 {
            nb += 9.0 + 7.0 * progress;
        }
        if nx > 0.0 && it + nx > cap && mean_residual >= nx {
            nb += 6.0 * (1.0 - progress);
        }
        if progress > 0.75 && fitting_bins_count > 0 && mean_residual >= it {
            nb += 5.5 + 4.5 * progress;
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_left = mean_residual - it;
            if best_left >= nx && (best_left - nx) < 12.0 {
                nb += 4.0 * (1.0 - (best_left - nx) / 12.0) * (0.5 + progress);
            }
            let leftover = best_left - nx;
            if leftover >= 0.0 && leftover < 0.1 * cap && progress > 0.45 {
                nb -= 5.0 * (1.0 - leftover / (0.1 * cap)) * progress;
            }
            let best_post = best_left.max(0.0);
            if best_post > 0.0 && best_post < 0.06 * cap && (cap - it) >= nx {
                nb -= 7.0 * (1.0 - best_post / (0.06 * cap)) * (0.5 + progress);
            }
            if best_post >= nx && best_post - nx > 0.18 * cap && progress > 0.35 {
                nb -= 6.0 * ((best_post - nx) / cap).min(0.4) * (0.4 + progress);
            }
        }
        if it < 0.2 * cap && progress < 0.3 && open_bins_count < 6 {
            nb += 7.0 * (1.0 - progress);
        }
        if it / cap > 0.6 && nx > 0.0 && cap >= it + nx && cap - it - nx < 0.03 * cap {
            nb -= 5.5 * (1.0 - (cap - it - nx) / (0.03 * cap));
        }
        if progress > 0.85 && mean_residual < 0.15 * cap {
            nb += 7.0 * progress * (1.0 - mean_residual / (0.15 * cap));
        }
        if item_frac > 0.45 && item_frac < 0.75 && progress > 0.5 {
            nb -= 5.0 * (item_frac - 0.45) * progress;
        }
        if fitting_bins_count >= 2 && mean_residual < 0.25 * cap && progress > 0.6 {
            nb += 6.0 * (1.0 - mean_residual / (0.25 * cap)) * progress;
        }
        if fitting_bins_count >= 3 && mean_residual - it >= nx && progress > 0.5 {
            nb += 4.5 * progress * (1.0 - ((mean_residual - it - nx) / cap).min(1.0));
        }
        if open_bins_count > 10 && progress < 0.35 && item_frac < 0.3 {
            nb += 6.0 * (1.0 - progress) * (1.0 - item_frac / 0.3);
        }
        if open_bins_count > 6 && mean_residual > 0.4 * cap && progress < 0.6 {
            nb += 5.0 * ((mean_residual - 0.4 * cap) / cap) * (1.0 - progress) * ((open_bins_count as f64 - 6.0).min(8.0) / 8.0);
        }
        if item_frac < 0.15 && progress > 0.55 && fitting_bins_count >= 1 {
            nb += 6.0 * progress * (1.0 - item_frac / 0.15);
        }
        if open_bins_count > 12 && progress > 0.6 && item_frac < 0.25 {
            nb += 5.0 * progress * (1.0 - item_frac / 0.25);
        }
        if fitting_bins_count >= 2 && mean_residual >= it + nx && progress > 0.4 {
            let rem = mean_residual - it - nx;
            if rem < 0.05 * cap {
                nb -= 4.5 * (1.0 - rem / (0.05 * cap)) * progress;
            }
        }
        if fitting_bins_count == 1 && mean_residual >= it && (mean_residual - it) < 0.04 * cap && progress > 0.3 {
            nb -= 3.0 * (1.0 - (mean_residual - it) / (0.04 * cap)) * (0.5 + progress);
        }
        if open_bins_count > 8 && mean_residual < 0.1 * cap && progress > 0.5 {
            nb -= 4.0 * (1.0 - mean_residual / (0.1 * cap)) * progress;
        }
        score = nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lies in
    // "usable" residue classes (small, re-fillable gaps) are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: post_residual divisible by 10 (clean harmonic slot, e.g. 0/10/20...)
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    // Class B: post_residual divisible by 5 but not 10 (half-harmonic)
    else if post_residual % 5 == 0 {
        score -= 3.0;
    }
    // Class C: tiny dead space (< 10) is nearly unusable for items >= 10
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fill is the ideal outcome
    if post_residual == 0 {
        score -= 40.0;
    }

    // Integer-division thresholds: how many "typical" items (size >= 10) fit in the gap
    let slots = post_residual / 10;
    score -= slots as f64 * 4.0;

    // Coupling with lookahead: does the gap hold the next item exactly / at all?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect follow-up fill
        } else if next_item_size < post_residual {
            score -= 8.0; // next item still fits
            // harmonic bonus: next item leaves a clean residue class again
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 6.0;
            }
        } else {
            score += 10.0; // next item cannot use this gap
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is huge
    // relative to capacity or the stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 - 10.0 * progress;
        if item_size as f64 > 0.6 * cap {
            score -= 18.0;
        }
        // opening a bin when many are open wastes fragmentation
        score += (open_bins_count as f64).sqrt() * 2.0;
    }

    // Mild pull toward bins near the mean residual (balanced packing)
    score += (pr - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
