pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // matches the next item's size (perfect chain placement).
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_gap = post_residual - next_item_size;
        score -= 30.0 * (1.0 - match_gap as f64 / 100.0);
    } else if next_item_size > 0 {
        // Next item won't fit in this bin after placement: penalize dead space.
        score += 0.35 * (next_item_size as f64 - post_residual as f64);
    }

    // Penalize tiny unusable leftovers (< smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward tight fits relative to mean residual.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: only bin that fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless current placement is bad.
    if bin_residual == bin_capacity {
        score += 60.0;
        // Late in the stream, opening a fresh bin is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
    }

    // Mild preference for fuller bins overall.
    score -= 0.1 * (bin_residual as f64 - post_residual as f64);

    score
}

