            }
        }
        if it < 0.2 * cap && progress < 0.3 && open_bins_count < 6 {
            nb += 7.0 * (1.0 - progress);
        }
        if it / cap > 0.6 && nx > 0.0 && cap >= it + nx && cap - it - nx < 0.03 * cap {
            nb -= 5.5 * (1.0 - (cap - it - nx) / (0.03 * cap));
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_pr = (mean_residual - it).max(0.0);
            if best_pr > 0.0 && best_pr < 0.06 * cap && (cap - it) >= nx {
                nb -= 7.0 * (1.0 - best_pr / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if progress > 0.85 && mean_residual < 0.15 * cap {
            nb += 7.0 * progress * (1.0 - mean_residual / (0.15 * cap));
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_post = (mean_residual - it).max(0.0);
            if best_post >= nx && best_post - nx > 0.18 * cap && progress > 0.35 {
                nb -= 6.0 * ((best_post - nx) / cap).min(0.4) * (0.4 + progress);
            }
        }
        if item_frac > 0.45 && item_frac < 0.75 && progress > 0.5 {
            nb -= 5.0 * (item_frac - 0.45) * progress;
        }
        if fitting_bins_count >= 2 && mean_residual < 0.25 * cap && progress > 0.6 {
            nb += 6.0 * (1.0 - mean_residual / (0.25 * cap)) * progress;
        }
        if fitting_bins_count >= 3 && mean_residual - it >= nx && progress > 0.5 {
            nb += 4.5 * progress * (1.0 - ((mean_residual - it - nx) / cap).min(1.0));
        }
        if open_bins_count > 10 && progress < 0.35 && item_frac < 0.3 {
            nb += 6.0 * (1.0 - progress) * (1.0 - item_frac / 0.3);
        }
        if open_bins_count > 6 && mean_residual > 0.4 * cap && progress < 0.6 {
            nb += 5.0 * ((mean_residual - 0.4 * cap) / cap) * (1.0 - progress) * ((open_bins_count as f64 - 6.0).min(8.0) / 8.0);
        }
        if item_frac < 0.15 && progress > 0.55 && fitting_bins_count >= 1 {
            nb += 6.0 * progress * (1.0 - item_frac / 0.15);
        }
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin < 0.15 * cap {
                nb -= 6.0 * (1.0 - margin / (0.15 * cap)) * (0.6 + 0.4 * progress);
            }
        }
        if nx > 0.0 && fitting_bins_count >= 1 && mean_residual - it >= nx {
            let leftover = mean_residual - it - nx;
            if leftover < 0.1 * cap && progress > 0.45 {
                nb -= 5.0 * (1.0 - leftover / (0.1 * cap)) * progress;
            }
        }
        if open_bins_count > 12 && progress > 0.6 && item_frac < 0.25 {
            nb += 5.0 * progress * (1.0 - item_frac / 0.25);
        }
        if nx > 0.0 && fitting_bins_count >= 1 && (cap - it) >= nx && (cap - it - nx) < 0.05 * cap && progress < 0.5 {
            nb -= 4.0 * (1.0 - (cap - it - nx) / (0.05 * cap)) * (1.0 - progress);
        }
        if fitting_bins_count == 1 && mean_residual >= it && (mean_residual - it) < 0.04 * cap && progress > 0.3 {
            nb -= 3.0 * (1.0 - (mean_residual - it) / (0.04 * cap)) * (0.5 + progress);
        }
        if open_bins_count > 8 && mean_residual < 0.1 * cap && progress > 0.5 {
            nb -= 4.0 * (1.0 - mean_residual / (0.1 * cap)) * progress;
        }
        score = nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space, amplified for large items.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= (post_residual as f64).powi(2) / bin_capacity as f64 * (0.5 + fill_ratio);

    // Last-chance bonus: strongly favor the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0 + 0.5 * item_size as f64;
    }

    // Many open bins: discourage fragmenting further; prefer consolidating into fuller bins.
    score += open_bins_count as f64 * 0.35;

    // Global pressure: when mean residual is low, preserve bins with large residuals
    // for future large items; when mean residual is high, prefer using spacious bins.
    if mean_residual > 0.0 {
        let dev = bin_residual as f64 - mean_residual;
        if post_residual < 10 {
            // Dead space creation: unusable slivers are costly.
            score += 25.0;
        } else if post_residual < 20 {
            score += 8.0;
        }
        // Penalize consuming a bin whose residual far exceeds the average
        // (it may be the only one able to host a big future item).
        score += 0.15 * dev.max(0.0);
        // Slight reward for using below-average-residual bins (already fragmented).
        score -= 0.05 * (-dev).max(0.0);
    }

    // Lookahead: if the next item would fit exactly into the post-residual,
    // reward this placement (chain fit). If next item is large and this bin
    // is one of few with big residual, penalize consuming it.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 40.0;
        } else if next_item_size as i64 - post_residual as i64 == 0 {
            score -= 40.0;
        } else if (next_item_size as f64 - post_residual as f64).abs() <= 3.0 {
            score -= 15.0;
        }
        if next_item_size > post_residual && post_residual >= item_size && bin_residual > 60 {
            score += 5.0; // keeping big residual may help next item elsewhere anyway
        }
        if next_item_size <= post_residual && post_residual - next_item_size < 5 {
            score -= 20.0;
        }
    }

    // Time horizon: early in the stream, be conservative with new bins;
    // late in the stream, allow tighter packing to dominate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * progress;

    // New-bin candidate (empty bin): only attractive when item is large and
    // no open bin fits well, or when open-bin population is huge.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 > 0.7 * bin_capacity as f64;
        if big_item || open_bins_count > 12 {
            score -= 10.0 + 0.3 * item_size as f64;
        } else {
            score += 55.0; // prefer existing bins for small/medium items
        }
    }

    score
}

