            if r1 < nx && r1 > 0.0 {
                nb += (1.0 + 2.0 * progress) * (nx - r1) * 0.55;
            }
            if r1 >= nx && (r1 - nx) > 0.25 * cap && progress > 0.45 {
                nb += 4.5 * ((r1 - nx) / cap).min(0.5) * progress;
            }
        }
        // Chainable it+nx tightly is attractive when fragmented.
        if nx > 0.0 && cap >= it + nx && (cap - it - nx) < 0.08 * cap && progress > 0.3 {
            nb -= 5.0 * (1.0 - (cap - it - nx) / (0.08 * cap)) * (0.5 + progress);
        }
        // NEW: discourage opening a bin whose first residual is unusable for nx
        // (mirrors the open-bin dead-space shaping).
        if nx > 0.0 && cap - it < nx && cap - it > 0.0 {
            nb += (10.5 + 3.2 * progress) * ((nx - (cap - it)) / cap).min(0.4) * (0.45 + progress);
        }
        // NEW: reward opening a bin when mean residual is large and fragmented
        // (many open bins with fat residuals) — consolidate instead of spreading.
