        if it >= cap - 1 { nb -= 30.0; }
        if nx > 0.0 && cap - it >= nx { nb -= 9.0 + 0.10 * (cap - it - nx); }
        if fitting_bins_count == 0 { nb -= 8.0; }
        if fitting_bins_count <= 2 { nb += 18.0 + 9.0 * (1.0 - progress); }
        if fitting_bins_count >= 4 { nb -= 6.0 + 8.0 * progress; }
        if mean_residual >= it && progress > 0.5 { nb += 6.0 + 8.0 * progress; }
        if nx > it && mean_residual >= nx && progress < 0.6 { nb += 9.0 * (1.0 - progress); }
        if progress > 0.85 && mean_residual < 0.15 * cap { nb += 6.5 * progress; }
        if nx > 0.0 && cap - it > 0.0 && cap - it < nx { nb += 4.0 * (1.0 - progress) * ((nx - (cap - it)) / cap).min(0.3) * 10.0; }
        if nx > 0.0 && cap >= it + nx && (cap - it - nx) < 0.08 * cap && progress > 0.3 { nb -= 5.0 * (1.0 - (cap - it - nx) / (0.08 * cap)) * (0.5 + progress); }
