    let mut score = pr * (1.0 + 0.03 * (pr / cap) * (pr / cap));
    let tightness = 1.0 + 2.4 * progress * progress + 2.2 * progress * progress * progress;
    score *= tightness;

    // Lookahead chain logic
    if nx > 0.0 {
        if pr < nx {
            let gap = nx - pr;
            score += gap * (2.0 + 6.0 * (1.0 - progress));
        } else {
            let chain_gap = pr - nx;
            let slack = chain_gap / cap;
            if chain_gap <= 42.0 { score -= 6.0 + 0.10 * chain_gap; }
            if slack < 0.04 { score -= 8.0 * (1.0 - slack * 25.0) * (1.0 + progress); }
            let chain = 1.0 - slack.min(1.0);
            score -= 4.5 + 4.0 * (nx / cap) + 9.0 * chain * (1.0 - progress);
        }
    }

    // Dead-space penalty scaled by unusability
    let dead_ratio = (pr / cap).max(0.0);
    let unusable = if nx > 0.0 && pr > 0.0 && pr < nx { 1.0 } else { 0.55 };
    score += (10.0 + 3.0 * progress) * dead_ratio * dead_ratio * cap * (0.45 + progress) * unusable;

    // Near-perfect fits
    if dead_ratio > 0.0 && dead_ratio < 0.12 { score -= 8.5 * (1.0 - dead_ratio / 0.12) * (0.4 + progress); }
    if pr == 0.0 { score -= 60.0; }
    else if pr <= 5.0 { score -= 30.0 * (1.0 - 0.4 * progress); }
    else if pr > 0.0 && pr < 10.0 { score += 38.0 * (1.0 - 0.5 * progress); }

    // Next item won't fit here: penalize
    if nx > 0.0 && pr > 0.0 && pr < nx {
