pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;

    // ---- Aggressive 2-step lookahead matching ----
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if post_residual == next_item_size {
            // Perfect chain: leftover exactly hosts the next item
            score -= 12.0;
        } else if pr > ni {
            // Leftover can still host next item; reward tighter couplings
            score -= 3.0 * (1.0 - (pr - ni) / cap);
        } else {
            // Dead space: next item cannot use the leftover; penalize more later in stream
            score += 0.35 * pr * (1.0 + progress);
        }
    }

    // ---- Last-chance bin before opening a new one ----
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    if bin_residual == bin_capacity {
        // ---- New-bin candidate: penalized so it loses to any decent existing fit,
        // but large items make opening a fresh bin relatively attractive ----
        score += 15.0 + 0.1 * open_bins_count as f64;
        score -= 0.1 * item_size as f64;
    } else {
        // Prefer bins tighter than the current mean residual (best-fit coupling)
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        } else {
            score += 1.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
