        if fill_ratio > 0.92 && pr > 0.0 {
            score -= 2.0 * (fill_ratio - 0.92) * 10.0 * (0.5 + progress);
        }
        if waste > 0.22 && fitting_bins_count <= 1 && progress > 0.5 {
            score += 2.8 * (waste - 0.22) * 10.0 * progress;
        }
        if waste > 0.08 && waste < 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.07 * cap && progress > 0.35 {
            score -= 2.9 * (1.0 - (pr - nx) / (0.07 * cap)) * (0.5 + progress);
        }
        if waste > 0.3 && fitting_bins_count > 2 && progress > 0.5 {
            score += 3.5 * (waste - 0.3) * 10.0 * progress;
        }

        // Crowding bonus
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio * fit_ratio * bin_capacity as f64;

    // Penalize dead space that is too small for typical future items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 {
        let dead = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { post_residual as f64 };
        score += 0.9 * dead * (0.5 + 0.5 * progress);
    }

    // Lookahead coupling: reward if the next item fits exactly in the post residual.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0 * (next_item_size as f64 / post_residual as f64);
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Spread pressure: when many bins are open, prefer bins below mean residual
    // (consolidate waste into few bins).
    let diff = mean_residual - bin_residual as f64;
    score += 0.35 * diff;

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 {
            0.0
        } else {
            let best_possible_waste = bin_residual.saturating_sub(item_size) as f64;
            (best_possible_waste / bin_capacity as f64).min(1.0)
        };
        // Cost of a fresh bin grows with stream progress and open-bin count.
        score = bin_capacity as f64 + 30.0 * progress + 2.0 * open_bins_count as f64
                 - 60.0 * (1.0 - desperation) - 40.0 * desperation * desperation;
        // If the only fitting bin would leave large unusable waste, new bin is fine.
        if fitting_bins_count == 1 {
            let waste = bin_residual.saturating_sub(item_size) as f64;
            if waste > 0.5 * bin_capacity as f64 {
                score -= 35.0;
            }
        }
    }

    // Mild entropy term for exploratory diversity, damped over time.
    let phase = ((step_index as f64 * 0.37).sin()) * (1.0 - progress);
    score += 1.5 * phase;

    score
}

