            nb += 4.5 * (1.0 - progress) * ((nx - (cap - it)) / cap).min(0.3) * 10.0;
        }
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin < 0.15 * cap {
                nb -= 6.0 * (1.0 - margin / (0.15 * cap)) * (0.6 + 0.4 * progress);
            }
        }
        if nx > 0.0 && fitting_bins_count >= 1 && mean_residual - it >= nx {
            let leftover = mean_residual - it - nx;
            if leftover < 0.1 * cap && progress > 0.45 {
                nb -= 5.0 * (1.0 - leftover / (0.1 * cap)) * progress;
            }
        }
        if nx > 0.0 && fitting_bins_count >= 2 && mean_residual > 0.5 * cap && progress < 0.4 {
            nb += 4.5 * ((mean_residual - 0.5 * cap) / cap) * (1.0 - progress);
        }
        if open_bins_count > 12 && progress > 0.6 && item_frac < 0.25 {
            nb += 5.0 * progress * (1.0 - item_frac / 0.25);
        }
        if nx > 0.0 && fitting_bins_count >= 1 && (cap - it) >= nx && (cap - it - nx) < 0.05 * cap && progress < 0.5 {
            nb -= 4.0 * (1.0 - (cap - it - nx) / (0.05 * cap)) * (1.0 - progress);
        }
        if nx > 0.0 && (cap - it).max(0.0) < nx && fitting_bins_count <= 1 && mean_residual < 0.3 * cap {
            nb += 3.5 * (1.0 - mean_residual / (0.3 * cap)) * (0.5 + progress);
        }
        if fitting_bins_count >= 2 && mean_residual >= it + nx && progress > 0.4 {
            let rem = mean_residual - it - nx;
            if rem < 0.05 * cap {
                nb -= 4.5 * (1.0 - rem / (0.05 * cap)) * progress;
            }
        }
        if fitting_bins_count == 1 && mean_residual >= it && (mean_residual - it) < 0.04 * cap && progress > 0.3 {
            nb -= 3.0 * (1.0 - (mean_residual - it) / (0.04 * cap)) * (0.5 + progress);
        }
        if open_bins_count > 8 && mean_residual < 0.1 * cap && progress > 0.5 {
            nb -= 4.0 * (1.0 - mean_residual / (0.1 * cap)) * progress;
        }
        if fitting_bins_count >= 1 && mean_residual >= it && progress > 0.65 {
            let best_pr = (mean_residual - it).max(0.0);
            if best_pr > 0.0 && best_pr < 0.05 * cap {
                nb += 5.5 * (1.0 - best_pr / (0.05 * cap)) * progress;
            }
        }
        if nx > 0.0 && mean_residual >= it + nx && progress > 0.55 {
            let rem = mean_residual - it - nx;
            if rem > 0.2 * cap {
                nb += 3.5 * ((rem - 0.2 * cap) / cap).min(0.3) * 10.0 * progress;
            }
        }
        if nx > 0.0 && cap >= it + nx && cap - it - nx < 0.02 * cap && fitting_bins_count <= 3 {
            nb -= 3.5 * (1.0 - (cap - it - nx) / (0.02 * cap)) * (0.6 + progress);
        }
        if open_bins_count > 14 && mean_residual > 0.55 * cap && progress > 0.5 {
            nb += 4.0 * ((mean_residual - 0.55 * cap) / cap).min(0.3) * 10.0 * progress;
        }
        if item_frac < 0.1 && progress > 0.7 && fitting_bins_count >= 2 {
            nb += 5.0 * progress;
        }
        if nx > 0.0 && fitting_bins_count >= 1 && mean_residual >= it + nx && progress > 0.7 {
            let rem = mean_residual - it - nx;
            if rem < 0.03 * cap {
                nb -= 3.2 * (1.0 - rem / (0.03 * cap)) * progress;
            }
        }
        if item_frac < 0.2 && nx > 0.0 && mean_residual >= it + nx && progress > 0.6 {
            nb -= 4.0 * (1.0 - item_frac / 0.2) * progress;
        }
        if nx > 0.0 && mean_residual < nx && progress > 0.55 && item_frac < 0.5 {
            nb += 3.5 * (nx - mean_residual).min(0.1 * cap) / (0.1 * cap) * progress;
        }
        if nx > 0.0 && fitting_bins_count >= 1 && mean_residual >= it + nx && progress > 0.45 {
            let rem = mean_residual - it - nx;
            if rem > 0.12 * cap && rem < 0.3 * cap {
                nb -= 3.8 * (1.0 - (rem - 0.12 * cap) / (0.18 * cap)) * (0.4 + progress);
            }
        }
        if open_bins_count > 5 && progress > 0.3 && item_frac > 0.55 {
            nb -= 3.5 * (item_frac - 0.55) * 2.0 * progress;
        }
        if nx > 0.0 && mean_residual > 0.6 * cap && progress < 0.5 && fitting_bins_count >= 3 {
            nb += 4.0 * ((mean_residual - 0.6 * cap) / cap).min(0.3) * 10.0 * (1.0 - progress);
        }
        score = nb;
    } else {
        let fill_ratio = 1.0 - res / cap;
        let waste = pr / cap;

        if waste < 0.08 {
            score -= 48.0 * (1.0 - progress) * (0.08 - waste);
        }
        if fill_ratio > 0.65 {
            score -= 4.8 * (fill_ratio - 0.65) * 10.0 * (0.4 + progress);
        }
        if nx > 0.0 && nx <= pr && pr > 0.0 {
            let gap = (pr - nx) / cap;
            if gap < 0.03 {
                score -= 7.5 * (1.0 - gap * 33.0);
            }
        }
        if pr > 0.0 && pr < 10.0 {
            score += 41.0 * (1.0 - 0.5 * progress);
        }
        if pr == 0.0 {
            score -= 62.0;
        } else if pr <= 5.0 {
            score -= 31.0 * (1.0 - 0.4 * progress);
        }
        if nx > 0.0 && pr > 0.0 && pr < nx {
            score += 6.5 + 2.2 * progress;
            if nx - pr <= 3.0 {
                score -= 9.0 * (1.0 - progress);
            }
        }
        let dev = mean_residual - res;
        score += 0.085 * dev;
        if dev > -5.0 && dev < 15.0 && pr > 0.0 {
            score -= 4.2;
        }
        let tight_fit = (pr == 0.0) || (nx > 0.0 && pr == nx);
        if tight_fit {
            score -= 10.5 * (0.3 + progress);
        }
        if nx > 0.0 && pr >= nx {
            let room = pr - nx;
            if room < 0.06 * cap {
                score -= 6.5 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
            }
        }
        // Mid-range waste band penalty (dead-space control)
        if waste > 0.14 && waste < 0.34 {
            score += 13.0 * (waste - 0.14) * (0.6 + 0.8 * progress);
        }
        if fitting_bins_count > 3 && waste < 0.12 {
            score -= 5.5 * (1.0 - waste * 8.0) * (0.5 + progress);
        }
        if nx > 0.0 && pr > 0.0 && pr > nx && (pr - nx) < 0.02 * cap {
            score -= 4.0 * (1.0 - (pr - nx) / (0.02 * cap)) * (0.4 + progress);
        }
        if pr > 0.0 && (pr as f64).sqrt() < 2.6 {
            score -= 3.5 * (1.0 - progress);
        }
        if waste > 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.09 * cap && progress > 0.4 {
            score -= 4.0 * (1.0 - (pr - nx) / (0.09 * cap)) * progress;
        }
        if pr > 0.0 && nx > 0.0 && pr < nx && (nx - pr) > 0.1 * cap && waste > 0.25 {
            score += 5.0 * (waste - 0.25) * 10.0 * (0.4 + progress);
        }
        if pr > 0.0 && nx > 0.0 && pr < 0.5 * nx && progress > 0.3 {
            score += 3.5 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
        }
        if waste > 0.3 && pr > nx && progress < 0.5 {
            score += 3.0 * (waste - 0.3) * 10.0 * (1.0 - progress);
        }
        if fill_ratio > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
            score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
        }
        if waste > 0.35 && progress > 0.55 && nx > 0.0 && pr >= nx {
            score -= 4.5 * ((pr - nx) / cap).min(0.2) * 5.0 * progress;
        }
        if nx > 0.0 && pr > 0.0 && pr < nx {
            let closeness = 1.0 - pr / nx;
            score += 3.0 * closeness * closeness * (0.6 + progress);
        }
        if nx > 0.0 && pr > nx && (pr - nx) <= 0.04 * cap {
            score -= 3.2 * (1.0 - (pr - nx) / (0.04 * cap)) * (1.0 - progress);
        }
        if nx > 0.0 && pr > nx && (pr - nx) > 0.04 * cap && (pr - nx) < 0.18 * cap {
            score -= 2.2 * (1.0 - ((pr - nx) / (0.18 * cap))) * (0.3 + progress);
        }
        if pr > 0.0 && it > 0.0 && pr < it * 0.5 && waste > 0.05 {
            score += 2.5 * (1.0 - pr / (it * 0.5)) * (0.4 + progress);
        }
        if waste > 0.18 && waste < 0.4 && nx > 0.0 && pr >= nx && (pr - nx) < 0.12 * cap {
            score += 3.0 * (1.0 - (pr - nx) / (0.12 * cap)) * (0.5 + progress);
        }
        if waste > 0.28 && fitting_bins_count > 2 && progress > 0.5 {
            score += 3.5 * (waste - 0.28) * 10.0 * progress;
        }
        if waste > 0.4 && pr > 0.0 && nx > 0.0 && pr < nx && progress > 0.6 {
            score += 4.0 * (waste - 0.4) * 10.0 * progress;
        }
        if pr > 0.0 && nx > 0.0 && pr >= nx && (pr - nx) < 0.5 * nx && progress > 0.6 {
            score -= 2.8 * (1.0 - (pr - nx) / (0.5 * nx)) * progress;
        }
        if nx > 0.0 && pr >= nx && (pr - nx) > 0.06 * cap && (pr - nx) < 0.22 * cap && fitting_bins_count <= 2 {
            score -= 2.0 * (1.0 - ((pr - nx) / (0.22 * cap))) * (0.6 + progress);
        }
        if waste > 0.05 && waste < 0.14 && pr >= nx && progress > 0.5 {
            score -= 2.4 * (1.0 - (waste - 0.05) / 0.09) * progress;
        }
        if fill_ratio > 0.92 && pr > 0.0 {
            score -= 2.0 * (fill_ratio - 0.92) * 10.0 * (0.5 + progress);
        }
        if waste > 0.08 && waste < 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.07 * cap && progress > 0.35 {
            score -= 2.9 * (1.0 - (pr - nx) / (0.07 * cap)) * (0.5 + progress);
        }
        if waste > 0.22 && fitting_bins_count <= 1 && progress > 0.5 {
            score += 2.8 * (waste - 0.22) * 10.0 * progress;
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues near capacity fractions
    // (0, 25, 50) are "good" because many item sizes can still pair into them.
    let pr = post_residual;
    let good = (pr == 0) as f64 * 40.0
        + ((pr % 25 == 0) && pr > 0) as f64 * 18.0
        + ((pr % 10 == 0) && pr > 0 && pr % 25 != 0) as f64 * 8.0;
    score -= good;

    // Penalize awkward dead space: small nonzero residues that few items fit.
    if pr > 0 && pr < 10 {
        score += 30.0; // unusable sliver
    } else if pr >= 10 && pr < 25 {
        score += 10.0; // only tiny items fit
    }

    // Lookahead coupling: reward if next item fits exactly or well into post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0; // perfect follow-up pairing
        } else if next_item_size <= pr {
            score -= 25.0 * (next_item_size as f64 / pr as f64);
        } else {
            score += 5.0; // next item won't fit here; slight penalty
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Penalize opening a new bin when open bins have plenty of room.
    if bin_residual == bin_capacity {
        if mean_residual > 40.0 && fitting_bins_count > 0 {
            score += 45.0;
        } else {
            score += 12.0; // mild preference to reuse existing bins
        }
    }

    // Encourage tight fills as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity - pr) as f64 * 0.15 * (0.5 + 0.5 * progress);

    // Mild penalty for spreading across many bins with high mean residual.
    score += 0.02 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest possible
    // item are pure waste; penalize quadratically.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 6.0;
    }

    // Penalize small-but-usable gaps less harshly, proportional to how unusable
    // they are likely to be relative to typical item sizes.
    if post_residual > 0 && post_residual < 30 {
        score += (30 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits strongly (post_residual near zero but not dead).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 12.0;

    // Open-bin pressure: with many open bins, favor filling existing ones
    // over opening new ones; with few bins, opening is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 8.0 + pressure * 4.0;
        // If only this new bin fits, opening is unavoidable; soften penalty.
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly reward using it to avoid a new bin.
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual as u32 {
        // Next item won't fit here; slightly penalize leaving a gap it can't use.
        score += 2.0;
    }

    // Late in the stream, consolidate: prefer bins below mean residual (fuller bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dev = mean_residual - post_residual as f64;
    score += dev * (0.3 + 0.7 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;
    let waste = pr / cap;
    let mut score = pr * (1.0 + 0.03 * waste * waste);

    let tightness = 1.0 + 2.4 * progress * progress + 2.2 * progress * progress * progress;
    score *= tightness;

    // Borrowed from best: dead-space quadratic penalty on post residual
    let dead_ratio = (pr / cap).max(0.0);
    let unusable = if nx > 0.0 && pr > 0.0 && pr < nx { 1.0 } else { 0.55 };
    score += (10.5 + 3.2 * progress) * dead_ratio * dead_ratio * cap * (0.45 + progress) * unusable;
    if dead_ratio > 0.0 && dead_ratio < 0.12 {
        score -= 9.0 * (1.0 - dead_ratio / 0.12) * (0.4 + progress);
    }

    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let item_frac = (it / cap).min(1.0);
        let mut nb = cap * (1.35 + 1.15 * progress);
        nb -= 26.0 * scarcity * (1.0 - progress);
        nb -= 19.0 * item_frac * (1.0 - progress);
        if nx >= 0.5 * cap {
            nb -= 12.0 * progress + 6.0 * (1.0 - progress);
        }
        nb += 15.0 * progress * (1.0 - item_frac);
        if it >= cap - 1.0 {
            nb -= 32.0;
        }
        if nx > 0.0 && cap - it >= nx {
            nb -= 10.5 + 0.11 * (cap - it - nx);
        }
        if nx > 0.0 {
            let r1 = cap - it;
            if r1 >= nx && (r1 - nx) < 6.0 && (r1 - nx) > 0.0 {
                nb += 8.5 * (1.0 - progress);
            }
        }
        if fitting_bins_count <= 2 {
            nb += 21.0 + 10.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 4 {
            nb -= 6.5 + 8.5 * progress;
        }
        if nx > 0.0 && mean_residual > nx + 8.0 && progress < 0.7 {
            nb += 8.5 * ((mean_residual - nx) / cap).min(0.5) * cap * 0.1;
        }
        if mean_residual >= it && progress > 0.5 {
            nb += 6.5 + 8.5 * progress;
        }
        if nx > it && mean_residual >= nx && progress < 0.6 {
            nb += 10.0 * (1.0 - progress);
        }
        if nx > 0.0 && mean_residual >= it + nx && progress < 0.6 {
            nb -= 5.5 * (1.0 - progress) * ((mean_residual - it - nx) / cap).min(0.3) * 10.0;
        }
        if it > 0.85 * cap && progress > 0.3 {
            nb -= 9.0 * progress;
        }
        if nx > 0.0 && mean_residual > nx {
            let excess = mean_residual - nx;
            if excess < 0.05 * cap && progress < 0.55 {
                nb += 5.0 * (1.0 - excess / (0.05 * cap)) * (1.0 - progress);
            }
        }
        if fitting_bins_count == 0 && progress > 0.25 {
            nb += 9.0 + 7.0 * progress;
        }
        if nx > 0.0 && it + nx > cap && mean_residual >= nx {
            nb += 6.0 * (1.0 - progress);
        }
        if progress > 0.75 && fitting_bins_count > 0 && mean_residual >= it {
            nb += 5.5 + 4.5 * progress;
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_left = mean_residual - it;
            if best_left >= nx && (best_left - nx) < 12.0 {
                nb += 4.0 * (1.0 - (best_left - nx) / 12.0) * (0.5 + progress);
            }
        }
        if it < 0.2 * cap && progress < 0.3 && open_bins_count < 6 {
            nb += 7.0 * (1.0 - progress);
        }
        if item_frac > 0.6 && nx > 0.0 && cap >= it + nx && cap - it - nx < 0.03 * cap {
            nb -= 5.5 * (1.0 - (cap - it - nx) / (0.03 * cap));
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_pr = (mean_residual - it).max(0.0);
            if best_pr > 0.0 && best_pr < 0.06 * cap && (cap - it) >= nx {
                nb -= 7.0 * (1.0 - best_pr / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if progress > 0.85 && mean_residual < 0.15 * cap {
            nb += 7.0 * progress * (1.0 - mean_residual / (0.15 * cap));
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_post = (mean_residual - it).max(0.0);
            if best_post >= nx && best_post - nx > 0.18 * cap && progress > 0.35 {
                nb -= 6.0 * ((best_post - nx) / cap).min(0.4) * (0.4 + progress);
            }
        }
        if item_frac > 0.45 && item_frac < 0.75 && progress > 0.5 {
            nb -= 5.0 * (item_frac - 0.45) * progress;
        }
        if fitting_bins_count >= 2 && mean_residual < 0.25 * cap && progress > 0.6 {
            nb += 6.0 * (1.0 - mean_residual / (0.25 * cap)) * progress;
        }
        if fitting_bins_count >= 3 && mean_residual - it >= nx && progress > 0.5 {
            nb += 4.5 * progress * (1.0 - ((mean_residual - it - nx) / cap).min(1.0));
        }
        if open_bins_count > 10 && progress < 0.35 && item_frac < 0.3 {
            nb += 6.0 * (1.0 - progress) * (1.0 - item_frac / 0.3);
        }
        if nx > 0.0 {
            let r1 = cap - it;
            if r1 < nx && r1 > 0.0 {
                nb += (1.0 + 2.0 * progress) * (nx - r1) * 0.55;
            }
            if r1 >= nx && (r1 - nx) > 0.25 * cap && progress > 0.45 {
                nb += 4.5 * ((r1 - nx) / cap).min(0.5) * progress;
            }
        }
        if nx > 0.0 && cap >= it + nx && (cap - it - nx) < 0.08 * cap && progress > 0.3 {
            nb -= 5.0 * (1.0 - (cap - it - nx) / (0.08 * cap)) * (0.5 + progress);
        }
        // NEW: two-item chain margin from best heuristic
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin < 0.15 * cap {
                nb -= 6.0 * (1.0 - margin / (0.15 * cap)) * (0.6 + 0.4 * progress);
            }
        }
        // NEW: resist opening bins when existing mean residual already chains
        if nx > 0.0 && fitting_bins_count >= 1 && mean_residual - it >= nx {
            let leftover = mean_residual - it - nx;
            if leftover < 0.1 * cap && progress > 0.45 {
                nb -= 5.0 * (1.0 - leftover / (0.1 * cap)) * progress;
            }
        }
        if open_bins_count > 6 && mean_residual > 0.4 * cap && progress < 0.6 {
            nb += 5.0 * ((mean_residual - 0.4 * cap) / cap) * (1.0 - progress) * (((open_bins_count as f64 - 6.0).min(8.0)) / 8.0);
        }
        score = nb;
    } else {
        // Fine-grained residual fitting with lookahead anticipation
        let fill_ratio = 1.0 - res / cap;
        if waste < 0.08 {
            score -= 48.0 * (1.0 - progress) * (0.08 - waste);
        }
        if fill_ratio > 0.65 {
            score -= 4.8 * (fill_ratio - 0.65) * 10.0 * (0.4 + progress);
        }
        if nx > 0.0 && pr > 0.0 {
            if nx <= pr {
                let gap = (pr - nx) / cap;
                if gap < 0.03 {
                    score -= 7.5 * (1.0 - gap * 33.0);
                }
                if gap <= 0.04 {
                    score -= 3.2 * (1.0 - gap / 0.04) * (1.0 - progress);
                }
                let chain_gap = pr - nx;
                let slack = chain_gap / cap;
                if chain_gap <= 42.0 {
                    score -= 6.5 + 0.11 * chain_gap;
                }
                if slack < 0.04 {
                    score -= 8.5 * (1.0 - slack * 25.0) * (1.0 + progress);
                }
                let chain = 1.0 - slack.min(1.0);
                score -= 5.0 + 4.0 * (nx / cap) + 9.5 * chain * (1.0 - progress);
            } else {
                let gap = nx - pr;
                score += gap * (2.0 + 6.5 * (1.0 - progress));
                if gap <= 3.0 {
                    score -= 9.0 * (1.0 - progress);
                }
                let closeness = 1.0 - pr / nx;
                score += 3.0 * closeness * closeness * (0.6 + progress);
            }
        }
        if pr > 0.0 && pr < 10.0 {
            score += 41.0 * (1.0 - 0.5 * progress);
        }
        if pr == 0.0 {
            score -= 62.0;
        } else if pr <= 5.0 {
            score -= 31.0 * (1.0 - 0.4 * progress);
        }
        let dev = mean_residual - res;
        score += 0.085 * dev;
        if dev > -5.0 && dev < 15.0 && pr > 0.0 {
            score -= 4.2;
        }
        let tight_fit = (pr == 0.0) || (nx > 0.0 && pr == nx);
        if tight_fit {
            score -= 10.5 * (0.3 + progress);
        }
        if nx > 0.0 && pr >= nx {
            let room = pr - nx;
            if room < 0.06 * cap {
                score -= 6.5 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if waste > 0.14 && waste < 0.34 {
            score += 13.0 * (waste - 0.14) * (0.6 + 0.8 * progress);
        }
        if fitting_bins_count > 3 && waste < 0.12 {
            score -= 5.5 * (1.0 - waste * 8.0) * (0.5 + progress);
        }
        if nx > 0.0 && pr > 0.0 && pr > nx && (pr - nx) < 0.02 * cap {
            score -= 4.0 * (1.0 - (pr - nx) / (0.02 * cap)) * (0.4 + progress);
        }
        if pr > 0.0 && (pr as f64).sqrt() < 2.6 {
            score -= 3.5 * (1.0 - progress);
        }
        if waste > 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.09 * cap && progress > 0.4 {
            score -= 4.0 * (1.0 - (pr - nx) / (0.09 * cap)) * progress;
        }
        if pr > 0.0 && nx > 0.0 && pr < nx && (nx - pr) > 0.1 * cap && waste > 0.25 {
            score += 5.0 * (waste - 0.25) * 10.0 * (0.4 + progress);
        }
        if pr > 0.0 && nx > 0.0 && pr < 0.5 * nx && progress > 0.3 {
            score += 3.5 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
        }
        if waste > 0.3 && pr > nx && progress < 0.5 {
            score += 3.0 * (waste - 0.3) * 10.0 * (1.0 - progress);
        }
        if fill_ratio > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
            score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
        }
        if waste > 0.35 && progress > 0.55 && nx > 0.0 && pr >= nx {
            score -= 4.5 * ((pr - nx) / cap).min(0.2) * 5.0 * progress;
        }
        // Scarcity: prefer using existing bins when few can fit
        if fitting_bins_count == 1 {
            score -= 14.0 + 12.0 * progress;
        } else if fitting_bins_count == 2 {
            score -= 4.0 + 3.0 * progress;
        }
        // NEW: graded reward for near-exact chain fits beyond the next item
        if nx > 0.0 && pr > nx && (pr - nx) <= 0.04 * cap {
            score -= 3.2 * (1.0 - (pr - nx) / (0.04 * cap)) * (1.0 - progress);
        }
        if nx > 0.0 && pr > nx && (pr - nx) > 0.04 * cap && (pr - nx) < 0.18 * cap {
            score -= 2.2 * (1.0 - ((pr - nx) / (0.18 * cap))) * (0.3 + progress);
        }
        // NEW: penalize leaving space too small for the item after next
        if nx > 0.0 && pr >= nx && (pr - nx) > 0.0 && (pr - nx) < it * 0.5 && waste > 0.05 {
            score += 2.5 * (1.0 - (pr - nx) / (it * 0.5)) * (0.4 + progress);
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect match between post_residual and next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.8 * diff;
        if post_residual == next_item_size {
            score -= 40.0; // perfect 2-step fit: strongly favor
        } else if post_residual < next_item_size {
            // next item cannot follow here; penalize proportionally to wasted potential
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // last item: minimize leftover as much as possible
        score += 0.5 * post_residual as f64;
    }

    // Compare post_residual against mean residual: leaving residual far below mean
    // creates fragmented unusable space.
    let mean_gap = mean_residual - post_residual as f64;
    score += 0.25 * mean_gap.max(0.0);
    score -= 0.15 * (-mean_gap).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Tight fits are good in general.
    if post_residual < 10 {
        score -= 15.0;
    }

    // Prefer filling nearly-full bins over opening new bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize, less so as stream progresses or many bins open.
        score += 30.0 - 10.0 * progress - (open_bins_count.min(10) as f64);
        // If the item fits best alone (very large relative to mean residual), allow new bin.
        if item_size as f64 > mean_residual + 20.0 {
            score -= 20.0;
        }
    }

    // Mild penalty when many bins are open and this bin is quite empty (avoid sprawl).
    if bin_residual as f64 > mean_residual + 30.0 && open_bins_count > 3 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
