pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Tightness: squared small residual bonus.
        score -= 60.0 / (post_residual as f64).sqrt();
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            // next item fits, but leave reasonable space after
            let after_next = post_residual - next_item_size;
            score -= 120.0 * (1.0 - after_next as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this residual: penalize leaving medium dead space
            score += 0.15 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 250.0;
    } else if fitting_bins_count > 1 {
        score += 20.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Penalize new-bin candidates unless nothing decent is open.
    if bin_residual == bin_capacity {
        let urgency = if next_item_size > 0 && next_item_size >= bin_capacity {
            0.0
        } else {
            1.0
        };
        let pressure = if fitting_bins_count == 0 { 500.0 } else { 0.0 };
        score += 300.0 * urgency - pressure;
        // Later in the stream, be less eager to open new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 150.0 * progress;
    }

    // Prefer bins whose residual is already below mean (consolidate fragmented space).
    score += 0.1 * (mean_residual - bin_residual as f64);

    // Mild penalty for leaving awkward residual sizes (hard to fill: 1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
