        score -= 14.0 + 12.0 * progress;
    } else if fitting_bins_count == 2 {
        score -= 4.0 + 3.0 * progress;
    }

    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let item_frac = (it / cap).min(1.0);
        let mut nb = cap * (1.35 + 1.15 * progress);
        nb -= 26.0 * scarcity * (1.0 - progress);
        nb -= 19.0 * item_frac * (1.0 - progress);
        if nx >= 0.5 * cap {
            nb -= 12.0 * progress + 6.0 * (1.0 - progress);
        }
        nb += 15.0 * progress * (1.0 - item_frac);
        if it >= cap - 1.0 {
            nb -= 32.0;
        }
        if nx > 0.0 && cap - it >= nx {
            nb -= 10.5 + 0.11 * (cap - it - nx);
        }
        // Penalize new bins when the residual after this item would be a
        // stranded sliver relative to next item
        if nx > 0.0 {
            let r1 = cap - it;
            if r1 >= nx && (r1 - nx) < 6.0 && (r1 - nx) > 0.0 {
                nb += 8.5 * (1.0 - progress);
            }
            if r1 < nx && r1 > 0.0 {
                nb += (1.0 + 2.0 * progress) * (nx - r1) * 0.55;
            }
        }
        if fitting_bins_count <= 2 {
            nb += 21.0 + 10.0 * (1.0 - progress);
        } else if fitting_bins_count >= 4 {
            nb -= 6.5 + 8.5 * progress;
        }
        if nx > 0.0 && mean_residual > nx + 8.0 && progress < 0.7 {
            nb += 8.5 * ((mean_residual - nx) / cap).min(0.5) * cap * 0.1;
        }
        if mean_residual >= it && progress > 0.5 {
            nb += 6.5 + 8.5 * progress;
        }
        if nx > it && mean_residual >= nx && progress < 0.6 {
            nb += 10.0 * (1.0 - progress);
        }
        if nx > 0.0 && mean_residual >= it + nx && progress < 0.6 {
            nb -= 5.5 * (1.0 - progress) * ((mean_residual - it - nx) / cap).min(0.3) * 10.0;
        }
        if it > 0.85 * cap && progress > 0.3 {
            nb -= 9.0 * progress;
        }
        if nx > 0.0 && mean_residual > nx {
            let excess = mean_residual - nx;
            if excess < 0.05 * cap && progress < 0.55 {
                nb += 5.0 * (1.0 - excess / (0.05 * cap)) * (1.0 - progress);
            }
        }
        if fitting_bins_count == 0 && progress > 0.25 {
            nb += 9.0 + 7.0 * progress;
        }
        if nx > 0.0 && it + nx > cap && mean_residual >= nx {
            nb += 6.0 * (1.0 - progress);
        }
        if progress > 0.75 && fitting_bins_count > 0 && mean_residual >= it {
            nb += 5.5 + 4.5 * progress;
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_left = mean_residual - it;
            if best_left >= nx && (best_left - nx) < 12.0 {
                nb += 4.0 * (1.0 - (best_left - nx) / 12.0) * (0.5 + progress);
            }
        }
        if item_frac / cap > 0.6 && nx > 0.0 && cap >= it + nx && cap - it - nx < 0.03 * cap {
            nb -= 5.5 * (1.0 - (cap - it - nx) / (0.03 * cap));
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_pr = (mean_residual - it).max(0.0);
            if best_pr > 0.0 && best_pr < 0.06 * cap && (cap - it) >= nx {
                nb -= 7.0 * (1.0 - best_pr / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if progress > 0.85 && mean_residual < 0.15 * cap {
            nb += 7.0 * progress * (1.0 - mean_residual / (0.15 * cap));
        }
        if item_frac < 0.15 && progress > 0.55 && fitting_bins_count >= 1 {
            nb += 6.0 * progress * (1.0 - item_frac / 0.15);
        }
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin < 0.15 * cap {
                nb -= 6.0 * (1.0 - margin / (0.15 * cap)) * (0.6 + 0.4 * progress);
            }
        }
        score = nb;
    } else {
        let fill_ratio = 1.0 - res / cap;
        let waste = pr / cap;

        if waste < 0.08 {
            score -= 48.0 * (1.0 - progress) * (0.08 - waste);
        }
        if fill_ratio > 0.65 {
            score -= 4.8 * (fill_ratio - 0.65) * 10.0 * (0.4 + progress);
        }
        if nx > 0.0 && nx <= pr && pr > 0.0 {
            let gap = (pr - nx) / cap;
            if gap < 0.03 {
                score -= 7.5 * (1.0 - gap * 33.0);
            }
        }
        if pr > 0.0 && pr < 10.0 {
            score += 41.0 * (1.0 - 0.5 * progress);
        }
        if pr == 0.0 {
            score -= 62.0;
        } else if pr <= 5.0 {
            score -= 31.0 * (1.0 - 0.4 * progress);
        }
        if nx > 0.0 && pr > 0.0 && pr < nx {
            score += 6.5 + 2.2 * progress;
            if nx - pr <= 3.0 {
                score -= 9.0 * (1.0 - progress);
            }
        }
        let dev = mean_residual - res;
        score += 0.085 * dev;
        score += 0.01 * dev * dev;
        if dev > -5.0 && dev < 15.0 && pr > 0.0 {
            score -= 4.2;
        }
        let tight_fit = (pr == 0.0) || (nx > 0.0 && pr == nx);
        if tight_fit {
            score -= 10.5 * (0.3 + progress);
        }
        if nx > 0.0 && pr >= nx {
            let room = pr - nx;
            if room < 0.06 * cap {
                score -= 6.5 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
            }
        }
        // Mid-band waste penalty (dead space control)
        if waste > 0.14 && waste < 0.34 {
            score += 13.0 * (waste - 0.14) * (0.6 + 0.8 * progress);
        }
        if fitting_bins_count > 3 && waste < 0.12 {
            score -= 5.5 * (1.0 - waste * 8.0) * (0.5 + progress);
        }
        if nx > 0.0 && pr > 0.0 && pr > nx && (pr - nx) < 0.02 * cap {
            score -= 4.0 * (1.0 - (pr - nx) / (0.02 * cap)) * (0.4 + progress);
        }
        if pr > 0.0 && (pr as f64).sqrt() < 2.6 {
            score -= 3.5 * (1.0 - progress);
        }
        if waste > 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.09 * cap && progress > 0.4 {
            score -= 4.0 * (1.0 - (pr - nx) / (0.09 * cap)) * progress;
        }
        if pr > 0.0 && nx > 0.0 && pr < 0.5 * nx && progress > 0.3 {
            score += 3.5 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
        }
        if nx > 0.0 && pr > 0.0 && pr < nx {
            let closeness = 1.0 - pr / nx;
            score += 3.0 * closeness * closeness * (0.6 + progress);
        }
        if nx > 0.0 && pr > nx && (pr - nx) <= 0.04 * cap {
            score -= 3.2 * (1.0 - (pr - nx) / (0.04 * cap)) * (1.0 - progress);
        }
        if waste > 0.18 && waste < 0.4 && nx > 0.0 && pr >= nx && (pr - nx) < 0.12 * cap {
            score += 3.0 * (1.0 - (pr - nx) / (0.12 * cap)) * (0.5 + progress);
        }
        if waste > 0.28 && fitting_bins_count > 2 && progress > 0.5 {
            score += 3.5 * (waste - 0.28) * 10.0 * progress;
        }
        if fill_ratio > 0.92 && pr > 0.0 {
            score -= 2.0 * (fill_ratio - 0.92) * 10.0 * (0.5 + progress);
        }
        if waste > 0.08 && waste < 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.07 * cap && progress > 0.35 {
            score -= 2.9 * (1.0 - (pr - nx) / (0.07 * cap)) * (0.5 + progress);
        }
        if waste > 0.22 && fitting_bins_count <= 1 && progress > 0.5 {
            score += 2.8 * (waste - 0.22) * 10.0 * progress;
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post-residual, with non-linear (quadratic) waste penalty.
    let mut score = pr + (pr * pr) / cap;

    // Tightness reward: smooth interaction between fill ratio and stream progress.
    let fill = 1.0 - (pr / cap);
    score -= 12.0 * fill * fill * (0.5 + progress);

    // Lookahead coupling: reward if next item fits into post-residual (chaining).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = pr - nxt;
            score -= 10.0 * (1.0 - slack / cap) * (1.0 + progress);
        } else {
            // Penalize post-residuals that are almost-but-not-quite usable.
            let gap = (nxt - pr) / cap;
            score += 6.0 * gap * (1.0 - gap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 * (1.0 + progress);
    }

    // Crowding pressure: many open bins with high mean residual -> encourage consolidation.
    let crowd = open_bins_count as f64 / (1.0 + mean_residual / cap);
    score += 0.02 * crowd * pr / cap;

    // New-bin candidate handling: make empty bin attractive only when current fit is bad.
    if bin_residual == bin_capacity {
        score = cap * (1.0 + 0.3 * progress) + 0.5 * crowd;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity quantized into quarters.
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter.max(1);
    score += class as f64 * 6.0;

    // Exact-fit reward: post_residual near zero is perfect packing.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Modulo arithmetic: penalize residuals that are "awkward" mod 10
    // (dead space unlikely to be filled by integer item sizes).
    let rem = post_residual % 10;
    score += (rem as f64) * 0.8;
    if rem != 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }

    // Lookahead coupling: bonus if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 25.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // Next item cannot follow here; penalize proportionally to overshoot.
            score += 10.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: empty bin gets a baseline cost that grows with
    // open bin count and mean residual, encouraging reuse when sensible.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.85
            + open_bins_count as f64 * 2.0
            + mean_residual * 0.5;
        // But if no open bin fits well, opening is fine.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Late in stream, avoid opening bins for small leftovers.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size < 20 && progress > 0.5 {
            score += 20.0;
        }
    }

    // Mild pressure to fill bins with large residual relative to mean.
    if bin_residual < bin_capacity {
        score -= (mean_residual - post_residual as f64).max(0.0) * 0.2;
    }

    score
}

