        }
        if waste > 0.45 && pr >= nx && nx > 0.0 && progress > 0.65 {
            score -= 3.0 * (waste - 0.45) * 10.0 * progress;
        }
        if waste > 0.06 && waste < 0.16 && nx > 0.0 && pr >= nx && (pr - nx) < 0.04 * cap && progress > 0.55 {
            score -= 2.6 * (1.0 - (pr - nx) / (0.04 * cap)) * progress;
        }
        if waste > 0.5 && pr > 0.0 && nx > 0.0 && pr >= nx && progress > 0.7 {
            score -= 2.4 * ((pr - nx) / cap).min(0.25) * 4.0 * progress;
        }
        if waste > 0.08 && waste < 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.07 * cap && progress > 0.35 {
            score -= 2.9 * (1.0 - (pr - nx) / (0.07 * cap)) * (0.5 + progress);
        }
        if waste > 0.22 && fitting_bins_count <= 1 && progress > 0.5 {
            score += 2.8 * (waste - 0.22) * 10.0 * progress;
        }
        if fitting_bins_count == 1 {
            score -= 14.0 + 12.0 * progress;
        } else if fitting_bins_count == 2 {
            score -= 4.0 + 3.0 * progress;
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps (< 10, or below min item size).
    let min_item = 1u32; // unknown distribution: assume smallest possible item
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual > 0 && post_residual < min_item + 4 {
        score += 40.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Tight fit bonus: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if post_residual as f64 <= (1.0 - fill_ratio) * 5.0 {
        score -= 10.0;
    }

    // Open bins pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 20.0;
        // If lookahead can pair with this item nicely in a fresh bin, reduce penalty.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity && item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Lookahead coupling: favor leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Mean residual alignment: prefer bins whose residual is near mean (avoid fragmentation).
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
