pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale base by relative fill achieved.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 0.8 * fill_ratio * (bin_residual as f64 - post_residual as f64);

    // Penalize dead space that cannot hold a typical future item.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers
    } else if post_residual > 0 {
        // dead space penalty grows if it's below the smallest plausible item
        if post_residual < 20 {
            score += 6.0 * (20.0 - post_residual as f64) / 10.0;
        }
    }

    // Lookahead: reward leaving room for the next item, punish near-misses.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // perfect pairing bonus if residual equals next item size
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // near miss: next item almost fits -> mild penalty for wasting potential
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 15.0 {
                score += 1.5 * miss;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when
    // existing bins have large mean residual but poor fit, or stream is early.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 8.0;
        // cheaper to open new bins early in the stream (long horizon to amortize)
        score -= 6.0 * (1.0 - t);
        // if many bins fit the item, opening a new one is wasteful
        score += 2.0 * (fitting_bins_count as f64).min(5.0);
        // if open bins have high mean residual, prefer consolidating there instead
        score += 0.15 * mean_residual;
        // penalize opening bins when item is small (small items should fill gaps)
        score += 0.3 * (100 - item_size.min(100)) as f64 * 0.1;
    } else {
        // mild bonus for using existing bins as open-bin count grows (consolidation)
        score -= 0.05 * (open_bins_count as f64).min(10.0);
        // prefer bins whose residual is close to the mean (balanced packing)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Late-stream urgency: near the end, prefer minimizing bin count aggressively.
    score -= 3.0 * t * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear penalty on wasted residual (quadratic coupling, normalized by capacity)
    let x = pr / cap;
    score += 40.0 * x * x * (1.0 + progress);

    // Reward tight fits: smooth decay of bonus as post_residual grows
    score -= 25.0 * (-(pr * pr) / (2.0 * cap * cap * (0.05 + 0.1 * progress + 0.05))).exp();

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead coupling: if next item can fill the post_residual, reward this placement
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (-(gap * gap) / 200.0).exp();
        // Penalize leaving residual slightly larger than next item (dead space)
        if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score += 20.0;
        }
    }

    // New-bin candidate handling: mildly discourage opening new bins unless residuals are messy
    if bin_residual == bin_capacity {
        let open_bonus = (open_bins_count as f64).ln().max(0.0);
        let mess = (mean_residual - cap * 0.5).abs() / cap;
        score = cap * 0.35 + 15.0 * open_bonus + 25.0 * (1.0 - progress) - 20.0 * mess;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Small regularization toward mean residual to keep bin balance
    score += 0.1 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
