            score -= 14.0 + 12.0 * progress;
        } else if fitting_bins_count == 2 {
            score -= 4.0 + 3.0 * progress;
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions
    let pr = post_residual;
    let class = pr % (bin_capacity / 4).max(1); // quarter-capacity harmonic class
    // Penalize residuals that fall into "dead" classes (small, hard-to-fill)
    if pr > 0 {
        if pr < 10 {
            score += 30.0; // unusable sliver
        } else if class == 0 {
            score -= 12.0; // exact quarter alignment -> easy to fill later
        } else if class == (bin_capacity / 8).max(1) {
            score -= 6.0; // eighth alignment
        } else {
            score += class as f64 * 0.4; // off-harmonic penalty grows with offset
        }
    }

    // Perfect fit reward via integer division thresholds
    if pr == 0 {
        score -= 100.0;
    } else if bin_residual % 10 == 0 && item_size % 10 == 0 && pr % 10 == 0 {
        score -= 8.0; // decade-aligned packing keeps future items (decade sizes) fitting
    }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 10.0 + (pr - next_item_size) as f64 * 0.3;
            // harmonic match: next item leaves another aligned residual
            if pr % 10 == 0 && next_item_size % 10 == 0 {
                score -= 5.0;
            }
        } else {
            score += 8.0; // next item won't fit here; bin likely dead after this
        }
    } else {
        // last item: prefer exact closure
        score -= pr as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current open bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / cap_f;
        score = cap_f * 0.9
            - fragmentation * 40.0
            - (open_bins_count as f64) * 2.0
            + progress * 10.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 15.0; // big next item: fresh bin is valuable
        }
    }

    // Mild preference to balance load across open bins
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    score
}

