pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it cannot hold even the smallest plausible future item.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64);
    }

    // Non-linear penalty: residuals in the awkward band (1..=15) waste capacity.
    if post_residual >= 1 && post_residual <= 15 {
        score += 25.0 * (16.0 - post_residual as f64);
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * tightness * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Open-bin pressure: discourage spreading across many bins early on.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * open_bins_count as f64 * (1.0 - progress);

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (balanced packing), penalize outliers.
    score += 0.5 * (bin_residual as f64 - mean_residual).abs();

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // Lookahead coupling: if the next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 20.0;
    }
    // If next item almost fits (small shortfall), mildly penalize creating a near-miss.
    if next_item_size > post_residual && next_item_size - post_residual <= 5 && post_residual > 0 {
        score += 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current bins would leave large dead space; make the empty-bin baseline
    // moderately high so it wins only on poor fits.
    if bin_residual == bin_capacity {
        score += 30.0 + 3.0 * open_bins_count as f64 * (1.0 - progress);
        if next_item_size > 0 && (bin_capacity as f64 - item_size as f64) >= next_item_size as f64 {
            score -= 25.0;
        }
    }

    score
}

