            nb -= 5.0 * (1.0 - (cap - it - nx) / (0.08 * cap)) * (0.5 + progress);
        }
        if fitting_bins_count <= 2 {
            nb += 21.0 + 10.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 4 {
            nb -= 6.5 + 8.5 * progress;
        }
        if nx > 0.0 && mean_residual > nx + 8.0 && progress < 0.7 {
            nb += 8.5 * ((mean_residual - nx) / cap).min(0.5) * cap * 0.1;
        }
        if mean_residual >= it && progress > 0.5 {
            nb += 6.5 + 8.5 * progress;
        }
        if nx > it && mean_residual >= nx && progress < 0.6 {
            nb += 10.0 * (1.0 - progress);
        }
        if nx > 0.0 && mean_residual >= it + nx && progress < 0.6 {
            nb -= 5.5 * (1.0 - progress) * ((mean_residual - it - nx) / cap).min(0.3) * 10.0;
        }
        if it > 0.85 * cap && progress > 0.3 {
            nb -= 9.0 * progress;
        }
        if nx > 0.0 && mean_residual > nx {
            let excess = mean_residual - nx;
            if excess < 0.05 * cap && progress < 0.55 {
                nb += 5.0 * (1.0 - excess / (0.05 * cap)) * (1.0 - progress);
            }
        }
        if fitting_bins_count == 0 && progress > 0.25 {
            nb += 9.0 + 7.0 * progress;
        }
        if nx > 0.0 && it + nx > cap && mean_residual >= nx {
            nb += 6.0 * (1.0 - progress);
        }
        if progress > 0.75 && fitting_bins_count > 0 && mean_residual >= it {
            nb += 5.5 + 4.5 * progress;
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_left = mean_residual - it;
            if best_left >= nx && (best_left - nx) < 12.0 {
                nb += 4.0 * (1.0 - (best_left - nx) / 12.0) * (0.5 + progress);
            }
        }
        if it < 0.2 * cap && progress < 0.3 && open_bins_count < 6 {
            nb += 7.0 * (1.0 - progress);
        }
        if item_frac > 0.6 && nx > 0.0 && cap >= it + nx && cap - it - nx < 0.03 * cap {
            nb -= 5.5 * (1.0 - (cap - it - nx) / (0.03 * cap));
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_pr = (mean_residual - it).max(0.0);
            if best_pr > 0.0 && best_pr < 0.06 * cap && (cap - it) >= nx {
                nb -= 7.0 * (1.0 - best_pr / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if progress > 0.85 && mean_residual < 0.15 * cap {
            nb += 7.0 * progress * (1.0 - mean_residual / (0.15 * cap));
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_post = (mean_residual - it).max(0.0);
            if best_post >= nx && best_post - nx > 0.18 * cap && progress > 0.35 {
                nb -= 6.0 * ((best_post - nx) / cap).min(0.4) * (0.4 + progress);
            }
        }
        if item_frac > 0.45 && item_frac < 0.75 && progress > 0.5 {
            nb -= 5.0 * (item_frac - 0.45) * progress;
        }
        if fitting_bins_count >= 2 && mean_residual < 0.25 * cap && progress > 0.6 {
            nb += 6.0 * (1.0 - mean_residual / (0.25 * cap)) * progress;
        }
        if fitting_bins_count >= 3 && mean_residual - it >= nx && progress > 0.5 {
            nb += 4.5 * progress * (1.0 - ((mean_residual - it - nx) / cap).min(1.0));
        }
        if open_bins_count > 10 && progress < 0.35 && item_frac < 0.3 {
            nb += 6.0 * (1.0 - progress) * (1.0 - item_frac / 0.3);
        }
        // NEW: discourage opening a new bin when existing mean residual could
        // still host the item plus the next one (fragmentation guard).
        if nx > 0.0 && mean_residual >= it + nx && progress < 0.65 {
            let rem = mean_residual - it - nx;
            if rem < 0.12 * cap {
                nb += 4.5 * (1.0 - rem / (0.12 * cap)) * (0.6 + progress);
            }
        }
        // NEW: mid-stream, avoid new bins whose first residual would be a
        // near-dead sliver for the next item (tightened threshold).
        if nx > 0.0 && progress > 0.5 {
            let r1 = cap - it;
            if r1 > 0.0 && r1 < 0.5 * nx {
                nb += 6.0 * (1.0 - r1 / (0.5 * nx)) * progress;
            }
        }
        score = nb;
    } else {
        // Fine-grained residual fitting with lookahead anticipation
        let fill_ratio = 1.0 - res / cap;
        if waste < 0.08 {
            score -= 48.0 * (1.0 - progress) * (0.08 - waste);
        }
        if fill_ratio > 0.65 {
            score -= 4.8 * (fill_ratio - 0.65) * 10.0 * (0.4 + progress);
        }
        if nx > 0.0 && nx <= pr && pr > 0.0 {
            let gap = (pr - nx) / cap;
            if gap < 0.03 {
                score -= 7.5 * (1.0 - gap * 33.0);
            }
            if gap <= 0.04 {
                score -= 3.2 * (1.0 - gap / 0.04) * (1.0 - progress);
            }
        }
        if pr > 0.0 && pr < 10.0 {
            score += 41.0 * (1.0 - 0.5 * progress);
        }
        if pr == 0.0 {
            score -= 62.0;
        } else if pr <= 5.0 {
            score -= 31.0 * (1.0 - 0.4 * progress);
        }
        let dev = mean_residual - res;
        score += 0.085 * dev;
        if dev > -5.0 && dev < 15.0 && pr > 0.0 {
            score -= 4.2;
        }
        let tight_fit = (pr == 0.0) || (nx > 0.0 && pr == nx);
        if tight_fit {
            score -= 10.5 * (0.3 + progress);
        }
        if nx > 0.0 && pr >= nx {
            let room = pr - nx;
            if room < 0.06 * cap {
                score -= 6.5 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if waste > 0.14 && waste < 0.34 {
            score += 13.0 * (waste - 0.14) * (0.6 + 0.8 * progress);
        }
        if fitting_bins_count > 3 && waste < 0.12 {
            score -= 5.5 * (1.0 - waste * 8.0) * (0.5 + progress);
        }
        if nx > 0.0 && pr > 0.0 && pr > nx && (pr - nx) < 0.02 * cap {
            score -= 4.0 * (1.0 - (pr - nx) / (0.02 * cap)) * (0.4 + progress);
        }
        if pr > 0.0 && (pr as f64).sqrt() < 2.6 {
            score -= 3.5 * (1.0 - progress);
        }
        if waste > 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.09 * cap && progress > 0.4 {
            score -= 4.0 * (1.0 - (pr - nx) / (0.09 * cap)) * progress;
        }
        if pr > 0.0 && nx > 0.0 && pr < 0.5 * nx && progress > 0.3 {
            score += 3.5 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
        }
        if waste > 0.3 && pr > nx && progress < 0.5 {
            score += 3.0 * (waste - 0.3) * 10.0 * (1.0 - progress);
        }
        if fill_ratio > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
            score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
        }
        if waste > 0.35 && progress > 0.55 && nx > 0.0 && pr >= nx {
            score -= 4.5 * ((pr - nx) / cap).min(0.2) * 5.0 * progress;
        }
        // NEW: sharpen dead-space penalty when residual slightly misses next item
        if nx > 0.0 && pr > 0.0 && pr < nx {
            let closeness = 1.0 - pr / nx;
            score += 3.5 * closeness * closeness * (0.6 + progress);
        }
        // NEW: reward bins whose post-residual leaves exactly chainable room
        if nx > 0.0 && pr > nx && (pr - nx) <= 0.04 * cap {
            score -= 3.2 * (1.0 - (pr - nx) / (0.04 * cap)) * (1.0 - progress);
        }
        // Scarcity: prefer using existing bins when few can fit
        if fitting_bins_count == 1 {
            score -= 14.0 + 12.0 * progress;
        } else if fitting_bins_count == 2 {
            score -= 4.0 + 3.0 * progress;
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // Slight penalty if next item can't fit here (post_residual < next_item_size)
        if post_residual < next_item_size {
            score += 8.0;
        }
    } else {
        // Last item: prefer minimal waste
        score += 5.0;
    }

    // Penalize dead space that is too small for typical items (unusable gap)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward using bins with below-average residual (consolidate emptier bins)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor filling it rather than opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 30.0 + 20.0 * progress - crowding;
        // If next item is large, a fresh bin is more attractive
        if next_item_size >= 60 {
            score -= 15.0;
        }
    }

    // Mild pressure toward tight fits as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64 / bin_capacity as f64) * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual is good, but dead space 1..=5 is worst.
    if post_residual > 0 && post_residual <= 5 {
        score += 25.0; // unusable sliver
    } else {
        score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use leftover; penalize large leftover proportionally
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let crowding = (open_bins_count as f64).ln() + 1.0;
    score -= crowding * (mean_residual / bin_capacity as f64) * (5.0 + 10.0 * progress);

    // New-bin candidate: penalize opening a bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 35.0
            - 20.0 * (1.0 - item_size as f64 / bin_residual as f64)
            + 15.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 25.0; // pair large items together in fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in [0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear polynomial coupling of post_residual with progress.
    // Early in the stream, minimize post_residual aggressively (tight packing);
    // later, allow larger residuals since bins are already committed.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap; // in [0,1]
    let w = 0.5 + 1.5 * progress; // weight grows smoothly with progress
    let coupling = w * (norm_pr * norm_pr) * cap;
    score += coupling;

    // Penalize wasted space relative to mean residual across open bins (smooth quadratic divergence)
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Lookahead: reward leaving room for the next item (smooth Gaussian-like affinity)
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let diff = pr - next_item_size as f64;
        score -= 8.0 * (-(diff * diff) / 1800.0).exp();
    } else if next_item_size > 0 {
        // residual can't fit next item: mild penalty growing with shortfall
        let short = next_item_size as f64 - pr;
        score += 2.0 + 0.05 * short;
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize opening a new bin, more so early in the stream
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { (step_index as f64 / total_items as f64).clamp(0.0, 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;
    let waste = (pr / cap).max(0.0);

    // New-bin candidate: rich lookahead model deciding when a fresh bin beats a poor fit.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let item_frac = (it / cap).min(1.0);
        let mut nb = cap * (1.35 + 1.15 * progress);
        nb -= 26.0 * scarcity * (1.0 - progress);
        nb -= 19.0 * item_frac * (1.0 - progress);
        if nx >= 0.5 * cap { nb -= 12.0 * progress + 6.0 * (1.0 - progress); }
        nb += 15.0 * progress * (1.0 - item_frac);
        if it >= cap - 1.0 { nb -= 32.0; }
        if nx > 0.0 && cap - it >= nx { nb -= 10.5 + 0.11 * (cap - it - nx); }
        if nx > 0.0 {
            let r1 = cap - it;
            if r1 >= nx && (r1 - nx) < 6.0 && (r1 - nx) > 0.0 { nb += 8.5 * (1.0 - progress); }
        }
        if fitting_bins_count <= 2 { nb += 21.0 + 10.0 * (1.0 - progress); }
        if fitting_bins_count >= 4 { nb -= 6.5 + 8.5 * progress; }
        if nx > 0.0 && mean_residual > nx + 8.0 && progress < 0.7 {
            nb += 8.5 * ((mean_residual - nx) / cap).min(0.5) * cap * 0.1;
        }
        if mean_residual >= it && progress > 0.5 { nb += 6.5 + 8.5 * progress; }
        if nx > it && mean_residual >= nx && progress < 0.6 { nb += 10.0 * (1.0 - progress); }
        if nx > 0.0 && mean_residual >= it + nx && progress < 0.6 {
            nb -= 5.5 * (1.0 - progress) * ((mean_residual - it - nx) / cap).min(0.3) * 10.0;
        }
        if it > 0.85 * cap && progress > 0.3 { nb -= 9.0 * progress; }
        if nx > 0.0 && mean_residual > nx {
            let excess = mean_residual - nx;
            if excess < 0.05 * cap && progress < 0.55 { nb += 5.0 * (1.0 - excess / (0.05 * cap)) * (1.0 - progress); }
        }
        if fitting_bins_count == 0 && progress > 0.25 { nb += 9.0 + 7.0 * progress; }
        if nx > 0.0 && it + nx > cap && mean_residual >= nx { nb += 6.0 * (1.0 - progress); }
        if progress > 0.75 && fitting_bins_count > 0 && mean_residual >= it { nb += 5.5 + 4.5 * progress; }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_left = mean_residual - it;
            if best_left >= nx && (best_left - nx) < 12.0 {
                nb += 4.0 * (1.0 - (best_left - nx) / 12.0) * (0.5 + progress);
            }
        }
        if item_frac / cap > 0.6 && nx > 0.0 && cap >= it + nx && cap - it - nx < 0.03 * cap {
            nb -= 5.5 * (1.0 - (cap - it - nx) / (0.03 * cap));
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_pr = (mean_residual - it).max(0.0);
            if best_pr > 0.0 && best_pr < 0.06 * cap && (cap - it) >= nx {
                nb -= 7.0 * (1.0 - best_pr / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if progress > 0.85 && mean_residual < 0.15 * cap {
            nb += 7.0 * progress * (1.0 - mean_residual / (0.15 * cap));
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_post = (mean_residual - it).max(0.0);
            if best_post >= nx && best_post - nx > 0.18 * cap && progress > 0.35 {
                nb -= 6.0 * ((best_post - nx) / cap).min(0.4) * (0.4 + progress);
            }
        }
        if item_frac > 0.45 && item_frac < 0.75 && progress > 0.5 {
            nb -= 5.0 * (item_frac - 0.45) * progress;
        }
        if fitting_bins_count >= 2 && mean_residual < 0.25 * cap && progress > 0.6 {
            nb += 6.0 * (1.0 - mean_residual / (0.25 * cap)) * progress;
        }
        if open_bins_count > 10 && progress < 0.35 && item_frac < 0.3 {
            nb += 6.0 * (1.0 - progress) * (1.0 - item_frac / 0.3);
        }
        if nx > 0.0 {
            let r1 = cap - it;
            if r1 < nx && r1 > 0.0 { nb += (1.0 + 2.0 * progress) * (nx - r1) * 0.55; }
            if r1 >= nx && (r1 - nx) > 0.25 * cap && progress > 0.45 {
                nb += 4.5 * ((r1 - nx) / cap).min(0.5) * progress;
            }
        }
        if nx > 0.0 && cap >= it + nx && (cap - it - nx) < 0.08 * cap && progress > 0.3 {
            nb -= 5.0 * (1.0 - (cap - it - nx) / (0.08 * cap)) * (0.5 + progress);
        }
        if open_bins_count > 6 && mean_residual > 0.4 * cap && progress < 0.6 {
            nb += 5.0 * ((mean_residual - 0.4 * cap) / cap) * (1.0 - progress)
                * ((open_bins_count as f64 - 6.0).min(8.0) / 8.0);
        }
        if item_frac < 0.15 && progress > 0.55 && fitting_bins_count >= 1 {
            nb += 6.0 * progress * (1.0 - item_frac / 0.15);
        }
        return nb;
    }

    // Existing-bin scoring: tightness-driven with lookahead chain rewards.
    let mut score = pr * (1.0 + 0.03 * waste * waste);
    let tightness = 1.0 + 2.6 * progress * progress + 2.4 * progress * progress * progress;
    score *= tightness;

    // Chain fit: reward placements whose post-residual hosts the next item well.
    if nx > 0.0 {
        if pr < nx {
            let gap = nx - pr;
            score += gap * (2.0 + 6.5 * (1.0 - progress));
            if gap <= 3.0 { score -= 9.0 * (1.0 - progress); }
        } else {
            let chain_gap = pr - nx;
            let slack = chain_gap / cap;
            if chain_gap <= 42.0 { score -= 6.5 + 0.11 * chain_gap; }
            if slack < 0.04 { score -= 8.5 * (1.0 - slack * 25.0) * (1.0 + progress); }
            let chain = 1.0 - slack.min(1.0);
            score -= 5.0 + 4.0 * (nx / cap) + 9.5 * chain * (1.0 - progress);
        }
    }

    // Dead-space penalty scaled by unusability for the next item.
    let unusable = if nx > 0.0 && pr > 0.0 && pr < nx { 1.0 } else { 0.55 };
    score += (10.5 + 3.2 * progress) * waste * waste * cap * (0.45 + progress) * unusable;

    // Near-perfect fit bonus: tiny slivers are excellent outcomes.
    if waste > 0.0 && waste < 0.12 {
        score -= 9.0 * (1.0 - waste / 0.12) * (0.4 + progress);
    }

    // Next item almost fits the leftover: mild penalty for blocking the chain.
    if pr > 0.0 && nx > 0.0 && pr < nx && (nx - pr) <= 0.04 * cap {
        score += 3.5 * (1.0 - (nx - pr) / (0.04 * cap)) * (0.5 + progress);
    }

    // Exact-fill reward (item consumes the whole residual).
    if pr == 0.0 { score -= 62.0; }
    else if pr <= 5.0 { score -= 31.0 * (1.0 - 0.4 * progress); }

    // Deviation from mean residual: keep big-residual bins available for big items.
    let dev = mean_residual - res;
    score += 0.085 * dev;
    if dev > -5.0 && dev < 15.0 && pr > 0.0 { score -= 4.2; }

    // Last-chance bin: strongly prefer the only fitting bin.
    if fitting_bins_count == 1 { score -= 12.0 + 0.4 * it; }

    // Moderate waste band penalty: avoid mid-range fragmentation.
    if waste > 0.14 && waste < 0.34 {
        score += 13.0 * (waste - 0.14) * (0.6 + 0.8 * progress);
    }

    // Many fitting bins + low waste: this is a great consolidation target.
    if fitting_bins_count > 3 && waste < 0.12 {
        score -= 5.5 * (1.0 - waste * 8.0) * (0.5 + progress);
    }

    // Next item leaves a near-exact second fit.
    if nx > 0.0 && pr > nx && (pr - nx) < 0.02 * cap {
        score -= 4.0 * (1.0 - (pr - nx) / (0.02 * cap)) * (0.4 + progress);
    }

    // Small absolute residual: hard-to-use sliver.
    if pr > 0.0 && pr.sqrt() < 2.6 { score -= 3.5 * (1.0 - progress); }

    // Large leftover after next item with high waste: keep for later.
    if waste > 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.09 * cap && progress > 0.4 {
        score -= 4.0 * (1.0 - (pr - nx) / (0.09 * cap)) * progress;
    }

    // Very small residual relative to next item: bad target late.
    if pr > 0.0 && nx > 0.0 && pr < 0.5 * nx && progress > 0.3 {
        score += 3.5 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
    }

    // High fill ratio with room for next item: strong consolidation.
    if res / cap > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 3.0 * (res / cap - 0.85) * 10.0 * progress;
    }

    // Wide-band chain fit with next item.
    if nx > 0.0 && pr > nx && (pr - nx) <= 0.04 * cap {
        score -= 3.2 * (1.0 - (pr - nx) / (0.04 * cap)) * (1.0 - progress);
    }
    if nx > 0.0 && pr > nx && (pr - nx) > 0.04 * cap && (pr - nx) < 0.18 * cap {
        score -= 2.2 * (1.0 - ((pr - nx) / (0.18 * cap))) * (0.3 + progress);
    }

    // Closing many open bins: mild consolidation pressure via log count.
    score -= 0.42 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how it decomposes modulo capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space classes: residuals that no item (1..=100) can use well.
    // Residuals < 10 are near-waste (interface note allows items >= 1, but tiny
    // residuals are still poor); residuals in "prime-ish" awkward classes get penalized.
    if post_residual < 5 {
        score -= 40.0; // tiny residual is effectively closed, that's fine
    } else if post_residual <= 10 {
        score -= 15.0;
    } else {
        // Modulo-10 harmonic class: residuals that are multiples of 10 pair well
        // with the classic 10..80 size grid; odd/prime residuals waste more.
        let m10 = post_residual % 10;
        let m5 = post_residual % 5;
        let class_penalty = match m10 {
            0 => -20.0,
            5 => -10.0,
            _ => {
                if m5 == 0 { -5.0 } else { 3.0 + (m10 as f64) * 0.4 }
            }
        };
        score += class_penalty;

        // Integer-division thresholds: residual in [11,50] can host a mid item;
        // residual in [51,100] is a "half-open" class, valuable.
        let half = (bin_capacity / 2) as f64;
        if pr > half {
            score -= 12.0;
        } else if pr > half * 0.5 {
            score -= 4.0;
        } else {
            score += 6.0;
        }
    }

    // Lookahead coupling: does post_residual fit the next item exactly or well?
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 300.0; // perfect chain
        } else if next_item_size < post_residual {
            // Harmonic compatibility: next item's class vs residual class
            let slack = (post_residual - next_item_size) as f64;
            if slack < 5.0 {
                score -= 60.0;
            } else {
                // penalize by leftover after next placement, damped
                score += slack * 0.5;
                // reward if post_residual - next is a multiple of 10
                if (post_residual - next_item_size) % 10 == 0 {
                    score -= 10.0;
                }
            }
        } else {
            // next item cannot use this bin's remainder: residual may be wasted
            score += 8.0 + (n - pr).min(50.0) * 0.1;
        }
    } else {
        // Last item: prefer exact/tight fits, close bins greedily.
        score -= 50.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // current bin would leave a large, awkward residual.
    if bin_residual == bin_capacity {
        // New bin: score is the residual after placing = capacity - item.
        // Bias it so it's chosen only for large items / bad existing fits.
        score += 25.0;
        if item_size >= 60 {
            score -= 30.0; // big items start fresh bins happily
        }
    }

    // Congestion: many open bins with high mean residual -> consolidate.
    if open_bins_count > 2 && mean_residual > 40.0 && bin_residual != bin_capacity {
        score -= (mean_residual - 40.0).min(30.0) * 0.3;
    }

    // Stream progression: late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;
    let waste = pr / cap;
    let mut score = pr * (1.0 + 0.03 * waste * waste);

    let tightness = 1.0 + 2.6 * progress * progress + 2.4 * progress * progress * progress;
    score *= tightness;

    // Combined: dead-space quadratic penalty (from best) with lookahead chain logic
    let dead_ratio = (pr / cap).max(0.0);
    let unusable = if nx > 0.0 && pr > 0.0 && pr < nx { 1.0 } else { 0.55 };
    score += (10.5 + 3.2 * progress) * dead_ratio * dead_ratio * cap * (0.45 + progress) * unusable;
    if dead_ratio > 0.0 && dead_ratio < 0.12 {
        score -= 9.0 * (1.0 - dead_ratio / 0.12) * (0.4 + progress);
    }
    if pr > 0.0 && nx > 0.0 && pr < nx && (nx - pr) <= 0.04 * cap {
        score += 3.5 * (1.0 - (nx - pr) / (0.04 * cap)) * (0.5 + progress);
    }

    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let item_frac = (it / cap).min(1.0);
        let mut nb = cap * (1.35 + 1.15 * progress);
        nb -= 26.0 * scarcity * (1.0 - progress);
        nb -= 19.0 * item_frac * (1.0 - progress);
        if nx >= 0.5 * cap {
            nb -= 12.0 * progress + 6.0 * (1.0 - progress);
        }
        nb += 15.0 * progress * (1.0 - item_frac);
        if it >= cap - 1.0 {
            nb -= 32.0;
        }
        if nx > 0.0 && cap - it >= nx {
            nb -= 10.5 + 0.11 * (cap - it - nx);
        }
        if nx > 0.0 {
            let r1 = cap - it;
            if r1 >= nx && (r1 - nx) < 6.0 && (r1 - nx) > 0.0 {
                nb += 8.5 * (1.0 - progress);
            }
        }
        if fitting_bins_count <= 2 {
            nb += 21.0 + 10.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 4 {
            nb -= 6.5 + 8.5 * progress;
        }
        if nx > 0.0 && mean_residual > nx + 8.0 && progress < 0.7 {
            nb += 8.5 * ((mean_residual - nx) / cap).min(0.5) * cap * 0.1;
        }
        if mean_residual >= it && progress > 0.5 {
            nb += 6.5 + 8.5 * progress;
        }
        if nx > it && mean_residual >= nx && progress < 0.6 {
            nb += 10.0 * (1.0 - progress);
        }
        if nx > 0.0 && mean_residual >= it + nx && progress < 0.6 {
            nb -= 5.5 * (1.0 - progress) * ((mean_residual - it - nx) / cap).min(0.3) * 10.0;
        }
        if it > 0.85 * cap && progress > 0.3 {
            nb -= 9.0 * progress;
        }
        if nx > 0.0 && mean_residual > nx {
            let excess = mean_residual - nx;
            if excess < 0.05 * cap && progress < 0.55 {
                nb += 5.0 * (1.0 - excess / (0.05 * cap)) * (1.0 - progress);
            }
        }
        if fitting_bins_count == 0 && progress > 0.25 {
            nb += 9.0 + 7.0 * progress;
        }
        if nx > 0.0 && it + nx > cap && mean_residual >= nx {
            nb += 6.0 * (1.0 - progress);
        }
        if progress > 0.75 && fitting_bins_count > 0 && mean_residual >= it {
            nb += 5.5 + 4.5 * progress;
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_left = mean_residual - it;
            if best_left >= nx && (best_left - nx) < 12.0 {
                nb += 4.0 * (1.0 - (best_left - nx) / 12.0) * (0.5 + progress);
            }
        }
        if it < 0.2 * cap && progress < 0.3 && open_bins_count < 6 {
            nb += 7.0 * (1.0 - progress);
        }
        if item_frac > 0.6 && nx > 0.0 && cap >= it + nx && cap - it - nx < 0.03 * cap {
            nb -= 5.5 * (1.0 - (cap - it - nx) / (0.03 * cap));
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_pr = (mean_residual - it).max(0.0);
            if best_pr > 0.0 && best_pr < 0.06 * cap && (cap - it) >= nx {
                nb -= 7.0 * (1.0 - best_pr / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if progress > 0.85 && mean_residual < 0.15 * cap {
            nb += 7.0 * progress * (1.0 - mean_residual / (0.15 * cap));
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_post = (mean_residual - it).max(0.0);
            if best_post >= nx && best_post - nx > 0.18 * cap && progress > 0.35 {
                nb -= 6.0 * ((best_post - nx) / cap).min(0.4) * (0.4 + progress);
            }
        }
        if item_frac > 0.45 && item_frac < 0.75 && progress > 0.5 {
            nb -= 5.0 * (item_frac - 0.45) * progress;
        }
        if fitting_bins_count >= 2 && mean_residual < 0.25 * cap && progress > 0.6 {
            nb += 6.0 * (1.0 - mean_residual / (0.25 * cap)) * progress;
        }
        if fitting_bins_count >= 3 && mean_residual - it >= nx && progress > 0.5 {
            nb += 4.5 * progress * (1.0 - ((mean_residual - it - nx) / cap).min(1.0));
        }
        if open_bins_count > 10 && progress < 0.35 && item_frac < 0.3 {
            nb += 6.0 * (1.0 - progress) * (1.0 - item_frac / 0.3);
        }
        if nx > 0.0 {
            let r1 = cap - it;
            if r1 < nx && r1 > 0.0 {
                nb += (1.0 + 2.0 * progress) * (nx - r1) * 0.55;
            }
            if r1 >= nx && (r1 - nx) > 0.25 * cap && progress > 0.45 {
                nb += 4.5 * ((r1 - nx) / cap).min(0.5) * progress;
            }
        }
        if nx > 0.0 && cap >= it + nx && (cap - it - nx) < 0.08 * cap && progress > 0.3 {
            nb -= 5.0 * (1.0 - (cap - it - nx) / (0.08 * cap)) * (0.5 + progress);
        }
        // NEW: open-bins fragmentation pressure — avoid new bins when many
        // open bins still carry generous mean residual.
        if open_bins_count > 6 && mean_residual > 0.4 * cap && progress < 0.6 {
            nb += 5.0 * ((mean_residual - 0.4 * cap) / cap) * (1.0 - progress) * ((open_bins_count as f64 - 6.0).min(8.0) / 8.0);
        }
        if item_frac < 0.15 && progress > 0.55 && fitting_bins_count >= 1 {
            nb += 6.0 * progress * (1.0 - item_frac / 0.15);
        }
        if nx > 0.0 && cap - it > 0.0 && cap - it < nx {
            nb += 4.5 * (1.0 - progress) * ((nx - (cap - it)) / cap).min(0.3) * 10.0;
        }
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin < 0.15 * cap {
                nb -= 6.0 * (1.0 - margin / (0.15 * cap)) * (0.6 + 0.4 * progress);
            }
        }
        if nx > 0.0 && fitting_bins_count >= 1 && mean_residual - it >= nx {
            let leftover = mean_residual - it - nx;
            if leftover < 0.1 * cap && progress > 0.45 {
                nb -= 5.0 * (1.0 - leftover / (0.1 * cap)) * progress;
            }
        }
        if nx > 0.0 && fitting_bins_count >= 2 && mean_residual > 0.5 * cap && progress < 0.4 {
            nb += 4.5 * ((mean_residual - 0.5 * cap) / cap) * (1.0 - progress);
        }
        if open_bins_count > 12 && progress > 0.6 && item_frac < 0.25 {
            nb += 5.0 * progress * (1.0 - item_frac / 0.25);
        }
        if nx > 0.0 && fitting_bins_count >= 1 && (cap - it) >= nx && (cap - it - nx) < 0.05 * cap && progress < 0.5 {
            nb -= 4.0 * (1.0 - (cap - it - nx) / (0.05 * cap)) * (1.0 - progress);
        }
        if nx > 0.0 && (cap - it).max(0.0) < nx && fitting_bins_count <= 1 && mean_residual < 0.3 * cap {
            nb += 3.5 * (1.0 - mean_residual / (0.3 * cap)) * (0.5 + progress);
        }
        if fitting_bins_count >= 2 && mean_residual >= it + nx && progress > 0.4 {
            let rem = mean_residual - it - nx;
            if rem < 0.05 * cap {
                nb -= 4.5 * (1.0 - rem / (0.05 * cap)) * progress;
            }
        }
        if fitting_bins_count == 1 && mean_residual >= it && (mean_residual - it) < 0.04 * cap && progress > 0.3 {
            nb -= 3.0 * (1.0 - (mean_residual - it) / (0.04 * cap)) * (0.5 + progress);
        }
        if open_bins_count > 8 && mean_residual < 0.1 * cap && progress > 0.5 {
            nb -= 4.0 * (1.0 - mean_residual / (0.1 * cap)) * progress;
        }
        if fitting_bins_count >= 1 && mean_residual >= it && progress > 0.65 {
            let best_pr = (mean_residual - it).max(0.0);
            if best_pr > 0.0 && best_pr < 0.05 * cap {
                nb += 5.5 * (1.0 - best_pr / (0.05 * cap)) * progress;
            }
        }
        if nx > 0.0 && mean_residual >= it + nx && progress > 0.55 {
            let rem = mean_residual - it - nx;
            if rem > 0.2 * cap {
                nb += 3.5 * ((rem - 0.2 * cap) / cap).min(0.3) * 10.0 * progress;
            }
        }
        if nx > 0.0 && cap >= it + nx && cap - it - nx < 0.02 * cap && fitting_bins_count <= 3 {
            nb -= 3.5 * (1.0 - (cap - it - nx) / (0.02 * cap)) * (0.6 + progress);
        }
        if open_bins_count > 14 && mean_residual > 0.55 * cap && progress > 0.5 {
            nb += 4.0 * ((mean_residual - 0.55 * cap) / cap).min(0.3) * 10.0 * progress;
        }
        if item_frac < 0.1 && progress > 0.7 && fitting_bins_count >= 2 {
            nb += 5.0 * progress;
        }
        if nx > 0.0 && fitting_bins_count >= 1 && mean_residual >= it + nx && progress > 0.7 {
            let rem = mean_residual - it - nx;
            if rem < 0.03 * cap {
                nb -= 3.2 * (1.0 - rem / (0.03 * cap)) * progress;
            }
        }
        if item_frac < 0.2 && nx > 0.0 && mean_residual >= it + nx && progress > 0.6 {
            nb -= 4.0 * (1.0 - item_frac / 0.2) * progress;
        }
        if nx > 0.0 && mean_residual < nx && progress > 0.55 && item_frac < 0.5 {
            nb += 3.5 * (nx - mean_residual).min(0.1 * cap) / (0.1 * cap) * progress;
        }
        if nx > 0.0 && fitting_bins_count >= 1 && mean_residual >= it + nx && progress > 0.45 {
            let rem = mean_residual - it - nx;
            if rem > 0.12 * cap && rem < 0.3 * cap {
                nb -= 3.8 * (1.0 - (rem - 0.12 * cap) / (0.18 * cap)) * (0.4 + progress);
            }
        }
        if open_bins_count > 5 && progress > 0.3 && item_frac > 0.55 {
            nb -= 3.5 * (item_frac - 0.55) * 2.0 * progress;
        }
        if nx > 0.0 && mean_residual > 0.6 * cap && progress < 0.5 && fitting_bins_count >= 3 {
            nb += 4.0 * ((mean_residual - 0.6 * cap) / cap).min(0.3) * 10.0 * (1.0 - progress);
        }
        score = nb;
    } else {
        // Fine-grained residual fitting with lookahead anticipation
        let fill_ratio = 1.0 - res / cap;
        if waste < 0.08 {
            score -= 48.0 * (1.0 - progress) * (0.08 - waste);
        }
        if fill_ratio > 0.65 {
            score -= 4.8 * (fill_ratio - 0.65) * 10.0 * (0.4 + progress);
        }
        if nx > 0.0 && nx <= pr && pr > 0.0 {
            let gap = (pr - nx) / cap;
            if gap < 0.03 {
                score -= 7.5 * (1.0 - gap * 33.0);
            }
            if gap <= 0.04 {
                score -= 3.2 * (1.0 - gap / 0.04) * (1.0 - progress);
            }
            let chain = 1.0 - gap.min(1.0);
            score -= 5.0 + 4.0 * (nx / cap) + 9.5 * chain * (1.0 - progress);
        }
        if pr > 0.0 && pr < 10.0 {
            score += 41.0 * (1.0 - 0.5 * progress);
        }
        if pr == 0.0 {
            score -= 62.0;
        } else if pr <= 5.0 {
            score -= 31.0 * (1.0 - 0.4 * progress);
        }
        if nx > 0.0 && pr > 0.0 && pr < nx {
            let gap = nx - pr;
            score += gap * (2.0 + 6.5 * (1.0 - progress));
            if gap <= 3.0 {
                score -= 9.0 * (1.0 - progress);
            }
            let closeness = 1.0 - pr / nx;
            score += 3.0 * closeness * closeness * (0.6 + progress);
        }
        let dev = mean_residual - res;
        score += 0.085 * dev;
        if dev > -5.0 && dev < 15.0 && pr > 0.0 {
            score -= 4.2;
        }
        let tight_fit = (pr == 0.0) || (nx > 0.0 && pr == nx);
        if tight_fit {
            score -= 10.5 * (0.3 + progress);
        }
        if nx > 0.0 && pr >= nx {
            let room = pr - nx;
            if room < 0.06 * cap {
                score -= 6.5 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if waste > 0.14 && waste < 0.34 {
            score += 13.0 * (waste - 0.14) * (0.6 + 0.8 * progress);
        }
        if fitting_bins_count > 3 && waste < 0.12 {
            score -= 5.5 * (1.0 - waste * 8.0) * (0.5 + progress);
        }
        if nx > 0.0 && pr > 0.0 && pr > nx && (pr - nx) < 0.02 * cap {
            score -= 4.0 * (1.0 - (pr - nx) / (0.02 * cap)) * (0.4 + progress);
        }
        if pr > 0.0 && (pr as f64).sqrt() < 2.6 {
            score -= 3.5 * (1.0 - progress);
        }
        if waste > 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.09 * cap && progress > 0.4 {
            score -= 4.0 * (1.0 - (pr - nx) / (0.09 * cap)) * progress;
        }
        if pr > 0.0 && nx > 0.0 && pr < nx && (nx - pr) > 0.1 * cap && waste > 0.25 {
            score += 5.0 * (waste - 0.25) * 10.0 * (0.4 + progress);
        }
        if pr > 0.0 && nx > 0.0 && pr < 0.5 * nx && progress > 0.3 {
            score += 3.5 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
        }
        if waste > 0.3 && pr > nx && progress < 0.5 {
            score += 3.0 * (waste - 0.3) * 10.0 * (1.0 - progress);
        }
        if fill_ratio > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
            score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
        }
        if waste > 0.35 && progress > 0.55 && nx > 0.0 && pr >= nx {
            score -= 4.5 * ((pr - nx) / cap).min(0.2) * 5.0 * progress;
        }
        if nx > 0.0 && pr > nx && (pr - nx) > 0.04 * cap && (pr - nx) < 0.18 * cap {
            score -= 2.2 * (1.0 - ((pr - nx) / (0.18 * cap))) * (0.3 + progress);
        }
        if nx > 0.0 && pr >= nx && (pr - nx) < 0.5 * nx && progress > 0.6 {
            score -= 2.8 * (1.0 - (pr - nx) / (0.5 * nx)) * progress;
        }
        if waste > 0.18 && waste < 0.4 && nx > 0.0 && pr >= nx && (pr - nx) < 0.12 * cap {
            score += 3.0 * (1.0 - (pr - nx) / (0.12 * cap)) * (0.5 + progress);
        }
        // Scarcity: prefer using existing bins when few can fit
        if fitting_bins_count == 1 {
            score -= 14.0 + 12.0 * progress;
        } else if fitting_bins_count == 2 {
            score -= 4.0 + 3.0 * progress;
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: the smaller the post_residual, the better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Dead-space penalty: gap too small for the lookahead item is unusable next step.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0 + 0.5 * post_residual as f64;
    }
    // Dead space below the minimum plausible item (1) is truly unusable.
    if post_residual == 0 {
        score -= 25.0; // perfect fit
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate penalty: opening a new bin wastes residual capacity of
    // all open bins; scale pressure with number of open bins and progress.
    if bin_residual == bin_capacity {
        score += 18.0 + 2.0 * open_bins_count as f64 + 10.0 * progress;
    } else {
        // Mild reward for consolidating into already-open bins.
        score -= 2.0 + 0.3 * open_bins_count as f64;
    }

    // Prefer bins whose residual is close to the item (avoid spreading waste).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * gap;

    // Slight preference for bins below mean residual (fill the emptier ones
    // less; keep fat bins for future big items) — invert: filling a bin with
    // residual above mean wastes less per bin on average.
    if bin_residual as f64 > mean_residual {
        score -= 1.5;
    } else {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.94;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * tightness * tightness;

    // Perfect fit gets a large bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize leaving dead space that no plausible future item could use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver is wasted capacity
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // this placement is part of a chain — reward it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here after placement; slight penalty for
            // fragmenting this bin beyond use.
            score += 5.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    } else {
        // Last item in stream: only the fill matters.
        score -= 30.0 * (1.0 - tightness);
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item fits poorly in existing bins and many bins are already open.
    if bin_residual == bin_capacity {
        // Base cost of consuming a fresh bin.
        let mut new_bin_score = 70.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Late in the stream, prefer consolidating into open bins.
        new_bin_score += 30.0 * progress;
        // If the current bin fits poorly (large post_residual relative to item),
        // opening a new bin becomes more attractive.
        let poor_fit = (post_residual as f64) / (item_size.max(1) as f64);
        if poor_fit > 1.0 {
            new_bin_score -= 25.0 * (poor_fit - 1.0).min(2.0);
        }
        // If many open bins with large mean residual, consolidation is cheap.
        if mean_residual > item_size as f64 * 1.5 {
            new_bin_score += 20.0;
        }
        // Perfect fit in an existing bin makes new-bin very unattractive.
        if post_residual == 0 && bin_residual != bin_capacity {
            new_bin_score += 50.0;
        }
        return new_bin_score;
    }

    // Global state: with many open bins, slightly favor filling existing ones
    // (reduces fragmentation) over opening new bins.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Mild preference for bins with residual close to the mean (keeps
    // residuals uniform, improving future fit chances).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual cost, with smooth non-linear penalty on wasted space
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth interaction: post-residual scaled by stream progress (tighten late in stream)
    score += 25.0 * norm_pr * (progress * progress);

    // Favor bins whose post-residual matches the next item (lookahead coupling)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let match_term = 1.0 - (pr - n).abs() / cap;
        score -= 12.0 * match_term.max(0.0) * (0.5 + 0.5 * progress);
    } else {
        // Last item: strongly prefer minimizing residual
        score += 20.0 * norm_pr;
    }

    // Last-chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Slight penalty for spreading across many open bins relative to mean residual
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (pr - mean_residual).abs();

    // New-bin candidate: penalize mildly so it wins only when fits are poor
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: classify post_residual into coarse buckets
    // using integer division on a 12-unit grid (capacity 100 -> 8 classes).
    let class = post_residual / 12;
    let class_penalty = match class {
        0 => -40.0,                    // perfect / near-perfect fit
        1 => -18.0,                    // excellent (1..12)
        2 => -8.0,                     // good
        3 => 0.0,
        4 => 6.0,
        5 => 12.0,                     // medium dead space
        6 => 20.0,
        _ => 30.0,                     // large dead space
    };
    score += class_penalty;

    // Exact-tightness bonus: residual that exactly matches small harmonic classes
    // (classic known sizes) is highly desirable.
    if post_residual == 0 { score -= 60.0; }
    if post_residual == 10 || post_residual == 20 || post_residual == 25 || post_residual == 50 {
        score -= 15.0;
    }

    // Modulo-10 harmony: residuals that are multiples of 10 pair well with
    // typical item granularities.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead coupling: reward residuals that can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size && (post_residual - next_item_size) <= 10 {
            score -= 20.0;
        } else if post_residual < next_item_size {
            // Dead for the lookahead: penalize proportionally.
            score += 0.15 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: the empty bin should only win when no open bin
    // offers a decent fit. Give it a base penalty that scales with how many
    // alternatives exist and how fragmented the open bins are.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 55.0 + 2.0 * open_bins_count as f64 + 0.05 * fragmentation;
        // Late in the stream, opening fresh bins is more acceptable.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress;
        // If next item is large, a fresh bin is more attractive.
        if next_item_size > 60 { score -= 15.0; }
    }

    // Mild preference to fill already-open bins when many are open.
    if bin_residual < bin_capacity {
        score -= 0.3 * open_bins_count as f64;
    }

    // Deviation from mean residual: bins far from the mean are either
    // nearly-full (good to use) or nearly-empty (bad to fragment).
    let dev = post_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += 0.2 * dev; // below mean residual -> tighter bin -> reward
    } else {
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { (step_index as f64 / total_items as f64).clamp(0.0, 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;

    // Base: post residual with quadratic waste amplification
    let mut score = pr * (1.0 + 0.035 * (pr / cap) * (pr / cap));

    // Tightness grows over the stream: pack tighter as we approach the end.
    let tightness = 1.0 + 2.4 * progress * progress + 2.2 * progress * progress * progress;
    score *= tightness;

    // Lookahead chain logic
    if nx > 0.0 {
        if pr < nx {
            let gap = nx - pr;
            score += gap * (1.8 + 6.0 * (1.0 - progress));
        } else {
            let chain_gap = pr - nx;
            let slack = chain_gap / cap;
            if chain_gap <= 42.0 {
                score -= 6.0 + 0.11 * chain_gap;
            }
            if slack < 0.04 {
                score -= 8.0 * (1.0 - slack * 25.0) * (1.0 + progress);
            }
            let chain = 1.0 - slack.min(1.0);
            score -= 4.5 + 4.0 * (nx / cap) + 9.0 * chain * (1.0 - progress);
        }
    }

    // Dead-space penalty: unusable slivers are costly, scaled by progress.
    let dead_ratio = (pr / cap).max(0.0);
    let unusable = if nx > 0.0 && pr > 0.0 && pr < nx { 1.0 } else { 0.55 };
    score += (10.0 + 3.0 * progress) * dead_ratio * dead_ratio * cap * (0.45 + progress) * unusable;

    // Tiny-sliver dead space
    if dead_ratio > 0.0 && dead_ratio < 0.12 {
        score -= 8.5 * (1.0 - dead_ratio / 0.12) * (0.4 + progress);
    }
    if pr > 0.0 && pr < 10.0 {
        score += 30.0 * (1.0 - 0.5 * progress);
    }
    if pr == 0.0 {
        score -= 55.0;
    } else if pr <= 5.0 {
        score -= 25.0 * (1.0 - 0.4 * progress);
    }

    // Next item nearly fits post residual
    if nx > 0.0 && pr > 0.0 && pr < nx && (nx - pr) <= 0.04 * cap {
        score += 3.0 * (1.0 - (nx - pr) / (0.04 * cap)) * (0.5 + progress);
    }
    if nx > 0.0 && pr >= nx && (pr - nx) < 0.06 * cap {
        score -= 6.0 * (1.0 - (pr - nx) / (0.06 * cap)) * (0.5 + progress);
    }

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0 + 0.4 * it * (1.0 - progress);
    }

    // Consolidation pressure when many bins are open.
    score += 0.32 * (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Mean-residual deviation: preserve large-residual bins for big future items.
    if mean_residual > 0.0 {
        let dev = res - mean_residual;
        score += 0.13 * dev.max(0.0);
        score -= 0.05 * (-dev).max(0.0);
        if dev > -5.0 && dev < 15.0 && pr > 0.0 {
            score -= 3.5;
        }
    }

    // Fill ratio bonus for very full bins.
    let fill_ratio = 1.0 - res / cap;
    if fill_ratio > 0.65 {
        score -= 4.0 * (fill_ratio - 0.65) * 10.0 * (0.4 + progress);
    }

    // New-bin candidate (empty bin): decide when opening a new bin beats a poor fit.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let item_frac = (it / cap).min(1.0);
        let mut nb = cap * (1.3 + 1.1 * progress);
        nb -= 24.0 * scarcity * (1.0 - progress);
        nb -= 18.0 * item_frac * (1.0 - progress);
        if nx >= 0.5 * cap {
            nb -= 10.0 * progress + 5.0 * (1.0 - progress);
        }
        nb += 14.0 * progress * (1.0 - item_frac);
        if it >= cap - 1.0 {
            nb -= 30.0;
        }
        // If next item fits exactly in the new bin's post residual, favor opening.
        if nx > 0.0 && cap - it >= nx {
            nb -= 9.5 + 0.1 * (cap - it - nx);
        }
        if nx > 0.0 {
            let r1 = cap - it;
            if r1 >= nx && (r1 - nx) < 6.0 && (r1 - nx) > 0.0 {
                nb += 8.0 * (1.0 - progress);
            }
            if r1 < nx && r1 > 0.0 {
                nb += (1.0 + 2.0 * progress) * (nx - r1) * 0.5;
            }
        }
        if fitting_bins_count <= 2 {
            nb += 20.0 + 9.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 4 {
            nb -= 6.0 + 8.0 * progress;
        }
        // If mean residual can host next item, avoid fragmenting into new bins.
        if nx > 0.0 && mean_residual >= it + nx && progress < 0.6 {
            nb -= 5.0 * (1.0 - progress) * ((mean_residual - it - nx) / cap).min(0.3) * 10.0;
        }
        if mean_residual >= it && progress > 0.5 {
            nb += 6.0 + 8.0 * progress;
        }
        if nx > it && mean_residual >= nx && progress < 0.6 {
            nb += 9.0 * (1.0 - progress);
        }
        if it > 0.85 * cap && progress > 0.3 {
            nb -= 8.5 * progress;
        }
        if fitting_bins_count == 0 && progress > 0.25 {
            nb += 8.5 + 6.5 * progress;
        }
        if progress > 0.75 && fitting_bins_count > 0 && mean_residual >= it {
            nb += 5.0 + 4.0 * progress;
        }
        if item_frac > 0.45 && item_frac < 0.75 && progress > 0.5 {
            nb -= 4.5 * (item_frac - 0.45) * progress;
        }
        score = nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical items are wasted. Penalize "unusable" gaps quadratically.
    // Threshold: assume smallest plausible item is ~10% of capacity.
    let dead_threshold = (bin_capacity as f64 * 0.10).max(1.0);
    if (post_residual as f64) < dead_threshold {
        let deficit = dead_threshold - post_residual as f64;
        score += 4.0 * deficit * deficit / bin_capacity as f64;
    }

    // Reward tight fits: fraction of the bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Reward near-perfect packing even harder.
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual <= dead_threshold as u32 {
        score -= 6.0;
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // this placement chains nicely; reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 10.0;
        } else if post_residual >= next_item_size {
            score -= 3.0;
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += 0.05 * post_residual as f64;
        }
    }

    // Open-bin pressure: discourage proliferating bins when existing
    // residuals are already large (mean residual high).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += 1.5 * pressure * (mean_residual / bin_capacity as f64);

    // New-bin candidate handling: empty bin gets a mild handicap so we
    // only open a new bin when no reasonable fit exists among open bins.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if current bin would leave a dead gap anyway, soften it.
        if (post_residual as f64) < dead_threshold && post_residual > 0 {
            score -= 18.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { (step_index as f64 / total_items as f64).clamp(0.0, 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;

    // Base: penalize leftover space, amplified for large waste.
    let waste = pr / cap;
    let mut score = pr * (1.0 + 0.03 * waste * waste);

    // Tightness pressure grows over the stream: late items must pack tight.
    let tightness = 1.0 + 2.6 * progress * progress + 2.4 * progress * progress * progress;
    score *= tightness;

    // Lookahead: leaving a gap that cannot host the next item is risky waste.
    if nx > 0.0 {
        if pr < nx {
            let gap = nx - pr;
            score += gap * (2.0 + 6.5 * (1.0 - progress));
        } else {
            let chain_gap = pr - nx;
            let slack = chain_gap / cap;
            if chain_gap <= 42.0 { score -= 6.5 + 0.11 * chain_gap; }
            if slack < 0.04 { score -= 8.5 * (1.0 - slack * 25.0) * (1.0 + progress); }
            let chain = 1.0 - slack.min(1.0);
            score -= 5.0 + 4.0 * (nx / cap) + 9.5 * chain * (1.0 - progress);
        }
    }

    // Dead-space penalty: unusable slivers are pure loss.
    let dead_ratio = waste.max(0.0);
    let unusable = if nx > 0.0 && pr > 0.0 && pr < nx { 1.0 } else { 0.55 };
    score += (10.5 + 3.2 * progress) * dead_ratio * dead_ratio * cap * (0.45 + progress) * unusable;

    // Small-but-usable residual bonus.
    if dead_ratio > 0.0 && dead_ratio < 0.12 {
        score -= 9.0 * (1.0 - dead_ratio / 0.12) * (0.4 + progress);
    }

    // Perfect / near-perfect fits.
    if pr == 0.0 {
        score -= 62.0;
    } else if pr <= 5.0 {
        score -= 31.0 * (1.0 - 0.4 * progress);
    } else if pr < 10.0 {
        score += 41.0 * (1.0 - 0.5 * progress);
    }

    // Next item exactly fills the remaining gap: strong chain signal.
    if nx > 0.0 && pr > 0.0 && pr < nx {
        score += 6.5 + 2.2 * progress;
        if nx - pr <= 3.0 { score -= 9.0 * (1.0 - progress); }
    }
    if nx > 0.0 && pr >= nx {
        let room = pr - nx;
        if room < 0.06 * cap {
            score -= 6.5 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
        }
    }

    // Homogeneity: keep residuals near the mean for future flexibility.
    let dev = mean_residual - res;
    score += 0.085 * dev;
    if dev > -5.0 && dev < 15.0 && pr > 0.0 { score -= 4.2; }

    // Mid-range waste is suspicious unless it chains.
    if waste > 0.14 && waste < 0.34 {
        score += 13.0 * (waste - 0.14) * (0.6 + 0.8 * progress);
    }
    if fitting_bins_count > 3 && waste < 0.12 {
        score -= 5.5 * (1.0 - waste * 8.0) * (0.5 + progress);
    }

    // Open-bin pressure (mild, log-scaled).
    score -= 0.42 * (open_bins_count as f64).ln().max(0.0);

    // Last-chance bonus: only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (0.5 + progress);
    }

    // New-bin candidate: decide when a fresh bin beats a poor fit.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let item_frac = (it / cap).min(1.0);
        let mut nb = cap * (1.35 + 1.15 * progress);
        nb -= 26.0 * scarcity * (1.0 - progress);
        nb -= 19.0 * item_frac * (1.0 - progress);
        if nx >= 0.5 * cap { nb -= 12.0 * progress + 6.0 * (1.0 - progress); }
        nb += 15.0 * progress * (1.0 - item_frac);
        if it >= cap - 1.0 { nb -= 32.0; }
        // If the residual after placing here can host the next item, a new
        // bin is a good chain start.
        if nx > 0.0 && cap - it >= nx { nb -= 10.5 + 0.11 * (cap - it - nx); }
        if nx > 0.0 {
            let r1 = cap - it;
            if r1 >= nx && (r1 - nx) < 6.0 && (r1 - nx) > 0.0 {
                nb += 8.5 * (1.0 - progress);
            }
        }
        if fitting_bins_count <= 2 { nb += 21.0 + 10.0 * (1.0 - progress); }
        if fitting_bins_count >= 4 { nb -= 6.5 + 8.5 * progress; }
        if nx > 0.0 && mean_residual > nx + 8.0 && progress < 0.7 {
            nb += 8.5 * ((mean_residual - nx) / cap).min(0.5) * cap * 0.1;
        }
        if mean_residual >= it && progress > 0.5 { nb += 6.5 + 8.5 * progress; }
        if nx > it && mean_residual >= nx && progress < 0.6 { nb += 10.0 * (1.0 - progress); }
        if nx > 0.0 && mean_residual >= it + nx && progress < 0.6 {
            nb -= 5.5 * (1.0 - progress) * ((mean_residual - it - nx) / cap).min(0.3) * 10.0;
        }
