        }
        if pr > 0.0 && it > 0.0 && pr < it * 0.5 && waste > 0.05 {
            score += 2.5 * (1.0 - pr / (it * 0.5)) * (0.4 + progress);
        }
        if waste > 0.18 && waste < 0.4 && nx > 0.0 && pr >= nx && (pr - nx) < 0.12 * cap {
            score += 3.0 * (1.0 - (pr - nx) / (0.12 * cap)) * (0.5 + progress);
        }
        if waste > 0.28 && fitting_bins_count > 2 && progress > 0.5 {
            score += 3.5 * (waste - 0.28) * 10.0 * progress;
        }
        if nx > 0.0 && pr >= nx && (pr - nx) > 0.06 * cap && (pr - nx) < 0.22 * cap && fitting_bins_count <= 2 {
            score -= 2.0 * (1.0 - ((pr - nx) / (0.22 * cap))) * (0.6 + progress);
        }
        if waste > 0.05 && waste < 0.14 && pr >= nx && progress > 0.5 {
            score -= 2.4 * (1.0 - (waste - 0.05) / 0.09) * progress;
        }
        if waste > 0.22 && fitting_bins_count <= 1 && progress > 0.5 {
            score += 2.8 * (waste - 0.22) * 10.0 * progress;
        }
        // Scarcity: prefer using existing bins when few can fit
        if fitting_bins_count == 1 {
            score -= 14.0 + 12.0 * progress;
        } else if fitting_bins_count == 2 {
            score -= 4.0 + 3.0 * progress;
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Classes: exact fill (0), tiny (<=5), small (<=15), medium (<=34), large (<=50), huge (>50)
    let class_bonus = if post_residual == 0 {
        -40.0
    } else if post_residual <= 5 {
        -30.0
    } else if post_residual <= 15 {
        -15.0
    } else if post_residual <= 34 {
        -5.0
    } else if post_residual <= 50 {
        0.0
    } else {
        8.0
    };
    score += class_bonus;

    // Modulo arithmetic: post_residual divisible by common small sizes (10,20,25) is reusable
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 20 == 0 { score -= 3.0; }
        if post_residual % 25 == 0 { score -= 3.0; }
        if post_residual % 50 == 0 { score -= 4.0; }
    }

    // Perfect compatibility: next item exactly fits post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item fits: residual class of the next-next residual matters
            let next_post = post_residual - next_item_size;
            if next_post <= 10 { score -= 8.0; }
            else if next_post % 10 == 0 { score -= 4.0; }
        } else {
            // next item cannot use this residual: dead space penalty grows with size
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Integer-division threshold on bin fill level
    let used = bin_capacity - bin_residual;
    let fill_class = used / 25; // 0..4 quartiles
    score -= fill_class as f64 * 2.0;

    // Last chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: only open a new bin when existing bins fit poorly
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 30.0;
        // If item is large relative to capacity, fresh bin is attractive
        score -= (item_size as f64 / bin_capacity as f64) * 25.0;
        // If open bins are mostly full (low mean residual), new bin is fine
        if mean_residual < item_size as f64 {
            score -= 15.0;
        }
        // Late in stream, avoid bin proliferation slightly less
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
        // Big item with no good reuse prospect
        if item_size > 50 { score -= 10.0; }
    }

    // Prefer tight fits overall: reward small post_residual relative to mean
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    score
}

