pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (unusable for future items) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 + (10 - post_residual) as f64 / 10.0);
    } else if post_residual > 10 && post_residual <= 20 {
        score += 15.0; // moderate penalty for small-ish gaps
    }

    // Reward very tight fits (almost exact packing).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins with residuals below the mean (compact bins first).
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.2;

    // Lookahead: if next item fits exactly in the post-residual, bonus.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 {
        score -= 25.0;
    }
    // Penalize leaving a gap just above the next item (awkward dead space).
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 8 {
        score += 12.0;
    }

    // New-bin candidate: baseline cost, decreasing pressure as stream progresses.
    if bin_residual == bin_capacity {
        score = 55.0 - (step_index as f64 / total_items.max(1) as f64) * 20.0;
        // If nothing else fits well, allow the new bin.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

