    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer filling existing bins over opening new ones, more so early in the stream.
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * (1.0 - progress);
    }

    // Mild pressure to close bins as the stream progresses.
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized waste relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 30.0;

    // Penalize near-miss residuals that are too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to leftover
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bin residuals are fragmented
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // penalize opening new bins early; allow it when open bins are highly fragmented
        score += 15.0 + 20.0 * (1.0 - progress);
        score -= 25.0 * fragmentation;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
        if post_residual == bin_capacity - item_size && item_size >= bin_capacity / 2 {
            score -= 10.0; // large item into fresh bin is fine
        }
    } else {
        // Favor bins whose residual is close to mean (balance load) mildly
        score -= 3.0 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / bin_capacity as f64));
    }

    // Time horizon: later in stream, be more conservative (prefer filling existing bins)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - tightness);

    // Many open bins: discourage proliferation
    score += open_bins_count as f64 * 0.5 * if is_new_bin { 1.0 } else { 0.0 };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.97;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Base: wasted space, weighted more as stream progresses
    let mut score = norm_pr * (1.0 + 0.5 * progress);

    // Smooth quadratic dead-space penalty: residuals that are too small to fit typical items
    score += 0.8 * norm_pr * norm_pr;

    // Reward tight fits (small post_residual) with a smooth saturating term
    score -= 2.0 * (-norm_pr * 4.0).exp();

    // Penalize near-full residual waste asymmetry via cubic coupling with fit ratio
    score += 0.5 * norm_pr * norm_pr * norm_pr * (1.0 - fit_ratio);

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 1.5;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 0.6 * (-gap / cap * 3.0).exp();
        // Penalize if post_residual is awkwardly close but not fitting
        if pr < next_item_size as f64 {
            score += 0.3 * (1.0 - pr / next_item_size.max(1) as f64);
        }
    }

    // Smooth pressure term: many open bins with high mean residual -> prefer consolidation
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / cap.max(1.0));
    score += 0.05 * (progress * pressure).tanh();

    // New-bin candidate: penalize mildly so open bins with decent fit win
    if bin_residual == bin_capacity {
        score += 0.9 + 0.4 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
