                // COMBINED from best: graded chain-gap reward
                let chain_gap = pr - nx;
                if chain_gap <= 42.0 {
                    score -= 6.5 + 0.11 * chain_gap;
                }
                let slack = gap;
                if slack < 0.04 {
                    score -= 8.5 * (1.0 - slack * 25.0) * (1.0 + progress);
                }
                let chain = 1.0 - slack.min(1.0);
                score -= 5.0 + 4.0 * (nx / cap) + 9.5 * chain * (1.0 - progress);
            } else {
                let gap = nx - pr;
                score += gap * (2.0 + 6.5 * (1.0 - progress));
                if gap <= 3.0 {
                    score -= 9.0 * (1.0 - progress);
                }
                let closeness = 1.0 - pr / nx;
                score += 3.0 * closeness * closeness * (0.6 + progress);
                if gap <= 0.04 * cap {
                    score += 3.5 * (1.0 - gap / (0.04 * cap)) * (0.5 + progress);
                }
            }
        }
        if pr > 0.0 && pr < 10.0 {
            score += 41.0 * (1.0 - 0.5 * progress);
        }
        if pr == 0.0 {
            score -= 62.0;
        } else if pr <= 5.0 {
            score -= 31.0 * (1.0 - 0.4 * progress);
        }
        let dev = mean_residual - res;
        score += 0.085 * dev;
        if dev > -5.0 && dev < 15.0 && pr > 0.0 {
            score -= 4.2;
        }
        let tight_fit = (pr == 0.0) || (nx > 0.0 && pr == nx);
        if tight_fit {
            score -= 10.5 * (0.3 + progress);
        }
        if nx > 0.0 && pr >= nx {
            let room = pr - nx;
            if room < 0.06 * cap {
                score -= 6.5 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
            }
            if room > 0.04 * cap && room < 0.18 * cap {
                score -= 2.2 * (1.0 - room / (0.18 * cap)) * (0.3 + progress);
            }
        }
        if waste > 0.14 && waste < 0.34 {
            score += 13.0 * (waste - 0.14) * (0.6 + 0.8 * progress);
        }
        if fitting_bins_count > 3 && waste < 0.12 {
            score -= 5.5 * (1.0 - waste * 8.0) * (0.5 + progress);
        }
        if nx > 0.0 && pr > 0.0 && pr > nx && (pr - nx) < 0.02 * cap {
            score -= 4.0 * (1.0 - (pr - nx) / (0.02 * cap)) * (0.4 + progress);
        }
        if pr > 0.0 && (pr as f64).sqrt() < 2.6 {
            score -= 3.5 * (1.0 - progress);
        }
        if waste > 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.09 * cap && progress > 0.4 {
            score -= 4.0 * (1.0 - (pr - nx) / (0.09 * cap)) * progress;
        }
        if pr > 0.0 && nx > 0.0 && pr < nx && (nx - pr) > 0.1 * cap && waste > 0.25 {
            score += 5.0 * (waste - 0.25) * 10.0 * (0.4 + progress);
        }
        if pr > 0.0 && nx > 0.0 && pr < 0.5 * nx && progress > 0.3 {
            score += 3.5 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
        }
        if waste > 0.3 && pr > nx && progress < 0.5 {
            score += 3.0 * (waste - 0.3) * 10.0 * (1.0 - progress);
        }
        if fill_ratio > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
            score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
        }
        if waste > 0.35 && progress > 0.55 && nx > 0.0 && pr >= nx {
            score -= 4.5 * ((pr - nx) / cap).min(0.2) * 5.0 * progress;
        }
        // Scarcity: prefer using existing bins when few can fit
        if fitting_bins_count == 1 {
            score -= 14.0 + 12.0 * progress;
        } else if fitting_bins_count == 2 {
            score -= 4.0 + 3.0 * progress;
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals near multiples of common item
    // sizes are more reusable. Penalize residuals in "dead zones".
    let r = post_residual as i64;
    if r > 0 {
        // distance to nearest multiple of 10 (harmonic base)
        let m10 = r % 10;
        let d10 = m10.min(10 - m10) as f64;
        score -= 3.0 * (1.0 - d10 / 5.0); // aligned residuals rewarded
        // dead-space penalty: tiny unusable residuals
        if r < 10 {
            score += 25.0 * (10 - r) as f64 / 10.0;
        }
        // modulo classes of common item sizes 20/25/40
        let m20 = r % 20;
        let d20 = m20.min(20 - m20) as f64;
        score -= 1.5 * (1.0 - d20 / 10.0);
        if r % 25 == 0 { score -= 2.0; }
        if r % 40 == 0 { score -= 2.0; }
    } else {
        // perfect fit is best
        score -= 40.0;
    }

    // Lookahead coupling: reward residuals that exactly fit the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual > next_item_size {
            let slack = post_residual - next_item_size;
            if slack < 10 { score -= 6.0; } // near-perfect chain
        } else {
            // next item cannot fit here; residual likely dead
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current fit is poor
    if bin_residual == bin_capacity {
        score = post_residual as f64 + 12.0
            + 0.3 * mean_residual
            - if fitting_bins_count == 0 { 0.0 } else { 0.0 };
        if next_item_size > 0 && next_item_size > bin_residual {
            score -= 5.0;
        }
        if item_size > bin_capacity / 2 {
            score -= 4.0; // big items start fresh bins
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Late-stream tightening: prefer tight fits as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: the smaller the post_residual, the better.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 40.0; // near-perfect, dead space is minimal
    } else if post_residual < next_item_size as f64 && next_item_size > 0 {
        // Gap too small for the next item: unusable dead space penalty
        score += (post_residual as f64) * 1.5 + 15.0;
    } else {
        // Usable gap: mild reward proportional to how well next item fits
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoids opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is
    // large or existing residuals are too fragmented to matter.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64 / 8.0;
        let fragmentation = mean_residual / bin_capacity as f64;
        // open a new bin if fragmentation is high (open bins have small gaps)
        score += 30.0 - fragmentation * 40.0 + open_pressure * 10.0;
        if item_size >= 60 {
            score -= 20.0; // large items start fresh bins more readily
        }
    }

    // Open-bins pressure: discourage spreading across many bins early.
    score += (open_bins_count as f64) * 0.5;

    // Waste ratio: relative dead space created by this placement.
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
