            if gap <= 0.04 {
                score -= 3.2 * (1.0 - gap / 0.04) * (1.0 - progress);
            }
            let chain = 1.0 - gap.min(1.0);
            score -= 5.0 + 4.0 * (nx / cap) + 9.5 * chain * (1.0 - progress);
            // NEW: moderate leftover after chaining is still valuable —
            // reward keeping room for a second future item.
            if gap > 0.04 * cap && gap < 0.18 * cap {
                score -= 2.2 * (1.0 - gap / (0.18 * cap)) * (0.3 + progress);
            }
        }
        if pr > 0.0 && pr < 10.0 {
            score += 41.0 * (1.0 - 0.5 * progress);
        }
        if pr == 0.0 {
            score -= 62.0;
        } else if pr <= 5.0 {
            score -= 31.0 * (1.0 - 0.4 * progress);
        }
        if nx > 0.0 && pr > 0.0 && pr < nx {
            let gap = nx - pr;
            score += gap * (2.0 + 6.5 * (1.0 - progress));
            if gap <= 3.0 {
                score -= 9.0 * (1.0 - progress);
            }
            // Sharpen dead-space penalty — residual slightly below next
            // item is the worst case; scale with closeness to usability.
            let closeness = 1.0 - pr / nx;
            score += 3.0 * closeness * closeness * (0.6 + progress);
        }
        let dev = mean_residual - res;
        score += 0.085 * dev;
        if dev > -5.0 && dev < 15.0 && pr > 0.0 {
            score -= 4.2;
        }
        let tight_fit = (pr == 0.0) || (nx > 0.0 && pr == nx);
        if tight_fit {
            score -= 10.5 * (0.3 + progress);
        }
        if nx > 0.0 && pr >= nx {
            let room = pr - nx;
            if room < 0.06 * cap {
                score -= 6.5 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if waste > 0.14 && waste < 0.34 {
            score += 13.0 * (waste - 0.14) * (0.6 + 0.8 * progress);
        }
        if fitting_bins_count > 3 && waste < 0.12 {
            score -= 5.5 * (1.0 - waste * 8.0) * (0.5 + progress);
        }
        if nx > 0.0 && pr > 0.0 && pr > nx && (pr - nx) < 0.02 * cap {
            score -= 4.0 * (1.0 - (pr - nx) / (0.02 * cap)) * (0.4 + progress);
        }
        if pr > 0.0 && (pr as f64).sqrt() < 2.6 {
            score -= 3.5 * (1.0 - progress);
        }
        if waste > 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.09 * cap && progress > 0.4 {
            score -= 4.0 * (1.0 - (pr - nx) / (0.09 * cap)) * progress;
        }
        if pr > 0.0 && nx > 0.0 && pr < nx && (nx - pr) > 0.1 * cap && waste > 0.25 {
            score += 5.0 * (waste - 0.25) * 10.0 * (0.4 + progress);
        }
        if pr > 0.0 && nx > 0.0 && pr < 0.5 * nx && progress > 0.3 {
            score += 3.5 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
        }
        if waste > 0.3 && pr > nx && progress < 0.5 {
            score += 3.0 * (waste - 0.3) * 10.0 * (1.0 - progress);
        }
        if fill_ratio > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
            score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
        }
        if waste > 0.35 && progress > 0.55 && nx > 0.0 && pr >= nx {
            score -= 4.5 * ((pr - nx) / cap).min(0.2) * 5.0 * progress;
        }
        // Scarcity: prefer using existing bins when few can fit
        if fitting_bins_count == 1 {
            score -= 14.0 + 12.0 * progress;
        } else if fitting_bins_count == 2 {
            score -= 4.0 + 3.0 * progress;
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
        // NEW: near-exact fill with room for next item gets extra reward.
        if nx > 0.0 && pr >= nx && (pr - nx) < 0.5 * nx && progress > 0.6 {
            score -= 2.8 * (1.0 - (pr - nx) / (0.5 * nx)) * progress;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 - norm_post) * (1.0 - norm_post);
    score += 8.0 * poly * cap * (0.5 + progress);

    // Reward tight fits more strongly later in the stream
    score -= (1.0 - norm_post) * (1.0 + 2.0 * progress) * 10.0;

    // Penalize residual that cannot fit the next item (dead space)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 12.0 * (1.0 - post / nxt) * (1.0 + progress);
        } else {
            score -= 3.0 * (1.0 - nxt / post) * (1.0 - progress);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin, more so when many bins are open
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * open_bins_count as f64;
    } else {
        // Favor bins with low residual relative to mean (compact usage)
        score += 0.5 * (post - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes capture "how dead" leftover space is.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Class A: near-perfect fit (tiny residue) -> strong reward.
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 5 {
        score -= 25.0;
    } else if pr <= 10 {
        score -= 10.0;
    }

    // Class B: residue in "awkward band" (11..=20) -> penalty, hard to fill later.
    if pr > 10 && pr <= 20 {
        score += 8.0;
    }

    // Class C: harmonic divisibility — residue divisible by common item granularities
    // (5, 10, 20, 25) is more likely to be filled by future items.
    let div_bonus = if pr % 25 == 0 && pr > 0 { 12.0 }
        else if pr % 20 == 0 && pr > 0 { 9.0 }
        else if pr % 10 == 0 && pr > 0 { 6.0 }
        else if pr % 5 == 0 && pr > 0 { 3.0 }
        else { 0.0 };
    score -= div_bonus;

    // Lookahead: does the next item fit exactly into the post-residual? (harmonic pairing)
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr && pr - next_item_size <= 10 {
            score -= 15.0;
        } else if next_item_size > pr {
            // Next item cannot use leftover; leftover becomes dead unless divisible.
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (residual would be a fresh 100 minus item, i.e., post_residual == cap - item).
    if bin_residual == bin_capacity {
        // Neutral base; penalize slightly so a good existing fit wins,
        // but reward when item is large (fresh bin keeps big residue usable).
        let frac = item_size as f64 / cap;
        if frac > 0.5 {
            score -= 6.0;
        } else {
            score += 5.0;
        }
        // If many open bins with high mean residual, opening fresh is fine.
        if mean_residual > 40.0 {
            score -= 3.0;
        }
    }

    // Progress-coupled tightening: late in the stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (pr as f64) * 0.15 * progress;

    // Congestion: many open bins -> prefer compacting into existing ones.
    if open_bins_count > 8 {
        score += (open_bins_count as f64 - 8.0) * 0.5;
    }

    score
}

