pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;
    // Smooth progress-dependent weighting: waste matters more later
    let w = 1.0 + 2.0 * progress * progress;
    score *= w;
    // Cubic penalty on normalized dead space, amplified with progress
    score += cap * (norm_pr * norm_pr * norm_pr) * (0.5 + progress);
    // Reward tight fits (small post_residual) smoothly
    score -= cap * 0.3 * (1.0 - norm_pr) * (1.0 - norm_pr);
    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= cap * 1.5;
    }
    // Discourage spreading thin: penalize when bin residual far below mean residual
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.2;
