        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= cap * 0.25 * (1.0 - ((pr - nxt) / cap).abs());
        } else {
            score += cap * 0.15 * (nxt - pr) / cap;
        }
    }
    // Slight preference for fuller bins overall
    score -= (item_size as f64 / cap) * 5.0;
    score
}

