        } else if post_residual <= 25 {
            score -= 10.0;
        } else if post_residual <= 50 {
            score -= 3.0;
        } else {
            // large leftover: penalize mildly, it's fine space but wasteful placement
            score += 5.0 * frac;
        }

        // Modulo-harmonic bonus: leftover divisible by common size classes
        let nxt = next_item_size;
        if nxt > 0 && post_residual >= nxt {
            // next item fits here: strong reward, keeps chains going
            score -= 15.0;
