    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item can use are pure waste.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score -= 1000.0; // perfect fit, extremely favored
    } else if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize unusable dead space nonlinearly: gaps below the smallest item
    // class are worthless; scale penalty by how dead the gap is.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }

    // Reward tight fits (small post_residual relative to bin).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are badly fragmented or the fit here is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        // If many bins are open with large mean residual, prefer reusing them.
        score += open_bins_count as f64 * 2.0;
        score += mean_residual * 0.3;
        // If the next item is large and this item is small, opening a fresh
        // bin preserves flexibility: slight discount.
        if next_item_size > 60 && item_size < 30 {
            score -= 12.0;
        }
        // Early in the stream, opening bins is cheaper (more future to amortize).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    } else {
        // Reusing an open bin: mild reward scaling with open-bin pressure.
        score -= open_bins_count as f64 * 0.5;
        // Prefer bins whose residual deviates favorably from the mean
        // (using a tighter-than-average bin packs better).
        score -= (mean_residual - bin_residual as f64) * 0.2;
        // If the next item fits exactly in the post-residual, big bonus.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0;
        } else if next_item_size > post_residual && next_item_size > 0 {
            // Next item won't fit here; dead space penalty more severe.
            score += 10.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
