pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit: post_residual near zero is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 100.0; // next item can still go here: good chaining
        } else {
            // dead space relative to lookahead item: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // last item: minimize post residual aggressively
        score -= 200.0;
    }

    // Penalize bins whose residual is far below the mean (fragmented bins).
    let diff = post_residual as f64 - mean_residual;
    score += diff * 0.3;

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless current bin would leave big dead space
    // or there are many open bins already (consolidation pressure).
    if bin_residual == bin_capacity {
        score += 50.0;
        if open_bins_count > 0 {
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 100.0 * (1.0 - progress);
        }
        // allow new bin only if no open bin fits well
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
    }

    // Prefer filling bins with small residuals more tightly.
    score += (bin_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer tight fits (low post residual).
    let mut score = post;

    // Strongly reward near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Penalize dead space relative to capacity.
    score += (post / cap) * 20.0;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward leaving room for the next item; penalize if next item won't fit leftover.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post - nxt) / cap);
