            score -= 4.5 * ((pr - nx) / cap).min(0.2) * 5.0 * progress;
        }
        if nx > 0.0 && pr > nx && (pr - nx) <= 0.04 * cap {
            score -= 3.2 * (1.0 - (pr - nx) / (0.04 * cap)) * (1.0 - progress);
        }
        if nx > 0.0 && pr > nx && (pr - nx) > 0.04 * cap && (pr - nx) < 0.18 * cap {
            score -= 2.2 * (1.0 - ((pr - nx) / (0.18 * cap))) * (0.3 + progress);
        }
        if fitting_bins_count == 1 {
            score -= 14.0 + 12.0 * progress;
        } else if fitting_bins_count == 2 {
            score -= 4.0 + 3.0 * progress;
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let has_next = next_item_size > 0;
    let pr = post_residual as f64;
    let nx = next_item_size as f64;

    // Aggressive 2-step lookahead matching (only meaningful for existing bins)
    if has_next && !is_new_bin {
        if pr == nx {
            // Perfect chain: the next item exactly fills this bin's leftover
            score -= 80.0;
        } else if pr == 0.0 {
            // Bin closed exactly, zero waste
            score -= 40.0;
        } else if pr > nx {
            // Next item still fits into the leftover: keep space usable
            score -= 0.5 * (pr - nx).min(30.0);
        } else {
            // Dead space: leftover smaller than next item (unusable for lookahead)
            score += 12.0 + 0.6 * (nx - pr);
        }
    }

    // Last-chance bin: only one open bin can fit the item, avoid opening a new bin
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Penalize the brand-new empty bin candidate when open bins could fit
    if is_new_bin {
        score += 20.0 + 15.0 * (fitting_bins_count as f64) + 30.0 * (1.0 - progress);
        // But a new bin enabling a perfect lookahead chain is somewhat attractive
        if has_next && pr == nx {
            score -= 25.0;
        }
    }

    // Prefer tighter bins relative to the current mean residual
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual), especially exact fits.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits the post-residual exactly or well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 8.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is bad.
    if bin_residual == bin_capacity {
        let crowded = mean_residual / (bin_capacity as f64);
        score = bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        if crowded < 0.25 {
            score -= 10.0 * (0.25 - crowded);
        }
        // Late in the stream, prefer filling existing bins more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Mild pressure to consolidate: prefer bins with below-average residual
    // (i.e., more filled) to keep many small residuals from accumulating.
    let diff = (bin_residual as f64) - mean_residual;
    score += 0.05 * diff;

    // Slight preference for bins that are more than half full.
    if bin_residual < bin_capacity / 2 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
