pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual, with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth progress coupling: late in stream, penalize residual more strongly
    score += 20.0 * progress * norm_pr * norm_pr * cap;

    // Reward tight fits non-linearly
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * tightness;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: penalize if post-residual can't fit next item but is small (wasted sliver)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            // dead space relative to next item
            score += 0.15 * (nxt - pr);
        } else {
            // reward bins that leave room exactly matching next item
            score -= 3.0 * (1.0 - ((pr - nxt) / cap).abs());
        }
    }

    // Penalize bins far below mean residual (creates fragmentation)
    score += 2.0 * (mean_residual - pr).abs() / cap;

    // Mild penalty for opening new bins when many bins already fit
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64) / (1.0 + progress);
        score += 4.0 + 0.5 * openness;
        // but allow new bin if item is large relative to capacity and fits poorly elsewhere
        score -= 10.0 * (item_size as f64 / cap) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;
    let waste = pr / cap;
    let mut score = pr * (1.0 + 0.03 * waste * waste);

    let tightness = 1.0 + 2.6 * progress * progress + 2.4 * progress * progress * progress;
    score *= tightness;

    // COMBINED: dead-space ratio penalty with unusability weighting
    // (borrowed idea from best heuristic, fused into parent's base score)
    let dead_ratio = (pr / cap).max(0.0);
    let unusable = if nx > 0.0 && pr > 0.0 && pr < nx { 1.0 } else { 0.55 };
    score += (10.5 + 3.2 * progress) * dead_ratio * dead_ratio * cap * (0.45 + progress) * unusable;
    if dead_ratio > 0.0 && dead_ratio < 0.12 {
        score -= 9.0 * (1.0 - dead_ratio / 0.12) * (0.4 + progress);
    }

    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let item_frac = (it / cap).min(1.0);
        let mut nb = cap * (1.35 + 1.15 * progress);
        nb -= 26.0 * scarcity * (1.0 - progress);
        nb -= 19.0 * item_frac * (1.0 - progress);
        if nx >= 0.5 * cap {
            nb -= 12.0 * progress + 6.0 * (1.0 - progress);
        }
        nb += 15.0 * progress * (1.0 - item_frac);
        if it >= cap - 1.0 {
            nb -= 32.0;
        }
        if nx > 0.0 && cap - it >= nx {
            nb -= 10.5 + 0.11 * (cap - it - nx);
        }
        if nx > 0.0 {
            let r1 = cap - it;
            if r1 >= nx && (r1 - nx) < 6.0 && (r1 - nx) > 0.0 {
                nb += 8.5 * (1.0 - progress);
            }
        }
        if fitting_bins_count <= 2 {
            nb += 21.0 + 10.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 4 {
            nb -= 6.5 + 8.5 * progress;
        }
        if nx > 0.0 && mean_residual > nx + 8.0 && progress < 0.7 {
            nb += 8.5 * ((mean_residual - nx) / cap).min(0.5) * cap * 0.1;
        }
        if mean_residual >= it && progress > 0.5 {
            nb += 6.5 + 8.5 * progress;
        }
        if nx > it && mean_residual >= nx && progress < 0.6 {
            nb += 10.0 * (1.0 - progress);
        }
        if nx > 0.0 && mean_residual >= it + nx && progress < 0.6 {
            nb -= 5.5 * (1.0 - progress) * ((mean_residual - it - nx) / cap).min(0.3) * 10.0;
        }
        if it > 0.85 * cap && progress > 0.3 {
            nb -= 9.0 * progress;
        }
        if nx > 0.0 && mean_residual > nx {
            let excess = mean_residual - nx;
            if excess < 0.05 * cap && progress < 0.55 {
                nb += 5.0 * (1.0 - excess / (0.05 * cap)) * (1.0 - progress);
            }
        }
        if fitting_bins_count == 0 && progress > 0.25 {
            nb += 9.0 + 7.0 * progress;
        }
        if nx > 0.0 && it + nx > cap && mean_residual >= nx {
            nb += 6.0 * (1.0 - progress);
        }
        if progress > 0.75 && fitting_bins_count > 0 && mean_residual >= it {
            nb += 5.5 + 4.5 * progress;
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_left = mean_residual - it;
            if best_left >= nx && (best_left - nx) < 12.0 {
                nb += 4.0 * (1.0 - (best_left - nx) / 12.0) * (0.5 + progress);
            }
        }
        if it < 0.2 * cap && progress < 0.3 && open_bins_count < 6 {
            nb += 7.0 * (1.0 - progress);
        }
        if item_frac > 0.6 && nx > 0.0 && cap >= it + nx && cap - it - nx < 0.03 * cap {
            nb -= 5.5 * (1.0 - (cap - it - nx) / (0.03 * cap));
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_pr = (mean_residual - it).max(0.0);
            if best_pr > 0.0 && best_pr < 0.06 * cap && (cap - it) >= nx {
                nb -= 7.0 * (1.0 - best_pr / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if progress > 0.85 && mean_residual < 0.15 * cap {
            nb += 7.0 * progress * (1.0 - mean_residual / (0.15 * cap));
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_post = (mean_residual - it).max(0.0);
            if best_post >= nx && best_post - nx > 0.18 * cap && progress > 0.35 {
                nb -= 6.0 * ((best_post - nx) / cap).min(0.4) * (0.4 + progress);
            }
        }
        if item_frac > 0.45 && item_frac < 0.75 && progress > 0.5 {
            nb -= 5.0 * (item_frac - 0.45) * progress;
        }
        if fitting_bins_count >= 2 && mean_residual < 0.25 * cap && progress > 0.6 {
            nb += 6.0 * (1.0 - mean_residual / (0.25 * cap)) * progress;
        }
        if fitting_bins_count >= 3 && mean_residual - it >= nx && progress > 0.5 {
            nb += 4.5 * progress * (1.0 - ((mean_residual - it - nx) / cap).min(1.0));
        }
        if open_bins_count > 10 && progress < 0.35 && item_frac < 0.3 {
            nb += 6.0 * (1.0 - progress) * (1.0 - item_frac / 0.3);
        }
        // penalize opening a bin whose first residual is a dead sliver
        if nx > 0.0 {
            let r1 = cap - it;
            if r1 < nx && r1 > 0.0 {
                nb += (1.0 + 2.0 * progress) * (nx - r1) * 0.55;
            }
            if r1 >= nx && (r1 - nx) > 0.25 * cap && progress > 0.45 {
                nb += 4.5 * ((r1 - nx) / cap).min(0.5) * progress;
            }
        }
        // chainable it+nx packing in a fresh bin
        if nx > 0.0 && cap >= it + nx && (cap - it - nx) < 0.08 * cap && progress > 0.3 {
            nb -= 5.0 * (1.0 - (cap - it - nx) / (0.08 * cap)) * (0.5 + progress);
        }
        // NEW: avoid opening bins that leave a margin too large to chain with
        // the mean-size item, when many bins are already open
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin > 0.22 * cap && open_bins_count > 6 && progress < 0.55 {
                nb += 5.5 * ((margin - 0.22 * cap) / cap).min(0.3) * 10.0 * (1.0 - progress) * ((open_bins_count as f64 - 6.0).min(8.0) / 8.0);
            }
        }
        score = nb;
    } else {
        // Fine-grained residual fitting with lookahead anticipation
        let fill_ratio = 1.0 - res / cap;
        if waste < 0.08 {
            score -= 48.0 * (1.0 - progress) * (0.08 - waste);
        }
        if fill_ratio > 0.65 {
            score -= 4.8 * (fill_ratio - 0.65) * 10.0 * (0.4 + progress);
        }
        if nx > 0.0 && nx <= pr && pr > 0.0 {
            let gap = (pr - nx) / cap;
            if gap < 0.03 {
                score -= 7.5 * (1.0 - gap * 33.0);
            }
            if gap <= 0.04 {
                score -= 3.2 * (1.0 - gap / 0.04) * (1.0 - progress);
            }
            let chain = 1.0 - gap.min(1.0);
            score -= 5.0 + 4.0 * (nx / cap) + 9.5 * chain * (1.0 - progress);
        }
        if pr > 0.0 && pr < 10.0 {
            score += 41.0 * (1.0 - 0.5 * progress);
        }
        if pr == 0.0 {
            score -= 62.0;
        } else if pr <= 5.0 {
            score -= 31.0 * (1.0 - 0.4 * progress);
        }
        if nx > 0.0 && pr > 0.0 && pr < nx {
            let gap = nx - pr;
            score += gap * (2.0 + 6.5 * (1.0 - progress));
            if gap <= 3.0 {
                score -= 9.0 * (1.0 - progress);
            }
            // sharpened dead-space penalty
            let closeness = 1.0 - pr / nx;
            score += 3.0 * closeness * closeness * (0.6 + progress);
            // NEW: extra penalty when the shortfall is tiny but fatal
            if gap <= 0.04 * cap {
                score += 3.2 * (1.0 - gap / (0.04 * cap)) * (0.5 + progress);
            }
        }
        let dev = mean_residual - res;
        score += 0.085 * dev;
        if dev > -5.0 && dev < 15.0 && pr > 0.0 {
            score -= 4.2;
        }
        let tight_fit = (pr == 0.0) || (nx > 0.0 && pr == nx);
        if tight_fit {
            score -= 10.5 * (0.3 + progress);
        }
        if nx > 0.0 && pr >= nx {
            let room = pr - nx;
            if room < 0.06 * cap {
                score -= 6.5 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if waste > 0.14 && waste < 0.34 {
            score += 13.0 * (waste - 0.14) * (0.6 + 0.8 * progress);
        }
        if fitting_bins_count > 3 && waste < 0.12 {
            score -= 5.5 * (1.0 - waste * 8.0) * (0.5 + progress);
        }
        if nx > 0.0 && pr > 0.0 && pr > nx && (pr - nx) < 0.02 * cap {
            score -= 4.0 * (1.0 - (pr - nx) / (0.02 * cap)) * (0.4 + progress);
        }
        if pr > 0.0 && (pr as f64).sqrt() < 2.6 {
            score -= 3.5 * (1.0 - progress);
        }
        if waste > 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.09 * cap && progress > 0.4 {
            score -= 4.0 * (1.0 - (pr - nx) / (0.09 * cap)) * progress;
        }
        if pr > 0.0 && nx > 0.0 && pr < nx && (nx - pr) > 0.1 * cap && waste > 0.25 {
            score += 5.0 * (waste - 0.25) * 10.0 * (0.4 + progress);
        }
        if pr > 0.0 && nx > 0.0 && pr < 0.5 * nx && progress > 0.3 {
            score += 3.5 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
        }
        if waste > 0.3 && pr > nx && progress < 0.5 {
            score += 3.0 * (waste - 0.3) * 10.0 * (1.0 - progress);
        }
        if fill_ratio > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
            score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
        }
        if waste > 0.35 && progress > 0.55 && nx > 0.0 && pr >= nx {
            score -= 4.5 * ((pr - nx) / cap).min(0.2) * 5.0 * progress;
        }
        // Scarcity: prefer using existing bins when few can fit
        if fitting_bins_count == 1 {
            score -= 14.0 + 12.0 * progress;
        } else if fitting_bins_count == 2 {
            score -= 4.0 + 3.0 * progress;
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod capacity fractions.
    // post_residual in {0} is perfect; small residues (1..10) are dead space.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr < 10 {
        score += (10 - pr) as f64 * 3.0; // dead-space penalty
    } else {
        // Harmonic bucket: how well can a typical future item (10..80) use it
        let class = pr / 10; // 1..=9 harmonic class
        score -= class as f64 * 2.5;
    }

    // Lookahead: if next item fits exactly or well into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 80.0; // chains a perfect fit
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            if slack < 10 {
                score -= 40.0;
            } else {
                score -= 15.0;
            }
        } else {
            // next item cannot fit here: penalize wasting this bin's residual
            score += 12.0 + (pr as f64) * 0.2;
        }
    }

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Prefer tighter bins among many candidates: relative tightness
        score += (bin_residual - item_size) as f64 * 0.1;
    }

    // New-bin candidate handling: empty bin should only win when open bins are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, reduced late in stream or when few bins fit.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 45.0 - 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: must open
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 5.0;
        }
    }

    // Mild preference for consolidating into bins below mean residual (fill emptier bins).
    if (bin_residual as f64) > mean_residual {
        score += 3.0;
    } else {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if post_residual > 0 {
        // Gaps below the smallest plausible item (<= 10) are pure dead space.
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual <= 20 {
            // Small gaps that few items can use: quadratic penalty.
            score += (20.0 - pr) * 3.0;
        }
        // Reward tight fits (small waste relative to item).
        let tightness = item_size as f64 / bin_residual as f64;
        score -= tightness * 25.0;
    } else {
        // Perfect closure of a bin is highly desirable.
        score -= 40.0;
    }

    // Reward using a bin whose residual is close to the item (best fit sharpening).
    let slack = (bin_residual as f64 - item_size as f64).max(0.0);
    score += slack * 0.35;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the item would
    // leave a large awkward gap in every existing bin, or no bin fits well.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin.
        score = bin_capacity as f64 * 0.9;
        // Prefer new bin if item is large (fills fresh capacity efficiently).
        score -= item_size as f64 * 0.55;
        // If a lookahead item pairs well with a fresh bin, favor opening.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 15.0;
        }
        // Pressure: many open bins already -> discourage opening another.
        score += open_bins_count as f64 * 2.5;
        // Late in the stream, opening new bins is less attractive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 12.0;
    } else {
        // Mild pressure to close bins rather than spread across many.
        score += open_bins_count as f64 * 0.8;
        // Prefer bins with residual above the mean (keep small-residual bins for small items).
        if (bin_residual as f64) < mean_residual && post_residual > 0 && post_residual < 25 {
            score += 10.0;
        }
        // Lookahead coupling: if next item fits the post residual, reward.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size > post_residual && post_residual > 0 && post_residual < 15 {
            score += 8.0; // dead space unusable by the known next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
