            score -= 5.5 * (1.0 - waste * 8.0) * (0.5 + progress);
        }
        if nx > 0.0 && pr > 0.0 && pr > nx && (pr - nx) < 0.02 * cap {
            score -= 4.0 * (1.0 - (pr - nx) / (0.02 * cap)) * (0.4 + progress);
        }
        if pr > 0.0 && (pr as f64).sqrt() < 2.6 {
            score -= 3.5 * (1.0 - progress);
        }
        if waste > 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.09 * cap && progress > 0.4 {
            score -= 4.0 * (1.0 - (pr - nx) / (0.09 * cap)) * progress;
        }
        if pr > 0.0 && nx > 0.0 && pr < nx && (nx - pr) > 0.1 * cap && waste > 0.25 {
            score += 5.0 * (waste - 0.25) * 10.0 * (0.4 + progress);
        }
        if pr > 0.0 && nx > 0.0 && pr < 0.5 * nx && progress > 0.3 {
            score += 3.5 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
        }
        if waste > 0.3 && pr > nx && progress < 0.5 {
            score += 3.0 * (waste - 0.3) * 10.0 * (1.0 - progress);
        }
        if fill_ratio > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
            score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
        }
        if waste > 0.35 && progress > 0.55 && nx > 0.0 && pr >= nx {
            score -= 4.5 * ((pr - nx) / cap).min(0.2) * 5.0 * progress;
        }
        if fitting_bins_count == 1 {
            score -= 14.0 + 12.0 * progress;
        } else if fitting_bins_count == 2 {
            score -= 4.0 + 3.0 * progress;
        }
        // Sharpened mid-range chain-gap reward for open bins
        if nx > 0.0 && pr > nx && (pr - nx) > 0.04 * cap && (pr - nx) < 0.18 * cap {
            score -= 2.6 * (1.0 - ((pr - nx) / (0.18 * cap))) * (0.3 + progress);
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward placements where the leftover exactly hosts the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) == nxt {
            score -= 60.0; // perfect chain fit
        } else if post_residual >= next_item_size {
            // leftover can host next item; reward closeness of fit
            score -= 0.5 * (post_residual as f64 - nxt).max(0.0);
        } else {
            // dead space relative to next item: penalize proportionally
            score += (nxt - post_residual as f64) * 0.8;
        }
    } else {
        // last item: minimize leftover
        score += 0.2 * post_residual as f64;
    }

    // Compare post_residual against mean residual across open bins
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: keep it neutral-to-slightly-poor so we only
    // open a new bin when no open bin offers a decent fit
    if bin_residual == bin_capacity {
        score += 25.0 + 0.1 * post_residual as f64;
        // but if the item perfectly fills a fresh bin, open it eagerly
        if item_size == bin_capacity {
            score -= 200.0;
        }
    }

    // Tight fits are generally good
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Late in the stream, be more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post_residual nonlinearly.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to wasted potential.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer bins with smaller residual relative to mean (best-fit flavor).
    score += (bin_residual as f64 - mean_residual) * 0.4;

    // Penalize opening new bins when decent fitting bins exist, especially early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln().max(1.0);
        score += 30.0 / pressure + 10.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress;
    }

    // Prefer bins whose residual is close to item size (tight packing).
    score += ((bin_residual - item_size) as f64).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let base = (x - 0.25 * progress).powi(2) + 0.5 * x.powi(3);
    let mut score = base * (1.0 + 0.3 * progress);

    // Reward tight fits (small post_residual) more strongly late in the stream
    score -= (1.0 - x) * (1.0 + progress);

    // Penalize leaving residuals that could waste space, weighted by mean residual context
    let dead = (x - mean_residual / cap).abs();
    score += 0.4 * dead * dead;

    // Last-chance bonus: strongly favor this bin if it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 2.0 + progress;
    }

    // Lookahead: reward if next item fits into resulting post_residual
    if next_item_size > 0 {
        if (post_residual as u64) >= next_item_size as u64 {
            score -= 0.6 + 0.4 * progress;
        } else {
            score += 0.3 * (next_item_size as f64 - pr).max(0.0) / cap;
        }
    }

    // Mild penalty for spreading across many open bins
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

