        }
        if it / cap > 0.6 && nx > 0.0 && cap >= it + nx && cap - it - nx < 0.03 * cap {
            nb -= 5.5 * (1.0 - (cap - it - nx) / (0.03 * cap));
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_pr = (mean_residual - it).max(0.0);
            if best_pr > 0.0 && best_pr < 0.06 * cap && (cap - it) >= nx {
                nb -= 7.0 * (1.0 - best_pr / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if progress > 0.85 && mean_residual < 0.15 * cap {
            nb += 7.0 * progress * (1.0 - mean_residual / (0.15 * cap));
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_post = (mean_residual - it).max(0.0);
            if best_post >= nx && best_post - nx > 0.18 * cap && progress > 0.35 {
                nb -= 6.0 * ((best_post - nx) / cap).min(0.4) * (0.4 + progress);
            }
        }
        if item_frac > 0.45 && item_frac < 0.75 && progress > 0.5 {
            nb -= 5.0 * (item_frac - 0.45) * progress;
        }
        if fitting_bins_count >= 2 && mean_residual < 0.25 * cap && progress > 0.6 {
            nb += 6.0 * (1.0 - mean_residual / (0.25 * cap)) * progress;
        }
        if open_bins_count > 10 && progress < 0.35 && item_frac < 0.3 {
            nb += 6.0 * (1.0 - progress) * (1.0 - item_frac / 0.3);
        }
        if nx > 0.0 {
            let r1 = cap - it;
            if r1 < nx && r1 > 0.0 { nb += (1.0 + 2.0 * progress) * (nx - r1) * 0.55; }
            if r1 >= nx && (r1 - nx) > 0.25 * cap && progress > 0.45 {
                nb += 4.5 * ((r1 - nx) / cap).min(0.5) * progress;
            }
        }
        if nx > 0.0 && cap >= it + nx && (cap - it - nx) < 0.08 * cap && progress > 0.3 {
            nb -= 5.0 * (1.0 - (cap - it - nx) / (0.08 * cap)) * (0.5 + progress);
        }
        if open_bins_count > 6 && mean_residual > 0.4 * cap && progress < 0.6 {
            nb += 5.0 * ((mean_residual - 0.4 * cap) / cap) * (1.0 - progress)
                * ((open_bins_count as f64 - 6.0).min(8.0) / 8.0);
        }
        if item_frac < 0.15 && progress > 0.55 && fitting_bins_count >= 1 {
            nb += 6.0 * progress * (1.0 - item_frac / 0.15);
        }
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin < 0.15 * cap {
                nb -= 6.0 * (1.0 - margin / (0.15 * cap)) * (0.6 + 0.4 * progress);
            }
        }
        if nx > 0.0 && fitting_bins_count >= 1 && mean_residual - it >= nx {
            let leftover = mean_residual - it - nx;
            if leftover < 0.1 * cap && progress > 0.45 {
                nb -= 5.0 * (1.0 - leftover / (0.1 * cap)) * progress;
            }
        }
        score = nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;
    let waste = pr / cap;
    let mut score = pr * (1.0 + 0.03 * waste * waste);

    let tightness = 1.0 + 2.4 * progress * progress + 2.2 * progress * progress * progress;
    score *= tightness;

    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let item_frac = (it / cap).min(1.0);
        let mut nb = cap * (1.35 + 1.15 * progress);
        nb -= 26.0 * scarcity * (1.0 - progress);
        nb -= 19.0 * item_frac * (1.0 - progress);
        if nx >= 0.5 * cap {
            nb -= 12.0 * progress + 6.0 * (1.0 - progress);
        }
        nb += 15.0 * progress * (1.0 - item_frac);
        if it >= cap - 1.0 {
            nb -= 32.0;
        }
        if nx > 0.0 && cap - it >= nx {
            nb -= 10.5 + 0.11 * (cap - it - nx);
        }
        if nx > 0.0 {
            let r1 = cap - it;
            if r1 >= nx && (r1 - nx) < 6.0 && (r1 - nx) > 0.0 {
                nb += 8.5 * (1.0 - progress);
            }
        }
        if fitting_bins_count <= 2 {
            nb += 21.0 + 10.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 4 {
            nb -= 6.5 + 8.5 * progress;
        }
        if nx > 0.0 && mean_residual > nx + 8.0 && progress < 0.7 {
            nb += 8.5 * ((mean_residual - nx) / cap).min(0.5) * cap * 0.1;
        }
        if mean_residual >= it && progress > 0.5 {
            nb += 6.5 + 8.5 * progress;
        }
        if nx > it && mean_residual >= nx && progress < 0.6 {
            nb += 10.0 * (1.0 - progress);
        }
        if nx > 0.0 && mean_residual >= it + nx && progress < 0.6 {
            nb -= 5.5 * (1.0 - progress) * ((mean_residual - it - nx) / cap).min(0.3) * 10.0;
        }
        if it > 0.85 * cap && progress > 0.3 {
            nb -= 9.0 * progress;
        }
        if nx > 0.0 && mean_residual > nx {
            let excess = mean_residual - nx;
            if excess < 0.05 * cap && progress < 0.55 {
                nb += 5.0 * (1.0 - excess / (0.05 * cap)) * (1.0 - progress);
            }
        }
        if fitting_bins_count == 0 && progress > 0.25 {
            nb += 9.0 + 7.0 * progress;
        }
        if nx > 0.0 && it + nx > cap && mean_residual >= nx {
            nb += 6.0 * (1.0 - progress);
        }
        if progress > 0.75 && fitting_bins_count > 0 && mean_residual >= it {
            nb += 5.5 + 4.5 * progress;
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_left = mean_residual - it;
            if best_left >= nx && (best_left - nx) < 12.0 {
                nb += 4.0 * (1.0 - (best_left - nx) / 12.0) * (0.5 + progress);
            }
        }
        if it < 0.2 * cap && progress < 0.3 && open_bins_count < 6 {
            nb += 7.0 * (1.0 - progress);
        }
        if item_frac > 0.6 && nx > 0.0 && cap >= it + nx && cap - it - nx < 0.03 * cap {
            nb -= 5.5 * (1.0 - (cap - it - nx) / (0.03 * cap));
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_pr = (mean_residual - it).max(0.0);
            if best_pr > 0.0 && best_pr < 0.06 * cap && (cap - it) >= nx {
                nb -= 7.0 * (1.0 - best_pr / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if progress > 0.85 && mean_residual < 0.15 * cap {
            nb += 7.0 * progress * (1.0 - mean_residual / (0.15 * cap));
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_post = (mean_residual - it).max(0.0);
            if best_post >= nx && best_post - nx > 0.18 * cap && progress > 0.35 {
                nb -= 6.0 * ((best_post - nx) / cap).min(0.4) * (0.4 + progress);
            }
        }
        if item_frac > 0.45 && item_frac < 0.75 && progress > 0.5 {
            nb -= 5.0 * (item_frac - 0.45) * progress;
        }
        if fitting_bins_count >= 2 && mean_residual < 0.25 * cap && progress > 0.6 {
            nb += 6.0 * (1.0 - mean_residual / (0.25 * cap)) * progress;
        }
        if fitting_bins_count >= 3 && mean_residual - it >= nx && progress > 0.5 {
            nb += 4.5 * progress * (1.0 - ((mean_residual - it - nx) / cap).min(1.0));
        }
        if open_bins_count > 10 && progress < 0.35 && item_frac < 0.3 {
            nb += 6.0 * (1.0 - progress) * (1.0 - item_frac / 0.3);
        }
        if nx > 0.0 {
            let r1 = cap - it;
            if r1 < nx && r1 > 0.0 {
                nb += (1.0 + 2.0 * progress) * (nx - r1) * 0.55;
            }
            if r1 >= nx && (r1 - nx) > 0.25 * cap && progress > 0.45 {
                nb += 4.5 * ((r1 - nx) / cap).min(0.5) * progress;
            }
        }
        if nx > 0.0 && cap >= it + nx && (cap - it - nx) < 0.08 * cap && progress > 0.3 {
            nb -= 5.0 * (1.0 - (cap - it - nx) / (0.08 * cap)) * (0.5 + progress);
        }
        // NEW: strengthen dead-sliver penalty on fresh bins, scaled by
        // how much of the next item cannot fit in the first residual.
        if nx > 0.0 {
            let r1 = cap - it;
            if r1 > 0.0 && r1 < nx {
                let dead_frac = ((nx - r1) / nx).min(1.0);
                nb += (2.0 + 3.0 * progress) * dead_frac * (0.25 * cap).min(nx);
            }
        }
        // NEW: reward fresh bins that chain it+nx with near-zero margin,
        // strongly at all stages (combines compaction + lookahead).
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin < 0.06 * cap {
                nb -= 9.0 * (1.0 - margin / (0.06 * cap)) * (0.7 + 0.6 * progress);
            }
        }
        // NEW: when existing bins are plentiful and roomy, discourage
        // opening a new one for small items (fragmentation control).
        if open_bins_count > 6 && mean_residual > 0.4 * cap && progress < 0.6 {
            nb += 5.0 * ((mean_residual - 0.4 * cap) / cap) * (1.0 - progress) * ((open_bins_count as f64 - 6.0).min(8.0) / 8.0);
        }
        score = nb;
    } else {
        // Fine-grained residual fitting with lookahead anticipation
        let fill_ratio = 1.0 - res / cap;
        if waste < 0.08 {
            score -= 48.0 * (1.0 - progress) * (0.08 - waste);
        }
        if fill_ratio > 0.65 {
            score -= 4.8 * (fill_ratio - 0.65) * 10.0 * (0.4 + progress);
        }
        if nx > 0.0 && nx <= pr && pr > 0.0 {
            let gap = (pr - nx) / cap;
            if gap < 0.03 {
                score -= 7.5 * (1.0 - gap * 33.0);
            }
            if gap <= 0.04 {
                score -= 3.2 * (1.0 - gap / 0.04) * (1.0 - progress);
            }
            let chain = 1.0 - gap.min(1.0);
            score -= 5.0 + 4.0 * (nx / cap) + 9.5 * chain * (1.0 - progress);
        }
        if pr > 0.0 && pr < 10.0 {
            score += 41.0 * (1.0 - 0.5 * progress);
        }
        if pr == 0.0 {
            score -= 62.0;
        } else if pr <= 5.0 {
            score -= 31.0 * (1.0 - 0.4 * progress);
        }
        if nx > 0.0 && pr > 0.0 && pr < nx {
            let gap = nx - pr;
            score += gap * (2.0 + 6.5 * (1.0 - progress));
            if gap <= 3.0 {
                score -= 9.0 * (1.0 - progress);
            }
            let closeness = 1.0 - pr / nx;
            score += 3.0 * closeness * closeness * (0.6 + progress);
        }
        let dev = mean_residual - res;
        score += 0.085 * dev;
        if dev > -5.0 && dev < 15.0 && pr > 0.0 {
            score -= 4.2;
        }
        let tight_fit = (pr == 0.0) || (nx > 0.0 && pr == nx);
        if tight_fit {
            score -= 10.5 * (0.3 + progress);
        }
        if nx > 0.0 && pr >= nx {
            let room = pr - nx;
            if room < 0.06 * cap {
                score -= 6.5 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if waste > 0.14 && waste < 0.34 {
            score += 13.0 * (waste - 0.14) * (0.6 + 0.8 * progress);
        }
        if fitting_bins_count > 3 && waste < 0.12 {
            score -= 5.5 * (1.0 - waste * 8.0) * (0.5 + progress);
        }
        if nx > 0.0 && pr > 0.0 && pr > nx && (pr - nx) < 0.02 * cap {
            score -= 4.0 * (1.0 - (pr - nx) / (0.02 * cap)) * (0.4 + progress);
        }
        if pr > 0.0 && (pr as f64).sqrt() < 2.6 {
            score -= 3.5 * (1.0 - progress);
        }
        if waste > 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.09 * cap && progress > 0.4 {
            score -= 4.0 * (1.0 - (pr - nx) / (0.09 * cap)) * progress;
        }
        if pr > 0.0 && nx > 0.0 && pr < nx && (nx - pr) > 0.1 * cap && waste > 0.25 {
            score += 5.0 * (waste - 0.25) * 10.0 * (0.4 + progress);
        }
        if pr > 0.0 && nx > 0.0 && pr < 0.5 * nx && progress > 0.3 {
            score += 3.5 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
        }
        if waste > 0.3 && pr > nx && progress < 0.5 {
            score += 3.0 * (waste - 0.3) * 10.0 * (1.0 - progress);
        }
        if fill_ratio > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
            score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
        }
        if waste > 0.35 && progress > 0.55 && nx > 0.0 && pr >= nx {
            score -= 4.5 * ((pr - nx) / cap).min(0.2) * 5.0 * progress;
        }
        // NEW: reward near-exact chain fits (pr - nx small) across the
        // whole residual band, not just the tightest slivers.
        if nx > 0.0 && pr > nx && (pr - nx) <= 0.04 * cap {
            score -= 3.2 * (1.0 - (pr - nx) / (0.04 * cap)) * (1.0 - progress);
        }
        if nx > 0.0 && pr > nx && (pr - nx) > 0.04 * cap && (pr - nx) < 0.18 * cap {
            score -= 2.2 * (1.0 - ((pr - nx) / (0.18 * cap))) * (0.3 + progress);
        }
        // NEW: penalize leaving residuals that are dead for the next item
        // when the bin is otherwise nearly full (avoid stranded slivers).
        if nx > 0.0 && pr > 0.0 && pr < nx && fill_ratio > 0.7 {
            score += 4.0 * (1.0 - pr / nx) * (0.5 + progress);
        }
        // Scarcity: prefer using existing bins when few can fit
        if fitting_bins_count == 1 {
            score -= 14.0 + 12.0 * progress;
        } else if fitting_bins_count == 2 {
            score -= 4.0 + 3.0 * progress;
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: quantize leftover space into
    // capacity fractions. Small classes (near 0) are "dead space" classes.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let class = (post / cap * 10.0).floor(); // 0..=10 harmonic class

    // Penalize dead-space classes heavily (residuals that few item sizes can use).
    let dead_penalty = match post_residual {
        0 => -30.0,                 // perfect fit: strongly reward
        1..=9 => 25.0,              // unusable sliver
        10..=19 => 18.0,
        20..=29 => 10.0,
        30..=39 => 4.0,
        40..=59 => 0.0,
        60..=79 => -6.0,            // roomy: still useful
        _ => -10.0,
    };
    score += dead_penalty;

    // Modular coupling: does next_item_size divide nicely into the post_residual?
    if next_item_size > 0 && post_residual > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as u64) % (next_item_size.max(1) as u64) == 0 {
            score -= 12.0; // next item would tile the leftover exactly
        } else if next_item_size <= post_residual {
            let frac = nxt / post;
            score -= 10.0 * (1.0 - (frac - 0.5).abs() * 2.0).abs(); // tight fit reward
        } else {
            score += 6.0; // next item cannot use this leftover anyway
        }
    }

    // Last-chance bonus: only this bin can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * 0.5 + mean_residual * 0.05;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bin when mean residual is small (open bins nearly full)
        // or late in the stream; penalize opening bins early with room available.
        score = cap - crowded - 20.0 * progress + (mean_residual - post).abs() * 0.3;
        if mean_residual > item_size as f64 * 1.5 && open_bins_count > 0 {
            score += 15.0; // open bins still have usable space: discourage new bin
        }
    }

    // Mild stream-phase modulation: tighten packing as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += class * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is below average (consolidate fullness).
    score += (bin_residual as f64 - mean_residual) * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Reward tight fits generally (small waste relative to item size).
    score -= 12.0 * (item_size as f64 / (bin_residual as f64).max(1.0));

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage proliferating bins unless placement is poor.
    score += 2.5 * open_bins_count as f64;

    // New-bin candidate handling: prefer new bin only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Mild penalty so existing decent fits win, but good enough to beat bad fits.
        score += 15.0 + mean_residual * 0.1;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // Slight bonus if next item would also fit a fresh bin pair.
            score -= 3.0;
        }
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // residual too small for lookahead item: penalize
    }

    // Late in stream, be more conservative about waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / near-exact fits aggressively.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: if the next item fits the post-residual
    // exactly or nearly, strongly favor this bin.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if next_item_size as u32 <= post_residual {
            // Next item fits here after this placement.
            score -= (60.0 - diff.min(60.0)) * 2.0;
            if diff == 0.0 {
                score -= 400.0; // perfect 2-chain
            }
        } else {
            // Next item would not fit after this placement: penalize slightly,
            // unless post_residual is tiny (dead space anyway).
            score += diff * 0.15;
        }
    }

    // Compare post_residual against mean residual: creating a residual far
    // below the mean wastes the bin's remaining capacity.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += (mean_residual - pr) * 0.3;
    } else {
        score -= (pr - mean_residual).min(20.0) * 0.2;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 120.0;
        if item_size >= 50 {
            score -= 100.0; // large items are fine in fresh bins
        }
        if next_item_size > 0 && next_item_size >= post_residual - item_size {
            score -= 30.0; // room for next item too
        }
    }

    // Late in the stream, consolidate: favor bins with smaller residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * (0.5 + 0.5 * progress);

    // Slight preference for keeping fewer open bins when residuals are similar.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: penalize large post_residual non-linearly.
    if post_residual < 10 {
        score -= 40.0;
    } else if post_residual < 25 {
        score -= (25 - post_residual) as f64 * 0.8;
    }

    // Penalize dead space relative to capacity fill fraction.
    let fill = (bin_residual as f64 - post_residual as f64) / bin_capacity as f64;
    score -= fill * 15.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 20.0;
        } else {
            // Penalize leaving residual just below next item size (wasted gap).
            let gap = next_item_size as f64 - post_residual as f64;
            if gap < 15.0 {
                score += gap * 1.5;
            }
        }
    }

    // Compare against mean residual: prefer bins with residual below mean
    // (tighter bins) when placing, to keep larger residuals for future items.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Time horizon: late in the stream, be more aggressive about using open bins
    // (avoid opening new bins); early, allow exploration of new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: accept early, penalize as stream progresses.
        score += 10.0 + 40.0 * progress;
        // Also penalize new bins when many bins are already open.
        score += open_bins_count as f64 * 1.5;
    } else {
        score -= 10.0 * progress;
    }

    // Mild penalty for very small residual leftovers that are hard to fill.
    if post_residual > 0 && post_residual < 5 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
