pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) - norm_pr * progress * (1.0 - norm_pr);
    score += 40.0 * poly;

    // Tight fits are rewarded more as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Penalize dead space that cannot fit the next item (smooth coupling)
    if next_item_size > 0 && post_residual > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 25.0 * gap * gap;
        // Reward leaving exactly room for the next item
        let fit_next = (next_item_size as f64 <= pr) as i32 as f64;
        score -= 12.0 * fit_next * (pr / cap) * (1.0 - progress);
    }

    // Last-chance bin bonus (smooth penalty on alternatives via fitting count)
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0 * (1.0 + progress);
    }

    // Mild preference for bins below mean residual early (load balancing)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * (1.0 - progress) * (1.0 - progress);

    // Slight penalty for opening new bins when many bins are open late in stream
    if bin_residual == bin_capacity {
        score += 5.0 * (open_bins_count as f64).sqrt() * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Harmonic classes of post_residual: residues that pair well with common
    // item sizes (10..80) are valuable dead space; large usable space is fine.
    let pr = post_residual;
    if pr > 0 {
        // Exact harmonic splits: half / quarter / eighth of capacity are
        // "friendly" residuals that many items can still use.
        let half = bin_capacity / 2;
        let quarter = bin_capacity / 4;
        let eighth = bin_capacity / 8;
        if pr == half {
            score -= 12.0;
        } else if pr == quarter || pr == 3 * quarter {
            score -= 9.0;
        } else if pr == eighth || pr == 3 * eighth || pr == 5 * eighth || pr == 7 * eighth {
            score -= 6.0;
        }
        // Modulo classes: residuals divisible by 10 or 5 align with item sizes.
        if pr % 10 == 0 {
            score -= 5.0;
        } else if pr % 5 == 0 {
            score -= 2.5;
        }
        // Integer-division thresholds: tiny unusable dead space is penalized.
        if pr < 10 {
            score += (10 - pr) as f64 * 3.0;
        } else if pr < 20 {
            score += 4.0;
        }
        // Very large residual: near-empty bin, mild penalty to prefer tighter fits.
        if pr > bin_capacity * 3 / 4 {
            score += 8.0;
        }
    }

    // Lookahead coupling: reward if the next item fits the post residual
    // exactly or comfortably (harmonic chaining).
    if next_item_size > 0 && next_item_size <= pr {
        let slack = pr - next_item_size;
        if slack == 0 {
            score -= 15.0;
        } else if slack < 10 {
            score -= 10.0;
        } else if slack <= 30 {
            score -= 4.0;
        }
        // Penalize if next item is huge and would leave us stranded anyway.
        if next_item_size > 70 && slack > 20 {
            score += 3.0;
        }
    } else if next_item_size > pr {
        // Next item cannot use this bin's remainder: dead space risk.
        score += (next_item_size - pr).min(30) as f64 * 0.3;
    }

    // Last-chance logic: if this is the only open bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large (leaves a small, clean residual) or nothing fits.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Some open bin fits; discourage new bin unless residual here is
            // harmonically ideal (e.g. item is 50, 25, 20 -> exact splits).
            if pr == half || pr == quarter || pr % 10 == 0 {
                score += 2.0; // still slightly discouraged vs reusing
            } else {
                score += 15.0 + 0.1 * open_bins_count as f64;
            }
        }
        if next_item_size > 0 && pr >= next_item_size && pr % next_item_size.max(1) == 0 {
            score -= 8.0; // new bin whose remainder chains perfectly
        }
    }

    // Mean-residual coupling: placing into a bin far from the mean reduces
    // fragmentation variance; mildly reward tightness.
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += diff * 0.05;

    // Late in the stream, prefer closing bins tightly (minimize post residual).
    score += post_residual as f64 * (0.2 * progress);

    score
}

