            }
        }
        if fitting_bins_count == 0 && progress > 0.25 {
            nb += 9.0 + 7.0 * progress;
        }
        if nx > 0.0 && it + nx > cap && mean_residual >= nx {
            nb += 6.0 * (1.0 - progress);
        }
        if progress > 0.75 && fitting_bins_count > 0 && mean_residual >= it {
            nb += 5.5 + 4.5 * progress;
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_left = mean_residual - it;
            if best_left >= nx && (best_left - nx) < 12.0 {
                nb += 4.0 * (1.0 - (best_left - nx) / 12.0) * (0.5 + progress);
            }
        }
        if it < 0.2 * cap && progress < 0.3 && open_bins_count < 6 {
            nb += 7.0 * (1.0 - progress);
        }
        if item_frac > 0.6 && nx > 0.0 && cap >= it + nx && cap - it - nx < 0.03 * cap {
            nb -= 5.5 * (1.0 - (cap - it - nx) / (0.03 * cap));
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_pr = (mean_residual - it).max(0.0);
            if best_pr > 0.0 && best_pr < 0.06 * cap && (cap - it) >= nx {
                nb -= 7.0 * (1.0 - best_pr / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if progress > 0.85 && mean_residual < 0.15 * cap {
            nb += 7.0 * progress * (1.0 - mean_residual / (0.15 * cap));
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_post = (mean_residual - it).max(0.0);
            if best_post >= nx && best_post - nx > 0.18 * cap && progress > 0.35 {
                nb -= 6.0 * ((best_post - nx) / cap).min(0.4) * (0.4 + progress);
            }
        }
        if item_frac > 0.45 && item_frac < 0.75 && progress > 0.5 {
            nb -= 5.0 * (item_frac - 0.45) * progress;
        }
        if fitting_bins_count >= 2 && mean_residual < 0.25 * cap && progress > 0.6 {
            nb += 6.0 * (1.0 - mean_residual / (0.25 * cap)) * progress;
        }
        if fitting_bins_count >= 3 && mean_residual - it >= nx && progress > 0.5 {
            nb += 4.5 * progress * (1.0 - ((mean_residual - it - nx) / cap).min(1.0));
        }
        if open_bins_count > 10 && progress < 0.35 && item_frac < 0.3 {
            nb += 6.0 * (1.0 - progress) * (1.0 - item_frac / 0.3);
        }
        // Dead-sliver penalty for new-bin first residual
        if nx > 0.0 {
            let r1 = cap - it;
            if r1 < nx && r1 > 0.0 {
                nb += (1.0 + 2.0 * progress) * (nx - r1) * 0.55;
            }
            if r1 >= nx && (r1 - nx) > 0.25 * cap && progress > 0.45 {
                nb += 4.5 * ((r1 - nx) / cap).min(0.5) * progress;
            }
        }
        // Tight chain it+nx in fresh bin is attractive
        if nx > 0.0 && cap >= it + nx && (cap - it - nx) < 0.08 * cap && progress > 0.3 {
            nb -= 5.0 * (1.0 - (cap - it - nx) / (0.08 * cap)) * (0.5 + progress);
        }
        // Fragmentation pressure: many open bins with large mean residual -> prefer filling them
        if open_bins_count > 6 && mean_residual > 0.4 * cap && progress < 0.6 {
            nb += 5.0 * ((mean_residual - 0.4 * cap) / cap) * (1.0 - progress) * ((open_bins_count as f64 - 6.0).min(8.0) / 8.0);
        }
        if item_frac < 0.15 && progress > 0.55 && fitting_bins_count >= 1 {
            nb += 6.0 * progress * (1.0 - item_frac / 0.15);
        }
        if nx > 0.0 && cap - it > 0.0 && cap - it < nx {
            nb += 4.5 * (1.0 - progress) * ((nx - (cap - it)) / cap).min(0.3) * 10.0;
        }
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin < 0.15 * cap {
                nb -= 6.0 * (1.0 - margin / (0.15 * cap)) * (0.6 + 0.4 * progress);
            }
        }
        if nx > 0.0 && fitting_bins_count >= 1 && mean_residual - it >= nx {
            let leftover = mean_residual - it - nx;
            if leftover < 0.1 * cap && progress > 0.45 {
                nb -= 5.0 * (1.0 - leftover / (0.1 * cap)) * progress;
            }
        }
        if open_bins_count > 12 && progress > 0.6 && item_frac < 0.25 {
            nb += 5.0 * progress * (1.0 - item_frac / 0.25);
        }
        if nx > 0.0 && fitting_bins_count >= 1 && (cap - it) >= nx && (cap - it - nx) < 0.05 * cap && progress < 0.5 {
            nb -= 4.0 * (1.0 - (cap - it - nx) / (0.05 * cap)) * (1.0 - progress);
        }
        if nx > 0.0 && (cap - it).max(0.0) < nx && fitting_bins_count <= 1 && mean_residual < 0.3 * cap {
            nb += 3.5 * (1.0 - mean_residual / (0.3 * cap)) * (0.5 + progress);
        }
        if fitting_bins_count >= 2 && mean_residual >= it + nx && progress > 0.4 {
            let rem = mean_residual - it - nx;
            if rem < 0.05 * cap {
                nb -= 4.5 * (1.0 - rem / (0.05 * cap)) * progress;
            }
        }
        if open_bins_count > 8 && mean_residual < 0.1 * cap && progress > 0.5 {
            nb -= 4.0 * (1.0 - mean_residual / (0.1 * cap)) * progress;
        }
        if nx > 0.0 && cap >= it + nx && cap - it - nx < 0.02 * cap && fitting_bins_count <= 3 {
            nb -= 3.5 * (1.0 - (cap - it - nx) / (0.02 * cap)) * (0.6 + progress);
        }
        score = nb;
    } else {
        let fill_ratio = 1.0 - res / cap;
        if waste < 0.08 {
            score -= 48.0 * (1.0 - progress) * (0.08 - waste);
        }
        if fill_ratio > 0.65 {
            score -= 4.8 * (fill_ratio - 0.65) * 10.0 * (0.4 + progress);
        }
        if pr > 0.0 && pr < 10.0 {
            score += 41.0 * (1.0 - 0.5 * progress);
        }
        if pr == 0.0 {
            score -= 62.0;
        } else if pr <= 5.0 {
            score -= 31.0 * (1.0 - 0.4 * progress);
        }
        let dev = mean_residual - res;
        score += 0.085 * dev;
        if dev > -5.0 && dev < 15.0 && pr > 0.0 {
            score -= 4.2;
        }
        let tight_fit = (pr == 0.0) || (nx > 0.0 && pr == nx);
        if tight_fit {
            score -= 10.5 * (0.3 + progress);
        }
        if waste > 0.14 && waste < 0.34 {
            score += 13.0 * (waste - 0.14) * (0.6 + 0.8 * progress);
        }
        if fitting_bins_count > 3 && waste < 0.12 {
            score -= 5.5 * (1.0 - waste * 8.0) * (0.5 + progress);
        }
        if pr > 0.0 && (pr as f64).sqrt() < 2.6 {
            score -= 3.5 * (1.0 - progress);
        }
        if waste > 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.09 * cap && progress > 0.4 {
            score -= 4.0 * (1.0 - (pr - nx) / (0.09 * cap)) * progress;
        }
        if fill_ratio > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
            score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
        }
        if waste > 0.35 && progress > 0.55 && nx > 0.0 && pr >= nx {
            score -= 4.5 * ((pr - nx) / cap).min(0.2) * 5.0 * progress;
        }
        // Scarcity: prefer using existing bins when few can fit
        if fitting_bins_count == 1 {
            score -= 14.0 + 12.0 * progress;
        } else if fitting_bins_count == 2 {
            score -= 4.0 + 3.0 * progress;
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize residuals that cannot fit even the smallest plausible item.
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 15.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bins pressure: many open bins -> discourage spreading, favor tight fills.
    let open_pressure = open_bins_count as f64 / 8.0;
    score += open_pressure * (post_residual as f64 / 10.0);

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    }
    // If next item cannot fit in post_residual, mild penalty for wasting space.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate: only attractive when open bins are tight or residual is large.
    if bin_residual == bin_capacity {
        // Base new-bin cost: opening bins is expensive.
        score += 30.0;
        // But if no good fit exists among open bins (large mean residual spread), relax.
        if mean_residual < 25.0 {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer filling bins whose residual is close to the item (tight fits).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Mild bonus for using bins with below-average residual (consolidating).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward a post-residual that exactly matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.35 * diff;                    // penalize mismatch with next item
        if post_residual == next_item_size {
            score -= 18.0;                       // perfect 2-step fit
        }
        // Next item must at least fit after this placement
        if next_item_size > post_residual {
            score += 0.10 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: minimize waste directly
        score += 0.5 * post_residual as f64;
    }

    // Relative-to-mean coupling: bins with unusually large residual are better hosts.
    let dev = post_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Penalize creating tiny unusable dead space (< 10, minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: neutral baseline, slightly favored when open bins are crowded
    // (high mean residual means poor fits elsewhere) or few bins fit.
    if bin_residual == bin_capacity {
        score = 60.0 - 0.15 * mean_residual - 2.0 * fitting_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 0.2 * (bin_capacity as f64 - next_item_size as f64);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Penalize small, hard-to-use dead space (post_residual < 10 is nearly dead).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fill
    }

    // Lookahead: bonus if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual {
            // dead space for the next item: penalize proportionally
            score += 0.3 * (next_item_size as f64 - post_residual as f64).min(60.0);
        } else {
            score -= 8.0; // next item can still go here
        }
    }

    // Last chance: strongly prefer using the only bin that fits, avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are fragmented / mean residual is low.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin
        score += 45.0;
        if mean_residual < 15.0 {
            score -= 40.0; // open bins nearly full -> new bin sensible
        }
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 20.0; // keep room for large upcoming item
        }
        // late in stream, prefer filling existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Slight preference for fuller bins among equals.
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + 2.0 * progress * norm_pr + (progress * norm_pr).powi(2));

    // Smooth dead-space penalty: small residuals are less useful later
    let dead = (1.0 - norm_pr).powi(3) * 8.0;

    // Lookahead: reward if next item fits into post_residual (smooth sigmoid-like)
    let fits_next = if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        let s = 1.0 / (1.0 + (-gap / 10.0).exp());
        6.0 * s
    } else {
        0.0
    };

    // Last-chance bonus: avoid opening new bin when few alternatives exist
    let last_chance = if fitting_bins_count == 1 { 10.0 } else { 0.0 };

    // Tightness of current fit
    let tight = (item_size as f64 / bin_residual.max(1) as f64) * 4.0;

    // Mean residual divergence: prefer bins far from the mean to diversify
    let div = ((pr - mean_residual) / cap).abs() * 3.0 * (1.0 - progress);

    let mut score = poly * 12.0 + dead - fits_next - last_chance + tight + div;
    // Slight preference for reusing open bins over new bin (new bin has pr == cap)
    let new_bin = if bin_residual == bin_capacity { 3.0 } else { 0.0 };
    score += new_bin;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: post_residual buckets via integer division.
    // Residuals divisible into small classes are more reusable.
    let class = post_residual / 10; // 0..=10 harmonic class
    score -= (10 - class) as f64 * 3.0; // prefer bins whose leftover is small-but-usable

    // Dead-space penalty: leftover that cannot pair with the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8; // next item won't fit here
        } else {
            // next item fits: reward tight pairing
            score -= (10 - ((post_residual - next_item_size) / 10)) as f64 * 2.0;
        }
    }

    // Modulo coupling: leftover in "awkward" remainder classes (prime-ish gaps) penalized.
    let rem = post_residual % 10;
    if rem == 1 || rem == 3 || rem == 7 {
        score += 2.5;
    } else if rem == 0 {
        score -= 1.5; // round leftover is flexible
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.1 * open_bins_count as f64;
        if post_residual as f64 > mean_residual {
            score -= 4.0;
        }
    } else {
        // reward tightness relative to mean residual
        score -= (mean_residual - post_residual as f64) * 0.3;
    }

    // Late in stream: consolidate, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 5.0;
    }

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;
    let mut score = pr * (1.0 + 0.03 * (pr / cap) * (pr / cap));

    let tightness = 1.0 + 2.5 * progress * progress + 2.3 * progress * progress * progress;
    score *= tightness;

    // Lookahead: penalize bins that can't host the next item, reward chained fits
    if nx > 0.0 {
        if pr < nx {
            let gap = nx - pr;
            score += gap * (2.0 + 6.5 * (1.0 - progress));
        } else {
            let chain_gap = pr - nx;
            let slack = chain_gap / cap;
            if chain_gap <= 41.0 {
                score -= 6.5 + 0.11 * chain_gap;
            }
            if slack < 0.04 {
                score -= 8.5 * (1.0 - slack * 25.0) * (1.0 + progress);
            }
            let chain = 1.0 - slack.min(1.0);
            score -= 5.0 + 4.0 * (nx / cap) + 9.5 * chain * (1.0 - progress);
        }
    }

    // Dead-space penalty with next-item usability weighting
    let dead_ratio = (pr / cap).max(0.0);
    let unusable = if nx > 0.0 && pr > 0.0 && pr < nx { 1.0 } else { 0.55 };
    score += (10.5 + 3.2 * progress) * dead_ratio * dead_ratio * cap * (0.45 + progress) * unusable;
    if dead_ratio > 0.0 && dead_ratio < 0.12 {
        score -= 9.0 * (1.0 - dead_ratio / 0.12) * (0.4 + progress);
    }
    if dead_ratio > 0.25 && dead_ratio < 0.6 {
        score += 4.5 * (dead_ratio - 0.25) * (0.5 + progress);
    }
    if pr > 0.0 && nx > 0.0 && pr < nx && (nx - pr) <= 0.04 * cap {
        score += 3.5 * (1.0 - (nx - pr) / (0.04 * cap)) * (0.5 + progress);
    }

    // Scarcity handling
    if fitting_bins_count == 1 {
        score -= 14.0 + 12.0 * progress;
    } else if fitting_bins_count == 2 {
        score -= 4.0 + 3.0 * progress;
    }

    // NEW-BIN CANDIDATE scoring
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let item_frac = (it / cap).min(1.0);
        let mut nb = cap * (1.35 + 1.15 * progress);
        nb -= 26.0 * scarcity * (1.0 - progress);
        nb -= 19.0 * item_frac * (1.0 - progress);
        if nx >= 0.5 * cap {
            nb -= 12.0 * progress + 6.0 * (1.0 - progress);
        }
        nb += 15.0 * progress * (1.0 - item_frac);
        if it >= cap - 1.0 {
            nb -= 32.0;
        }
        if nx > 0.0 && cap - it >= nx {
            nb -= 10.5 + 0.11 * (cap - it - nx);
        }
        if nx > 0.0 {
            let r1 = cap - it;
            if r1 >= nx && (r1 - nx) < 6.0 && (r1 - nx) > 0.0 {
                nb += 8.5 * (1.0 - progress);
            }
            if r1 < nx && r1 > 0.0 {
                nb += (1.0 + 2.0 * progress) * (nx - r1) * 0.55;
            }
            if r1 >= nx && (r1 - nx) > 0.25 * cap && progress > 0.45 {
                nb += 4.5 * ((r1 - nx) / cap).min(0.5) * progress;
            }
        }
        if fitting_bins_count <= 2 {
            nb += 21.0 + 10.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 4 {
            nb -= 6.5 + 8.5 * progress;
        }
        if nx > 0.0 && mean_residual > nx + 8.0 && progress < 0.7 {
            nb += 8.5 * ((mean_residual - nx) / cap).min(0.5) * cap * 0.1;
        }
        if mean_residual >= it && progress > 0.5 {
            nb += 6.5 + 8.5 * progress;
        }
        if nx > it && mean_residual >= nx && progress < 0.6 {
            nb += 10.0 * (1.0 - progress);
        }
        if nx > 0.0 && mean_residual >= it + nx && progress < 0.6 {
            nb -= 5.5 * (1.0 - progress) * ((mean_residual - it - nx) / cap).min(0.3) * 10.0;
        }
        if it > 0.85 * cap && progress > 0.3 {
            nb -= 9.0 * progress;
        }
        if nx > 0.0 && mean_residual > nx {
            let excess = mean_residual - nx;
            if excess < 0.05 * cap && progress < 0.55 {
                nb += 5.0 * (1.0 - excess / (0.05 * cap)) * (1.0 - progress);
            }
        }
        if fitting_bins_count == 0 && progress > 0.25 {
            nb += 9.0 + 7.0 * progress;
        }
        if nx > 0.0 && it + nx > cap && mean_residual >= nx {
            nb += 6.0 * (1.0 - progress);
        }
        if progress > 0.75 && fitting_bins_count > 0 && mean_residual >= it {
            nb += 5.5 + 4.5 * progress;
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_left = mean_residual - it;
            if best_left >= nx && (best_left - nx) < 12.0 {
                nb += 4.0 * (1.0 - (best_left - nx) / 12.0) * (0.5 + progress);
            }
        }
        if it / cap > 0.6 && nx > 0.0 && cap >= it + nx && cap - it - nx < 0.03 * cap {
            nb -= 5.5 * (1.0 - (cap - it - nx) / (0.03 * cap));
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_pr = (mean_residual - it).max(0.0);
            if best_pr > 0.0 && best_pr < 0.06 * cap && (cap - it) >= nx {
                nb -= 7.0 * (1.0 - best_pr / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if progress > 0.85 && mean_residual < 0.15 * cap {
            nb += 7.0 * progress * (1.0 - mean_residual / (0.15 * cap));
