        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_post = (mean_residual - it).max(0.0);
            if best_post >= nx && best_post - nx > 0.18 * cap && progress > 0.35 {
                nb -= 6.0 * ((best_post - nx) / cap).min(0.4) * (0.4 + progress);
            }
        }
        if item_frac > 0.45 && item_frac < 0.75 && progress > 0.5 {
            nb -= 5.0 * (item_frac - 0.45) * progress;
        }
        if fitting_bins_count >= 2 && mean_residual < 0.25 * cap && progress > 0.6 {
            nb += 6.0 * (1.0 - mean_residual / (0.25 * cap)) * progress;
        }
        if fitting_bins_count >= 3 && mean_residual - it >= nx && progress > 0.5 {
            nb += 4.5 * progress * (1.0 - ((mean_residual - it - nx) / cap).min(1.0));
        }
        if open_bins_count > 10 && progress < 0.35 && item_frac < 0.3 {
            nb += 6.0 * (1.0 - progress) * (1.0 - item_frac / 0.3);
        }
        if nx > 0.0 && cap >= it + nx && (cap - it - nx) < 0.08 * cap && progress > 0.3 {
            nb -= 5.0 * (1.0 - (cap - it - nx) / (0.08 * cap)) * (0.5 + progress);
        }
        if open_bins_count > 6 && mean_residual > 0.4 * cap && progress < 0.6 {
            nb += 5.0 * ((mean_residual - 0.4 * cap) / cap) * (1.0 - progress) * ((open_bins_count as f64 - 6.0).min(8.0) / 8.0);
        }
        if item_frac < 0.15 && progress > 0.55 && fitting_bins_count >= 1 {
            nb += 6.0 * progress * (1.0 - item_frac / 0.15);
        }
        if nx > 0.0 && cap - it > 0.0 && cap - it < nx {
            nb += 4.5 * (1.0 - progress) * ((nx - (cap - it)) / cap).min(0.3) * 10.0;
        }
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin < 0.15 * cap {
                nb -= 6.0 * (1.0 - margin / (0.15 * cap)) * (0.6 + 0.4 * progress);
            }
        }
        if nx > 0.0 && fitting_bins_count >= 1 && mean_residual - it >= nx {
            let leftover = mean_residual - it - nx;
            if leftover < 0.1 * cap && progress > 0.45 {
                nb -= 5.0 * (1.0 - leftover / (0.1 * cap)) * progress;
            }
        }
        if nx > 0.0 && fitting_bins_count >= 2 && mean_residual > 0.5 * cap && progress < 0.4 {
            nb += 4.5 * ((mean_residual - 0.5 * cap) / cap) * (1.0 - progress);
        }
        if open_bins_count > 12 && progress > 0.6 && item_frac < 0.25 {
            nb += 5.0 * progress * (1.0 - item_frac / 0.25);
        }
        if nx > 0.0 && fitting_bins_count >= 1 && (cap - it) >= nx && (cap - it - nx) < 0.05 * cap && progress < 0.5 {
            nb -= 4.0 * (1.0 - (cap - it - nx) / (0.05 * cap)) * (1.0 - progress);
        }
        if nx > 0.0 && (cap - it).max(0.0) < nx && fitting_bins_count <= 1 && mean_residual < 0.3 * cap {
            nb += 3.5 * (1.0 - mean_residual / (0.3 * cap)) * (0.5 + progress);
        }
        if fitting_bins_count >= 2 && mean_residual >= it + nx && progress > 0.4 {
            let rem = mean_residual - it - nx;
            if rem < 0.05 * cap {
                nb -= 4.5 * (1.0 - rem / (0.05 * cap)) * progress;
            }
        }
        if fitting_bins_count == 1 && mean_residual >= it && (mean_residual - it) < 0.04 * cap && progress > 0.3 {
            nb -= 3.0 * (1.0 - (mean_residual - it) / (0.04 * cap)) * (0.5 + progress);
        }
        if open_bins_count > 8 && mean_residual < 0.1 * cap && progress > 0.5 {
            nb -= 4.0 * (1.0 - mean_residual / (0.1 * cap)) * progress;
        }
        if fitting_bins_count >= 1 && mean_residual >= it && progress > 0.65 {
            let best_pr = (mean_residual - it).max(0.0);
            if best_pr > 0.0 && best_pr < 0.05 * cap {
                nb += 5.5 * (1.0 - best_pr / (0.05 * cap)) * progress;
            }
        }
        if nx > 0.0 && mean_residual >= it + nx && progress > 0.55 {
            let rem = mean_residual - it - nx;
            if rem > 0.2 * cap {
                nb += 3.5 * ((rem - 0.2 * cap) / cap).min(0.3) * 10.0 * progress;
            }
        }
        if nx > 0.0 && cap >= it + nx && cap - it - nx < 0.02 * cap && fitting_bins_count <= 3 {
            nb -= 3.5 * (1.0 - (cap - it - nx) / (0.02 * cap)) * (0.6 + progress);
        }
        if open_bins_count > 14 && mean_residual > 0.55 * cap && progress > 0.5 {
            nb += 4.0 * ((mean_residual - 0.55 * cap) / cap).min(0.3) * 10.0 * progress;
        }
        if item_frac < 0.1 && progress > 0.7 && fitting_bins_count >= 2 {
            nb += 5.0 * progress;
        }
        if nx > 0.0 && fitting_bins_count >= 1 && mean_residual >= it + nx && progress > 0.7 {
            let rem = mean_residual - it - nx;
            if rem < 0.03 * cap {
                nb -= 3.2 * (1.0 - rem / (0.03 * cap)) * progress;
            }
        }
        if item_frac < 0.2 && nx > 0.0 && mean_residual >= it + nx && progress > 0.6 {
            nb -= 4.0 * (1.0 - item_frac / 0.2) * progress;
        }
        if nx > 0.0 && mean_residual < nx && progress > 0.55 && item_frac < 0.5 {
            nb += 3.5 * (nx - mean_residual).min(0.1 * cap) / (0.1 * cap) * progress;
        }
        if nx > 0.0 && fitting_bins_count >= 1 && mean_residual >= it + nx && progress > 0.45 {
            let rem = mean_residual - it - nx;
            if rem > 0.12 * cap && rem < 0.3 * cap {
                nb -= 3.8 * (1.0 - (rem - 0.12 * cap) / (0.18 * cap)) * (0.4 + progress);
            }
        }
        if open_bins_count > 5 && progress > 0.3 && item_frac > 0.55 {
            nb -= 3.5 * (item_frac - 0.55) * 2.0 * progress;
        }
        if nx > 0.0 && mean_residual > 0.6 * cap && progress < 0.5 && fitting_bins_count >= 3 {
            nb += 4.0 * ((mean_residual - 0.6 * cap) / cap).min(0.3) * 10.0 * (1.0 - progress);
        }
        if nx > 0.0 && cap >= it + nx && (cap - it - nx) < 0.07 * cap && progress < 0.5 {
            nb -= 4.5 * (1.0 - (cap - it - nx) / (0.07 * cap)) * (1.0 - progress);
        }
        if nx > 0.0 && item_frac + (nx / cap) > 1.0 && fitting_bins_count >= 1 && mean_residual >= nx && progress > 0.5 {
            nb -= 3.0 * (1.0 - mean_residual / (0.5 * cap)) * progress;
        }
        if nx > 0.0 && fitting_bins_count >= 1 && mean_residual - it >= nx && (mean_residual - it - nx) < 0.04 * cap && progress > 0.35 {
            nb -= 4.2 * (1.0 - (mean_residual - it - nx) / (0.04 * cap)) * (0.5 + progress);
        }
        score = nb;
    } else {
        let fill_ratio = 1.0 - res / cap;
        let waste = pr / cap;

        // Near-perfect fit bonuses
        if waste < 0.08 {
            score -= 48.0 * (1.0 - progress) * (0.08 - waste);
        }
        if fill_ratio > 0.65 {
            score -= 4.8 * (fill_ratio - 0.65) * 10.0 * (0.4 + progress);
        }
        if nx > 0.0 && nx <= pr && pr > 0.0 {
            let gap = (pr - nx) / cap;
            if gap < 0.03 {
                score -= 7.5 * (1.0 - gap * 33.0);
            }
        }

        // Tiny residual penalties (avoid stranding slivers)
        if pr > 0.0 && pr < 10.0 {
            score += 41.0 * (1.0 - 0.5 * progress);
        }
        if pr == 0.0 {
            score -= 62.0;
        } else if pr <= 5.0 {
            score -= 31.0 * (1.0 - 0.4 * progress);
        }
        if nx > 0.0 && pr > 0.0 && pr < nx {
            score += 6.5 + 2.2 * progress;
            if nx - pr <= 3.0 {
                score -= 9.0 * (1.0 - progress);
            }
            let closeness = 1.0 - pr / nx;
            score += 3.0 * closeness * closeness * (0.6 + progress);
        }

        // Balance vs mean residual with quadratic deviation
        let dev = mean_residual - res;
        score += 0.085 * dev;
        score += 0.01 * dev * dev;
        if dev > -5.0 && dev < 15.0 && pr > 0.0 {
            score -= 4.2;
        }

        // Exact chain fit bonus
        let tight_fit = (pr == 0.0) || (nx > 0.0 && pr == nx);
        if tight_fit {
            score -= 10.5 * (0.3 + progress);
        }

        // Reward bins whose post-residual still fits next item with small slack
        if nx > 0.0 && pr >= nx {
            let room = pr - nx;
            if room < 0.06 * cap {
                score -= 6.5 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
            }
            if room > 0.06 * cap && room < 0.22 * cap && fitting_bins_count <= 2 {
                score -= 2.0 * (1.0 - (room / (0.22 * cap))) * (0.6 + progress);
            }
        }

        // Mid-range waste penalty for dead-space control
        if waste > 0.14 && waste < 0.34 {
            score += 13.0 * (waste - 0.14) * (0.6 + 0.8 * progress);
        }
        if fitting_bins_count > 3 && waste < 0.12 {
            score -= 5.5 * (1.0 - waste * 8.0) * (0.5 + progress);
        }
        if nx > 0.0 && pr > 0.0 && pr > nx && (pr - nx) < 0.02 * cap {
            score -= 4.0 * (1.0 - (pr - nx) / (0.02 * cap)) * (0.4 + progress);
        }
        if pr > 0.0 && (pr as f64).sqrt() < 2.6 {
            score -= 3.5 * (1.0 - progress);
        }
        if waste > 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.09 * cap && progress > 0.4 {
            score -= 4.0 * (1.0 - (pr - nx) / (0.09 * cap)) * progress;
        }
        if pr > 0.0 && nx > 0.0 && pr < nx && (nx - pr) > 0.1 * cap && waste > 0.25 {
            score += 5.0 * (waste - 0.25) * 10.0 * (0.4 + progress);
        }
        if pr > 0.0 && nx > 0.0 && pr < 0.5 * nx && progress > 0.3 {
            score += 3.5 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
        }
        if waste > 0.3 && pr > nx && progress < 0.5 {
            score += 3.0 * (waste - 0.3) * 10.0 * (1.0 - progress);
        }
        if fill_ratio > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
            score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
        }
        if waste > 0.35 && progress > 0.55 && nx > 0.0 && pr >= nx {
            score -= 4.5 * ((pr - nx) / cap).min(0.2) * 5.0 * progress;
        }
        if nx > 0.0 && pr > nx && (pr - nx) <= 0.04 * cap {
            score -= 3.2 * (1.0 - (pr - nx) / (0.04 * cap)) * (1.0 - progress);
        }
        if nx > 0.0 && pr > nx && (pr - nx) > 0.04 * cap && (pr - nx) < 0.18 * cap {
            score -= 2.2 * (1.0 - ((pr - nx) / (0.18 * cap))) * (0.3 + progress);
        }
        if pr > 0.0 && it > 0.0 && pr < it * 0.5 && waste > 0.05 {
            score += 2.5 * (1.0 - pr / (it * 0.5)) * (0.4 + progress);
        }
        if waste > 0.18 && waste < 0.4 && nx > 0.0 && pr >= nx && (pr - nx) < 0.12 * cap {
            score += 3.0 * (1.0 - (pr - nx) / (0.12 * cap)) * (0.5 + progress);
        }
        if waste > 0.28 && fitting_bins_count > 2 && progress > 0.5 {
            score += 3.5 * (waste - 0.28) * 10.0 * progress;
        }
        if waste > 0.4 && pr > 0.0 && nx > 0.0 && pr < nx && progress > 0.6 {
            score += 4.0 * (waste - 0.4) * 10.0 * progress;
        }
        if pr > 0.0 && nx > 0.0 && pr >= nx && (pr - nx) < 0.5 * nx && progress > 0.6 {
            score -= 2.8 * (1.0 - (pr - nx) / (0.5 * nx)) * progress;
        }
        if waste > 0.05 && waste < 0.14 && pr >= nx && progress > 0.5 {
            score -= 2.4 * (1.0 - (waste - 0.05) / 0.09) * progress;
        }
        if waste > 0.12 && waste < 0.3 && nx > 0.0 && pr >= nx && (pr - nx) >= 0.12 * cap {
            score += 2.2 * ((pr - nx) / cap) * (0.4 + progress);
        }
        if fill_ratio > 0.92 && pr > 0.0 {
            score -= 2.0 * (fill_ratio - 0.92) * 10.0 * (0.5 + progress);
        }
        if waste > 0.45 && pr >= nx && nx > 0.0 && progress > 0.65 {
            score -= 3.0 * (waste - 0.45) * 10.0 * progress;
        }
        if nx > 0.0 && pr > nx && (pr - nx) > 0.22 * cap && progress > 0.3 {
            score -= 1.8 * ((pr - nx) / cap).min(0.35) * (0.5 + progress);
        }
        if waste > 0.06 && waste < 0.16 && nx > 0.0 && pr >= nx && (pr - nx) < 0.04 * cap && progress > 0.55 {
            score -= 2.6 * (1.0 - (pr - nx) / (0.04 * cap)) * progress;
        }
        if waste > 0.08 && waste < 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.07 * cap && progress > 0.35 {
            score -= 2.9 * (1.0 - (pr - nx) / (0.07 * cap)) * (0.5 + progress);
        }
        if waste > 0.22 && fitting_bins_count <= 1 && progress > 0.5 {
            score += 2.8 * (waste - 0.22) * 10.0 * progress;
        }
        if waste > 0.5 && pr > 0.0 && nx > 0.0 && pr >= nx && progress > 0.7 {
            score -= 2.4 * ((pr - nx) / cap).min(0.25) * 4.0 * progress;
        }
        if nx > 0.0 && pr > nx && (pr - nx) > 0.3 * cap && progress > 0.6 && fitting_bins_count >= 2 {
            score -= 2.5 * ((pr - nx) / cap).min(0.4) * progress;
        }
        if waste > 0.1 && waste < 0.3 && pr > 0.0 && nx > 0.0 && pr >= nx && (pr - nx) > 0.05 * cap && (pr - nx) < 0.15 * cap && progress > 0.2 {
            score -= 2.4 * (1.0 - ((pr - nx) - 0.05 * cap) / (0.10 * cap)) * (0.4 + progress);
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Gaps below ~half of the smallest possible item (10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 15.0;
    } else if post_residual < 40 {
        score += 5.0;
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Tightness ratio: prefer bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Dead-space curvature: quadratic penalty on wasted space, scaled by stream progress
    // (later in the stream, waste matters more since fewer chances to recover).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / cap).powi(2) * (30.0 + 40.0 * progress);

    // Open-bin pressure: when many bins are open, avoid opening new ones;
    // when few are open, consolidation pressure is relaxed.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += pressure * 12.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Lookahead: if the next item can use this bin's post-residual, reward placement.
    if next_item_size > 0 && (post_residual as u64) >= next_item_size as u64 {
        score -= 18.0;
    }
    // If next item cannot fit in the leftover, penalize creating that leftover.
    if next_item_size > 0 && post_residual > 0 && (post_residual as u64) < next_item_size as u64 {
        score += 8.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Opening a new bin is only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by open-bin count and mean residual.
        score += 20.0 + pressure * 25.0;
        // If mean residual of open bins is large, opening new bins is wasteful.
        score += (mean_residual / cap).clamp(0.0, 1.0) * 15.0;
        // Early in the stream, new bins are cheaper to open.
        score -= 10.0 * (1.0 - progress);
        // If the next item is large, a fresh bin gives flexibility.
        if next_item_size >= 50 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.10;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: post_residual as dead-space measure
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let nis = next_item_size as f64;

    // 2-step lookahead: perfect match bonus — next item exactly fills leftover
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0; // exact fill of both item and next item => ideal
    } else if next_item_size > 0 && post_residual > next_item_size {
        // next item fits here afterwards: mild reward proportional to tightness
        let slack_after_pair = pr - nis;
        score -= 10.0 * (1.0 - slack_after_pair / cap);
        // penalize leaving awkward gap smaller than min item size
        if slack_after_pair < 1.0 {
            score += 0.0;
        } else if slack_after_pair < 10.0 {
            score += 6.0 * (10.0 - slack_after_pair) / 10.0;
        }
    } else if next_item_size > 0 && next_item_size > bin_residual {
        // next item won't fit here even before placement: neutral
    } else if next_item_size > 0 {
        // next item cannot follow into post_residual: penalize dead space
        score += 8.0;
    }

    // Penalize small unusable leftovers (dead space below min plausible item)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (10.0 - pr) / 10.0;
    }

    // Reward tight fits relative to bin capacity
    score -= 12.0 * (item_size as f64 / cap) * (1.0 - pr / cap);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Compare against mean residual: placing into below-average residual bin
    // keeps a spread of useful residuals
    if pr < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0 * (pr - mean_residual).min(20.0) / 20.0;
    }

    // New-bin candidate handling: empty bin gets a moderate baseline penalty
    // so it only wins when open bins would create large dead space
    if bin_residual == bin_capacity {
        score += 25.0;
        // early in stream, opening bins is cheaper; late, consolidate
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
        // if next item is large, a fresh bin is more attractive
        if nis >= 50.0 {
            score -= 8.0;
        }
    }

    // Slight penalty for bin proliferation
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large post_residual unless it can host the next item (lookahead).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 0.6 * next_item_size as f64;
        } else {
            score += 0.35 * (next_item_size as f64 - post_residual as f64).min(60.0);
        }
    } else {
        // Last item: minimize waste directly.
        score += 0.5 * post_residual as f64;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    } else if post_residual < 20 {
        score -= 3.0;
    }

    // Dead-space penalty: residual too small for the smallest possible item (1).
    // With unknown distribution, mildly penalize residuals below ~15.
    if post_residual > 0 && post_residual < 15 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: prefer tightening existing bins over spreading.
    let pressure = (open_bins_count as f64) / (1.0 + mean_residual / 10.0);
    score += 0.05 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Early in the stream: opening new bins is cheap, allow new-bin candidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New bin: base cost; cheaper early, more expensive late.
        score = 55.0 + 60.0 * progress;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        }
        // If current bin fits would be very wasteful, new bin is attractive.
        if item_size <= 30 && fitting_bins_count > 0 {
            score -= 10.0;
        }
    } else {
        // Late in stream: consolidate, penalize leaving big residuals in many bins.
        score += 15.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic non-linear coupling of post_residual with stream progress.
    // Early on, prefer tight fits (low post_residual). Late in the stream,
    // residual waste matters even more, so the penalty steepens smoothly.
    let mut score = pr * (1.0 + 1.5 * progress * progress);

    // Smooth cubic interaction: waste is increasingly punished as stream progresses.
    score += 40.0 * norm_pr * norm_pr * norm_pr * (0.5 + progress);

    // Reward near-perfect fills smoothly: gaussian-like bump around post_residual == 0.
    score -= 25.0 * (-(norm_pr * norm_pr) / 0.02).exp();

    // Lookahead coupling: if the next item fits the post-residual, reward this bin smoothly.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            let tight = 1.0 - (pr - ns) / cap;
            score -= 15.0 * tight * (0.5 + progress);
        } else {
            // Penalize creating residual that the next item cannot use, smoothly.
            let gap = (ns - pr) / cap;
            score += 20.0 * gap * gap * (0.5 + progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // rather than opening a new bin (scaled smoothly with progress).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 * (1.0 + progress);
    }

    // Mild penalty for scattering across many open bins when mean residual is high.
    let open_f = open_bins_count as f64;
    score += 0.05 * open_f * (mean_residual / cap).abs() * (1.0 - progress);

    // New-bin candidate handling: make an empty bin mildly attractive only when
    // no open bin offers a good fit (post_residual would be large relative to cap).
    if bin_residual == bin_capacity {
        // Empty-bin baseline: prefer it when it would waste less than the mean open bin.
        score = pr * (1.0 + 1.5 * progress * progress)
            + 40.0 * norm_pr * norm_pr * norm_pr * (0.5 + progress)
            + 10.0 * (mean_residual / cap).min(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "friendly"
    // divisors/multiples for common item sizes (mod classes 0, 10, 20, 25, 50).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is always excellent
    } else {
        // residual divisible by small harmonic steps -> likely reusable
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 25 == 0 { score -= 6.0; }
        if pr % 50 == 0 { score -= 4.0; }
        // dead space: residual too small for the smallest plausible item
        if pr < 10 { score += 45.0; }
        else if pr < 20 { score += 15.0; }
        // integer-division threshold: residual in awkward mid-band
        let band = pr / 20; // 0..=5
        score += (band as f64 - 2.5).abs() * 3.0;
    }

    // Coupling with lookahead item: does post_residual still fit next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            // exact harmonic match: next item exactly fills remainder
            if post_residual == next_item_size { score -= 25.0; }
            // next item then divides residual into a friendly class
            let rr = post_residual - next_item_size;
            if rr % 10 == 0 { score -= 5.0; }
        } else {
            score += 12.0; // next item won't fit here -> dead-end risk
        }
    }

    // Last-chance bin: strong penalty if we skip it a new bin opens
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive early or when open bins are tight
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = mean_residual < item_size as f64;
        let penalty = 25.0 + 40.0 * progress + if tight { -20.0 } else { 0.0 };
        score += penalty;
        // opening a bin is fine if item is large and would leave bad residue elsewhere
        if item_size as f64 > 0.7 * cap { score -= 15.0; }
    }

    // Prefer bins with residual close to item (tight fit), scaled by mean state
    let waste = (bin_residual as f64 - item_size as f64).abs();
    score += waste * 0.3;
    score -= mean_residual * 0.05;

    // Spread load when many bins open, consolidate when few
    if open_bins_count > 8 { score += 2.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 4.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 8.0;

    // Open bins pressure: discourage spreading across many bins unless fit is good.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot use the gap: penalize dead space more.
        score += post_residual as f64 * 0.5;
    }

    // New-bin candidate handling: neutral-to-slightly-high baseline so it is
    // only chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 12.0 + mean_residual * 0.1;
    }

    // Mild stream-progression scaling of dead-space penalty.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    if bin_residual == bin_capacity {
        // New-bin candidate: penalize so it's only chosen when open bins are hopeless.
        score = bin_capacity as f64 * 0.65;
        // If this bin is the last chance among open bins, strongly discourage opening a new bin.
        if fitting_bins_count <= 1 {
            score += 40.0;
        }
        // Early in stream, new bins are cheap; later, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 10.0;
        return score;
    }

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 {
        if post_residual as u64 == next_item_size as u64 {
            score -= 55.0;
        } else if post_residual >= next_item_size {
            // Slack matches next item with some room: mild reward.
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space: post_residual can't fit the next item.
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.9;
        }
    } else {
        // Last item: just minimize post residual.
        score -= 15.0;
    }

    // Reward tight fits relative to current residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 25.0;

    // Penalize deviation from mean residual: prefer balanced bins unless last chance.
    score += (post_residual as f64 - mean_residual).abs() * 0.15;
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Slight preference for filling bins when many bins are open.
    score += open_bins_count as f64 * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (fragmentation)
    if post_residual < item_size.min(10) && post_residual > 0 {
        score += 40.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Last chance: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Lookahead: if next item fits in post residual, reward; else penalize
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
        } else {
            score += (next_item_size as f64) * 0.15;
        }
    }

    // Time horizon: later in stream, prefer consolidating into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 15.0;

    // Global state: many open bins -> discourage spreading; compare residual to mean
    score += (bin_residual as f64 - mean_residual) * 0.3;
    if open_bins_count > 8 {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        // baseline cost of opening a bin, reduced when current bins are fragmented
        let frag = mean_residual / bin_capacity as f64;
        score = 30.0 + frag * 40.0 - (fitting_bins_count as f64) * 5.0;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 25.0; // large next item: fresh bin useful
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits (small post_residual), with a non-linear
    // polynomial coupling to stream progress — early on, waste tolerance
    // is higher; later, tight packing matters more.
    let mut score = post * (1.0 + 1.5 * progress * progress) + 40.0 * norm_post * norm_post;

    // Dead-space penalty grows super-linearly for unusable remnants
    // (residual too small for the smallest plausible item).
    let min_item = item_size.min(next_item_size.max(1)).max(1) as f64;
    if post < min_item {
        score += 30.0 * (1.0 - post / min_item) * (1.0 + progress);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward bins whose post-residual still admits the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 8.0 * (1.0 - (post - nxt) / cap) * (0.5 + 0.5 * progress);
        } else {
            score += 6.0 * (1.0 - post / nxt.max(1.0));
        }
    }

    // New-bin candidate: make it mildly attractive early (spread items),
    // progressively expensive as the stream advances unless it is the only option.
    if bin_residual == bin_capacity {
        let openness = (1.0 - progress).powf(1.5);
        score = cap as f64 * (1.0 + 0.5 * progress)
            - 30.0 * openness
            - (if fitting_bins_count == 0 { 40.0 } else { 0.0 });
    }

    // Slight preference for bins deviating below the mean residual
    // (fill the emptiest bins first when ties otherwise).
    if bin_residual != bin_capacity {
        score += 0.05 * (bin_residual as f64 - mean_residual).max(-20.0);
    }

    score
}

