        else if post_residual >= 50 { 1 }
        else if post_residual >= 33 { 2 }
        else if post_residual >= 25 { 3 }
        else if post_residual >= 20 { 4 }
        else { 5 };
    score += class as f64 * 3.0;

    // Reward exact-fill and near-fill strongly
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 40.0;
    }

    // Penalize dead space that no plausible item (>=1) can be wasted on:
    // tiny residuals are fine, but mid-range residuals (11..19) are classic traps
    if post_residual >= 11 && post_residual <= 19 {
        score += 15.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
