        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no open bin
    // fits well. Penalize the fresh bin by its full residual unless stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 20.0 };
        score += 10.0 + 30.0 * progress + scarcity;
        // but if item is huge relative to typical residual, new bin is fine
        if item_size as f64 > mean_residual + 0.5 * cap {
            score -= 15.0;
        }
    }

