pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: gaps too small to plausibly fit future items.
    // Items range 1..100, but typical useful gaps are >= ~10-20; treat small
    // post_residual as wasted capacity with a superlinear penalty.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 10.0 {
