        if fitting_bins_count >= 1 && mean_residual >= it && progress > 0.65 {
            let best_pr = (mean_residual - it).max(0.0);
            if best_pr > 0.0 && best_pr < 0.05 * cap {
                nb += 5.5 * (1.0 - best_pr / (0.05 * cap)) * progress;
            }
        }
        if nx > 0.0 && mean_residual >= it + nx && progress > 0.55 {
            let rem = mean_residual - it - nx;
            if rem > 0.2 * cap {
                nb += 3.5 * ((rem - 0.2 * cap) / cap).min(0.3) * 10.0 * progress;
            }
        }
        if nx > 0.0 && cap >= it + nx && cap - it - nx < 0.02 * cap && fitting_bins_count <= 3 {
            nb -= 3.5 * (1.0 - (cap - it - nx) / (0.02 * cap)) * (0.6 + progress);
        }
        if open_bins_count > 14 && mean_residual > 0.55 * cap && progress > 0.5 {
            nb += 4.0 * ((mean_residual - 0.55 * cap) / cap).min(0.3) * 10.0 * progress;
        }
        if item_frac < 0.1 && progress > 0.7 && fitting_bins_count >= 2 {
            nb += 5.0 * progress;
        }
        if nx > 0.0 && fitting_bins_count >= 1 && mean_residual >= it + nx && progress > 0.7 {
            let rem = mean_residual - it - nx;
            if rem < 0.03 * cap {
                nb -= 3.2 * (1.0 - rem / (0.03 * cap)) * progress;
            }
        }
        if item_frac < 0.2 && nx > 0.0 && mean_residual >= it + nx && progress > 0.6 {
            nb -= 4.0 * (1.0 - item_frac / 0.2) * progress;
        }
        if nx > 0.0 && mean_residual < nx && progress > 0.55 && item_frac < 0.5 {
            nb += 3.5 * (nx - mean_residual).min(0.1 * cap) / (0.1 * cap) * progress;
        }
        if nx > 0.0 && fitting_bins_count >= 1 && mean_residual >= it + nx && progress > 0.45 {
            let rem = mean_residual - it - nx;
            if rem > 0.12 * cap && rem < 0.3 * cap {
                nb -= 3.8 * (1.0 - (rem - 0.12 * cap) / (0.18 * cap)) * (0.4 + progress);
            }
        }
        if open_bins_count > 5 && progress > 0.3 && item_frac > 0.55 {
            nb -= 3.5 * (item_frac - 0.55) * 2.0 * progress;
        }
        if nx > 0.0 && mean_residual > 0.6 * cap && progress < 0.5 && fitting_bins_count >= 3 {
            nb += 4.0 * ((mean_residual - 0.6 * cap) / cap).min(0.3) * 10.0 * (1.0 - progress);
        }
        if nx > 0.0 && cap >= it + nx && (cap - it - nx) < 0.07 * cap && progress < 0.5 {
            nb -= 4.5 * (1.0 - (cap - it - nx) / (0.07 * cap)) * (1.0 - progress);
        }
        if nx > 0.0 && item_frac + (nx / cap) > 1.0 && fitting_bins_count >= 1 && mean_residual >= nx && progress > 0.5 {
            nb -= 3.0 * (1.0 - mean_residual / (0.5 * cap)) * progress;
        }
        if nx > 0.0 && fitting_bins_count >= 1 && mean_residual - it >= nx && (mean_residual - it - nx) < 0.04 * cap && progress > 0.35 {
            nb -= 4.2 * (1.0 - (mean_residual - it - nx) / (0.04 * cap)) * (0.5 + progress);
        }
        score = nb;
    } else {
        // Fine-grained residual fitting with lookahead anticipation
        let fill_ratio = 1.0 - res / cap;
        if waste < 0.08 {
            score -= 48.0 * (1.0 - progress) * (0.08 - waste);
        }
        if fill_ratio > 0.65 {
            score -= 4.8 * (fill_ratio - 0.65) * 10.0 * (0.4 + progress);
        }
        if nx > 0.0 && nx <= pr && pr > 0.0 {
            let gap = (pr - nx) / cap;
            if gap < 0.03 {
                score -= 7.5 * (1.0 - gap * 33.0);
            }
            if gap <= 0.04 {
                score -= 3.2 * (1.0 - gap / 0.04) * (1.0 - progress);
            }
        }
        if pr > 0.0 && pr < 10.0 {
            score += 41.0 * (1.0 - 0.5 * progress);
        }
        if pr == 0.0 {
            score -= 62.0;
        } else if pr <= 5.0 {
            score -= 31.0 * (1.0 - 0.4 * progress);
        }
        if nx > 0.0 && pr > 0.0 && pr < nx {
            let gap = nx - pr;
            score += gap * (2.0 + 6.5 * (1.0 - progress));
            if gap <= 3.0 {
                score -= 9.0 * (1.0 - progress);
            }
            let closeness = 1.0 - pr / nx;
            score += 3.0 * closeness * closeness * (0.6 + progress);
        }
        let dev = mean_residual - res;
        score += 0.085 * dev;
        if dev > -5.0 && dev < 15.0 && pr > 0.0 {
            score -= 4.2;
        }
        let tight_fit = (pr == 0.0) || (nx > 0.0 && pr == nx);
        if tight_fit {
            score -= 10.5 * (0.3 + progress);
        }
        if nx > 0.0 && pr >= nx {
            let room = pr - nx;
            if room < 0.06 * cap {
                score -= 6.5 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if waste > 0.14 && waste < 0.34 {
            score += 13.0 * (waste - 0.14) * (0.6 + 0.8 * progress);
        }
        if fitting_bins_count > 3 && waste < 0.12 {
            score -= 5.5 * (1.0 - waste * 8.0) * (0.5 + progress);
        }
        if nx > 0.0 && pr > 0.0 && pr > nx && (pr - nx) < 0.02 * cap {
            score -= 4.0 * (1.0 - (pr - nx) / (0.02 * cap)) * (0.4 + progress);
        }
        if pr > 0.0 && (pr as f64).sqrt() < 2.6 {
            score -= 3.5 * (1.0 - progress);
        }
        if waste > 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.09 * cap && progress > 0.4 {
            score -= 4.0 * (1.0 - (pr - nx) / (0.09 * cap)) * progress;
        }
        if pr > 0.0 && nx > 0.0 && pr < nx && (nx - pr) > 0.1 * cap && waste > 0.25 {
            score += 5.0 * (waste - 0.25) * 10.0 * (0.4 + progress);
        }
        if pr > 0.0 && nx > 0.0 && pr < 0.5 * nx && progress > 0.3 {
            score += 3.5 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
        }
        if waste > 0.3 && pr > nx && progress < 0.5 {
            score += 3.0 * (waste - 0.3) * 10.0 * (1.0 - progress);
        }
        if fill_ratio > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
            score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
        }
        if waste > 0.35 && progress > 0.55 && nx > 0.0 && pr >= nx {
            score -= 4.5 * ((pr - nx) / cap).min(0.2) * 5.0 * progress;
        }
        // Scarcity: prefer using existing bins when few can fit
        if fitting_bins_count == 1 {
            score -= 14.0 + 12.0 * progress;
        } else if fitting_bins_count == 2 {
            score -= 4.0 + 3.0 * progress;
        }
        // NEW: mid-range chain gaps between 0.04 and 0.18 of capacity are
        // still useful for the next item — reward them more smoothly.
        if nx > 0.0 && pr > nx && (pr - nx) > 0.04 * cap && (pr - nx) < 0.18 * cap {
            score -= 2.2 * (1.0 - ((pr - nx) / (0.18 * cap))) * (0.3 + progress);
        }
        // NEW: tiny residuals that fit nothing (below item) are dead space;
        // penalize proportionally to closeness of being half-usable.
        if pr > 0.0 && it > 0.0 && pr < it * 0.5 && waste > 0.05 {
            score += 2.5 * (1.0 - pr / (it * 0.5)) * (0.4 + progress);
        }
        // NEW: waste in the 0.18–0.4 band with a comfortable chain gap is
        // acceptable — soften the penalty for such bins.
        if waste > 0.18 && waste < 0.4 && nx > 0.0 && pr >= nx && (pr - nx) < 0.12 * cap {
            score += 3.0 * (1.0 - (pr - nx) / (0.12 * cap)) * (0.5 + progress);
        }
        // NEW: large chain gaps late in the stream are genuinely useful
        if nx > 0.0 && pr > nx && (pr - nx) > 0.22 * cap && progress > 0.3 {
            score -= 1.8 * ((pr - nx) / cap).min(0.35) * (0.5 + progress);
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in "reusable"
    // residue classes (multiples of 10 / half-capacity) are more attractive.
    let r = post_residual;
    let class_penalty: f64 = if r == 0 {
        -30.0 // perfect fit: huge reward
    } else if r % 10 == 0 {
        -12.0 // decadal leftover: highly reusable
    } else if r % 5 == 0 {
        -6.0
    } else if r <= 9 {
        18.0 // tiny dead space
    } else {
        0.0
    };
    score += class_penalty;

    // Integer-division thresholds: leftover large enough for typical next items
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.05 * next_item_size as f64;
            // harmonic bonus if next item exactly divides leftover
            if post_residual % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
        } else {
            score += 10.0; // cannot host the lookahead item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless current bin is hopeless
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.3;
        if post_residual % 10 == 0 {
            score -= 10.0; // fresh bin with decadal residual is fine late in stream
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Prefer tighter bins: relative fill coupling
    score += (1.0 - (bin_residual as f64 / cap_f)) * 4.0;

    // Slight preference when bin residual deviates from mean (consolidation)
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward using a bin whose residual closely matches the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness);

    // Last-chance bin: strongly favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.8 * open_bins_count as f64;

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // dead space relative to lookahead item
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is terrible.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        let penalty = 35.0 * (1.0 - crowding); // cheap to open when bins are full
        score += penalty;
        if post_residual >= 20 {
            score -= 10.0; // a fresh bin leaves useful space
        }
    }

    // Mild stream progression: later in stream, prefer consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

