        if nx > 0.0 && pr >= nx {
            let room = pr - nx;
            if room < 0.06 * cap {
                score -= 6.5 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if waste > 0.14 && waste < 0.34 {
            score += 13.0 * (waste - 0.14) * (0.6 + 0.8 * progress);
        }
        if fitting_bins_count > 3 && waste < 0.12 {
            score -= 5.5 * (1.0 - waste * 8.0) * (0.5 + progress);
        }
        if nx > 0.0 && pr > 0.0 && pr > nx && (pr - nx) < 0.02 * cap {
            score -= 4.0 * (1.0 - (pr - nx) / (0.02 * cap)) * (0.4 + progress);
        }
        if pr > 0.0 && (pr as f64).sqrt() < 2.6 {
            score -= 3.5 * (1.0 - progress);
        }
        if waste > 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.09 * cap && progress > 0.4 {
            score -= 4.0 * (1.0 - (pr - nx) / (0.09 * cap)) * progress;
        }
        if pr > 0.0 && nx > 0.0 && pr < nx && (nx - pr) > 0.1 * cap && waste > 0.25 {
            score += 5.0 * (waste - 0.25) * 10.0 * (0.4 + progress);
        }
        if pr > 0.0 && nx > 0.0 && pr < 0.5 * nx && progress > 0.3 {
            score += 3.5 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
        }
        if waste > 0.3 && pr > nx && progress < 0.5 {
            score += 3.0 * (waste - 0.3) * 10.0 * (1.0 - progress);
        }
        if fill_ratio > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
            score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
        }
        if waste > 0.35 && progress > 0.55 && nx > 0.0 && pr >= nx {
            score -= 4.5 * ((pr - nx) / cap).min(0.2) * 5.0 * progress;
        }
        if fitting_bins_count == 1 {
            score -= 14.0 + 12.0 * progress;
        } else if fitting_bins_count == 2 {
            score -= 4.0 + 3.0 * progress;
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match of next item into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-chain
        } else if next_item_size < post_residual {
            let new_post = (post_residual - next_item_size) as f64;
            // reward proportional to how tight the second placement is
            score -= 25.0 * (1.0 - new_post / bin_capacity as f64);
            // extra reward if the remaining space stays "usable" (>= typical small item)
            if new_post >= 10.0 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here: penalize mildly, more if this bin becomes dead space
            score += 8.0;
            if post_residual < 10 {
                score += 12.0; // dead space created
            }
        }
    }

    // Tightness of current placement: small post_residual is good (unless dead space).
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 20.0 * tightness;
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver penalty
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // default neutral-ish; penalize opening a new bin when open bins fit well
        score = bin_capacity as f64 + 40.0 - 55.0 * scarcity
            - if next_item_size > 0 && next_item_size <= bin_capacity { 0.0 } else { 0.0 };
        // if next item is large, a fresh bin is more valuable
        if next_item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Late-stream consolidation: as stream progresses, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Lookahead: reward leaving space usable by next item, penalize awkward leftovers
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 4.0;
        }
        if post_residual > 0 && post_residual < next_item_size.min(10) {
            score += 5.0; // tiny dead space
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is bad when decent alternatives exist
        if fitting_bins_count > 0 {
            let tightness = (bin_capacity as f64 - item_size as f64) / bin_capacity as f64;
            if tightness < 0.25 {
                score -= 8.0; // item nearly fills a fresh bin anyway
            } else {
                score += 20.0 + 10.0 * (open_bins_count as f64).ln().max(0.0);
            }
        }
        // Late in the stream, prefer reusing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer bins tighter than average (fill down the residuals)
    let avg = mean_residual;
    if (bin_residual as f64) < avg - 5.0 {
        score -= 3.0;
    } else if (bin_residual as f64) > avg + 5.0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    let mut score = pr * (1.0 + 0.5 * progress + 0.75 * progress * progress);

    // Penalize large dead space quadratically, amplified late in the stream.
    score += 8.0 * norm_pr * norm_pr * (0.5 + progress) * cap * 0.1;

    // Reward tight fits: cubic decay of score as post_residual shrinks.
    score -= 6.0 * (1.0 - norm_pr).powi(3) * (1.0 + progress);

    // Lookahead coupling: reward bins whose post_residual fits the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = norm_pr - norm_next;
        score -= 5.0 * (1.0 - gap * gap) * (0.6 + 0.4 * progress);
    } else if next_item_size > 0 {
        score += 2.0 * norm_next * (0.5 + progress);
    }

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 4.0 * (1.0 + progress);
    }

    // Mild penalty for proliferating bins relative to mean residual.
    score += 0.05 * (open_bins_count as f64) * (mean_residual / cap - norm_pr).abs();

    // New-bin candidate: penalize slightly unless residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap - 0.5).abs();
        score += 3.0 - 4.0 * fragmentation * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "nice"
    // classes (multiples of 10, or tiny residuals) are rewarded.
    let pr = post_residual;
    let class = pr % 10;
    if pr == 0 {
        score -= 40.0; // perfect fill: best possible outcome
    } else if class == 0 {
        score -= 12.0; // residual aligned to decile: easy for future items
    } else if pr < 10 {
        score -= 20.0; // dead space below minimum item size is harmless
    } else {
        // penalize awkward residuals proportional to how far from a decile
        score += (5 - class.min(10 - class)) as f64 * 1.5;
    }

    // Lookahead coupling: does next_item_size fit exactly or well into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0; // perfect chain
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            if slack % 10 == 0 {
                score -= 10.0;
            }
            score -= (20.0 - (slack as f64).min(20.0)) * 0.4;
        } else {
            // next item cannot fit here; residual becomes a waiting class
            score += 6.0;
            if pr < 10 {
                score -= 6.0; // but tiny residual is still fine
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless it is genuinely useful.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 / (total_items.max(1) as f64);
        score += 18.0 - 10.0 * progress + 15.0 * pressure;
        // opening a new bin is attractive when item is large and nothing fits well
        if item_size > 60 && fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mild preference toward filling fuller bins relative to fleet state.
    score -= (bin_residual as f64 / bin_capacity as f64) * 4.0;
    score += (mean_residual - post_residual as f64).max(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever host a future
    // item (items >= 1) are pure waste; residuals below the next item's size
    // are likely waste too. Penalize them sharply.
    if post_residual == 0 {
        score -= 60.0; // perfect fit: highly desirable
    } else if post_residual < 10 {
        score += 45.0; // unusable micro-gap under any realistic item
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0; // gap cannot host the lookahead item
    } else {
        // Usable residual: mild reward scaled by how much slack remains
        score -= 8.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins when the
    // placement is loose; encourage consolidation.
    score += 0.9 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is already below average (tighter bins),
    // keeping large-residual bins available for big future items.
    score += 0.35 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying as the stream progresses
        // (early on, opening bins is cheap and useful for future flexibility).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 - 25.0 * progress;
        // If this item is a last-resort case, opening a fresh bin is fine.
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
    }

    // Lookahead synergy: if the next item would fit exactly into the
    // post-residual, reward this placement strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward when post_residual exactly matches the next item (perfect 2-step chain)
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 60.0; // exact 2-step fill
        } else if post_residual > next_item_size {
            // next item fits but leaves more waste; penalize proportional to leftover
            score -= 20.0 - 0.3 * gap;
        } else {
            // next item won't fit here; penalize dead space
            score += 0.5 * gap;
        }
    }

    // Penalize large post_residual relative to mean residual (wasted space)
    score += 0.4 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: neutral-ish score so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    // Prefer tight fits overall (small post_residual bonus)
    score -= 0.2 * (bin_capacity - post_residual) as f64 / bin_capacity as f64 * 10.0;

    // Late in stream: tighten packing, avoid new bins
    let progress = step_index as f64 / total_items as f64;
    score -= 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
