        }
        if nx > 0.0 && pr > 0.0 && pr < nx {
            let gap = nx - pr;
            score += gap * (2.0 + 6.5 * (1.0 - progress));
            if gap <= 3.0 {
                score -= 9.0 * (1.0 - progress);
            }
            // sharpened dead-space penalty scaled by closeness to usability
            let closeness = 1.0 - pr / nx;
            score += 3.0 * closeness * closeness * (0.6 + progress);
            // NEW: near-miss residual just below next item, amplified when
            // the bin is otherwise well-filled
            if gap <= 0.04 * cap && fill_ratio > 0.7 {
