            score -= 4.5 * ((pr - nx) / cap).min(0.2) * 5.0 * progress;
        }
        // Scarcity: prefer using existing bins when few can fit
        if fitting_bins_count == 1 {
            score -= 14.0 + 12.0 * progress;
        } else if fitting_bins_count == 2 {
            score -= 4.0 + 3.0 * progress;
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual quadratically.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Post residual too small for next item: dead space risk, penalize.
        score += 8.0 * (post_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Many open bins: discourage spreading; prefer filling existing bins.
    score += 0.5 * open_bins_count as f64;

    // Prefer bins whose residual deviates favorably from the mean residual
    // (fill below-average-residual bins keeps large residual bins flexible).
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate: penalize opening a new bin, but relax it when the item
    // is huge (near capacity) or late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let huge_item = item_size as f64 / bin_capacity as f64;
        score += 55.0 - 45.0 * huge_item - 10.0 * progress;
        // If no open bin fits well (post residual would be tiny in existing bins),
        // opening a new bin is more attractive; handled via the tight-fit term above.
    }

    // Early stream: slightly favor opening bins to build diversity of residuals.
    score -= 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

