                nb += (1.0 + 2.0 * progress) * (nx - r1) * 0.55;
            }
            if r1 >= nx && (r1 - nx) > 0.25 * cap && progress > 0.45 {
                nb += 4.5 * ((r1 - nx) / cap).min(0.5) * progress;
            }
        }
        // Chain-friendly fresh bin
        if nx > 0.0 && cap >= it + nx && (cap - it - nx) < 0.08 * cap && progress > 0.3 {
            nb -= 5.0 * (1.0 - (cap - it - nx) / (0.08 * cap)) * (0.5 + progress);
        }
        // NEW: refuse new bins when plenty of roomy open bins exist
        if open_bins_count > 6 && mean_residual > 0.4 * cap && progress < 0.6 {
            nb += 5.0 * ((mean_residual - 0.4 * cap) / cap) * (1.0 - progress) * ((open_bins_count as f64 - 6.0).min(8.0) / 8.0);
        }
        if item_frac < 0.15 && progress > 0.55 && fitting_bins_count >= 1 {
            nb += 6.0 * progress * (1.0 - item_frac / 0.15);
        }
        // NEW: wide margin chain discount
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin < 0.15 * cap {
                nb -= 6.0 * (1.0 - margin / (0.15 * cap)) * (0.6 + 0.4 * progress);
            }
        }
        score = nb;
    } else {
        // Fine-grained residual fitting with lookahead anticipation
        let fill_ratio = 1.0 - res / cap;
        if waste < 0.08 {
            score -= 48.0 * (1.0 - progress) * (0.08 - waste);
        }
        if fill_ratio > 0.65 {
            score -= 4.8 * (fill_ratio - 0.65) * 10.0 * (0.4 + progress);
        }
        if nx > 0.0 && nx <= pr && pr > 0.0 {
            let gap = (pr - nx) / cap;
            if gap < 0.03 {
                score -= 7.5 * (1.0 - gap * 33.0);
            }
            if gap <= 0.04 {
                score -= 3.2 * (1.0 - gap / 0.04) * (1.0 - progress);
            }
            let chain = 1.0 - gap.min(1.0);
            score -= 5.0 + 4.0 * (nx / cap) + 9.5 * chain * (1.0 - progress);
        }
        if pr > 0.0 && pr < 10.0 {
            score += 41.0 * (1.0 - 0.5 * progress);
        }
        if pr == 0.0 {
            score -= 62.0;
        } else if pr <= 5.0 {
            score -= 31.0 * (1.0 - 0.4 * progress);
        }
        if nx > 0.0 && pr > 0.0 && pr < nx {
            let gap = nx - pr;
            score += gap * (2.0 + 6.5 * (1.0 - progress));
            if gap <= 3.0 {
                score -= 9.0 * (1.0 - progress);
            }
            let closeness = 1.0 - pr / nx;
            score += 3.0 * closeness * closeness * (0.6 + progress);
        }
        // NEW: moderate chain slack reward (from best heuristic)
        if nx > 0.0 && pr > nx && (pr - nx) > 0.04 * cap && (pr - nx) < 0.18 * cap {
            score -= 2.2 * (1.0 - ((pr - nx) / (0.18 * cap))) * (0.3 + progress);
        }
        let dev = mean_residual - res;
        score += 0.085 * dev;
        if dev > -5.0 && dev < 15.0 && pr > 0.0 {
            score -= 4.2;
        }
        let tight_fit = (pr == 0.0) || (nx > 0.0 && pr == nx);
        if tight_fit {
            score -= 10.5 * (0.3 + progress);
        }
        if nx > 0.0 && pr >= nx {
            let room = pr - nx;
            if room < 0.06 * cap {
                score -= 6.5 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if waste > 0.14 && waste < 0.34 {
            score += 13.0 * (waste - 0.14) * (0.6 + 0.8 * progress);
        }
        if fitting_bins_count > 3 && waste < 0.12 {
            score -= 5.5 * (1.0 - waste * 8.0) * (0.5 + progress);
        }
        if nx > 0.0 && pr > 0.0 && pr > nx && (pr - nx) < 0.02 * cap {
            score -= 4.0 * (1.0 - (pr - nx) / (0.02 * cap)) * (0.4 + progress);
        }
        if pr > 0.0 && (pr as f64).sqrt() < 2.6 {
            score -= 3.5 * (1.0 - progress);
        }
        if waste > 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.09 * cap && progress > 0.4 {
            score -= 4.0 * (1.0 - (pr - nx) / (0.09 * cap)) * progress;
        }
        if pr > 0.0 && nx > 0.0 && pr < nx && (nx - pr) > 0.1 * cap && waste > 0.25 {
            score += 5.0 * (waste - 0.25) * 10.0 * (0.4 + progress);
        }
        if pr > 0.0 && nx > 0.0 && pr < 0.5 * nx && progress > 0.3 {
            score += 3.5 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
        }
        if waste > 0.3 && pr > nx && progress < 0.5 {
            score += 3.0 * (waste - 0.3) * 10.0 * (1.0 - progress);
        }
        if fill_ratio > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
            score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
        }
        if waste > 0.35 && progress > 0.55 && nx > 0.0 && pr >= nx {
            score -= 4.5 * ((pr - nx) / cap).min(0.2) * 5.0 * progress;
        }
        // Scarcity: prefer using existing bins when few can fit
        if fitting_bins_count == 1 {
            score -= 14.0 + 12.0 * progress;
        } else if fitting_bins_count == 2 {
            score -= 4.0 + 3.0 * progress;
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tight = 1.0 - pr / cap; // how full the bin becomes (0..1)

    // Base: prefer small post-residual, with a non-linear (quadratic) reward
    // so very tight fits are disproportionately favored.
    let mut score = pr + 12.0 * (pr / cap) * (1.0 - tight);

    // Smooth progress coupling: as the stream advances, tighten preference for
    // filling bins completely (dead space becomes more costly).
    let progress_coupling = progress * progress * (1.0 - progress * 0.5);
    score -= 20.0 * progress_coupling * tight * tight;

    // Penalize residuals that are too small to be useful later, smoothly:
    // a residual near zero is fine (bin closed), mid-small residuals are worst.
    let r_norm = pr / cap;
    let deadness = r_norm * (1.0 - r_norm); // peaks at r=0.5
    score += 15.0 * deadness;

    // Lookahead: reward if next item fits into the resulting residual,
    // penalize smoothly otherwise.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            let fit_quality = 1.0 - ((pr - ni) / cap).abs();
            score -= 10.0 * fit_quality * fit_quality;
        } else {
            let gap = (ni - pr) / cap;
            score += 8.0 * gap * (1.0 + progress);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - deadness);
    }

    // Slight preference for reusing existing bins vs. opening new ones:
    // the new-bin candidate has bin_residual == bin_capacity (pr == cap),
    // which already gets a high pr score; add mild global pressure.
    score += 0.05 * (open_bins_count as f64) * (1.0 - tight);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of 10) are favored; odd/prime-like leftovers penalized.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty: tiny post_residual is either perfect (0) or wasteful.
    if post_residual == 0 {
        score -= 40.0; // perfect fit
    } else if post_residual < 10 {
        score += 60.0; // unusable dead space (min item size 10)
    }

    // Modulo-10 harmonic class: leftovers divisible by 10 pair well with
    // future items; penalize leftovers in awkward classes.
    let m = post_residual % 10;
    let class_penalty = match m {
        0 => -25.0,
        1 | 9 => 18.0,
        2 | 8 => 10.0,
        3 | 7 => 6.0,
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division thresholds: post_residual bucketed by quarters of capacity.
    let q = post_residual / (bin_capacity / 4);
    match q {
        0 => score += 8.0,   // nearly full bin: good packing
        1 => score -= 5.0,   // quarter-ish left
        2 => score -= 12.0,  // half empty: plenty of room
        _ => score -= 20.0,  // mostly empty
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / cap);
            // harmonic check: does the pair leave a class-0 remainder?
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 15.0;
            }
        } else {
            // next item cannot follow in this bin; slight penalty scaled by
            // how much leftover would be stranded
            score += 10.0 * (post / cap);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: fresh bins should only win when open bins
    // are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = (open_bins_count as f64) * (mean_residual / cap);
        score = cap * 0.55 + crowded * 0.5 - progress * 10.0;
        if fitting_bins_count == 0 {
            score -= cap; // no alternative: new bin is fine
        }
    }

    // Mild pressure toward tighter bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize small unusable dead space (nothing 1..100 fits well in tiny gaps).
    if post_residual > 0 && post_residual < 10 {
        score += 1000.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 30.0; // semi-waste zone: only small items can use it
    }

    // Reward tight fits: small post_residual that is still "usable-ish" or zero.
    if post_residual == 0 {
        score -= 200.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // If the next item fits exactly into the post residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack.min(40.0); // best when slack == 0
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few bins,
    // be more tolerant of imperfect fits so we don't proliferate bins early.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 12.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    // Make it attractive only when the item is large relative to capacity or
    // when no open bin offers a good fit (post_residual large).
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Big items start fresh bins cheaply; small items should use open bins.
        score -= 60.0 * fill_ratio * fill_ratio;
        // If the current best open-bin option wastes a lot, fresh bin is fine.
        if post_residual as f64 > mean_residual {
            score -= 10.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;
    let mut score = pr * (1.0 + 0.03 * (pr / cap) * (pr / cap));
    let tightness = 1.0 + 2.6 * progress * progress + 2.4 * progress * progress * progress;
    score *= tightness;

    // Perfect / near-perfect fills
    if pr == 0.0 {
        score -= 1000.0;
    } else if pr <= 5.0 {
        score -= 300.0 * (1.0 - 0.3 * progress);
    } else if pr <= 10.0 {
        score -= 120.0;
    }

    // 2-step lookahead
    if nx > 0.0 {
        if pr == nx {
            score -= 500.0;
        } else if nx <= pr {
            let frac = nx / pr;
            score -= 200.0 * frac * frac;
            let chain_left = pr - nx;
            if chain_left <= 5.0 {
                score -= 100.0;
            } else if chain_left <= 10.0 {
                score -= 40.0;
            } else if chain_left <= 42.0 {
                score -= 0.11 * chain_left * (0.5 + progress);
            }
        } else {
            let gap = nx - pr;
            score += 60.0 + gap * (2.0 + 4.0 * (1.0 - progress));
            if gap <= 0.04 * cap {
                score -= 3.5 * (1.0 - gap / (0.04 * cap)) * (0.5 + progress);
            }
        }
    }

    // Mean residual comparison
    if mean_residual > 0.0 {
        score -= 0.5 * (mean_residual - pr);
    }

    // Last-chance bin
    if fitting_bins_count == 1 {
        score -= 150.0 * (0.6 + progress);
    } else if fitting_bins_count >= 4 {
        score -= 6.5 + 8.5 * progress;
    }

    // Dead-space penalty, non-linear, scaled by progress
    let dead_ratio = (pr / cap).max(0.0);
    if dead_ratio >= 0.12 {
        let unusable = if nx > 0.0 && pr < nx { 1.0 } else { 0.55 };
        score += (10.5 + 3.2 * progress) * dead_ratio * dead_ratio * cap * (0.45 + progress) * unusable;
    } else if dead_ratio > 0.0 {
        score -= 9.0 * (1.0 - dead_ratio / 0.12) * (0.4 + progress);
    }

    // New-bin candidate
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let item_frac = (it / cap).min(1.0);
        let mut nb = cap * (1.35 + 1.15 * progress);
        nb -= 26.0 * scarcity * (1.0 - progress);
        nb -= 19.0 * item_frac * (1.0 - progress);
        if nx >= 0.5 * cap {
            nb -= 12.0 * progress + 6.0 * (1.0 - progress);
        }
        if it >= cap - 1.0 {
            nb -= 32.0;
        }
        if nx > 0.0 && cap - it >= nx {
            let r1 = cap - it - nx;
            if r1 < 6.0 {
                nb -= 10.5 + 0.11 * r1;
            }
        }
        if fitting_bins_count <= 2 {
            nb += 21.0 + 10.0 * (1.0 - progress);
        }
        if fitting_bins_count == 0 && progress > 0.25 {
            nb += 9.0 + 7.0 * progress;
        }
        if nx > 0.0 && mean_residual >= it + nx && progress < 0.6 {
            nb -= 5.5 * (1.0 - progress) * ((mean_residual - it - nx) / cap).min(0.3) * 10.0;
        }
        if item_frac > 0.85 && progress > 0.3 {
            nb -= 9.0 * progress;
        }
        if progress > 0.85 && mean_residual < 0.15 * cap {
            nb += 7.0 * progress * (1.0 - mean_residual / (0.15 * cap));
        }
        score = nb;
    } else {
        // Extra open-bin refinements
        let fill_ratio = 1.0 - bin_residual as f64 / cap;
        if fill_ratio > 0.65 {
            score -= 4.8 * (fill_ratio - 0.65) * 10.0 * (0.4 + progress);
        }
        let dev = mean_residual - bin_residual as f64;
        score += 0.085 * dev;
        if dev > -5.0 && dev < 15.0 && pr > 0.0 {
            score -= 4.2;
        }
        if nx > 0.0 && pr >= nx {
            let room = pr - nx;
            if room < 0.06 * cap {
                score -= 6.5 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if pr > 0.0 && nx > 0.0 && pr > nx && (pr - nx) <= 0.04 * cap {
            score -= 3.2 * (1.0 - (pr - nx) / (0.04 * cap)) * (1.0 - progress);
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
