            score += 6.5 + 2.2 * progress;
            if nx - pr <= 3.0 {
                score -= 9.0 * (1.0 - progress);
            }
            let closeness = 1.0 - pr / nx;
            score += 3.0 * closeness * closeness * (0.6 + progress);
        }
        if nx > 0.0 && pr >= nx {
            let room = pr - nx;
            if room < 0.06 * cap {
                score -= 6.5 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if waste > 0.14 && waste < 0.34 {
            score += 13.0 * (waste - 0.14) * (0.6 + 0.8 * progress);
        }
        if fitting_bins_count > 3 && waste < 0.12 {
            score -= 5.5 * (1.0 - waste * 8.0) * (0.5 + progress);
        }
        if waste > 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.09 * cap && progress > 0.4 {
            score -= 4.0 * (1.0 - (pr - nx) / (0.09 * cap)) * progress;
        }
        if fill_ratio > 0.92 && pr > 0.0 {
            score -= 2.0 * (fill_ratio - 0.92) * 10.0 * (0.5 + progress);
        }
        if waste > 0.1 && waste < 0.3 && nx > 0.0 && pr >= nx && (pr - nx) > 0.05 * cap && (pr - nx) < 0.15 * cap {
            score -= 2.4 * (1.0 - ((pr - nx) - 0.05 * cap) / (0.10 * cap)) * (0.4 + progress);
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which residue class mod 10 it falls into.
    // Residuals divisible by 10 are "harmonic" (best chance a future item fills them exactly).
    let harmonic = (post_residual % 10 == 0) as f64;
    score -= 12.0 * harmonic;

    // Penalize "dead" residuals: too small for the minimum item (1..100 => keep >= small threshold),
    // but not zero. Dead space = 1..10 cannot be filled by any item in most streams.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit: zero waste is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: does next_item_size exactly consume post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chained fit
        } else if next_item_size < post_residual {
            // reward proportionally to how much of the residual the next item consumes
            let frac = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * frac;
            // harmonic chain: next item leaves a multiple-of-10 residual again
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // next item cannot use this bin's residual anyway: slight penalty for hoarding space
            score += 3.0;
        }
    }

    // Integer-division thresholds on item_size relative to capacity fractions.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if item_size > half {
        score -= 8.0; // large items: prefer placing them early into roomy bins
    } else if item_size <= quarter {
        score += 2.0; // tiny items should go into leftover scraps, not fresh space
    }

    // Last-chance bin: strongly prefer using the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are badly fragmented
    // (mean residual too small to matter) or many bins are already open.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln() + 1.0;
        let fragmentation = mean_residual / bin_capacity as f64;
        score += 15.0 + pressure * 5.0 - 40.0 * (1.0 - fragmentation);
        // opening fresh is attractive if this item is large and mean residual can't host it
        if (item_size as f64) > mean_residual {
            score -= 20.0;
        }
    }

    // Stream progression: early on, be conservative with new bins; late, pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * harmonic;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { (step_index as f64 / total_items as f64).clamp(0.0, 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;

    // New-bin candidate handling (borrowed structure, retuned).
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let item_frac = (it / cap).min(1.0);
        let mut nb = cap * (1.3 + 1.1 * progress);
        nb -= 24.0 * scarcity * (1.0 - progress);
        nb -= 18.0 * item_frac * (1.0 - progress);
        if it >= cap - 1 { nb -= 30.0; }
        if nx > 0.0 && cap - it >= nx { nb -= 10.0 + 0.1 * (cap - it - nx); }
        if fitting_bins_count <= 2 { nb += 20.0 + 9.0 * (1.0 - progress); }
        if fitting_bins_count >= 4 { nb -= 6.0 + 8.0 * progress; }
        if nx > 0.0 && mean_residual >= it + nx && progress < 0.6 {
            nb -= 5.0 * (1.0 - progress) * ((mean_residual - it - nx) / cap).min(0.3) * 10.0;
        }
        if it > 0.85 * cap && progress > 0.3 { nb -= 8.0 * progress; }
        if nx > 0.0 && mean_residual > nx + 8.0 && progress < 0.7 {
            nb += 8.0 * ((mean_residual - nx) / cap).min(0.5) * cap * 0.1;
        }
        if mean_residual >= it && progress > 0.5 { nb += 6.0 + 8.0 * progress; }
        if nx > it && mean_residual >= nx && progress < 0.6 { nb += 9.0 * (1.0 - progress); }
        if fitting_bins_count == 0 && progress > 0.25 { nb += 8.0 + 6.0 * progress; }
        if nx > 0.0 { let r1 = cap - it; if r1 >= nx && (r1 - nx) < 6.0 { nb += 8.0 * (1.0 - progress); } }
        return nb;
    }

    // Open-bin scoring: base on post-residual with mild non-linear waste scaling.
    let mut score = pr * (1.0 + 0.03 * (pr / cap) * (pr / cap));
    let tightness = 1.0 + 2.4 * progress * progress + 2.2 * progress * progress * progress;
    score *= tightness;

    // Lookahead chain: next item fits into post-residual.
    if nx > 0.0 {
        if pr < nx {
            let gap = nx - pr;
            score += gap * (2.0 + 6.0 * (1.0 - progress));
            if gap <= 3.0 { score -= 8.0 * (1.0 - progress); }
        } else {
            let chain_gap = pr - nx;
            let slack = chain_gap / cap;
            if chain_gap <= 42.0 { score -= 6.0 + 0.1 * chain_gap; }
            if slack < 0.04 { score -= 8.0 * (1.0 - slack * 25.0) * (1.0 + progress); }
            let chain = 1.0 - slack.min(1.0);
            score -= 4.5 + 4.0 * (nx / cap) + 9.0 * chain * (1.0 - progress);
        }
    }

    // Perfect and near-perfect fills.
    if pr == 0.0 {
        score -= 60.0;
    } else if pr <= 5.0 {
        score -= 30.0 * (1.0 - 0.4 * progress);
    } else if pr <= 10.0 {
        score -= 12.0 * (1.0 - 0.3 * progress);
    }

    // Dead-space penalty grows with waste ratio, worse when next item can't use it.
    let waste = (pr / cap).max(0.0);
    let unusable = if nx > 0.0 && pr > 0.0 && pr < nx { 1.0 } else { 0.55 };
    score += (10.0 + 3.0 * progress) * waste * waste * cap * (0.45 + progress) * unusable;

    // Reward small-but-usable residual.
    if waste > 0.0 && waste < 0.12 {
        score -= 9.0 * (1.0 - waste / 0.12) * (0.4 + progress);
    }

    // Near-miss: next item almost fits but doesn't — penalize mildly, more early.
    if nx > 0.0 && pr > 0.0 && pr < nx && (nx - pr) <= 0.04 * cap {
        score += 3.0 * (1.0 - (nx - pr) / (0.04 * cap)) * (0.5 + progress);
    }

    // Mean-residual deviation: prefer bins leaving less than average.
    let dev = mean_residual - res;
    score += 0.08 * dev;
    if dev > -5.0 && dev < 15.0 && pr > 0.0 { score -= 4.0; }

    // Last-chance bin: strong preference to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 14.0 * (0.5 + progress);
    }

    // Mid-range waste band penalty (0.14..0.34 of capacity).
    if waste > 0.14 && waste < 0.34 {
        score += 12.0 * (waste - 0.14) * (0.6 + 0.8 * progress);
    }

    // Many fitting bins + small waste: good target.
    if fitting_bins_count > 3 && waste < 0.12 {
        score -= 5.0 * (1.0 - waste * 8.0) * (0.5 + progress);
    }

    // Tight chain fits at various scales.
    if nx > 0.0 && pr >= nx {
        let room = pr - nx;
        if room < 0.06 * cap {
            score -= 6.0 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
        } else if room < 0.22 * cap && fitting_bins_count <= 2 {
            score -= 2.0 * (1.0 - room / (0.22 * cap)) * (0.6 + progress);
        }
    }

    // Tiny residual sqrt bonus early.
    if pr > 0.0 && pr.sqrt() < 2.6 {
        score -= 3.0 * (1.0 - progress);
    }

    // High fill ratio bonus.
    let fill_ratio = 1.0 - res / cap;
    if fill_ratio > 0.65 {
        score -= 4.5 * (fill_ratio - 0.65) * 10.0 * (0.4 + progress);
    }

    // Large unusable residual with big next item.
    if pr > 0.0 && nx > 0.0 && pr < nx && (nx - pr) > 0.1 * cap && waste > 0.25 {
        score += 5.0 * (waste - 0.25) * 10.0 * (0.4 + progress);
    }

    // Residual much smaller than next item: dead space risk.
    if nx > 0.0 && pr > 0.0 && pr < 0.5 * nx && progress > 0.3 {
        score += 3.0 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
    }

    // Open-bin count pressure: slight bonus for consolidating into few bins.
    score -= 0.4 * (open_bins_count as f64).ln().max(0.0);

    score
}

