    if bin_residual == bin_capacity {
        score = bin_capacity as f64;
        if next_item_size > 0 && post_residual == next_item_size {
            // impossible for empty bin, keep baseline
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin good for pairing big items
