            score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
        }
        if waste > 0.35 && progress > 0.55 && nx > 0.0 && pr >= nx {
            score -= 4.5 * ((pr - nx) / cap).min(0.2) * 5.0 * progress;
        }
        // Scarcity: prefer using existing bins when few can fit
        if fitting_bins_count == 1 {
            score -= 14.0 + 12.0 * progress;
        } else if fitting_bins_count == 2 {
            score -= 4.0 + 3.0 * progress;
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let norm_post = post / cap;

    // Base: prefer small post-residual, with smooth non-linear shaping.
    let mut score = post * (1.0 + 0.35 * (1.0 - norm_post) * (1.0 - norm_post));

    // Polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger leftovers (score discounted); late, punish them.
    let progress_coupling = 1.0 - 0.6 * (1.0 - progress) * (1.0 - progress) * (1.0 - progress);
    score += 18.0 * norm_post * norm_post * progress_coupling;

    // Perfect-fit reward (smooth gaussian-like bump around post == 0).
    let fit_quality = (norm_post * 4.0).min(1.0);
    score -= 14.0 * (1.0 - fit_quality) * (1.0 - fit_quality);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * (1.0 - progress);
    }

    // Lookahead: reward if next item can use the post-residual exactly;
    // penalize if next item is large and post-residual is a useless sliver.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = (post - nxt) / cap;
            score -= 8.0 * (1.0 - gap) * (1.0 - gap);
        } else {
            score += 6.0 * (1.0 - post / nxt.max(1.0));
        }
    }

    // New-bin candidate: residual == capacity. Penalize mildly so we only open
    // a new bin when no open bin offers a decent fit; penalty grows with the
    // number of already-open bins and with stream progress.
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);
        // But if the item is huge relative to capacity, opening fresh is fine.
        score -= 20.0 * (item / cap) * (item / cap);
    }

    // Slight preference for bins below mean residual (consolidate emptier bins).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by capacity fractions.
    let pr = post_residual;
    let class = match pr {
        0 => 0.0,                     // perfect fit — best possible
        1..=9 => 1.0,                 // near-perfect: dead space
        10..=24 => 2.0,               // small-slot class
        25..=49 => 3.0,               // half-slot class
        50..=74 => 4.0,               // large-slot class
        _ => 5.0,                     // mostly-empty bin
    };
    score += class * 12.0;

    // Perfect closure bonus: strongly reward filling a bin exactly.
    if pr == 0 { score -= 200.0; }

    // Modulo-10 harmonic alignment: leftovers divisible by 10 pair better with typical item sizes.
    if pr % 10 == 0 && pr > 0 { score -= 8.0; }

    // Integer-division threshold: leftover that can hold the next item is valuable.
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 25.0 + 0.5 * (next_item_size as f64);
        } else {
            score += 15.0; // creates dead space relative to lookahead
        }
        // Exact harmonic pairing: leftover exactly equals next item.
        if pr == next_item_size { score -= 30.0; }
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // Tightness reward: prefer bins whose fill fraction is high.
    let fill_frac = (bin_capacity - pr) as f64 / cap;
    score -= 30.0 * fill_frac * fill_frac;

    // Penalize creating tiny unusable gaps (below min item size 1..10 harmonic band).
    if pr > 0 && pr < 10 { score += 20.0; }

    // Early in the stream, keep bins consolidated; late, exploit spread.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * (open_bins_count as f64).sqrt();

    // Deviation from mean residual: prefer bins near the mean (balanced packing).
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // New-bin candidate: opening a fresh bin should only win when current fit is terrible.
    if bin_residual == bin_capacity {
        score += 60.0 + 0.5 * (item_size as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly unusable.
    let pr = post_residual as f64;
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 45.0 - 3.0 * pr; // hard penalty for unusable slivers
        } else if post_residual <= 20 {
            score += 12.0 - 0.4 * pr;
        }
        // Perfect fit bonus
        if post_residual == 0 {
            score -= 60.0;
        }
    }

    // Reward tight fits relative to bin fill ratio
    let fill = (bin_residual - post_residual) as f64 / cap;
    score -= 25.0 * fill * fill;

    // Last-chance bin before opening a new bin: strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: discourage scattering across many bins
    score += 0.9 * open_bins_count as f64;

    // Lookahead: if next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual && post_residual > 0 {
            let nxt = next_item_size as f64;
            let ratio = nxt / pr;
            score -= 20.0 * ratio * (1.0 - (ratio - 1.0).abs().min(1.0));
        }
        // If next item won't fit anywhere else, keep residual flexible
        if next_item_size > post_residual && post_residual < next_item_size {
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // New-bin candidate: only attractive when current bin would leave bad dead space
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin, modulated by stream progress
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 0.5 * cap + 30.0 * progress;
        if item_size as f64 / cap > 0.7 {
            score -= 15.0; // large items fine in fresh bins
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild deviation from mean residual: prefer bins below mean (tighter bins)
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
