    let nx = next_item_size as f64;
    let mut score = pr * (1.0 + 0.03 * (pr / cap) * (pr / cap));
    // Tightness pressure: later in stream, penalize residual harder.
    let tightness = 1.0 + 2.4 * progress * progress + 2.2 * progress * progress * progress;
    score *= tightness;

    // 2-step lookahead
    if nx > 0.0 {
        if pr < nx {
            let gap = nx - pr;
            score += gap * (2.0 + 6.0 * (1.0 - progress));
            // gap small = near-chainable, soften penalty
            if gap <= 0.04 * cap {
                score -= 3.5 * (1.0 - gap / (0.04 * cap)) * (0.5 + progress);
            }
