        score -= 30.0 * (1.0 - 0.4 * progress);
    } else if pr <= 10.0 {
        score -= 12.0 * (1.0 - 0.3 * progress);
    }

    // Mean-residual pull
    score += 0.08 * (mean_residual - bin_residual as f64);

