    if dead_ratio > 0.14 && dead_ratio < 0.34 {
        score += 12.0 * (dead_ratio - 0.14) * (0.6 + 0.8 * progress);
    }

    // ---- NEW BIN CANDIDATE ----
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let item_frac = (it / cap).min(1.0);
        let mut nb = cap * (1.30 + 1.10 * progress);
        nb -= 25.0 * scarcity * (1.0 - progress);
        nb -= 18.0 * item_frac * (1.0 - progress);
        if nx >= 0.5 * cap {
            nb -= 12.0 * progress + 6.0 * (1.0 - progress);
        }
        nb += 14.0 * progress * (1.0 - item_frac);
        if it >= cap - 1.0 {
            nb -= 30.0;
        }
        // new bin leaves room for next item -> good
        if nx > 0.0 && cap - it >= nx {
            nb -= 10.0 + 0.10 * (cap - it - nx);
        }
        // but leaves a tiny awkward remainder -> bad
        if nx > 0.0 {
            let r1 = cap - it;
            if r1 >= nx && (r1 - nx) < 6.0 && (r1 - nx) > 0.0 {
                nb += 8.0 * (1.0 - progress);
            }
        }
        if fitting_bins_count <= 2 {
            nb += 20.0 + 10.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 4 {
            nb -= 6.0 + 8.0 * progress;
        }
        // mean residual large relative to item: open bins can absorb, keep new bin costly
        if mean_residual >= it && progress > 0.5 {
            nb += 6.0 + 8.0 * progress;
        }
        if nx > it && mean_residual >= nx && progress < 0.6 {
            nb += 9.0 * (1.0 - progress);
        }
        if nx > 0.0 && mean_residual >= it + nx && progress < 0.6 {
            nb -= 5.0 * (1.0 - progress) * ((mean_residual - it - nx) / cap).min(0.3) * 10.0;
        }
        if it > 0.85 * cap && progress > 0.3 {
            nb -= 8.5 * progress;
        }
        if fitting_bins_count == 0 && progress > 0.25 {
            nb += 8.5 + 7.0 * progress;
        }
        if progress > 0.75 && fitting_bins_count > 0 && mean_residual >= it {
            nb += 5.0 + 4.0 * progress;
        }
        // best open bin would leave near-perfect fit for next item -> avoid new bin
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_pr = (mean_residual - it).max(0.0);
            if best_pr > 0.0 && best_pr < 0.06 * cap && (cap - it) >= nx {
                nb -= 6.5 * (1.0 - best_pr / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if progress > 0.85 && mean_residual < 0.15 * cap {
            nb += 6.5 * progress * (1.0 - mean_residual / (0.15 * cap));
        }
        score = nb;
    } else {
        // fine-grained chain bonuses
        if nx > 0.0 && pr >= nx {
            let room = pr - nx;
            if room < 0.06 * cap {
                score -= 6.0 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
            }
            if room > 0.25 * cap && progress > 0.45 {
                score += 4.0 * (room / cap).min(0.5) * progress;
            }
        }
        // near-exact two-item chain
        if nx > 0.0 && pr > nx && (pr - nx) < 0.02 * cap {
            score -= 4.0 * (1.0 - (pr - nx) / (0.02 * cap)) * (0.4 + progress);
        }
        // item barely fits leaving usable room for next
        if nx > 0.0 && cap >= it + nx && (cap - it - nx) < 0.08 * cap && progress > 0.3 {
            score -= 4.5 * (1.0 - (cap - it - nx) / (0.08 * cap)) * (0.5 + progress);
        }
        // penalize leaving residual that next item cannot chain into, when open bins are plentiful
        if open_bins_count > 6 && mean_residual > 0.4 * cap && progress < 0.6 {
            score += 4.5 * ((mean_residual - 0.4 * cap) / cap) * (1.0 - progress) * ((open_bins_count as f64 - 6.0).min(8.0) / 8.0);
        }
        score -= 0.40 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    score -= 0.5 * (bin_capacity as f64 - post_residual as f64).abs().ln().max(0.0);

    // 2-step lookahead: if next item fits into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > post_residual {
        // Dead space: next item can't use this residual.
        score += 8.0;
    }

    // Penalize leaving residual below the minimum item size (1..100 unknown, use conservative threshold).
    if post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Compare against mean residual: bins with residual near/below mean are more valuable to fill.
    let mean_gap = mean_residual - bin_residual as f64;
    score += 0.05 * mean_gap;

    // Early in stream, be more willing to open new bins (keep options open).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize moderately; allow only when fit is poor or lookahead fails.
        score += 25.0 - 10.0 * progress;
        if next_item_size > post_residual || post_residual > 40 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on wasted space.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // Mild preference among many candidates based on tightness (already covered).
        score += 0.0;
    }

    // Lookahead: penalize leaving residual that cannot fit the next item
    // (dead space), reward residual that accommodates it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.15 * (next_item_size as f64);
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 6.0 + 0.2 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Penalize creating very small unusable fragments relative to mean residual.
    if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 {
        score += 10.0;
    }

    // Time horizon: early in the stream, allow more exploration / new bins;
    // late in the stream, consolidate aggressively into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;          // favor existing bins more as stream ends
    if open_bins_count > 8 {
        score += (open_bins_count as f64 - 8.0) * 0.5; // discourage bin proliferation
    }

    // New-bin candidate: opening a fresh bin is only attractive when current
    // item is large and existing residuals are poor fits.
    if bin_residual == bin_capacity {
        let poor_fits = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let big_item = (item_size as f64) / (bin_capacity as f64);
        let freshness = 1.0 - progress;
        // Prefer new bin early, for big items, or when few alternatives exist.
        let new_bin_bonus = 25.0 * big_item + 20.0 * freshness + 30.0 * poor_fits;
        score -= new_bin_bonus;
        // But discourage new bins if plenty of open bins already fit the item.
        if fitting_bins_count >= 2 {
            score += 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits, but with progress-dependent non-linear weighting.
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Smooth non-linear coupling: dead-space penalty grows super-linearly late in stream.
    score += 40.0 * x * x * (0.5 + progress);

    // Reward bins whose residual after placement matches the lookahead item smoothly.
    let nl = next_item_size as f64;
    if nl > 0.0 {
        let gap = (pr - nl).abs();
        score -= 12.0 * (1.0 - gap / cap) * (1.0 - progress * 0.5);
    }

    // Last-chance bonus: strongly favor the only fitting bin (smooth in fitting count).
    if fitting_bins_count > 0 {
        score -= 25.0 * (1.0 / fitting_bins_count as f64) * (1.0 + progress);
    }

    // Mild pressure toward consolidation relative to mean residual.
    score += 0.05 * (pr - mean_residual) * (1.0 - progress);

    // New-bin candidate: penalize opening bins early, reward late when open bins are fragmented.
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (20.0 - 30.0 * progress) + new_bin * 5.0 * (open_bins_count as f64).ln();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = ((step_index as f64) / (total_items as f64).max(1.0)).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;
    let res = bin_residual as f64;
    let waste = pr / cap;
    let item_frac = (it / cap).min(1.0);

    let mut score = pr * (1.0 + 0.03 * waste * waste) * (1.0 + 2.6 * progress * progress);

    if pr == 0.0 {
        score -= 1000.0;
    } else if pr <= 5.0 {
        score -= 300.0 * (1.0 - 0.3 * progress);
    } else if pr <= 10.0 {
        score -= 120.0;
    }

    // 2-step lookahead
    if nx > 0.0 {
        if pr == nx {
            score -= 500.0;
        } else if nx < pr {
            let chain_left = pr - nx;
            let frac = nx / pr;
            score -= 200.0 * frac * frac;
            if chain_left <= 5.0 {
                score -= 100.0 * (1.0 - 0.3 * progress);
            } else if chain_left <= 10.0 {
                score -= 40.0;
            }
            if chain_left > 0.25 * cap && progress > 0.45 {
                score += 3.0 * ((chain_left / cap).min(0.4)) * progress;
            }
        } else {
            score += 60.0 + 2.0 * progress * (nx - pr).min(30.0);
            if nx - pr <= 3.0 {
                score -= 9.0 * (1.0 - progress);
            }
        }
    }

    // dead-space penalty, stronger when next item can't use it
    let unusable = if nx > 0.0 && pr > 0.0 && pr < nx { 1.0 } else { 0.55 };
    score += (10.5 + 3.2 * progress) * waste * waste * cap * (0.45 + progress) * unusable;
    if waste > 0.0 && waste < 0.12 {
        score -= 9.0 * (1.0 - waste / 0.12) * (0.4 + progress);
    }
    if waste > 0.14 && waste < 0.34 {
        score += 13.0 * (waste - 0.14) * (0.6 + 0.8 * progress);
    }

    // mean residual comparison
    let dev = mean_residual - pr;
    score -= 0.5 * dev;
    if dev > -5.0 && dev < 15.0 && pr > 0.0 {
        score -= 4.2;
    }

    // last-chance bin
    if fitting_bins_count == 1 {
        score -= 150.0 * (0.5 + progress);
    }

    // ---- new-bin candidate logic ----
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let mut nb = cap * (1.35 + 1.15 * progress);
        nb -= 26.0 * scarcity * (1.0 - progress);
        nb -= 19.0 * item_frac * (1.0 - progress);
        if nx >= 0.5 * cap {
            nb -= 12.0 * progress + 6.0 * (1.0 - progress);
        }
        nb += 15.0 * progress * (1.0 - item_frac);
        if it >= cap - 1.0 {
            nb -= 32.0;
        }
        if nx > 0.0 && cap - it >= nx {
            nb -= 10.5 + 0.11 * (cap - it - nx);
        }
        if fitting_bins_count <= 2 {
            nb += 21.0 + 10.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 4 {
            nb -= 6.5 + 8.5 * progress;
        }
        if it > 0.85 * cap && progress > 0.3 {
            nb -= 9.0 * progress;
        }
        if nx > 0.0 && mean_residual >= it + nx && progress < 0.6 {
            nb -= 5.5 * (1.0 - progress) * ((mean_residual - it - nx) / cap).min(0.3) * 10.0;
        }
        if nx > 0.0 && cap >= it + nx && cap - it - nx < 0.08 * cap && progress > 0.3 {
            nb -= 5.0 * (1.0 - (cap - it - nx) / (0.08 * cap)) * (0.5 + progress);
        }
        if nx > 0.0 && cap >= it + nx && (cap - it - nx) < 0.02 * cap && fitting_bins_count <= 3 {
            nb -= 3.5 * (1.0 - (cap - it - nx) / (0.02 * cap)) * (0.6 + progress);
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_pr = (mean_residual - it).max(0.0);
            if best_pr >= nx && best_pr - nx > 0.18 * cap && progress > 0.35 {
                nb -= 6.0 * ((best_pr - nx) / cap).min(0.4) * (0.4 + progress);
            }
        }
        if progress > 0.85 && mean_residual < 0.15 * cap {
            nb += 7.0 * progress * (1.0 - mean_residual / (0.15 * cap));
        }
        if nx > 0.0 && cap - it > 0.0 && cap - it < nx {
            nb += 4.5 * (1.0 - progress) * ((nx - (cap - it)) / cap).min(0.3) * 10.0;
        }
        if fitting_bins_count == 0 && progress > 0.25 {
            nb += 9.0 + 7.0 * progress;
        }
        score = nb;
    } else {
        let fill_ratio = 1.0 - res / cap;
        if fill_ratio > 0.65 {
            score -= 4.8 * (fill_ratio - 0.65) * 10.0 * (0.4 + progress);
        }
        if fill_ratio > 0.92 && pr > 0.0 {
            score -= 2.0 * (fill_ratio - 0.92) * 10.0 * (0.5 + progress);
        }
        if pr > 0.0 && nx > 0.0 && pr > nx && (pr - nx) < 0.02 * cap {
            score -= 4.0 * (1.0 - (pr - nx) / (0.02 * cap)) * (0.4 + progress);
        }
        if pr > 0.0 && nx > 0.0 && pr >= nx {
            let room = pr - nx;
            if room < 0.06 * cap {
                score -= 6.5 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if fitting_bins_count > 3 && waste < 0.12 {
            score -= 5.5 * (1.0 - waste * 8.0) * (0.5 + progress);
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 16 define "good" fill classes.
    let pr = post_residual as i64;
    let residue = pr % 16;
    // Perfect-fill reward: post_residual exactly divisible by small divisors is more usable.
    if post_residual == 0 {
        score -= 500.0; // perfect fit, ideal bin closure
    } else {
        if post_residual % 25 == 0 { score -= 60.0; }
        if post_residual % 10 == 0 { score -= 25.0; }
        if post_residual % 5 == 0 { score -= 8.0; }
        // Penalize awkward residues (dead space unlikely to be filled)
        match residue {
            0 => score -= 15.0,
            1 | 2 => score += 12.0,
            3 | 5 | 7 => score += 4.0,
            _ => {}
        }
    }

    // Integer-division thresholds on post_residual: very small leftovers are dead space.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0; // unusable sliver
    } else if post_residual < 20 {
        score += 10.0;
    }

    // Lookahead coupling: does this bin's post_residual accommodate the next item well?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 30.0; // can host the lookahead item
            if slack % 10 == 0 { score -= 10.0; } // clean harmonic split
            if slack < 10 { score += 15.0; }      // but leaves a sliver
        } else {
            // post_residual too small for next item: dead space unless bin closes now
            score += (post_residual as f64) * 0.3;
        }
        // If next item is large, prefer keeping big residuals for it
        if next_item_size >= 60 && post_residual > 0 && post_residual < next_item_size {
            score += 20.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate handling: empty bin should lose unless current bins are crowded/poor fits.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are only opened when justified.
        score += 120.0;
        // Progress-scaled relaxation: later in stream, slightly more willing to open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * progress;
        // If many bins are open and fragmented, opening a fresh bin is reasonable.
        if open_bins_count > 3 {
            score -= 15.0;
        }
        // If mean residual is small (bins nearly full), new bin is attractive.
        if mean_residual < 30.0 {
            score -= 60.0;
        }
        // If item is large and would leave bad residue anywhere, prefer fresh bin.
        if item_size >= 50 && item_size % 10 != 0 {
            score -= 25.0;
        }
    } else {
        // Fragmentation pressure: penalize using bins when many open bins exist.
        score += open_bins_count as f64 * 0.5;
        // Tight-fit reward: item fills most of the residual.
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        if fill_ratio > 0.8 {
            score -= 50.0 * fill_ratio;
        }
        // Reward consuming bins whose residual matches item's harmonic class.
        if bin_residual % 16 == item_size % 16 {
            score -= 12.0;
        }
    }

    // Mild global preference to close bins early (reduce open_bins_count growth).
    if post_residual <= 15 && post_residual > 0 {
        score -= 5.0; // near-closed bins: finishing them is cheap
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
