            }
        }
        if item_frac > 0.45 && item_frac < 0.75 && progress > 0.5 {
            nb -= 5.0 * (item_frac - 0.45) * progress;
        }
        if fitting_bins_count >= 2 && mean_residual < 0.25 * cap && progress > 0.6 {
            nb += 6.0 * (1.0 - mean_residual / (0.25 * cap)) * progress;
        }
        if fitting_bins_count >= 3 && mean_residual - it >= nx && progress > 0.5 {
            nb += 4.5 * progress * (1.0 - ((mean_residual - it - nx) / cap).min(1.0));
        }
        if open_bins_count > 10 && progress < 0.35 && item_frac < 0.3 {
            nb += 6.0 * (1.0 - progress) * (1.0 - item_frac / 0.3);
        }
        // penalize opening a bin whose first residual is a dead sliver
        if nx > 0.0 {
            let r1 = cap - it;
            if r1 < nx && r1 > 0.0 {
                nb += (1.0 + 2.6 * progress) * (nx - r1) * 0.7;
            }
            if r1 >= nx && (r1 - nx) > 0.25 * cap && progress > 0.45 {
                nb += 4.5 * ((r1 - nx) / cap).min(0.5) * progress;
            }
        }
        // fresh bin that chains it+nx tightly is attractive
        if nx > 0.0 && cap >= it + nx && (cap - it - nx) < 0.08 * cap && progress > 0.3 {
            nb -= 5.0 * (1.0 - (cap - it - nx) / (0.08 * cap)) * (0.5 + progress);
        }
        if open_bins_count > 6 && mean_residual > 0.4 * cap && progress < 0.6 {
            nb += 5.0 * ((mean_residual - 0.4 * cap) / cap) * (1.0 - progress) * ((open_bins_count as f64 - 6.0).min(8.0) / 8.0);
        }
        if item_frac < 0.15 && progress > 0.55 && fitting_bins_count >= 1 {
            nb += 6.0 * progress * (1.0 - item_frac / 0.15);
        }
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin < 0.15 * cap {
                nb -= 6.0 * (1.0 - margin / (0.15 * cap)) * (0.6 + 0.4 * progress);
            }
        }
        if nx > 0.0 && fitting_bins_count >= 1 && mean_residual - it >= nx {
            let leftover = mean_residual - it - nx;
            if leftover < 0.1 * cap && progress > 0.45 {
                nb -= 5.0 * (1.0 - leftover / (0.1 * cap)) * progress;
            }
        }
        if open_bins_count > 12 && progress > 0.6 && item_frac < 0.25 {
            nb += 5.0 * progress * (1.0 - item_frac / 0.25);
        }
        if nx > 0.0 && fitting_bins_count >= 1 && (cap - it) >= nx && (cap - it - nx) < 0.05 * cap && progress < 0.5 {
            nb -= 4.0 * (1.0 - (cap - it - nx) / (0.05 * cap)) * (1.0 - progress);
        }
        if fitting_bins_count >= 2 && mean_residual >= it + nx && progress > 0.4 {
            let rem = mean_residual - it - nx;
            if rem < 0.05 * cap {
                nb -= 4.5 * (1.0 - rem / (0.05 * cap)) * progress;
            }
        }
        if fitting_bins_count == 1 && mean_residual >= it && (mean_residual - it) < 0.04 * cap && progress > 0.3 {
            nb -= 3.0 * (1.0 - (mean_residual - it) / (0.04 * cap)) * (0.5 + progress);
        }
        if open_bins_count > 8 && mean_residual < 0.1 * cap && progress > 0.5 {
            nb -= 4.0 * (1.0 - mean_residual / (0.1 * cap)) * progress;
        }
        if fitting_bins_count >= 1 && mean_residual >= it && progress > 0.65 {
            let best_pr = (mean_residual - it).max(0.0);
            if best_pr > 0.0 && best_pr < 0.05 * cap {
                nb += 5.5 * (1.0 - best_pr / (0.05 * cap)) * progress;
            }
        }
        if nx > 0.0 && cap >= it + nx && cap - it - nx < 0.02 * cap && fitting_bins_count <= 3 {
            nb -= 3.5 * (1.0 - (cap - it - nx) / (0.02 * cap)) * (0.6 + progress);
        }
        if item_frac < 0.1 && progress > 0.7 && fitting_bins_count >= 2 {
            nb += 5.0 * progress;
        }
        if item_frac < 0.2 && nx > 0.0 && mean_residual >= it + nx && progress > 0.6 {
            nb -= 4.0 * (1.0 - item_frac / 0.2) * progress;
        }
        if nx > 0.0 && mean_residual < nx && progress > 0.55 && item_frac < 0.5 {
            nb += 3.5 * (nx - mean_residual).min(0.1 * cap) / (0.1 * cap) * progress;
        }
        // NEW: opening a bin when a near-perfect fit exists elsewhere is wasteful
        if nx > 0.0 && fitting_bins_count >= 1 && mean_residual >= it {
            let best_pr = mean_residual - it;
            if best_pr < 0.03 * cap {
                nb += 6.0 * (1.0 - best_pr / (0.03 * cap)) * (0.5 + progress);
            }
        }
        // NEW: fresh bin whose first residual is a mid-size usable slack is mildly attractive
        if nx > 0.0 && cap >= it + nx {
            let m = cap - it - nx;
            if m >= 0.08 * cap && m < 0.2 * cap && progress > 0.4 {
                nb -= 3.0 * (1.0 - (m - 0.08 * cap) / (0.12 * cap)) * (0.4 + progress);
            }
        }
        score = nb;
    } else {
        // Fine-grained residual fitting with lookahead anticipation
        let fill_ratio = 1.0 - res / cap;
        if waste < 0.08 {
            score -= 48.0 * (1.0 - progress) * (0.08 - waste);
        }
        if fill_ratio > 0.65 {
            score -= 4.8 * (fill_ratio - 0.65) * 10.0 * (0.4 + progress);
        }
        if nx > 0.0 && nx <= pr && pr > 0.0 {
            let gap = (pr - nx) / cap;
            if gap < 0.03 {
                score -= 7.5 * (1.0 - gap * 33.0);
            }
            if gap <= 0.04 {
                score -= 3.2 * (1.0 - gap / 0.04) * (1.0 - progress);
            }
            let chain = 1.0 - gap.min(1.0);
            score -= 5.0 + 4.0 * (nx / cap) + 9.5 * chain * (1.0 - progress);
            // extended chain-slack reward — mid-size slack after nx is still useful
            if gap > 0.04 && gap < 0.18 {
                score -= 2.6 * (1.0 - gap / 0.18) * (0.3 + progress);
            }
        }
        if pr > 0.0 && pr < 10.0 {
            score += 41.0 * (1.0 - 0.5 * progress);
        }
        if pr == 0.0 {
            score -= 62.0;
        } else if pr <= 5.0 {
            score -= 31.0 * (1.0 - 0.4 * progress);
        }
        if nx > 0.0 && pr > 0.0 && pr < nx {
            let gap = nx - pr;
            score += gap * (2.0 + 6.5 * (1.0 - progress));
            if gap <= 3.0 {
                score -= 9.0 * (1.0 - progress);
            }
            // sharpened dead-space penalty: residual just below next item
            let closeness = 1.0 - pr / nx;
            score += 3.6 * closeness * closeness * (0.6 + progress);
            // dead-sliver that can never chain with typical items
            if gap > 0.1 * cap && waste > 0.2 {
                score += 4.5 * (waste - 0.2) * 10.0 * (0.4 + progress);
            }
        }
        // NEW: quadratic dead-space penalty on unusable residual (borrowed idea)
        let dead_ratio = waste.max(0.0);
        let unusable = if nx > 0.0 && pr > 0.0 && pr < nx { 1.0 } else { 0.55 };
        score += (10.5 + 3.2 * progress) * dead_ratio * dead_ratio * cap * (0.45 + progress) * unusable;
        if dead_ratio > 0.0 && dead_ratio < 0.12 {
            score -= 9.0 * (1.0 - dead_ratio / 0.12) * (0.4 + progress);
        }
        let dev = mean_residual - res;
        score += 0.085 * dev;
        if dev > -5.0 && dev < 15.0 && pr > 0.0 {
            score -= 4.2;
        }
        let tight_fit = (pr == 0.0) || (nx > 0.0 && pr == nx);
        if tight_fit {
            score -= 10.5 * (0.3 + progress);
        }
        if nx > 0.0 && pr >= nx {
            let room = pr - nx;
            if room < 0.06 * cap {
                score -= 6.5 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
            }
            // near-perfect double-fill lookahead
            if room < 0.02 * cap {
                score -= 4.0 * (1.0 - room / (0.02 * cap)) * (0.6 + progress);
            }
        }
        if waste > 0.14 && waste < 0.34 {
            score += 13.0 * (waste - 0.14) * (0.6 + 0.8 * progress);
        }
        if fitting_bins_count > 3 && waste < 0.12 {
            score -= 5.5 * (1.0 - waste * 8.0) * (0.5 + progress);
        }
        if nx > 0.0 && pr > 0.0 && pr > nx && (pr - nx) < 0.02 * cap {
            score -= 4.0 * (1.0 - (pr - nx) / (0.02 * cap)) * (0.4 + progress);
        }
        if pr > 0.0 && (pr as f64).sqrt() < 2.6 {
            score -= 3.5 * (1.0 - progress);
        }
        if waste > 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.09 * cap && progress > 0.4 {
            score -= 4.0 * (1.0 - (pr - nx) / (0.09 * cap)) * progress;
        }
        if pr > 0.0 && nx > 0.0 && pr < nx && (nx - pr) > 0.1 * cap && waste > 0.25 {
            score += 5.0 * (waste - 0.25) * 10.0 * (0.4 + progress);
        }
        if pr > 0.0 && nx > 0.0 && pr < 0.5 * nx && progress > 0.3 {
            score += 3.5 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
        }
        if waste > 0.3 && pr > nx && progress < 0.5 {
            score += 3.0 * (waste - 0.3) * 10.0 * (1.0 - progress);
        }
        if fill_ratio > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
            score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
        }
        if waste > 0.35 && progress > 0.55 && nx > 0.0 && pr >= nx {
            score -= 4.5 * ((pr - nx) / cap).min(0.2) * 5.0 * progress;
        }
        // Scarcity: prefer using existing bins when few can fit
        if fitting_bins_count == 1 {
            score -= 14.0 + 12.0 * progress;
        } else if fitting_bins_count == 2 {
            score -= 4.0 + 3.0 * progress;
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize leaving a gap that the lookahead item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 15.0;
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: only attractive when the item leaves a compact residual
    // (large item filling a fresh bin well); otherwise penalize.
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size >= 60 {
            score -= 30.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Slight late-stream conservatism: prefer closing bins tightly as stream ends.
    let progress = step_index as f64 / total_items as f64;
    score += post_residual as f64 * 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward exact/near match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.6; // penalty for imperfect chain match
        if post_residual == next_item_size {
            score -= 45.0; // perfect chain: fill bin completely next step
        } else if post_residual >= next_item_size {
            score -= 18.0; // next item still fits after this placement
        }
        // Chain tightness relative to bin capacity
        let chain = (item_size + next_item_size) as f64;
        if (chain / bin_capacity as f64) > 0.9 {
            score -= 12.0; // near-perfect two-item fill
        }
    } else {
        // Last item: strongly prefer minimal leftover
        score += 30.0;
    }

    // Penalize dead space relative to mean residual across open bins.
    let pr = post_residual as f64;
    if pr < mean_residual * 0.5 {
        score -= 8.0; // tighter than average: good compaction
    } else if pr > mean_residual * 1.5 {
        score += 10.0; // leaving unusually large slack
    }

    // Small residual waste penalty (nonlinear): waste under 10 is nearly unusable.
    if pr > 0.0 && pr < 10.0 {
        score += 25.0 * (1.0 - pr / 10.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it moderately attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win; relax late in stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 55.0 - 20.0 * progress;
        // If lookahead chains well into a fresh bin, allow opening.
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64) >= 0.0 {
            new_bin_penalty -= 10.0;
        }
        score += new_bin_penalty;
    }

    // Mild preference for consolidating among many open bins.
    score += (open_bins_count as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) nonlinearly.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) * 0.05;

    // Penalize dead space: post-residual that likely can't fit future items.
    if post_residual < 10 {
        score -= 25.0; // perfect fill bonus
    } else if post_residual < 20 {
        score -= 8.0;
    } else {
        score += (post_residual as f64 - 20.0).max(0.0) * 0.3;
    }

    // Lookahead: if next item fits in post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + next_item_size as f64 * 0.2;
        } else {
            score += 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // residuals are large (items won't fit well anywhere).
    if bin_residual == bin_capacity {
        let avg_fit_pressure = mean_residual - item_size as f64;
        if avg_fit_pressure > 30.0 {
            score -= 20.0; // open bins are too full; new bin is good
        } else {
            score += 40.0 + open_bins_count as f64 * 2.0;
        }
    }

    // Global state: many open bins -> prefer consolidation into existing bins.
    score += open_bins_count as f64 * 1.5;

    // Mean residual coupling: prefer bins below mean residual (less full than
    // average) to balance, unless it's a tight fit situation.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.15;

    // Time horizon: early in stream, be conservative about filling bins
    // unevenly; late in stream, prioritize closing out bins (small residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity as f64 - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let norm_post = post / cap;
    let poly = norm_post * norm_post * (1.0 + progress) + norm_post * progress * (1.0 - progress);
    score += 40.0 * poly;

    // Reward tight fits more strongly as stream progresses.
    let tightness = 1.0 - norm_post;
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual (smooth cubic term).
    let dead = (post - mean_residual) / cap;
    score += 15.0 * dead * dead * dead.abs().max(0.0) * (1.0 + progress);

    // Lookahead: reward leaving room for the next item, smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = if post >= nx { 1.0 } else { 0.0 };
        score -= 20.0 * fit_next * (1.0 - (post - nx) / cap);
        score += 10.0 * (1.0 - fit_next) * progress;
    }

    // Last-chance bonus: smooth sigmoid-like weight on fitting_bins_count.
    let last_chance = 1.0 / (1.0 + (fitting_bins_count.saturating_sub(1)) as f64);
    score -= 25.0 * last_chance * (0.3 + 0.7 * progress);

    // Mild penalty for proliferating open bins late in stream.
    score += 2.0 * (open_bins_count as f64).sqrt() * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;
    let mut score = pr * (1.0 + 0.03 * (pr / cap) * (pr / cap));
    let tightness = 1.0 + 2.6 * progress * progress + 2.4 * progress * progress * progress;
    score *= tightness;

    if nx > 0.0 {
        if pr < nx {
            let gap = nx - pr;
            score += gap * (2.0 + 6.5 * (1.0 - progress));
        } else {
            let chain_gap = pr - nx;
            let slack = chain_gap / cap;
            if chain_gap <= 42.0 {
                score -= 6.5 + 0.11 * chain_gap;
            }
            if slack < 0.04 {
                score -= 8.5 * (1.0 - slack * 25.0) * (1.0 + progress);
            }
            let chain = 1.0 - slack.min(1.0);
            score -= 5.0 + 4.0 * (nx / cap) + 9.5 * chain * (1.0 - progress);
        }
    }

    let dead_ratio = (pr / cap).max(0.0);
    let unusable = if nx > 0.0 && pr > 0.0 && pr < nx { 1.0 } else { 0.55 };
    score += (10.5 + 3.2 * progress) * dead_ratio * dead_ratio * cap * (0.45 + progress) * unusable;
    if dead_ratio > 0.0 && dead_ratio < 0.12 {
        score -= 9.0 * (1.0 - dead_ratio / 0.12) * (0.4 + progress);
    }
    if pr > 0.0 && nx > 0.0 && pr < nx && (nx - pr) <= 0.04 * cap {
        score += 3.5 * (1.0 - (nx - pr) / (0.04 * cap)) * (0.5 + progress);
    }

    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let item_frac = (it / cap).min(1.0);
        let mut nb = cap * (1.35 + 1.15 * progress);
        nb -= 26.0 * scarcity * (1.0 - progress);
        nb -= 19.0 * item_frac * (1.0 - progress);
        if nx >= 0.5 * cap {
            nb -= 12.0 * progress + 6.0 * (1.0 - progress);
        }
        nb += 15.0 * progress * (1.0 - item_frac);
        if it >= cap - 1.0 {
            nb -= 32.0;
        }
        if nx > 0.0 && cap - it >= nx {
            nb -= 10.5 + 0.11 * (cap - it - nx);
        }
        if nx > 0.0 {
            let r1 = cap - it;
            if r1 >= nx && (r1 - nx) < 6.0 && (r1 - nx) > 0.0 {
                nb += 8.5 * (1.0 - progress);
            }
        }
        if fitting_bins_count <= 2 {
            nb += 21.0 + 10.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 4 {
            nb -= 6.5 + 8.5 * progress;
        }
        if nx > 0.0 && mean_residual >= it + nx && progress < 0.6 {
            nb -= 5.5 * (1.0 - progress) * ((mean_residual - it - nx) / cap).min(0.3) * 10.0;
        }
        if it > 0.85 * cap && progress > 0.3 {
            nb -= 9.0 * progress;
        }
        if fitting_bins_count == 0 && progress > 0.25 {
            nb += 9.0 + 7.0 * progress;
        }
        if nx > 0.0 && it + nx > cap && mean_residual >= nx {
            nb += 6.0 * (1.0 - progress);
        }
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin < 0.15 * cap {
                nb -= 6.0 * (1.0 - margin / (0.15 * cap)) * (0.6 + 0.4 * progress);
            }
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_post = (mean_residual - it).max(0.0);
            if best_post >= nx && best_post - nx > 0.18 * cap && progress > 0.35 {
                nb -= 6.0 * ((best_post - nx) / cap).min(0.4) * (0.4 + progress);
            }
        }
        if open_bins_count > 5 && progress > 0.3 && item_frac > 0.55 {
            nb -= 3.5 * (item_frac - 0.55) * 2.0 * progress;
        }
        if nx > 0.0 && cap >= it + nx && (cap - it - nx) < 0.07 * cap && progress < 0.5 {
            nb -= 4.5 * (1.0 - (cap - it - nx) / (0.07 * cap)) * (1.0 - progress);
        }
        score = nb;
    } else {
        let fill_ratio = 1.0 - res / cap;
        let waste = pr / cap;
        if waste < 0.08 {
            score -= 48.0 * (1.0 - progress) * (0.08 - waste);
        }
        if fill_ratio > 0.65 {
            score -= 4.8 * (fill_ratio - 0.65) * 10.0 * (0.4 + progress);
        }
        if nx > 0.0 && nx <= pr && pr > 0.0 {
            let gap = (pr - nx) / cap;
            if gap < 0.03 {
                score -= 7.5 * (1.0 - gap * 33.0);
            }
        }
        if pr == 0.0 {
            score -= 62.0;
        } else if pr <= 5.0 {
            score -= 31.0 * (1.0 - 0.4 * progress);
        }
        if nx > 0.0 && pr > 0.0 && pr < nx {
