            score -= 3.0 * (1.0 - (mean_residual - it) / (0.04 * cap)) * (0.5 + progress);
        }
        if open_bins_count > 8 && mean_residual < 0.1 * cap && progress > 0.5 {
            score -= 4.0 * (1.0 - mean_residual / (0.1 * cap)) * progress;
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that are "perfect fits" vs dead space
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: post_residual divisible by common item-size classes (10,20,25,50)
    let harmonic = |r: u32| -> bool {
        r > 0 && (r % 10 == 0 || r % 25 == 0 || r % 20 == 0)
    };
    if harmonic(post_residual) {
        score -= 15.0; // residual likely reusable by future items
    } else {
        score += 10.0; // awkward residual
    }

    // Dead-space penalty: small unusable residual relative to capacity
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly or well
            if next_item_size == post_residual {
                score -= 60.0;
            } else {
                score -= 20.0 * (next_item_size as f64 / post);
            }
        } else {
            // next item won't fit here: mild penalty proportional to gap
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly
        // and mean residual is small (open bins are nearly full)
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fits = (mean_residual - item_size as f64).max(0.0);
        score = 120.0 - poor_fits * 2.0 - (1.0 - progress) * 10.0;
        if post_residual == 0 {
            score = 50.0; // fresh bin keeps full flexibility
        }
        // discourage hoarding bins early
        score += open_bins_count as f64 * 3.0;
    }

    // Prefer tighter existing bins (smaller residual -> lower score)
    score += (bin_residual as f64 / cap) * 8.0;

    // Mild penalty for fragmenting many open bins
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps heavily.
    // A residual gap is "dead" if it cannot hold even the smallest plausible item (1..=20).
    if post_residual > 0 && post_residual < 20 {
        score += 60.0 + (20 - post_residual) as f64 * 2.0;
    }

    // Penalize gaps that cannot fit the next item (lookahead k=2), forcing a new bin later.
    if next_item_size > 0 && post_residual < next_item_size as f64 {
        score += 25.0 + (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // Reward tight fits: post_residual == 0 is perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // rather than spreading items out.
    score += open_bins_count as f64 * 1.5;

    // Slight reward for bins with residual below mean (denser bins).
    score -= (mean_residual - post_residual as f64) * 0.1;

    // Prefer bins whose residual is close to the item size (tight fit coupling).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
