            // Small residues (<10) are dead space; large residues are fine.
            if post_residual < 10 {
                score += 120.0;
            } else {
                score += 30.0 * (1.0 - post / 100.0);
            }
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 400.0;
    }

    // New-bin candidate handling: only open a new bin when existing bins
    // offer poor fits (large post_residual or too many already-open bins).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress
        // and how crowded the current bin set is.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 150.0 + 100.0 * (1.0 - progress);
        // If many bins are open and mean residual is large, discourage
        // adding another bin (existing slack should be used).
        if mean_residual > 40.0 && open_bins_count > 2 {
            score += 200.0;
        }
        // A new bin is attractive when the item is huge and would leave
        // an awkward small residue anywhere else.
        if item_size > bin_capacity * 9 / 10 {
            score -= 100.0;
        }
    }

    // Mild penalty for scattering across many open bins.
    score += open_bins_count as f64 * 2.0;

    // Prefer tighter bins in general (smaller residual before placement).
    score += 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small leftover space.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Penalize creating tiny dead space that nothing can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item cannot use the leftover; penalize wasting residual.
            score += 0.15 * (next_item_size as f64 - post_residual as f64).max(0.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Prefer fuller bins relative to the fleet average.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Slight preference for keeping number of open bins modest early on.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate handling: make opening a new bin only attractive when
    // the item is large and no bin fits well (high post-residual waste elsewhere).
    if bin_residual == bin_capacity {
        // Base penalty so new bins are used sparingly.
        score += 30.0 + 0.2 * open_bins_count as f64;
        // Reward opening a fresh bin for large items that would leave awkward gaps.
        if item_size as f64 > bin_capacity as f64 * 0.6 {
            score -= 35.0;
        }
        // Late in the stream, avoid opening bins (closing out the fleet).
        if progress > 0.8 {
            score += 50.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
