pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth polynomial coupling to stream progress.
    let mut score = pr * (1.0 + 0.5 * progress * norm_pr);

    // Quadratic dead-space penalty: residuals that are hard to fill later get penalized more.
    score += 8.0 * norm_pr * norm_pr * (0.5 + progress);

    // Lookahead: reward residuals that can host the next item smoothly.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let slack = (pr - n) / cap;
            score -= 12.0 * (1.0 - slack) * (1.0 - progress);
        } else {
            score += 6.0 * (n - pr) / cap;
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - norm_pr);
    }

    // Mild penalty when many bins are open and residual is large (fragmentation risk).
    score += 0.15 * open_bins_count as f64 * norm_pr;

    // Prefer bins whose residual deviates favorably from the mean (tighter than average).
    score -= (mean_residual - pr) * 0.1;

    // New-bin candidate: make empty bins mildly unattractive unless residual is huge.
    if bin_residual == bin_capacity {
        score += 25.0 - 15.0 * progress;
    }

    score
}

