        }
        if waste > 0.4 && pr > 0.0 && nx > 0.0 && pr < nx && progress > 0.6 {
            score += 4.0 * (waste - 0.4) * 10.0 * progress;
        }
        // Chain with sub-slack room late
        if nx > 0.0 && pr >= nx && (pr - nx) < 0.5 * nx && progress > 0.6 {
            score -= 2.8 * (1.0 - (pr - nx) / (0.5 * nx)) * progress;
