}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post-residual exactly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-chain
        } else if next_item_size <= post_residual {
            // partial lookahead fit: reward closeness
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize wasted residual, more so for large overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 0.4 * over;
        }
    } else {
        // last item: minimize post residual
        score += 5.0;
    }

    // Compare post_residual against mean residual: prefer bins that keep residual near mean
    let diff = post_residual as f64 - mean_residual;
    score += 0.15 * diff.abs();

    // Penalize very small unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 20.0; // perfect closure
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize unless item is huge or lookahead demands fresh space
    if bin_residual == bin_capacity {
        let base = 40.0 + 0.5 * item_size as f64;
        let lookahead_bonus = if next_item_size > 0 && next_item_size > bin_residual - item_size { 20.0 } else { 0.0 };
        score += base - lookahead_bonus;
        // early stream: more willing to open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // Slight penalty when many bins are open (encourage consolidation)
    score += 0.05 * open_bins_count as f64;

    score
}

