            }
        }
        if item_frac > 0.45 && item_frac < 0.75 && progress > 0.5 {
            nb -= 5.0 * (item_frac - 0.45) * progress;
        }
        if fitting_bins_count >= 2 && mean_residual < 0.25 * cap && progress > 0.6 {
            nb += 6.0 * (1.0 - mean_residual / (0.25 * cap)) * progress;
        }
        if fitting_bins_count >= 3 && mean_residual - it >= nx && progress > 0.5 {
            nb += 4.5 * progress * (1.0 - ((mean_residual - it - nx) / cap).min(1.0));
        }
        if open_bins_count > 10 && progress < 0.35 && item_frac < 0.3 {
            nb += 6.0 * (1.0 - progress) * (1.0 - item_frac / 0.3);
        }
        // penalize opening a bin whose first residual is a dead sliver
        if nx > 0.0 {
            let r1 = cap - it;
            if r1 < nx && r1 > 0.0 {
                nb += (1.0 + 2.6 * progress) * (nx - r1) * 0.7;
            }
            if r1 >= nx && (r1 - nx) > 0.25 * cap && progress > 0.45 {
                nb += 4.5 * ((r1 - nx) / cap).min(0.5) * progress;
            }
        }
        // fresh bin that chains it+nx tightly is attractive
        if nx > 0.0 && cap >= it + nx && (cap - it - nx) < 0.08 * cap && progress > 0.3 {
            nb -= 5.0 * (1.0 - (cap - it - nx) / (0.08 * cap)) * (0.5 + progress);
        }
        if open_bins_count > 6 && mean_residual > 0.4 * cap && progress < 0.6 {
            nb += 5.0 * ((mean_residual - 0.4 * cap) / cap) * (1.0 - progress) * ((open_bins_count as f64 - 6.0).min(8.0) / 8.0);
        }
        if item_frac < 0.15 && progress > 0.55 && fitting_bins_count >= 1 {
            nb += 6.0 * progress * (1.0 - item_frac / 0.15);
        }
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin < 0.15 * cap {
                nb -= 6.0 * (1.0 - margin / (0.15 * cap)) * (0.6 + 0.4 * progress);
            }
        }
        if nx > 0.0 && fitting_bins_count >= 1 && mean_residual - it >= nx {
            let leftover = mean_residual - it - nx;
            if leftover < 0.1 * cap && progress > 0.45 {
                nb -= 5.0 * (1.0 - leftover / (0.1 * cap)) * progress;
            }
        }
        if open_bins_count > 12 && progress > 0.6 && item_frac < 0.25 {
            nb += 5.0 * progress * (1.0 - item_frac / 0.25);
        }
        if nx > 0.0 && fitting_bins_count >= 1 && (cap - it) >= nx && (cap - it - nx) < 0.05 * cap && progress < 0.5 {
            nb -= 4.0 * (1.0 - (cap - it - nx) / (0.05 * cap)) * (1.0 - progress);
        }
        if fitting_bins_count >= 2 && mean_residual >= it + nx && progress > 0.4 {
            let rem = mean_residual - it - nx;
            if rem < 0.05 * cap {
                nb -= 4.5 * (1.0 - rem / (0.05 * cap)) * progress;
            }
        }
        if fitting_bins_count == 1 && mean_residual >= it && (mean_residual - it) < 0.04 * cap && progress > 0.3 {
            nb -= 3.0 * (1.0 - (mean_residual - it) / (0.04 * cap)) * (0.5 + progress);
        }
        if open_bins_count > 8 && mean_residual < 0.1 * cap && progress > 0.5 {
            nb -= 4.0 * (1.0 - mean_residual / (0.1 * cap)) * progress;
        }
        if fitting_bins_count >= 1 && mean_residual >= it && progress > 0.65 {
            let best_pr = (mean_residual - it).max(0.0);
            if best_pr > 0.0 && best_pr < 0.05 * cap {
                nb += 5.5 * (1.0 - best_pr / (0.05 * cap)) * progress;
            }
        }
        if nx > 0.0 && cap >= it + nx && cap - it - nx < 0.02 * cap && fitting_bins_count <= 3 {
            nb -= 3.5 * (1.0 - (cap - it - nx) / (0.02 * cap)) * (0.6 + progress);
        }
        if item_frac < 0.1 && progress > 0.7 && fitting_bins_count >= 2 {
            nb += 5.0 * progress;
        }
        if item_frac < 0.2 && nx > 0.0 && mean_residual >= it + nx && progress > 0.6 {
            nb -= 4.0 * (1.0 - item_frac / 0.2) * progress;
        }
        if nx > 0.0 && mean_residual < nx && progress > 0.55 && item_frac < 0.5 {
            nb += 3.5 * (nx - mean_residual).min(0.1 * cap) / (0.1 * cap) * progress;
        }
        // NEW: quadratic dead-ratio term — a fresh bin whose first residual
        // is a large unusable chunk should be strongly discouraged.
        let dead_ratio = (waste).max(0.0);
        let unusable = if nx > 0.0 && cap - it > 0.0 && cap - it < nx { 1.0 } else { 0.55 };
        nb += (9.0 + 2.8 * progress) * dead_ratio * dead_ratio * cap * (0.45 + progress) * unusable;
        // NEW: reward opening a fresh bin when the first residual is exactly
        // a small chainable slack (it+nx nearly fills the bin).
        if nx > 0.0 && cap >= it + nx && (cap - it - nx) < 0.04 * cap {
            nb -= 4.5 * (1.0 - (cap - it - nx) / (0.04 * cap)) * (0.7 + progress);
        }
        score = nb;
    } else {
        // Fine-grained residual fitting with lookahead anticipation
        let fill_ratio = 1.0 - res / cap;
        if waste < 0.08 {
            score -= 48.0 * (1.0 - progress) * (0.08 - waste);
        }
        if fill_ratio > 0.65 {
            score -= 4.8 * (fill_ratio - 0.65) * 10.0 * (0.4 + progress);
        }
        if nx > 0.0 && nx <= pr && pr > 0.0 {
            let gap = (pr - nx) / cap;
            if gap < 0.03 {
                score -= 7.5 * (1.0 - gap * 33.0);
            }
            if gap <= 0.04 {
                score -= 3.2 * (1.0 - gap / 0.04) * (1.0 - progress);
            }
            let chain = 1.0 - gap.min(1.0);
            score -= 5.0 + 4.0 * (nx / cap) + 9.5 * chain * (1.0 - progress);
            // extended chain-slack reward — mid-size slack after nx is
            // still useful space; reward moderately up to 0.18*cap.
            if gap > 0.04 && gap < 0.18 {
                score -= 2.6 * (1.0 - gap / 0.18) * (0.3 + progress);
            }
        }
        if pr > 0.0 && pr < 10.0 {
            score += 41.0 * (1.0 - 0.5 * progress);
        }
        if pr == 0.0 {
            score -= 62.0;
        } else if pr <= 5.0 {
            score -= 31.0 * (1.0 - 0.4 * progress);
        }
        if nx > 0.0 && pr > 0.0 && pr < nx {
            let gap = nx - pr;
            score += gap * (2.0 + 6.5 * (1.0 - progress));
            if gap <= 3.0 {
                score -= 9.0 * (1.0 - progress);
            }
            // sharpened dead-space penalty: residual just below next item
            let closeness = 1.0 - pr / nx;
            score += 3.6 * closeness * closeness * (0.6 + progress);
            // dead-sliver that can never chain with typical items
            if gap > 0.1 * cap && waste > 0.2 {
                score += 4.5 * (waste - 0.2) * 10.0 * (0.4 + progress);
            }
        }
        let dev = mean_residual - res;
        score += 0.085 * dev;
        if dev > -5.0 && dev < 15.0 && pr > 0.0 {
            score -= 4.2;
        }
        let tight_fit = (pr == 0.0) || (nx > 0.0 && pr == nx);
        if tight_fit {
            score -= 10.5 * (0.3 + progress);
        }
        if nx > 0.0 && pr >= nx {
            let room = pr - nx;
            if room < 0.06 * cap {
                score -= 6.5 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
            }
            // near-perfect double-fill lookahead
            if room < 0.02 * cap {
                score -= 4.0 * (1.0 - room / (0.02 * cap)) * (0.6 + progress);
            }
        }
        if waste > 0.14 && waste < 0.34 {
            score += 13.0 * (waste - 0.14) * (0.6 + 0.8 * progress);
        }
        if fitting_bins_count > 3 && waste < 0.12 {
            score -= 5.5 * (1.0 - waste * 8.0) * (0.5 + progress);
        }
        if nx > 0.0 && pr > 0.0 && pr > nx && (pr - nx) < 0.02 * cap {
            score -= 4.0 * (1.0 - (pr - nx) / (0.02 * cap)) * (0.4 + progress);
        }
        if pr > 0.0 && (pr as f64).sqrt() < 2.6 {
            score -= 3.5 * (1.0 - progress);
        }
        if waste > 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.09 * cap && progress > 0.4 {
            score -= 4.0 * (1.0 - (pr - nx) / (0.09 * cap)) * progress;
        }
        if pr > 0.0 && nx > 0.0 && pr < nx && (nx - pr) > 0.1 * cap && waste > 0.25 {
            score += 5.0 * (waste - 0.25) * 10.0 * (0.4 + progress);
        }
        if pr > 0.0 && nx > 0.0 && pr < 0.5 * nx && progress > 0.3 {
            score += 3.5 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
        }
        if waste > 0.3 && pr > nx && progress < 0.5 {
            score += 3.0 * (waste - 0.3) * 10.0 * (1.0 - progress);
        }
        if fill_ratio > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
            score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
        }
        if waste > 0.35 && progress > 0.55 && nx > 0.0 && pr >= nx {
            score -= 4.5 * ((pr - nx) / cap).min(0.2) * 5.0 * progress;
        }
        // NEW: residual that exactly fits the next item is a perfect chain
        if nx > 0.0 && pr > 0.0 && pr == nx {
            score -= 6.0 * (0.5 + progress);
        }
        // NEW: reward bins whose remaining space after this item still
        // accommodates the next item with tight slack, even at low fill.
        if nx > 0.0 && pr >= nx && (pr - nx) >= 0.06 * cap && (pr - nx) < 0.14 * cap && fill_ratio > 0.5 {
            score -= 3.0 * (1.0 - ((pr - nx) - 0.06 * cap) / (0.08 * cap)) * (0.4 + progress);
        }
        // NEW: penalize leaving a residual slightly above the next item that
        // wastes more than the item itself would cost elsewhere.
        if nx > 0.0 && pr > 0.0 && pr < nx && (nx - pr) < 0.06 * cap && waste > 0.12 {
            score += 3.2 * (1.0 - (nx - pr) / (0.06 * cap)) * (0.5 + progress);
        }
        // Scarcity: prefer using existing bins when few can fit
        if fitting_bins_count == 1 {
            score -= 14.0 + 12.0 * progress;
        } else if fitting_bins_count == 2 {
            score -= 4.0 + 3.0 * progress;
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportional waste relative to capacity.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 18.0 * tightness;

    // Strongly reward near-perfect fills (post_residual small).
    if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 10.0;
    }

    // Dead-space penalty: residual that is too small to fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 12.0;
        } else if next_item_size > post_residual as u32
            && next_item_size <= bin_capacity
            && post_residual > 0
            && post_residual < next_item_size
        {
            // Post residual becomes dead space relative to the next item; penalize mildly.
            score += 4.0;
        }
        // If next item is large, prefer conserving larger residuals for it.
        if next_item_size > 50 && post_residual < next_item_size as u32 {
            score += 5.0;
        }
    }

    // Global state: many open bins with slack -> prefer filling existing bins.
    if open_bins_count > 3 {
        score -= (open_bins_count as f64).ln() * 3.0;
    }

    // Prefer bins whose residual deviates favorably from the mean:
    // a bin with residual below mean is "hot" (close to full) -> fill it.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.15 * dev;

    // Time horizon: early in the stream, be more willing to open new bins;
    // late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus early-stream discount.
        let mut new_bin_score = 40.0 + 55.0 * (1.0 - progress);
        // Opening a bin is more attractive if current bins have poor fit potential.
        if post_residual == bin_capacity {
            if fitting_bins_count == 0 {
                new_bin_score -= 60.0; // no open bin fits: must open
            }
            if next_item_size > 0 && next_item_size > 60 {
                new_bin_score += 10.0; // large upcoming item: keep fresh bins available
            }
            if open_bins_count > 6 {
                new_bin_score += 15.0; // too many bins open already
            }
        }
        score = new_bin_score;
    } else {
        // Late stream: extra consolidation pressure.
        score -= 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;
    let nxt = next_item_size as f64;

    // Base: prefer tight fits (small post_residual), smooth quadratic coupling with progress.
    let mut score = post * (1.0 + 0.8 * progress) + 0.35 * post * post / cap;

    // Dead-space penalty: residual that can't hold the lookahead item (smooth sigmoid-ish coupling).
    if nxt > 0.0 {
        let gap = (nxt - post).max(0.0);
        score += 4.0 * gap * gap / cap * (1.0 + progress);
        // Reward when post_residual still fits the next item exactly-ish.
        let fit_slack = (post - nxt).max(0.0);
        score -= 1.5 * (1.0 - fit_slack / cap).max(0.0) * (post / cap);
    }

    // Last-chance bonus: sole fitting bin should be strongly favored.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0 + 4.0 * progress;
    }

    // Penalize scattering across many open bins; encourage consolidation.
    score += 0.4 * open_bins_count as f64 * (post / cap);

    // Slight pull toward bins near the mean residual (smooth balancing term).
    score += 0.5 * (post - mean_residual).abs() / cap;

    // New-bin candidate: only attractive when it beats poor fits; make it moderately costly.
    if bin_residual == bin_capacity {
        score = cap * (1.1 + 0.5 * progress) + 0.5 * open_bins_count as f64;
        if nxt > 0.0 && nxt >= item_size as f64 {
            score -= 3.0; // pair-friendly opening
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any future item (1..10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }
    // Penalize awkward mid-range gaps that few item sizes can use.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Perfect or near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 - slack * 0.2;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this bin's remainder; mild penalty for stranding space.
        score += (next_item_size - post_residual) as f64 * 0.05;
    }

    // Pressure to close bins: more open bins -> prefer filling existing ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.6 * (0.5 + progress);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate (empty bin): baseline so it is chosen only when all
    // open-bin options score poorly (poor fits / heavy dead space).
    if bin_residual == bin_capacity {
        score = 90.0 + open_bins_count as f64 * 0.3 - progress * 10.0;
        // If no open bin fits at all, opening is clearly right.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild attraction toward bins tighter than average (best-fit flavor).
    score -= (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward if the next item exactly fills the post residual (perfect 2-step match)
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item still fits: mild reward proportional to tightness
        score -= 12.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > 0 {
        // Next item won't fit: penalize dead space creation
        score += 8.0 + 0.3 * (next_item_size as f64 - post_residual as f64);
    }

    // Reward tight fits relative to mean residual of open bins
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.4 * (mean_residual - pr);
    } else {
        score += 0.2 * (pr - mean_residual);
    }

    // Last-chance bonus: if this is the only bin that can fit, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when reasonable open bins exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + 20.0 * progress;
        if open_bins_count > 0 && item_size <= bin_residual / 2 {
            score += 10.0;
        }
    }

    // Small waste penalty (quadratic in leftover)
    score += 0.02 * pr * pr / 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
