            score += 2.8 * (waste - 0.22) * 10.0 * progress;
        }
        if waste > 0.5 && pr > 0.0 && nx > 0.0 && pr >= nx && progress > 0.7 {
            score -= 2.4 * ((pr - nx) / cap).min(0.25) * 4.0 * progress;
        }
        if nx > 0.0 && pr > nx && (pr - nx) > 0.3 * cap && progress > 0.6 && fitting_bins_count >= 2 {
            score -= 2.5 * ((pr - nx) / cap).min(0.4) * progress;
        }
        if waste > 0.1 && waste < 0.3 && pr > 0.0 && nx > 0.0 && pr >= nx && (pr - nx) > 0.05 * cap && (pr - nx) < 0.15 * cap && progress > 0.2 {
            score -= 2.4 * (1.0 - ((pr - nx) - 0.05 * cap) / (0.10 * cap)) * (0.4 + progress);
        }
        // MUTATION: mild bonus for being the last fitting bin (avoid new bins)
        if fitting_bins_count == 1 {
            score -= 3.0 * (1.0 + progress);
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space that is a multiple of common
    // item sizes (mod classes 10/20/25/50) is more likely reusable later.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -30.0 // perfect fit is ideal
    } else if pr % 50 == 0 {
        -12.0
    } else if pr % 25 == 0 {
        -7.0
    } else if pr % 20 == 0 {
        -5.0
    } else if pr % 10 == 0 {
        -3.0
    } else if pr < 10 {
        15.0 // tiny unusable sliver -> dead space penalty
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            // next item fits, but check leftover quality
            let nxt_left = pr - next_item_size;
            score -= 8.0 - (nxt_left % 10) as f64;
        } else {
            // next item won't fit here: penalize slightly more for larger overshoot class
            let overshoot = (next_item_size - pr) % 30;
            score += overshoot as f64 * 0.4;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + (bin_residual - item_size) as f64 * 0.05;
    }

    // New-bin candidate handling: empty bin should only win when open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowdedness = open_bins_count as f64 / (mean_residual / cap).max(0.05);
        score += 18.0 + crowdedness * 0.5 - progress * 4.0;
    } else {
        // Prefer bins tighter than the mean residual (best-fit-like gradient).
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.15;
    }

    // Integer-division threshold on residual fraction: residual in [1..25%] of cap
    // is near-dead space; penalize leaving it.
    let quarter = bin_capacity / 4;
    if post_residual > 0 && post_residual <= quarter {
        score += (quarter - post_residual + 1) as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
