        if nx > 0.0 && pr > 0.0 && pr > nx && (pr - nx) < 0.02 * cap {
            score -= 4.0 * (1.0 - (pr - nx) / (0.02 * cap)) * (0.4 + progress);
        }
        if pr > 0.0 && (pr as f64).sqrt() < 2.6 {
            score -= 3.5 * (1.0 - progress);
        }
        if waste > 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.09 * cap && progress > 0.4 {
            score -= 4.0 * (1.0 - (pr - nx) / (0.09 * cap)) * progress;
        }
        if pr > 0.0 && nx > 0.0 && pr < nx && (nx - pr) > 0.1 * cap && waste > 0.25 {
            score += 5.0 * (waste - 0.25) * 10.0 * (0.4 + progress);
        }
        if pr > 0.0 && nx > 0.0 && pr < 0.5 * nx && progress > 0.3 {
            score += 3.5 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
        }
        if waste > 0.3 && pr > nx && progress < 0.5 {
            score += 3.0 * (waste - 0.3) * 10.0 * (1.0 - progress);
        }
        if fill_ratio > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
            score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
        }
        if waste > 0.35 && progress > 0.55 && nx > 0.0 && pr >= nx {
            score -= 4.5 * ((pr - nx) / cap).min(0.2) * 5.0 * progress;
        }
        // Scarcity: prefer using existing bins when few can fit
        if fitting_bins_count == 1 {
            score -= 14.0 + 12.0 * progress;
        } else if fitting_bins_count == 2 {
            score -= 4.0 + 3.0 * progress;
        }
        // NEW: reward bins whose residual after placement still fits the
        // next item with mid-range slack (usable leftover, not dead space)
        if nx > 0.0 && pr >= nx && (pr - nx) > 0.06 * cap && (pr - nx) < 0.22 * cap && fitting_bins_count <= 2 {
            score -= 2.0 * (1.0 - ((pr - nx) / (0.22 * cap))) * (0.6 + progress);
        }
        // NEW: penalize leaving a residual that is neither reusable by nx
        // nor near-empty — a "stranded middle" residual
        if nx > 0.0 && pr > 0.0 && pr < nx && (nx - pr) > 0.04 * cap && waste > 0.15 {
            score += 3.2 * (1.0 - (nx - pr) / (0.25 * cap)).max(0.0) * (0.4 + progress);
        }
        // NEW: strong preference for bins that finish exactly (pr == 0)
        // late in the stream when alternatives are plentiful
        if pr == 0.0 && progress > 0.5 && fitting_bins_count >= 2 {
            score -= 8.0 * progress;
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize "dead space": small unusable gaps after placement.
    if post_residual > 0 {
        let dead_threshold = 15.0f64;
        if (post_residual as f64) < dead_threshold {
            // The smaller the leftover below the threshold, the worse it is.
            score += (dead_threshold - post_residual as f64) * 6.0;
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward fits that leave exactly enough room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 25.0;
    }
    // Penalize if the lookahead item cannot fit in this residual but might elsewhere.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into existing bins
    // (a new empty bin gets residual == capacity, so it needs a penalty to compete).
    if bin_residual == bin_capacity {
        score += 20.0 + (open_bins_count as f64) * 0.5;
        // But late in the stream, avoid opening bins needlessly.
        if step_index as f64 / total_items as f64 > 0.8 {
            score += 30.0;
        }
    }

    // Slight preference for bins below mean residual (tighter packing).
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core fit quality: reward tight fits (small post_residual)
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 40.0 * tightness * tightness;

    // 2-step lookahead: reward if next item fits into post_residual (perfect chain)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let leftover2 = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - leftover2 / bin_capacity as f64);
        } else {
            // next item won't fit: penalize dead space relative to next item size
            score += 0.5 * (next_item_size as f64).min(post_residual as f64);
            score += 8.0;
        }
    }

    // Relative-to-mean residual coupling: prefer bins with residual near mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize creating very small unusable slivers (dead space < 10)
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }

    // Early stream: mild preference to consolidate into few bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: default mild penalty so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 18.0;
        // but if next item is large and this item leaves a good complement, allow opening
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // Core: prefer tight fits; penalize leaving awkward gaps.
    let waste = post_residual as f64;
    score += 0.5 * waste;

    // Dead-space penalty: gaps too small for the smallest plausible item (1..100, so any gap < next_item is suspect).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 3.0 * (next_item_size - post_residual) as f64;
    }

    // Lookahead synergy: reward leaving exactly room for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        score -= 2.0 * (post_residual - next_item_size).min(20) as f64 * 0.25;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // New-bin candidate handling.
    if is_new_bin {
        // Base penalty: opening new bins is expensive.
        let mut nb = 40.0 + 2.0 * open_bins_count as f64;
        // Late in the stream, consolidating is better.
        nb += 30.0 * progress;
        // If other bins fit, only open a new bin when the item is huge (would leave tiny waste in a fresh bin)
        // and existing residuals are fragmented.
        if fitting_bins_count > 0 {
            let tightness = item_size as f64 / bin_capacity as f64;
            if tightness > 0.85 {
                nb -= 45.0; // near-perfect fresh fit is great
            }
            // Fragmentation pressure: many open bins with high mean residual -> prefer reusing.
            nb += (mean_residual - 50.0).max(0.0) * 0.6;
            // If existing bins would leave large waste, opening new is more attractive.
            nb -= 0.3 * (post_residual as f64); // post_residual == 0 for new bin call, so this is 0
        } else {
            // No bin fits: must open new bin.
            nb = -100.0;
        }
        score += nb;
    } else {
        // Prefer filling fuller bins when many bins are open.
        score -= (bin_residual as f64) * 0.05;
        // Slight preference for bins below mean residual (balance load).
        score += (mean_residual - bin_residual as f64) * 0.02;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
