    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, larger residuals are acceptable; late, penalize them quadratically.
    let norm_pr = pr / cap;
    score += progress * 12.0 * norm_pr * norm_pr * cap * 0.1;

    // Smooth interaction: dead-space penalty grows with (1 - progress) complement too,
    // favoring tight packing mid-stream via cubic term.
    score -= 4.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress * (1.0 - progress);

    // Last-chance bonus: strongly reward using a bin when few can fit.
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // Lookahead: reward leaving residual close to next item size (smooth quadratic).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 2.5 * (1.0 - gap / cap).max(0.0) * (1.0 - gap / cap);
    }

    // Prefer using bins whose residual deviates from mean (consolidate space).
    score += 0.3 * ((bin_residual as f64 - mean_residual).abs() / cap);

    // Mildly discourage opening new bins as stream progresses.
    if bin_residual == bin_capacity {
        score += 1.0 + 5.0 * progress - 0.05 * open_bins_count as f64;
    }

    score
}

