            nb += 5.0 * ((mean_residual - 0.4 * cap) / cap) * (1.0 - progress) * ((open_bins_count as f64 - 6.0).min(8.0) / 8.0);
        }
        if item_frac < 0.15 && progress > 0.55 && fitting_bins_count >= 1 {
            nb += 6.0 * progress * (1.0 - item_frac / 0.15);
        }
        if nx > 0.0 && cap - it > 0.0 && cap - it < nx {
            nb += 4.5 * (1.0 - progress) * ((nx - (cap - it)) / cap).min(0.3) * 10.0;
        }
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin < 0.15 * cap {
                nb -= 6.0 * (1.0 - margin / (0.15 * cap)) * (0.6 + 0.4 * progress);
            }
        }
        if nx > 0.0 && fitting_bins_count >= 1 && mean_residual - it >= nx {
            let leftover = mean_residual - it - nx;
            if leftover < 0.1 * cap && progress > 0.45 {
                nb -= 5.0 * (1.0 - leftover / (0.1 * cap)) * progress;
            }
        }
        if nx > 0.0 && fitting_bins_count >= 2 && mean_residual > 0.5 * cap && progress < 0.4 {
            nb += 4.5 * ((mean_residual - 0.5 * cap) / cap) * (1.0 - progress);
        }
        if open_bins_count > 12 && progress > 0.6 && item_frac < 0.25 {
            nb += 5.0 * progress * (1.0 - item_frac / 0.25);
        }
        if nx > 0.0 && fitting_bins_count >= 1 && (cap - it) >= nx && (cap - it - nx) < 0.05 * cap && progress < 0.5 {
            nb -= 4.0 * (1.0 - (cap - it - nx) / (0.05 * cap)) * (1.0 - progress);
        }
        if nx > 0.0 && (cap - it).max(0.0) < nx && fitting_bins_count <= 1 && mean_residual < 0.3 * cap {
            nb += 3.5 * (1.0 - mean_residual / (0.3 * cap)) * (0.5 + progress);
        }
        if fitting_bins_count >= 2 && mean_residual >= it + nx && progress > 0.4 {
            let rem = mean_residual - it - nx;
            if rem < 0.05 * cap {
                nb -= 4.5 * (1.0 - rem / (0.05 * cap)) * progress;
            }
        }
        if fitting_bins_count == 1 && mean_residual >= it && (mean_residual - it) < 0.04 * cap && progress > 0.3 {
            nb -= 3.0 * (1.0 - (mean_residual - it) / (0.04 * cap)) * (0.5 + progress);
        }
        if open_bins_count > 8 && mean_residual < 0.1 * cap && progress > 0.5 {
            nb -= 4.0 * (1.0 - mean_residual / (0.1 * cap)) * progress;
        }
        if fitting_bins_count >= 1 && mean_residual >= it && progress > 0.65 {
            let best_pr = (mean_residual - it).max(0.0);
            if best_pr > 0.0 && best_pr < 0.05 * cap {
                nb += 5.5 * (1.0 - best_pr / (0.05 * cap)) * progress;
            }
        }
        if nx > 0.0 && mean_residual >= it + nx && progress > 0.55 {
            let rem = mean_residual - it - nx;
            if rem > 0.2 * cap {
                nb += 3.5 * ((rem - 0.2 * cap) / cap).min(0.3) * 10.0 * progress;
            }
        }
        if nx > 0.0 && cap >= it + nx && cap - it - nx < 0.02 * cap && fitting_bins_count <= 3 {
            nb -= 3.5 * (1.0 - (cap - it - nx) / (0.02 * cap)) * (0.6 + progress);
        }
        if open_bins_count > 14 && mean_residual > 0.55 * cap && progress > 0.5 {
            nb += 4.0 * ((mean_residual - 0.55 * cap) / cap).min(0.3) * 10.0 * progress;
        }
        if item_frac < 0.1 && progress > 0.7 && fitting_bins_count >= 2 {
            nb += 5.0 * progress;
        }
        if nx > 0.0 && fitting_bins_count >= 1 && mean_residual >= it + nx && progress > 0.7 {
            let rem = mean_residual - it - nx;
            if rem < 0.03 * cap {
                nb -= 3.2 * (1.0 - rem / (0.03 * cap)) * progress;
            }
        }
        if item_frac < 0.2 && nx > 0.0 && mean_residual >= it + nx && progress > 0.6 {
            nb -= 4.0 * (1.0 - item_frac / 0.2) * progress;
        }
        if nx > 0.0 && mean_residual < nx && progress > 0.55 && item_frac < 0.5 {
            nb += 3.5 * (nx - mean_residual).min(0.1 * cap) / (0.1 * cap) * progress;
        }
        if nx > 0.0 && fitting_bins_count >= 1 && mean_residual - it >= nx && (mean_residual - it - nx) < 0.04 * cap && progress > 0.35 {
            nb -= 4.2 * (1.0 - (mean_residual - it - nx) / (0.04 * cap)) * (0.5 + progress);
        }
        if open_bins_count > 5 && progress > 0.3 && item_frac > 0.55 {
            nb -= 3.5 * (item_frac - 0.55) * 2.0 * progress;
        }
        if nx > 0.0 && mean_residual > 0.6 * cap && progress < 0.5 && fitting_bins_count >= 3 {
            nb += 4.0 * ((mean_residual - 0.6 * cap) / cap).min(0.3) * 10.0 * (1.0 - progress);
        }
        if nx > 0.0 && cap >= it + nx && (cap - it - nx) < 0.07 * cap && progress < 0.5 {
            nb -= 4.5 * (1.0 - (cap - it - nx) / (0.07 * cap)) * (1.0 - progress);
        }
        if nx > 0.0 && item_frac + (nx / cap) > 1.0 && fitting_bins_count >= 1 && mean_residual >= nx && progress > 0.5 {
            nb -= 3.0 * (1.0 - mean_residual / (0.5 * cap)) * progress;
        }
        if nx > 0.0 && fitting_bins_count >= 1 && mean_residual - it >= nx && (mean_residual - it - nx) < 0.04 * cap && progress > 0.35 {
            nb -= 4.2 * (1.0 - (mean_residual - it - nx) / (0.04 * cap)) * (0.5 + progress);
        }
        score = nb;
    } else {
        // ---- open-bin candidate logic ----
        let fill_ratio = 1.0 - bin_residual as f64 / cap;
        let waste = pr / cap;
        if waste < 0.08 {
            score -= 48.0 * (1.0 - progress) * (0.08 - waste);
        }
        if fill_ratio > 0.65 {
            score -= 4.8 * (fill_ratio - 0.65) * 10.0 * (0.4 + progress);
        }
        if nx > 0.0 && nx <= pr && pr > 0.0 {
            let gap = (pr - nx) / cap;
            if gap < 0.03 {
                score -= 7.5 * (1.0 - gap * 33.0);
            }
        }
        if pr > 0.0 && pr < 10.0 {
            score += 41.0 * (1.0 - 0.5 * progress);
        }
        if pr == 0.0 {
            score -= 62.0;
        } else if pr <= 5.0 {
            score -= 31.0 * (1.0 - 0.4 * progress);
        }
        if nx > 0.0 && pr > 0.0 && pr < nx {
            score += 6.5 + 2.2 * progress;
            if nx - pr <= 3.0 {
                score -= 9.0 * (1.0 - progress);
            }
        }
        let dev = mean_residual - bin_residual as f64;
        score += 0.085 * dev;
        if dev > -5.0 && dev < 15.0 && pr > 0.0 {
            score -= 4.2;
        }
        let tight_fit = (pr == 0.0) || (nx > 0.0 && pr == nx);
        if tight_fit {
            score -= 10.5 * (0.3 + progress);
        }
        if nx > 0.0 && pr >= nx {
            let room = pr - nx;
            if room < 0.06 * cap {
                score -= 6.5 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if waste > 0.14 && waste < 0.34 {
            score += 13.0 * (waste - 0.14) * (0.6 + 0.8 * progress);
        }
        if fitting_bins_count > 3 && waste < 0.12 {
            score -= 5.5 * (1.0 - waste * 8.0) * (0.5 + progress);
        }
        if nx > 0.0 && pr > 0.0 && pr > nx && (pr - nx) < 0.02 * cap {
            score -= 4.0 * (1.0 - (pr - nx) / (0.02 * cap)) * (0.4 + progress);
        }
        if pr > 0.0 && (pr as f64).sqrt() < 2.6 {
            score -= 3.5 * (1.0 - progress);
        }
        if waste > 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.09 * cap && progress > 0.4 {
            score -= 4.0 * (1.0 - (pr - nx) / (0.09 * cap)) * progress;
        }
        if pr > 0.0 && nx > 0.0 && pr < nx && (nx - pr) > 0.1 * cap && waste > 0.25 {
            score += 5.0 * (waste - 0.25) * 10.0 * (0.4 + progress);
        }
        if pr > 0.0 && nx > 0.0 && pr < 0.5 * nx && progress > 0.3 {
            score += 3.5 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
        }
        if waste > 0.3 && pr > nx && progress < 0.5 {
            score += 3.0 * (waste - 0.3) * 10.0 * (1.0 - progress);
        }
        if fill_ratio > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
            score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
        }
        if waste > 0.35 && progress > 0.55 && nx > 0.0 && pr >= nx {
            score -= 4.5 * ((pr - nx) / cap).min(0.2) * 5.0 * progress;
        }
        if nx > 0.0 && pr > 0.0 && pr < nx {
            let closeness = 1.0 - pr / nx;
            score += 3.0 * closeness * closeness * (0.6 + progress);
        }
        if nx > 0.0 && pr > nx && (pr - nx) <= 0.04 * cap {
            score -= 3.2 * (1.0 - (pr - nx) / (0.04 * cap)) * (1.0 - progress);
        }
        if nx > 0.0 && pr > nx && (pr - nx) > 0.04 * cap && (pr - nx) < 0.18 * cap {
            score -= 2.2 * (1.0 - ((pr - nx) / (0.18 * cap))) * (0.3 + progress);
        }
        if pr > 0.0 && it > 0.0 && pr < it * 0.5 && waste > 0.05 {
            score += 2.5 * (1.0 - pr / (it * 0.5)) * (0.4 + progress);
        }
        if waste > 0.18 && waste < 0.4 && nx > 0.0 && pr >= nx && (pr - nx) < 0.12 * cap {
            score += 3.0 * (1.0 - (pr - nx) / (0.12 * cap)) * (0.5 + progress);
        }
        if waste > 0.28 && fitting_bins_count > 2 && progress > 0.5 {
            score += 3.5 * (waste - 0.28) * 10.0 * progress;
        }
        if waste > 0.4 && pr > 0.0 && nx > 0.0 && pr < nx && progress > 0.6 {
            score += 4.0 * (waste - 0.4) * 10.0 * progress;
        }
        if pr > 0.0 && nx > 0.0 && pr >= nx && (pr - nx) < 0.5 * nx && progress > 0.6 {
            score -= 2.8 * (1.0 - (pr - nx) / (0.5 * nx)) * progress;
        }
        if nx > 0.0 && pr >= nx && (pr - nx) > 0.06 * cap && (pr - nx) < 0.22 * cap && fitting_bins_count <= 2 {
            score -= 2.0 * (1.0 - ((pr - nx) / (0.22 * cap))) * (0.6 + progress);
        }
        if waste > 0.05 && waste < 0.14 && pr >= nx && progress > 0.5 {
            score -= 2.4 * (1.0 - (waste - 0.05) / 0.09) * progress;
        }
        if waste > 0.12 && waste < 0.3 && nx > 0.0 && pr >= nx && (pr - nx) >= 0.12 * cap {
            score += 2.2 * ((pr - nx) / cap) * (0.4 + progress);
        }
        if fill_ratio > 0.92 && pr > 0.0 {
            score -= 2.0 * (fill_ratio - 0.92) * 10.0 * (0.5 + progress);
        }
        if waste > 0.45 && pr >= nx && nx > 0.0 && progress > 0.65 {
            score -= 3.0 * (waste - 0.45) * 10.0 * progress;
        }
        if nx > 0.0 && pr > nx && (pr - nx) > 0.22 * cap && progress > 0.3 {
            score -= 1.8 * ((pr - nx) / cap).min(0.35) * (0.5 + progress);
        }
        if waste > 0.06 && waste < 0.16 && nx > 0.0 && pr >= nx && (pr - nx) < 0.04 * cap && progress > 0.55 {
            score -= 2.6 * (1.0 - (pr - nx) / (0.04 * cap)) * progress;
        }
        if waste > 0.08 && waste < 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.07 * cap && progress > 0.35 {
            score -= 2.9 * (1.0 - (pr - nx) / (0.07 * cap)) * (0.5 + progress);
        }
        if waste > 0.22 && fitting_bins_count <= 1 && progress > 0.5 {
            score += 2.8 * (waste - 0.22) * 10.0 * progress;
        }
        if waste > 0.5 && pr > 0.0 && nx > 0.0 && pr >= nx && progress > 0.7 {
            score -= 2.4 * ((pr - nx) / cap).min(0.25) * 4.0 * progress;
        }
        if nx > 0.0 && pr > nx && (pr - nx) > 0.3 * cap && progress > 0.6 && fitting_bins_count >= 2 {
            score -= 2.5 * ((pr - nx) / cap).min(0.4) * progress;
        }
        if waste > 0.1 && waste < 0.3 && pr > 0.0 && nx > 0.0 && pr >= nx && (pr - nx) > 0.05 * cap && (pr - nx) < 0.15 * cap && progress > 0.2 {
            score -= 2.4 * (1.0 - ((pr - nx) - 0.05 * cap) / (0.10 * cap)) * (0.4 + progress);
        }
        // last-chance bin: mild extra reward when only one bin fits
        if fitting_bins_count == 1 && waste < 0.3 {
            score -= 5.0 * (1.0 - waste / 0.3) * (0.3 + progress);
        }
        // slight pressure to prefer bins with fewer open competitors
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in low classes is more wasteful.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Penalize post_residuals that fall into "unusable" classes (small leftovers).
    let class = post_residual % 10;
    if post_residual > 0 {
        score += (10 - class) as f64 * 0.8; // lower class (smaller leftover) -> bigger penalty
    }

    // Reward tight fits (post_residual near zero) strongly.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual <= 10 {
        score -= 7.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 12.0 * (1.0 - slack as f64 / cap);
        } else {
            // next item won't fit here; leftover likely dead space
            score += post as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer fuller bins when many bins are open (compaction pressure).
    let fill_ratio = 1.0 - post / cap;
    score -= fill_ratio * open_bins_count as f64 * 0.5;

    // Mean-residual coupling: if this bin's residual is far below mean, it's an outlier;
    // placing here keeps the distribution of residuals tidy.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // New-bin candidate handling: only prefer a fresh bin when current bins fit poorly
    // (large item, high post_residual would result elsewhere) and stream is early enough.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = cap * 0.9;
        // Cheaper to open a new bin early in the stream or when few bins are open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 15.0;
        score -= open_bins_count as f64 * 0.3;
        // If item is large, a fresh bin guarantees a good post_residual.
        if item_size >= 50 {
            score -= 10.0;
        }
        // If next item is large too, fresh bin is attractive.
        if next_item_size >= 50 {
            score -= 8.0;
        }
        // If the only fitting bin is this new one, it's forced anyway.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Integer-division threshold on post_residual: leftovers in (0,10) are near-dead.
    if post_residual > 0 && post_residual / 10 == 0 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;

    // NEW-BIN CANDIDATE: decide when a fresh bin beats a poor fit.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let item_frac = (it / cap).min(1.0);
        let mut nb = cap * (1.30 + 1.10 * progress);
        nb -= 24.0 * scarcity * (1.0 - progress);
        nb -= 18.0 * item_frac * (1.0 - progress);
        // If next item pairs perfectly after this one in a fresh bin, prefer opening.
        if nx > 0.0 {
            let r1 = cap - it;
            if r1 >= nx && (r1 - nx) < 5.0 {
                nb -= 12.0 * (1.0 - (r1 - nx) / 5.0) * (0.5 + progress);
            }
            if r1 < nx && r1 > 0.0 {
                nb += (1.0 + 2.5 * progress) * (nx - r1) * 0.6;
            }
        }
        // Big item: always welcome in a fresh bin.
        if it >= 0.85 * cap {
            nb -= 30.0 + 10.0 * progress;
        }
        // Scarcity of fitting bins: strongly prefer opening when nothing fits well.
        if fitting_bins_count == 0 {
            nb -= 25.0 + 15.0 * progress;
        } else if fitting_bins_count <= 2 {
            nb += 18.0 + 9.0 * (1.0 - progress);
        } else if fitting_bins_count >= 4 {
            nb -= 7.0 + 8.0 * progress;
        }
        // If mean residual suggests existing bins are roomy, keep using them.
        if mean_residual >= it + nx && nx > 0.0 && progress < 0.6 {
            nb -= 6.0 * (1.0 - progress);
        }
        if mean_residual >= it && progress > 0.5 {
            nb += 5.0 + 8.0 * progress;
        }
        if progress > 0.75 && mean_residual < 0.2 * cap {
            nb += 6.5 * progress;
        }
        return nb;
    }

    let mut score = pr * (1.0 + 0.03 * (pr / cap) * (pr / cap));

    // Tightness pressure grows over the stream: late items must pack tighter.
    let tightness = 1.0 + 2.4 * progress * progress + 2.2 * progress * progress * progress;
    score *= tightness;

    // Lookahead k=2: penalize residuals that can't hold the next item.
    if nx > 0.0 {
        if pr < nx {
            let gap = nx - pr;
            score += gap * (2.0 + 6.0 * (1.0 - progress));
        } else {
            let chain_gap = pr - nx;
            let slack = chain_gap / cap;
            if chain_gap <= 42.0 {
                score -= 6.0 + 0.11 * chain_gap;
            }
            if slack < 0.04 {
                score -= 8.0 * (1.0 - slack * 25.0) * (1.0 + progress);
            }
            let chain = 1.0 - slack.min(1.0);
            score -= 4.5 + 4.0 * (nx / cap) + 9.0 * chain * (1.0 - progress);
        }
    }

    // Dead-space avoidance: small unusable gaps.
    if pr > 0.0 && pr < 20.0 {
        score += (55.0 + (20.0 - pr) * 2.0) * (0.6 + 0.4 * progress);
    }

    // Perfect / near-perfect fills.
    if pr == 0.0 {
        score -= 95.0 + 20.0 * progress;
    } else if pr <= 5.0 {
        score -= 28.0 * (1.0 - 0.4 * progress);
    }

    // Waste-ratio shaping: small waste rewarded, mid waste penalized.
    let waste = pr / cap;
    if waste > 0.0 && waste < 0.12 {
        score -= 9.0 * (1.0 - waste / 0.12) * (0.4 + progress);
    }
    if waste > 0.2 && waste < 0.4 {
        score += 12.0 * (waste - 0.2) * (0.6 + 0.8 * progress);
    }

    // Last-chance bonus: sole fitting bin should absorb the item.
    if fitting_bins_count == 1 {
        score -= 38.0 + 12.0 * progress;
    } else if fitting_bins_count == 2 && waste < 0.15 {
        score -= 10.0 * (1.0 - waste / 0.15) * (0.5 + progress);
    }

    // Open-bin pressure: consolidate when many bins are open.
    score += 1.5 * open_bins_count as f64;

    // Density coupling: prefer bins below mean residual.
    let dev = mean_residual - res;
    score += 0.1 * dev;
    if dev > -5.0 && dev < 15.0 && pr > 0.0 {
        score -= 4.0;
    }

    // Tight-fit coupling with item size.
    let tight = (res - it).abs();
    score += tight * 0.05;

    // Exact-fit lookahead: if this bin's post-residual exactly matches next item.
    if nx > 0.0 && pr == nx {
        score -= 11.0 * (0.3 + progress);
    }
    if nx > 0.0 && pr > nx && (pr - nx) <= 0.04 * cap {
        score -= 3.5 * (1.0 - (pr - nx) / (0.04 * cap)) * (0.5 + progress);
    }

    score -= 0.4 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1..100 range)
    // are considered unusable dead space; penalize them super-linearly.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // perfect fit, huge reward
    } else if post_residual < 10 {
        // Small gap: unlikely to be filled by future items -> dead space penalty
        score += (10 - post_residual) as f64 * 6.0;
    } else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 2.0;
    }

    // Reward tight fits: fraction of bin used by this placement
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 15.0;

    // Open-bin pressure: prefer filling existing bins over opening new ones
    // when this bin is a good fit; penalize spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: make an empty bin unattractive unless
    // no open bin offers a reasonable fit (post_residual here == capacity - item).
    if bin_residual == bin_capacity {
        score += 8.0 + mean_residual * 0.15;
        // If item is large relative to mean residual, new bin is more acceptable
        if (item_size as f64) > mean_residual {
            score -= 6.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 3.0;
        } else {
            // next item cannot use this gap -> mild dead-space penalty
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Late in the stream, consolidation matters more: tighten bin selection.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    // Mean residual coupling: prefer bins close to the mean residual
    // (balanced packing) with a gentle pull.
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;
    let mut score = pr * (1.0 + 0.03 * (pr / cap) * (pr / cap));

    // Progress-driven tightness
    let tightness = 1.0 + 2.5 * progress * progress + 2.3 * progress * progress * progress;
    score *= tightness;

    // Lookahead: penalize bins that can't host the next item, reward chained fits
    if nx > 0.0 {
        if pr < nx {
            let gap = nx - pr;
            score += gap * (2.0 + 6.2 * (1.0 - progress));
            // near-miss: this bin becomes useless for the next item but barely
            if gap <= 0.04 * cap {
                score += 3.0 * (1.0 - gap / (0.04 * cap)) * (0.5 + progress);
            }
        } else {
            let chain_gap = pr - nx;
            let slack = chain_gap / cap;
            if chain_gap <= 41.0 {
                score -= 6.2 + 0.105 * chain_gap;
            }
            if slack < 0.04 {
                score -= 8.2 * (1.0 - slack * 25.0) * (1.0 + progress);
            }
            let chain = 1.0 - slack.min(1.0);
            score -= 5.0 + 4.0 * (nx / cap) + 9.2 * chain * (1.0 - progress);
        }
    }

    // Dead-space penalty (quadratic, progress-coupled), weighted by next-item usability
    let dead_ratio = (pr / cap).max(0.0);
    let unusable = if nx > 0.0 && pr > 0.0 && pr < nx { 1.0 } else { 0.55 };
    score += (10.2 + 3.0 * progress) * dead_ratio * dead_ratio * cap * (0.45 + progress) * unusable;
    // Mid-range residual penalty for dead space control
    if dead_ratio > 0.25 && dead_ratio < 0.6 {
        score += 4.5 * (dead_ratio - 0.25) * (0.5 + progress);
    }
    // Reward very small dead space
    if dead_ratio > 0.0 && dead_ratio < 0.12 {
        score -= 8.5 * (1.0 - dead_ratio / 0.12) * (0.4 + progress);
    }

    // Scarcity handling
    if fitting_bins_count == 1 {
        score -= 14.0 + 12.0 * progress;
    } else if fitting_bins_count == 2 {
        score -= 4.0 + 3.0 * progress;
    }

    // NEW-BIN CANDIDATE scoring
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let item_frac = (it / cap).min(1.0);
        let mut nb = cap * (1.35 + 1.12 * progress);
        nb -= 26.0 * scarcity * (1.0 - progress);
        nb -= 18.5 * item_frac * (1.0 - progress);
        if nx >= 0.5 * cap {
            nb -= 12.0 * progress + 6.0 * (1.0 - progress);
        }
        nb += 15.0 * progress * (1.0 - item_frac);
        if it >= cap - 1.0 {
            nb -= 31.0;
        }
        if nx > 0.0 && cap - it >= nx {
            nb -= 10.2 + 0.105 * (cap - it - nx);
        }
        // near-perfect two-item chain in a fresh bin
        if nx > 0.0 {
            let r1 = cap - it;
            if r1 >= nx && (r1 - nx) > 0.0 && (r1 - nx) < 6.0 {
                nb += 8.0 * (1.0 - progress);
            }
            if r1 >= nx && (r1 - nx) > 0.25 * cap && progress > 0.45 {
                nb += 4.2 * ((r1 - nx) / cap).min(0.5) * progress;
            }
            if r1 < nx && r1 > 0.0 {
                nb += (1.0 + 2.0 * progress) * (nx - r1) * 0.5;
            }
        }
        if fitting_bins_count <= 2 {
            nb += 20.5 + 10.0 * (1.0 - progress);
        } else if fitting_bins_count >= 4 {
            nb -= 6.0 + 8.0 * progress;
        }
        // Discourage new bins when mean residual across open bins still
        // comfortably exceeds the next item (reuse potential)
        if nx > 0.0 && mean_residual > nx + 8.0 && progress < 0.7 {
            nb += 8.2 * ((mean_residual - nx) / cap).min(0.5) * cap * 0.1;
        }
        // Stronger reuse pressure late in stream
        if mean_residual >= it && progress > 0.5 {
            nb += 6.2 + 8.2 * progress;
        }
        // If next item can't be hosted by average residual but this bin's
        // fresh residual would chain both items, prefer opening
        if nx > it && mean_residual >= nx && progress < 0.6 {
            nb += 9.5 * (1.0 - progress);
        }
        if nx > 0.0 && mean_residual >= it + nx && progress < 0.6 {
            nb -= 5.2 * (1.0 - progress) * ((mean_residual - it - nx) / cap).min(0.3) * 10.0;
        }
        if it > 0.85 * cap && progress > 0.3 {
            nb -= 8.5 * progress;
