            }
            if best_pr >= nx && best_pr - nx > 0.18 * cap && progress > 0.35 {
                nb -= 5.8 * ((best_pr - nx) / cap).min(0.4) * (0.4 + progress);
            }
        }
        if item_frac > 0.6 && nx > 0.0 && cap >= it + nx && cap - it - nx < 0.03 * cap {
            nb -= 5.2 * (1.0 - (cap - it - nx) / (0.03 * cap));
        }
        if progress > 0.85 && mean_residual < 0.15 * cap {
            nb += 7.0 * progress * (1.0 - mean_residual / (0.15 * cap));
        }
        if item_frac < 0.15 && progress > 0.55 && fitting_bins_count >= 1 {
            nb += 5.8 * progress * (1.0 - item_frac / 0.15);
        }
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin < 0.15 * cap {
                nb -= 5.8 * (1.0 - margin / (0.15 * cap)) * (0.6 + 0.4 * progress);
            }
        }
        score = nb;
    } else {
        let fill_ratio = 1.0 - res / cap;
        let waste = pr / cap;

        // Near-perfect fit bonuses
        if waste < 0.08 {
            score -= 48.0 * (1.0 - progress) * (0.08 - waste);
        }
        if fill_ratio > 0.65 {
            score -= 4.6 * (fill_ratio - 0.65) * 10.0 * (0.4 + progress);
        }
        if nx > 0.0 && nx <= pr && pr > 0.0 {
            let gap = (pr - nx) / cap;
            if gap < 0.03 {
                score -= 7.2 * (1.0 - gap * 33.0);
            }
        }

        // Tiny residual penalties (avoid stranding slivers)
        if pr > 0.0 && pr < 4.0 {
            score += 6.0 * (4.0 - pr) * (1.0 - progress);
        }
        if pr > 0.0 && pr < 10.0 {
            score += 40.5 * (1.0 - 0.5 * progress);
        }
        if pr == 0.0 {
            score -= 61.0;
        } else if pr <= 5.0 {
            score -= 30.5 * (1.0 - 0.4 * progress);
        }
        if nx > 0.0 && pr > 0.0 && pr < nx {
            score += 6.2 + 2.0 * progress;
            if nx - pr <= 3.0 {
                score -= 8.5 * (1.0 - progress);
            }
            let closeness = 1.0 - pr / nx;
            score += 3.0 * closeness * closeness * (0.6 + progress);
        }

        // Balance vs mean residual with quadratic deviation
        let dev = mean_residual - res;
        score += 0.082 * dev;
        score += 0.01 * dev * dev;
        if dev > -5.0 && dev < 15.0 && pr > 0.0 {
            score -= 4.1;
        }

        // Exact chain fit bonus
        let tight_fit = (pr == 0.0) || (nx > 0.0 && pr == nx);
        if tight_fit {
            score -= 10.2 * (0.3 + progress);
        }

        // Reward bins whose post-residual still fits next item with small slack
        if nx > 0.0 && pr >= nx {
            let room = pr - nx;
            if room < 0.06 * cap {
                score -= 6.2 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
            } else if room < 0.22 * cap && fitting_bins_count <= 2 {
                score -= 2.0 * (1.0 - (room / (0.22 * cap))) * (0.6 + progress);
            } else if room > 0.22 * cap && progress > 0.3 {
                score -= 1.8 * ((room / cap) as f64).min(0.35) * (0.5 + progress);
            }
        }

        // Mid-range waste penalty (dead space control)
        if waste > 0.14 && waste < 0.34 {
            score += 12.5 * (waste - 0.14) * (0.6 + 0.8 * progress);
        }
        // Competing fits: prefer the tightest when several bins fit
        if fitting_bins_count > 3 && waste < 0.12 {
            score -= 5.2 * (1.0 - waste * 8.0) * (0.5 + progress);
        }
        if waste > 0.28 && fitting_bins_count > 2 && progress > 0.5 {
            score += 3.4 * (waste - 0.28) * 10.0 * progress;
        }
        if fill_ratio > 0.92 && pr > 0.0 {
            score -= 2.0 * (fill_ratio - 0.92) * 10.0 * (0.5 + progress);
        }

        // Crowding bonus
        score -= 0.41 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for large dead space (unusable residual).
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // tiny residual => excellent fill
    } else if post_residual < 20 {
        score -= 12.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain fit
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (gap / 100.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Mild preference for filling existing bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize opening a new bin when decent alternatives exist.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
    }

    score
}

