                score -= 2.6 * (1.0 - gap / 0.18) * (0.3 + progress);
            }
        }
        if pr > 0.0 && pr < 10.0 {
            score += 41.0 * (1.0 - 0.5 * progress);
        }
        if pr == 0.0 {
            score -= 62.0;
        } else if pr <= 5.0 {
            score -= 31.0 * (1.0 - 0.4 * progress);
        }
        if nx > 0.0 && pr > 0.0 && pr < nx {
            let gap = nx - pr;
            score += gap * (2.0 + 6.5 * (1.0 - progress));
            if gap <= 3.0 {
                score -= 9.0 * (1.0 - progress);
            }
            let closeness = 1.0 - pr / nx;
            score += 3.6 * closeness * closeness * (0.6 + progress);
            if gap > 0.1 * cap && waste > 0.2 {
                score += 4.5 * (waste - 0.2) * 10.0 * (0.4 + progress);
            }
        }
        // NEW: global dead-space pressure — residual far above nx wastes space
        if nx > 0.0 && pr > nx {
            let slack = (pr - nx) / cap;
            if slack > 0.04 {
                score += 3.0 * (slack - 0.04).min(0.25) * (0.5 + progress);
            }
        }
        let dev = mean_residual - res;
        score += 0.085 * dev;
        if dev > -5.0 && dev < 15.0 && pr > 0.0 {
            score -= 4.2;
        }
        let tight_fit = (pr == 0.0) || (nx > 0.0 && pr == nx);
        if tight_fit {
            score -= 10.5 * (0.3 + progress);
        }
        if nx > 0.0 && pr >= nx {
            let room = pr - nx;
            if room < 0.06 * cap {
                score -= 6.5 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
            }
            if room < 0.02 * cap {
                score -= 4.0 * (1.0 - room / (0.02 * cap)) * (0.6 + progress);
            }
        }
        if waste > 0.14 && waste < 0.34 {
            score += 13.0 * (waste - 0.14) * (0.6 + 0.8 * progress);
        }
        if fitting_bins_count > 3 && waste < 0.12 {
            score -= 5.5 * (1.0 - waste * 8.0) * (0.5 + progress);
        }
        if nx > 0.0 && pr > 0.0 && pr > nx && (pr - nx) < 0.02 * cap {
            score -= 4.0 * (1.0 - (pr - nx) / (0.02 * cap)) * (0.4 + progress);
        }
        if pr > 0.0 && (pr as f64).sqrt() < 2.6 {
            score -= 3.5 * (1.0 - progress);
        }
        if waste > 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.09 * cap && progress > 0.4 {
            score -= 4.0 * (1.0 - (pr - nx) / (0.09 * cap)) * progress;
        }
        if pr > 0.0 && nx > 0.0 && pr < nx && (nx - pr) > 0.1 * cap && waste > 0.25 {
            score += 5.0 * (waste - 0.25) * 10.0 * (0.4 + progress);
        }
        if pr > 0.0 && nx > 0.0 && pr < 0.5 * nx && progress > 0.3 {
            score += 3.5 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
        }
        if waste > 0.3 && pr > nx && progress < 0.5 {
            score += 3.0 * (waste - 0.3) * 10.0 * (1.0 - progress);
        }
        if fill_ratio > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
            score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
        }
        if waste > 0.35 && progress > 0.55 && nx > 0.0 && pr >= nx {
            score -= 4.5 * ((pr - nx) / cap).min(0.2) * 5.0 * progress;
        }
        // Scarcity: prefer using existing bins when few can fit
        if fitting_bins_count == 1 {
            score -= 14.0 + 12.0 * progress;
        } else if fitting_bins_count == 2 {
            score -= 4.0 + 3.0 * progress;
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness: reward small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 25.0; // nearly unusable sliver
        } else {
            // dead space value depends on how much of the stream remains
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 0.15 * dead * (0.5 + 0.5 * progress);
        }
    }

    // Lookahead coupling: if the next item fits into post_residual, reward.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (post_residual as f64) >= ni {
            score -= 6.0 * (ni / bin_capacity as f64);
        } else {
            score += 3.0;
        }
        // double-coupling: next item also fits current bin residual exactly-ish
        if (bin_residual as f64 - ni).abs() < 5.0 && post_residual as f64 >= ni {
            score -= 4.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Pressure from many open bins: prefer consolidating into existing bins.
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual.max(0.0) / bin_capacity as f64);
    score += 0.05 * open_pressure;

    // Mean residual alignment: prefer bins close to mean residual (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // New-bin candidate handling: empty bin should only win when fits are bad.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 30.0;
        // cheaper to open a new bin early in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
        // if the item is large relative to capacity and no open bin is tight, opening is fine
        if item_size as f64 > 0.6 * bin_capacity as f64 && mean_residual < item_size as f64 {
            score -= 10.0;
        }
        // if next item is huge and this item is small, avoid wasting a fresh bin
        if next_item_size > item_size && item_size < 30 {
            score += 10.0;
        }
    }

    // Mild time-horizon scaling: late in the stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer small post-residual, with a non-linear (quadratic) penalty
    // that grows faster than linearly as dead space increases.
    let mut score = post + 0.9 * (post / cap) * post;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early in the stream, leaving room is cheaper; late, waste is costly.
    let progress_weight = 2.0 * progress * progress + 0.5 * progress;
    score += progress_weight * (post / cap) * 20.0;

    // Tightness reward: near-perfect fits get a strong smooth discount.
    let tightness = 1.0 - (post / cap);
    score -= 15.0 * tightness * tightness * tightness;

    // Penalize bins whose residual deviates from the mean residual
    // (prefer balanced residual profiles), smoothly.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin (scaled smoothly by progress).
    if fitting_bins_count == 1 {
        score -= 10.0 + 15.0 * progress;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        let slack = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 8.0 * (1.0 - slack * slack);
    } else if next_item_size > 0 {
        // Next item won't fit: mild penalty growing with how close it was.
        let miss = (next_item_size as f64 - post) / cap;
        score += 6.0 * miss * miss;
    }

    // Slight penalty for proliferating bins early on.
    score += 0.05 * (open_bins_count as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes of post_residual (mod small integers)
    let pr = post_residual;
    // Dead space penalty: residuals too small for the smallest plausible item (1..100 range)
    // but reward residuals in "useful" harmonic classes.
    if pr > 0 {
        // class by mod 10 (decade structure)
        let m10 = pr % 10;
        if m10 == 0 {
            score -= 12.0; // round residuals are highly reusable
        } else if m10 <= 3 {
            score += 10.0; // awkward sliver class
        } else {
            score -= 3.0;
        }
        // mod 5 sub-classes
        if pr % 5 == 0 {
            score -= 5.0;
        }
        // integer-division thresholds on post_residual
        let half = bin_capacity / 2;
        let quarter = bin_capacity / 4;
        if pr >= half {
            score -= 20.0; // bin still very usable
        } else if pr >= quarter {
            score -= 8.0;
        } else if pr < 10 {
            score += 15.0; // near-dead space
        }
    }

    // Lookahead coupling: does this bin's post-residual fit the next item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 25.0;
            // harmonic bonus: next item leaves another round residual
            let npr = pr - next_item_size;
            if npr % 10 == 0 {
                score -= 10.0;
            }
        } else {
            score += 6.0; // this bin will be dead for the next item
        }
        // penalize wasting a big bin on a tiny item when next item is huge
        if next_item_size > bin_capacity / 2 && pr > bin_capacity / 2 {
            score += 12.0;
        }
    }

    // Last-chance bonus: only bin that fits -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: neutral-ish, slightly discouraged unless open bins are crowded
    if bin_residual == bin_capacity {
        score += 30.0;
        if open_bins_count == 0 {
            score -= 500.0; // must open first bin
        }
        // open a new bin if existing residuals are all small
        if mean_residual < (bin_capacity as f64) * 0.25 && open_bins_count > 0 {
            score -= 45.0;
        }
        // late in stream, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild consolidation pressure toward mean residual
    score += 0.15 * ((post_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
