            }
            // sharpened dead-space penalty: residual just below next item
            let closeness = 1.0 - pr / nx;
            score += 3.6 * closeness * closeness * (0.6 + progress);
            // dead-sliver that can never chain with typical items
            if gap > 0.1 * cap && waste > 0.2 {
                score += 4.5 * (waste - 0.2) * 10.0 * (0.4 + progress);
            }
        }
        let dev = mean_residual - res;
        score += 0.085 * dev;
        if dev > -5.0 && dev < 15.0 && pr > 0.0 {
            score -= 4.2;
        }
        let tight_fit = (pr == 0.0) || (nx > 0.0 && pr == nx);
        if tight_fit {
            score -= 10.5 * (0.3 + progress);
        }
        if nx > 0.0 && pr >= nx {
            let room = pr - nx;
            if room < 0.06 * cap {
                score -= 6.5 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
            }
            // near-perfect double-fill lookahead
            if room < 0.02 * cap {
                score -= 4.0 * (1.0 - room / (0.02 * cap)) * (0.6 + progress);
            }
        }
        if waste > 0.14 && waste < 0.34 {
            score += 13.0 * (waste - 0.14) * (0.6 + 0.8 * progress);
        }
        if fitting_bins_count > 3 && waste < 0.12 {
            score -= 5.5 * (1.0 - waste * 8.0) * (0.5 + progress);
        }
        if nx > 0.0 && pr > 0.0 && pr > nx && (pr - nx) < 0.02 * cap {
            score -= 4.0 * (1.0 - (pr - nx) / (0.02 * cap)) * (0.4 + progress);
        }
        if pr > 0.0 && (pr as f64).sqrt() < 2.6 {
            score -= 3.5 * (1.0 - progress);
        }
        if waste > 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.09 * cap && progress > 0.4 {
            score -= 4.0 * (1.0 - (pr - nx) / (0.09 * cap)) * progress;
        }
        if pr > 0.0 && nx > 0.0 && pr < nx && (nx - pr) > 0.1 * cap && waste > 0.25 {
            score += 5.0 * (waste - 0.25) * 10.0 * (0.4 + progress);
        }
        if pr > 0.0 && nx > 0.0 && pr < 0.5 * nx && progress > 0.3 {
            score += 3.5 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
        }
        if waste > 0.3 && pr > nx && progress < 0.5 {
            score += 3.0 * (waste - 0.3) * 10.0 * (1.0 - progress);
        }
        if fill_ratio > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
            score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
        }
        if waste > 0.35 && progress > 0.55 && nx > 0.0 && pr >= nx {
            score -= 4.5 * ((pr - nx) / cap).min(0.2) * 5.0 * progress;
        }
        // Scarcity: prefer using existing bins when few can fit
        if fitting_bins_count == 1 {
            score -= 14.0 + 12.0 * progress;
        } else if fitting_bins_count == 2 {
            score -= 4.0 + 3.0 * progress;
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are small-but-nonzero are
    // nearly useless for future items (items are >= 1, but tiny gaps waste
    // capacity). Penalize gaps in the "dead zone" heavily.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable sliver: strong penalty.
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        } else {
            // Large leftovers are reusable; mildly reward.
            score -= (post_residual as f64 - 35.0).min(20.0) * 0.4;
        }
    } else {
        // Perfect fit: big reward.
        score -= 40.0;
    }

    // Tightness reward: the fuller we make the bin, the better.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 15.0;

    // Open-bin pressure: discourage spreading across many bins when few bins
    // can fit the item; encourage using last-chance bins.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    score += open_bins_count as f64 * 1.5;

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item cannot use the leftover: penalize dead space more.
            score += 12.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates from the
    // mean in a way that reduces fragmentation (target the largest residuals).
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate handling: an empty bin is a fallback. Make it
    // attractive only when the current fit is poor (large post_residual or
    // sliver) and there are alternatives; otherwise keep score high so we
    // reuse existing bins.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / bin_capacity as f64;
        // For an empty bin, post_residual == capacity - item_size.
        if poor_fit > 0.6 && fitting_bins_count > 1 {
            score -= 45.0; // opening a fresh bin is fine for small items
        } else {
            score += 35.0; // prefer filling existing bins
        }
    }

    // Slight stream-progression pressure: late in the stream, consolidate.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward an exact match between
    // post_residual and the next item's size (perfect 2-item bin fill).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Exact match: big bonus.
        if diff == 0.0 {
            score -= 60.0;
        } else {
            // Near matches still get a graded bonus.
            score -= (30.0 / (1.0 + diff * 0.35)).min(30.0);
        }
        // If the next item cannot fit in the post residual, the leftover is dead space
        // unless it is small; penalize proportionally to how unusable it is.
        if post_residual < next_item_size {
            let waste = post_residual as f64;
            score += 0.25 * waste;
        }
    }

    // Penalize large leftover space that is unlikely to be filled (dead space).
    if post_residual > 0 && post_residual < 10 {
        // Tiny sliver: nearly worthless, slight penalty beyond raw residual.
        score += 5.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when the item fits poorly
    // everywhere else. Empty-bin candidate gets post_residual == bin_capacity,
    // which is already a high raw score; add a mild bias so we prefer filling
    // existing bins unless they are bad fits.
    if bin_residual == bin_capacity {
        score += 8.0;
        // But if no existing bin fits well (many bins, poor mean residual),
        // relax the bias so opening a new bin is viable.
        if mean_residual < 20.0 {
            score -= 12.0;
        }
    }

    // Prefer bins whose residual is close to the item (tight fits) relative
    // to the mean residual of open bins.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * tightness;

    // Mild preference for bins with above-mean residual early in the stream
    // (keeps small bins available for small future items).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual as f64 > mean_residual {
        score -= 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
