pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post residual)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * (item_size as f64);

    // Penalize dead space that no plausible future item can use
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable slivers are wasteful only if bin then idle; slight penalty
    }

    // Last chance: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / 100.0);
        } else {
            score += 6.0;
        }
        // perfect pairing: post_residual exactly equals next item
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // New-bin candidate handling: only open a new bin when existing fits are poor
    if bin_residual == bin_capacity {
        // baseline cost of opening a bin; adjust by stream progress and congestion
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 60.0 + 25.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // opening fresh bin enables pairing
        }
    }

    // Global state coupling: prefer bins with residual below mean (consolidate large holes)
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Mild preference for filling more-open bins when many are open
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = ((step_index as f64) / (total_items.max(1) as f64)).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;

    // NEW-BIN CANDIDATE decision (borrowed from best heuristic, tuned)
    if bin_residual == bin_capacity {
        let item_frac = (it / cap).min(1.0);
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let mut nb = cap * (1.30 + 1.10 * progress);
        nb -= 30.0 * scarcity * (1.0 - progress);
        nb -= 22.0 * item_frac * (1.0 - progress);
        if it >= cap - 1.0 { nb -= 35.0; }
        if nx > 0.0 && cap - it >= nx {
            let chain_left = cap - it - nx;
            if chain_left < 0.08 * cap {
                nb -= 12.0 * (1.0 - chain_left / (0.08 * cap)) * (0.5 + progress);
            } else {
                nb -= 6.0;
            }
        }
        if nx > 0.0 {
            let r1 = cap - it;
            if r1 > 0.0 && r1 < nx {
                nb += 0.6 * (1.0 + 2.0 * progress) * (nx - r1);
            }
        }
        if fitting_bins_count <= 1 { nb += 24.0 + 12.0 * (1.0 - progress); }
        else if fitting_bins_count >= 4 { nb -= 8.0 + 9.0 * progress; }
        if nx >= 0.5 * cap { nb -= 10.0 * progress + 5.0 * (1.0 - progress); }
        if mean_residual >= it + nx && progress < 0.6 { nb -= 6.0 * (1.0 - progress); }
        if nx > it && mean_residual >= nx && progress < 0.6 { nb += 9.0 * (1.0 - progress); }
        if progress > 0.85 && mean_residual < 0.15 * cap {
            nb += 7.0 * progress * (1.0 - mean_residual / (0.15 * cap));
        }
        if item_frac > 0.85 && progress > 0.3 { nb -= 8.0 * progress; }
        return nb;
    }

    // OPEN-BIN scoring: base on post residual with mild quadratic growth
    let waste = pr / cap;
    let mut score = pr * (1.0 + 0.03 * waste * waste);

    // Tightness: penalize waste more as stream progresses
    let tightness = 1.0 + 2.4 * progress * progress;
    score *= tightness;

    if nx > 0.0 {
        if pr < nx {
            // next item won't chain here: dead space
            let gap = nx - pr;
            score += gap * (2.0 + 6.0 * (1.0 - progress));
            if gap <= 3.0 { score -= 8.0 * (1.0 - progress); }
        } else {
            let chain_left = pr - nx;
            let slack = chain_left / cap;
            if chain_left <= 8.0 { score -= 9.0 + 0.5 * chain_left; }
            else if chain_left <= 20.0 { score -= 5.0; }
            if slack < 0.04 {
                score -= 8.0 * (1.0 - slack * 25.0) * (1.0 + progress);
            }
            score -= 4.0 + 4.0 * (nx / cap) + 8.0 * (1.0 - slack.min(1.0)) * (1.0 - progress);
        }
    }

    // Perfect fill bonus
    if pr == 0.0 { score -= 65.0; }
    else if pr <= 5.0 { score -= 30.0 * (1.0 - 0.4 * progress); }

    // Small-but-usable residual bonus
    if waste > 0.0 && waste < 0.12 {
        score -= 9.0 * (1.0 - waste / 0.12) * (0.4 + progress);
    }

    // Compare against mean residual: leaving less than average is good
    let dev = mean_residual - res;
    score += 0.08 * dev;

    // Last-chance bin: favor using it
    if fitting_bins_count == 1 { score -= 18.0 * (0.5 + progress); }

    // Heavy dead-space penalty, worse if next item can't use it
    let unusable = if nx > 0.0 && pr > 0.0 && pr < nx { 1.0 } else { 0.55 };
    score += (10.0 + 3.0 * progress) * waste * waste * cap * (0.45 + progress) * unusable;

    // Mid-range waste band penalty
    if waste > 0.14 && waste < 0.34 {
        score += 12.0 * (waste - 0.14) * (0.6 + 0.8 * progress);
    }

    // Many open bins: slight preference for consolidation
    score -= 0.4 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear sharpening.
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth coupling: as stream progresses, waste becomes more costly.
    score *= 1.0 + 0.8 * progress * progress;

    // Reward using existing bins: penalty for the new-bin candidate (residual == capacity),
    // scaled by how many alternatives exist and how much slack is around.
    if bin_residual == bin_capacity {
        score += cap * (1.0 + progress) + 10.0 * open_bins_count as f64;
    } else {
        // Last-chance bonus: smooth reward when few bins fit.
        let fit_term = (fitting_bins_count as f64).recip();
        score -= 15.0 * fit_term * (1.0 + progress);
    }

    // Penalize bins whose residual deviates far below the mean (fragmented slack),
    // with smooth quadratic term.
    let dev = mean_residual - pr;
    score += 0.05 * dev * dev;

    // Lookahead: reward leaving space compatible with the next item (smooth interaction).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let compat = 1.0 - (pr - nxt).abs() / cap;
        score -= 8.0 * compat.max(0.0) * compat.max(0.0) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward residuals that sit on
    // "useful" class boundaries (multiples of common small item sizes).
    let harmonic = |r: u32| -> f64 {
        let mut h = 0.0;
        for m in [5u32, 10, 20, 25, 50].iter() {
            if r % m == 0 && r > 0 {
                h -= 3.0;
            }
        }
        h
    };
    score += harmonic(post_residual);

    // Penalize dead space that no future item (1..=100) can plausibly use:
    // tiny residuals (< 10) are nearly unusable.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves another residual: mild reward scaled by fit tightness
            let tight = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 15.0 * tight;
        } else {
            // next item cannot use this bin's remainder: penalize large leftover
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless residuals across
    // open bins are all poor fits for the item.
    if bin_residual == bin_capacity {
        let mean_fit_penalty = (mean_residual - item_size as f64).abs();
        // if open bins fit item poorly on average, allow new bin; otherwise penalize
        if mean_fit_penalty < 20.0 && fitting_bins_count > 0 {
            score += 80.0 + open_bins_count as f64;
        } else {
            score += 10.0;
        }
        // late in stream, prefer consolidation into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
    }

    // Prefer filling bins with already-low residual (consolidate fragmentation).
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.05;

    // Mild preference for bins below mean residual (balance load toward fuller bins).
    score += ((bin_residual as f64) - mean_residual) * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
