        score += 0.085 * dev;
        if dev > -5.0 && dev < 15.0 && pr > 0.0 {
            score -= 4.2;
        }
        let tight_fit = (pr == 0.0) || (nx > 0.0 && pr == nx);
        if tight_fit {
            score -= 10.5 * (0.3 + progress);
        }
        if nx > 0.0 && pr >= nx {
            let room = pr - nx;
            if room < 0.06 * cap {
                score -= 6.5 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
            }
            // near-perfect double-fill lookahead
            if room < 0.02 * cap {
                score -= 4.0 * (1.0 - room / (0.02 * cap)) * (0.6 + progress);
            }
        }
        if waste > 0.14 && waste < 0.34 {
            score += 13.0 * (waste - 0.14) * (0.6 + 0.8 * progress);
        }
        if fitting_bins_count > 3 && waste < 0.12 {
            score -= 5.5 * (1.0 - waste * 8.0) * (0.5 + progress);
        }
        if nx > 0.0 && pr > 0.0 && pr > nx && (pr - nx) < 0.02 * cap {
            score -= 4.0 * (1.0 - (pr - nx) / (0.02 * cap)) * (0.4 + progress);
        }
        if pr > 0.0 && (pr as f64).sqrt() < 2.6 {
            score -= 3.5 * (1.0 - progress);
        }
        if waste > 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.09 * cap && progress > 0.4 {
            score -= 4.0 * (1.0 - (pr - nx) / (0.09 * cap)) * progress;
        }
        if pr > 0.0 && nx > 0.0 && pr < nx && (nx - pr) > 0.1 * cap && waste > 0.25 {
            score += 5.0 * (waste - 0.25) * 10.0 * (0.4 + progress);
        }
        if pr > 0.0 && nx > 0.0 && pr < 0.5 * nx && progress > 0.3 {
            score += 3.5 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
        }
        if waste > 0.3 && pr > nx && progress < 0.5 {
            score += 3.0 * (waste - 0.3) * 10.0 * (1.0 - progress);
        }
        if fill_ratio > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
            score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
        }
        if waste > 0.35 && progress > 0.55 && nx > 0.0 && pr >= nx {
            score -= 4.5 * ((pr - nx) / cap).min(0.2) * 5.0 * progress;
        }
        // Scarcity: prefer using existing bins when few can fit
        if fitting_bins_count == 1 {
            score -= 14.0 + 12.0 * progress;
        } else if fitting_bins_count == 2 {
            score -= 4.0 + 3.0 * progress;
        }
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps after placement.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        // Gap too small for any item (min size 1..100, but small gaps are waste).
        score += (10.0 - pr) * 4.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Prefer tight fits: reward small post_residual relative to capacity.
    score += (pr / cap) * 20.0;

    // Lookahead: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post residual cannot host the next item -> dead space risk.
        score += 8.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    }

    // Open bins pressure: discourage spreading across too many bins.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 5.0;
        // But if no open bin can fit, opening new bin is fine.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's tight already.
    let cur_residual = bin_residual as f64;
    if cur_residual < mean_residual {
        score -= (mean_residual - cur_residual) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: fully consumed bin is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly favor bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + gap);
        // Exact chain fit: item then next item fill the bin completely.
        if post_residual == next_item_size {
            score -= 400.0;
        }
        // Penalize leaving dead space the next item cannot use.
        if post_residual > next_item_size {
            score += 0.3 * (post_residual as f64 - next_item_size as f64);
        }
        // Penalize leaving residual smaller than the smallest plausible item (dead space).
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.5 * post_residual as f64;
        }
    } else {
        // Last item: minimize wasted space aggressively.
        score += 2.0 * post_residual as f64;
    }

    // Reward tightness relative to the mean residual of open bins.
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0 + 0.5 * item_size as f64;
    }

    // New-bin candidate: penalize opening a new bin normally, but allow it when
    // existing residuals are all poor fits (large wasted space would result).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 300.0 - 50.0 * (open_bins_count as f64).ln().max(0.0) - 100.0 * progress;
        // If next item is huge and would need a fresh bin anyway, prefer opening now.
        if next_item_size > 0 && next_item_size > item_size && item_size + next_item_size <= bin_capacity {
            score -= 150.0;
        }
    }

    // Mild preference for filling larger-residual bins first (best-fit bias).
    score -= 0.1 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;

    // Base: post residual with mild non-linear scaling (borrowed from best).
    let mut score = pr * (1.0 + 0.03 * (pr / cap) * (pr / cap));

    // Progress-aware tightness: later in stream, compactness matters more.
    let tightness = 1.0 + 2.2 * progress * progress;
    score *= tightness;

    // Reward near-perfect fills.
    if pr == 0.0 {
        score -= 1000.0;
    } else if pr <= 5.0 {
        score -= 90.0 * (1.0 - 0.4 * progress);
    } else if pr <= 10.0 {
        score -= 40.0;
    }

    // 2-step lookahead.
    if nx > 0.0 {
        if pr == nx {
            score -= 500.0;
        } else if nx < pr {
            let chain_left = pr - nx;
            let frac = nx / pr;
            score -= 200.0 * frac * frac;
            if chain_left <= 5.0 {
                score -= 100.0;
            } else if chain_left <= 10.0 {
                score -= 40.0;
            }
            // Best-heuristic style: reward small chain gaps broadly.
            if chain_left <= 42.0 {
                score -= 6.5 + 0.11 * chain_left;
            }
            let slack = chain_left / cap;
            if slack < 0.04 {
                score -= 8.5 * (1.0 - slack * 25.0) * (1.0 + progress);
            }
        } else {
            // Next item can't follow: dead space likely.
            let gap = nx - pr;
            score += gap * (2.0 + 6.5 * (1.0 - progress));
            if gap <= 3.0 {
                score -= 9.0 * (1.0 - progress);
            }
        }
    }

    // Mean-residual comparison.
    let dev = mean_residual - pr;
    score -= 0.5 * dev;

    // Small residual band bonus (from best).
    let dead_ratio = (pr / cap).max(0.0);
    if dead_ratio > 0.0 && dead_ratio < 0.12 {
        score -= 9.0 * (1.0 - dead_ratio / 0.12) * (0.4 + progress);
    }
    // Penalize big residuals, worse if next item can't use them.
    let unusable = if nx > 0.0 && pr > 0.0 && pr < nx { 1.0 } else { 0.55 };
    score += (10.5 + 3.2 * progress) * dead_ratio * dead_ratio * cap * (0.45 + progress) * unusable;

    // Last-chance bin.
    if fitting_bins_count == 1 {
        score -= 150.0 * (0.5 + progress);
    } else if fitting_bins_count > 3 && dead_ratio < 0.12 {
        score -= 5.5 * (1.0 - dead_ratio * 8.0) * (0.5 + progress);
    }

    // New-bin candidate logic (enriched with best-heuristic couplings).
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let item_frac = (it / cap).min(1.0);
        let mut nb = cap * (1.3 + 1.1 * progress);
        nb -= 26.0 * scarcity * (1.0 - progress);
        nb -= 19.0 * item_frac * (1.0 - progress);
        // Prefer new bin for big items late in stream.
        if it >= 0.85 * cap && progress > 0.3 {
            nb -= 32.0 + 9.0 * progress;
        }
        // If next item fits exactly in the fresh residual, favor new bin.
        if nx > 0.0 && cap - it >= nx {
            nb -= 10.5 + 0.11 * (cap - it - nx);
        }
        // Few fitting bins: opening a bin is costly.
        if fitting_bins_count <= 2 {
            nb += 21.0 + 10.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 4 {
            nb -= 6.5 + 8.5 * progress;
        }
        // If mean residual can still host item + next, avoid new bin.
        if nx > 0.0 && mean_residual >= it + nx && progress < 0.6 {
            nb += 5.5 * (1.0 - progress);
        }
        if nx > it && mean_residual >= nx && progress < 0.6 {
            nb += 10.0 * (1.0 - progress);
        }
        // Very large dead space in open bins justifies a new bin.
        if dead_ratio > 0.6 {
            nb -= 100.0 * (dead_ratio - 0.6);
        }
        score = nb;
    }

    // Slight open-bin pressure to consolidate.
    score -= 0.42 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // this placement is excellent.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }
    // Penalize if next item would be stranded by the post-residual while
    // this bin still could have held both.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is large and few bins fit it, or stream is early with many
    // items remaining to fill it.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let scarcity = (fitting_bins_count as f64).max(1.0);
        let size_pressure = item_size as f64 / bin_capacity as f64;
        let horizon_value = (1.0 - progress) * (1.0 - progress);
        let new_bin_appeal = 30.0 * size_pressure * (1.0 / scarcity) + 45.0 * horizon_value * (1.0 - size_pressure);
        score += 55.0 - new_bin_appeal;
        // Empty-bin residual is large; pull it toward mean behavior otherwise.
        score += 0.15 * (mean_residual - post_residual as f64);
    }

    // Crowding: with many open bins, prefer consolidating into existing ones
    // (penalize new bins implicitly via open_bins_count coupling).
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Mild global balance: prefer bins whose residual is below the mean
    // (filling the fullest bins first keeps many usable mid-size residuals).
    if bin_residual < bin_capacity {
        score += 0.1 * ((bin_residual as f64) - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
