pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are multiples of
    // common item sizes (or of capacity fractions) are "usable" dead space.
    let cap_frac = bin_capacity / 4; // 25
    let post = post_residual;
    let mut usable_bonus = 0.0f64;
    if post == 0 {
        usable_bonus -= 60.0; // perfect fit, best possible
    } else {
        // multiples of 10 / 25 / 50 are harmonically reusable
        if post % 10 == 0 { usable_bonus -= 12.0; }
        if post % cap_frac == 0 { usable_bonus -= 10.0; }
        if post % 5 == 0 { usable_bonus -= 4.0; }
        // integer-division threshold classes on post_residual
        let class = post / 20; // 0..=4 harmonic buckets
        usable_bonus -= match class {
            0 => 8.0,          // tiny dead space, nearly full bin
            1 => 3.0,
            2 => 0.0,
            3 => 2.0,
            _ => 5.0,          // large residual left behind
        };
        // penalize dead space that next item cannot use
        if next_item_size > 0 {
            if next_item_size > post {
                usable_bonus += (next_item_size - post) as f64 * 0.35;
            } else {
                usable_bonus -= 6.0; // next item fits here too: chain bonus
            }
            // harmonic match: next item exactly divides residual
            if next_item_size > 0 && post % next_item_size == 0 {
                usable_bonus -= 9.0;
            }
        }
    }
    score += usable_bonus;

    // Last-chance bin before opening a new bin: strong reward to use it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }
    // Many fitting bins: mild penalty so we keep tighter bins for later.
    if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64 - 2.0) * 1.5;
    }

    // Progress-based modulation: later in the stream, prefer closing bins tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post as f64 * (0.15 + 0.25 * progress);

    // Deviation from mean residual: prefer bins tighter than average.
    score += (bin_residual as f64 - mean_residual) * 0.4;

    // New-bin candidate: only attractive if no open bin is a good harmonic fit.
    if bin_residual == bin_capacity {
        let threshold = if next_item_size > 0 && next_item_size > post { 70.0 } else { 55.0 };
        score = threshold + (item_size as f64) * 0.1 + open_bins_count as f64 * 0.3;
        if fitting_bins_count == 1 {
            score += 40.0; // never open new bin when it's the last chance
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are "dead space"
    // (unusable for typical items). Penalize them hard.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny sliver: worst outcome
        } else if post_residual < 20 {
            score += 35.0;
        } else if post_residual < 35 {
            score += 15.0;
        }
    } else {
        // Perfect fit: strongly reward closing the bin.
        score -= 80.0;
    }

    // Reward tight fits relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Open-bin pressure: with many open bins, prefer consolidating
    // into existing bins rather than spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += 0.4 * pressure;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: bonus if the post residual can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if post residual is nonzero but too small for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // New-bin candidate: keep it mildly unattractive so we only open
    // a fresh bin when no open bin fits decently.
    if bin_residual == bin_capacity {
        score += 45.0 + 2.0 * open_bins_count as f64;
    }

    // Slight preference toward bins with residual close to mean (balanced packing).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
