pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward (post_residual == 0 means no dead space).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward residuals that exactly host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 500.0; // chain of perfect fits
        } else {
            // mildly favor bins whose leftover still fits the next item
            score -= 20.0;
            // penalize large leftover after next placement (future dead space)
            let after_next = post_residual - next_item_size;
            score += after_next as f64 * 0.5;
        }
    } else if next_item_size > 0 {
        // leftover cannot host the next item: penalize small unusable slivers
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Penalize creating tiny dead space (below typical min item size ~10),
    // scaled by stream progress since late waste is more costly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + 100.0 * progress;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += (post_residual as f64 - mean_residual) * 0.2;

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New empty bin candidate: only attractive when current bins are crowded
    // or would leave terrible fits; add a mild penalty otherwise.
    if bin_residual == bin_capacity {
        score += 80.0 + 5.0 * (open_bins_count as f64);
        if mean_residual > item_size as f64 * 1.5 {
            score -= 100.0; // open bins are roomy: don't open a new one
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more aggressively than linear.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score += tight * tight * 40.0;

    // Reward perfect fit strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize dead space that no future item (min size 1) can use well:
    // small leftovers (<10) are nearly unusable -> extra penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item cannot follow here; slight penalty if we waste capacity
            score += 8.0;
        }
    }

    // Last-chance bonus: this is the only bin that fits -> avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // existing fits are bad. Penalize the fresh bin progressively.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 55.0 + 35.0 * (1.0 - progress) - (open_bins_count as f64).min(10.0);
        // If item is large relative to capacity, new bin is more attractive.
        score -= (item_size as f64 / bin_capacity as f64) * 40.0;
    }

    // Global state coupling: prefer bins below mean residual (evening out loads).
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.15 * dev;

    // Late in stream, consolidate more strongly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
