        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin < 0.08 * cap {
                nb -= 5.5 * (1.0 - margin / (0.08 * cap)) * (0.5 + progress);
            } else if margin > 0.25 * cap && progress > 0.45 {
                nb += 4.5 * (margin / cap).min(0.5) * progress;
            }
        }
