            score -= 48.0 * (1.0 - progress) * (0.08 - waste);
        }
        if fill_ratio > 0.65 {
            score -= 4.8 * (fill_ratio - 0.65) * 10.0 * (0.4 + progress);
        }
        if nx > 0.0 && nx <= pr && pr > 0.0 {
            let gap = (pr - nx) / cap;
