            score -= 10.5 * (0.3 + progress);
        }

        // Reward bins whose post-residual still fits next item with small slack
        if nx > 0.0 && pr >= nx {
            let room = pr - nx;
            if room < 0.06 * cap {
                score -= 6.5 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
            } else if room > 0.22 * cap && progress > 0.3 {
                score -= 1.8 * (room / cap).min(0.35) * (0.5 + progress);
            }
        }

        // Waste band shaping: discourage mid-range waste, favor tight fits when options exist
        if waste > 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.09 * cap && progress > 0.4 {
            score -= 4.0 * (1.0 - (pr - nx) / (0.09 * cap)) * progress;
        }
        if waste > 0.28 && fitting_bins_count > 2 && progress > 0.5 {
            score += 3.5 * (waste - 0.28) * 10.0 * progress;
        }
        if fitting_bins_count > 3 && waste < 0.12 {
            score -= 5.5 * (1.0 - waste * 8.0) * (0.5 + progress);
        }
        if waste > 0.08 && waste < 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.07 * cap && progress > 0.35 {
            score -= 2.9 * (1.0 - (pr - nx) / (0.07 * cap)) * (0.5 + progress);
        }
        if fill_ratio > 0.92 && pr > 0.0 {
            score -= 2.0 * (fill_ratio - 0.92) * 10.0 * (0.5 + progress);
        }

        // Crowding bonus
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space via integer division.
    // Class 0: post_residual == 0 (perfect fit) -> strong reward.
    // Class 1..: larger classes = larger unusable gaps.
    let class = (post_residual / 10) as f64;
    score += class * class * 3.0;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Tiny dead space classes (1..=9 residual) are nearly unusable: penalize.
    if post_residual > 0 && post_residual <= 9 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual <= 19 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item can fill this bin's post_residual
    // exactly (or nearly), reward heavily; if next item cannot fit, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit here regardless; dead space becomes final.
            score += (post_residual as f64) * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: make it attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 60.0;
        // More attractive late in the stream or when mean residual is high.
        score -= 0.5 * mean_residual;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 * progress;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Prefer fullest bins (small residual) mildly.
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.3;

    score
}

