pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: zero post-residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: if the NEXT item fits exactly in the
    // post-residual, strongly reward this placement.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next == post {
            score -= 900.0;
        } else if next < post {
            // Next item fits: reward proportionally to how snugly it fits.
            let slack_after_next = post - next;
            score -= 200.0 * (1.0 - slack_after_next / bin_capacity as f64);
            // Extra bonus if the pair leaves a near-perfect residual.
            if slack_after_next <= 5.0 {
                score -= 150.0;
            }
        } else {
            // Next item will NOT fit here: penalize leaving a residual that
            // is too small for the next item (dead space risk), scaled by
            // how far off the next item is.
            let gap = next - post;
            score += 60.0 + 1.5 * gap.min(100.0) as f64;
        }
    }

    // Penalize residuals that become hard-to-fill "dead zones" (very small
    // but nonzero, given items are >= 1).
    let post = post_residual as f64;
    if post > 0.0 && post < 10.0 {
        score += 120.0 - 10.0 * post;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.8 * (mean_residual - post);

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Mild preference for keeping the number of open bins low as the
    // stream progresses (consolidation pressure).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.3 * progress * post;

    // Penalize the fresh-bin candidate unless the item is large relative
    // to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * (bin_capacity as f64 - item_size as f64);
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: small post residual is good, but reward super-positively near zero.
    let t = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - t).powi(8) * (1.0 - t);

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead: if next item fits in post residual, big bonus (chaining).
    if next_item_size > 0 {
        if next_item_size as f64 <= post_residual as f64 {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            // Penalize leaving space that exactly blocks the next item awkwardly.
            score += 4.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Crowding: many open bins -> prefer consolidating into existing ones.
    score += 0.4 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Global balance: penalize bins deviating from mean residual (prefer uniform fills).
    score += 0.5 * ((bin_residual as f64 - mean_residual).abs());

    // Time horizon: late in the stream, be conservative; keep residual usable.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 20.0 - 15.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let fit_ratio = item_size as f64 / bin_residual as f64;

    // Reward tight fits: quadratic coupling of post_residual with fit ratio
    score -= (1.0 - fit_ratio).powi(2) * (cap - pr) * (0.5 + 0.5 * progress);

    // Penalize dead space that can't fit typical small items, smooth non-linear
    let dead = if pr > 0.0 { pr } else { 0.0 };
    score += (dead / cap).powi(3) * cap * (0.6 + 0.4 * (1.0 - progress));

    // Last-chance bonus: only one fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - pr / cap);
    } else {
        score += (fitting_bins_count as f64 - 1.0).ln_1p() * 2.0;
    }

    // Lookahead: reward if next item fits into post_residual (chain packing)
    if next_item_size > 0 {
        if (post_residual as u64) >= next_item_size as u64 {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            score += 5.0 * (next_item_size as f64 - pr) / cap;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (compact packing)
    score += (pr - mean_residual) * 0.3 * (0.5 + progress);

    // New-bin candidate: penalize mildly early, more when open bins exist and fit is decent
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 8.0 + 25.0 * pressure * (1.0 - progress) * (1.0 + (open_bins_count as f64).ln_1p() * 0.2);
        // late stream: new bins cheaper to open
        score -= 10.0 * progress;
    }

    // Mild preference for larger residual bins when many open
    score -= (pr / cap) * (open_bins_count as f64).ln_1p() * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits via post_residual, scaled by capacity fraction.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * 20.0;

    // Harmonic classes: reward post_residual falling into "useful" residue classes.
    // Small residues divisible by common item sizes (10/20/25/50) are re-usable.
    let pr = post_residual as i64;
    let mut bonus = 0.0;
    if pr > 0 {
        if pr % 10 == 0 { bonus += 6.0; }
        if pr % 20 == 0 { bonus += 4.0; }
        if pr % 25 == 0 { bonus += 4.0; }
        if pr % 50 == 0 { bonus += 3.0; }
    }
    // Dead-space penalty for awkward residues (prime-ish leftovers).
    if pr > 0 && pr < 10 {
        bonus -= 8.0; // tiny slivers are nearly useless
    }
    // Exact fill is perfect.
    if pr == 0 { bonus += 15.0; }

    // Lookahead coupling: reward bins whose post_residual can host next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        bonus += 5.0 + (next_item_size as f64 / 10.0);
    } else if next_item_size > 0 {
        bonus -= 3.0; // next item will need another bin anyway
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        bonus -= 10.0;
    }

    // Late in the stream: consolidate harder, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        bonus -= 4.0 * progress;
    }

    // Prefer bins below mean residual (fill emptier bins first when many open).
    if (bin_residual as f64) < mean_residual && open_bins_count > 2 {
        bonus += 2.0;
    }

    // New-bin candidate: make it moderately attractive only when the fit here is bad.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize new bins unless the resulting post_residual would be very tight
        // or the current bin would leave a bad residue class.
        let bad_fit = post_residual > 0 && post_residual < 10;
        if bad_fit { bonus -= 12.0; } else { bonus += 18.0; }
    }

    score -= bonus;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;

    // Base: post residual with mild non-linear scaling.
    let mut score = pr * (1.0 + 0.03 * (pr / cap) * (pr / cap));

    // Progress-aware tightness (combined quadratic + cubic ramp).
    let tightness = 1.0 + 2.4 * progress * progress + 1.2 * progress * progress * progress;
    score *= tightness;

    // Reward near-perfect fills.
    if pr == 0.0 {
        score -= 1000.0;
    } else if pr <= 5.0 {
        score -= 90.0 * (1.0 - 0.4 * progress);
    } else if pr <= 10.0 {
        score -= 40.0;
    }

    // 2-step lookahead with fine-grained chain fitting.
    if nx > 0.0 {
        if pr == nx {
            score -= 500.0;
        } else if nx < pr {
            let chain_left = pr - nx;
            let frac = nx / pr;
            score -= 200.0 * frac * frac;
            if chain_left <= 5.0 {
                score -= 100.0;
            } else if chain_left <= 10.0 {
                score -= 40.0;
            }
            if chain_left <= 42.0 {
                score -= 6.5 + 0.11 * chain_left;
            }
            let slack = chain_left / cap;
            if slack < 0.04 {
                score -= 8.5 * (1.0 - slack * 25.0) * (1.0 + progress);
            }
            // New: reward chains that leave room for a third small item.
            if chain_left > 0.0 && chain_left < 0.08 * cap {
                score -= 3.5 * (1.0 - chain_left / (0.08 * cap)) * (0.4 + progress);
            }
        } else {
            // Next item can't follow: dead space likely.
            let gap = nx - pr;
            score += gap * (2.0 + 6.5 * (1.0 - progress));
            if gap <= 3.0 {
                score -= 9.0 * (1.0 - progress);
            }
            // New: extra penalty when gap is small-but-unusable late in stream.
            if gap <= 0.05 * cap && progress > 0.4 {
                score += 3.5 * (1.0 - gap / (0.05 * cap)) * progress;
            }
        }
    }

    // Mean-residual comparison.
    let dev = mean_residual - pr;
    score -= 0.5 * dev;

