    let dead_ratio = (pr / cap).max(0.0);
    if dead_ratio > 0.0 && dead_ratio < 0.12 {
        score -= 9.0 * (1.0 - dead_ratio / 0.12) * (0.4 + progress);
    }
    // Penalize big residuals, worse if next item can't use them.
    let unusable = if nx > 0.0 && pr > 0.0 && pr < nx { 1.0 } else { 0.55 };
    score += (10.5 + 3.2 * progress) * dead_ratio * dead_ratio * cap * (0.45 + progress) * unusable;

    // Mid-band waste penalty (from best heuristic).
    if dead_ratio > 0.14 && dead_ratio < 0.34 {
        score += 13.0 * (dead_ratio - 0.14) * (0.6 + 0.8 * progress);
    }

    // Last-chance bin.
    if fitting_bins_count == 1 {
        score -= 150.0 * (0.5 + progress);
    } else if fitting_bins_count > 3 && dead_ratio < 0.12 {
        score -= 5.5 * (1.0 - dead_ratio * 8.0) * (0.5 + progress);
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let item_frac = (it / cap).min(1.0);
        let mut nb = cap * (1.3 + 1.1 * progress);
        nb -= 26.0 * scarcity * (1.0 - progress);
        nb -= 19.0 * item_frac * (1.0 - progress);
