            nb += 21.0 + 10.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 4 {
            nb -= 6.5 + 8.5 * progress;
        }
        // If mean residual can still host item + next, avoid new bin.
        if nx > 0.0 && mean_residual >= it + nx && progress < 0.6 {
            nb += 5.5 * (1.0 - progress);
        }
        if nx > it && mean_residual >= nx && progress < 0.6 {
            nb += 10.0 * (1.0 - progress);
        }
        // Very large dead space in open bins justifies a new bin.
        if dead_ratio > 0.6 {
            nb -= 100.0 * (dead_ratio - 0.6);
        }
        // New: avoid new bin when mean residual nearly fits item + next tightly.
        if nx > 0.0 && mean_residual >= it + nx {
            let rem = mean_residual - it - nx;
