            let best_pr = (mean_residual - it).max(0.0);
            if best_pr >= nx && best_pr - nx < 0.05 * cap {
                nb += 6.0 * (1.0 - (best_pr - nx) / (0.05 * cap)) * (0.5 + progress);
            }
        }
