    // Strong base penalty for wasted space, weighted by tightness of the fit.
    let tight_fit = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score += 12.0 * (1.0 - tight_fit);

    // --- 2-step lookahead: reward bins where the next item also fits ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: next item exactly consumes the remainder -> big reward.
            let exact = (post_residual - next_item_size) as f64;
            if exact == 0.0 {
                score -= 60.0;
            } else {
