                let match_quality = 1.0 - (exact / bin_capacity as f64);
                score -= 40.0 * match_quality;
            }
        } else {
            // Next item cannot follow into this bin: penalize dead space creation,
            // scaled by how close the chain just missed.
            let miss = (next_item_size - post_residual) as f64;
            score += 10.0 + 0.5 * miss.min(30.0);
        }
    } else {
        // Last item: just minimize post residual.
        score -= 5.0;
    }

    // Prefer bins whose residual is below the mean (compact bins absorb items),
    // leave high-residual bins for future large items.
    score += 0.35 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild pressure against opening new bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * progress;
    }

    // Slight preference to spread load when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

