pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small leftover space.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Lookahead: reward if next item can fit into the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward for near-perfect chain fit.
            let chain_gap = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - chain_gap / bin_capacity as f64);
        } else {
            // Penalize leaving a gap the next item cannot use.
            let gap = post_residual as f64;
            score += 6.0 * (gap / bin_capacity as f64);
        }
    } else {
        // Last item: strongly prefer minimal residual.
        score -= 20.0 * tightness;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when many bins are open
    // and the item fits reasonably well somewhere.
    if bin_residual == bin_capacity {
        let base_penalty = 55.0;
        let open_pressure = (open_bins_count as f64).ln().max(0.0) * 5.0;
        let fit_pressure = if fitting_bins_count > 0 {
            let best_possible = (bin_capacity - item_size) as f64;
            25.0 * (1.0 - (best_possible / bin_capacity as f64))
        } else { 0.0 };
        score += base_penalty + open_pressure + fit_pressure;
        // Late in the stream, opening new bins is more costly (waste accumulates).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Discourage placing into bins with large residuals when the mean residual
    // is small (preserve big bins for big future items).
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.08 * dev;
    } else {
        score += 0.04 * dev; // small reward for below-mean residual bins
    }

    // Mild penalty for very loose fits creating dead space below usable threshold.
    if post_residual > 0 && post_residual < 10 {
        score -= 10.0; // near-perfect fill
    } else if post_residual >= 10 && post_residual < item_size.min(80) {
        score += 4.0; // awkward small gap
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize leftover residual, with non-linear (quadratic) waste penalty
    let mut score = pr + 0.9 * (pr / cap) * pr;

    // Perfect fit reward (smooth gaussian-like bump near zero residual)
    let x = pr / cap;
    score -= 12.0 * (-x * x / 0.005).exp();

    // Tight-fit coupling: reward small post_residual as stream progresses
    score -= 6.0 * progress * (1.0 - x) * (1.0 - x);

    // Dead-space penalty: residuals too small for likely future items
    let ns = next_item_size as f64;
    if ns > 0.0 {
        let gap = (ns - pr).max(0.0) / cap;
        score += 4.0 * gap * gap * cap * 0.01;
        // Bonus if this bin can also hold the lookahead item
        let fits_next = if pr >= ns { 1.0 } else { 0.0 };
        score -= 5.0 * fits_next * (pr / cap);
    }

    // Last-chance bonus: only one fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Mild preference for fuller bins relative to fleet mean residual
    score -= 2.0 * ((bin_residual as f64 - mean_residual) / cap);

    // New-bin candidate: make empty bins moderately attractive only early or when
    // existing residuals are large; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let mean_frac = mean_residual / cap;
        score += 3.0 + 10.0 * (1.0 - progress) * 0.0 + 8.0 * (1.0 - mean_frac);
        score -= 4.0 * (1.0 - x); // empty bin x = 1, so this reduces penalty slightly
    }

    // Smooth open-bin pressure: many open bins -> favor consolidating
    score += 0.15 * (open_bins_count as f64).ln().max(0.0) * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;

    // Base: post residual with mild non-linear scaling.
    let mut score = pr * (1.0 + 0.03 * (pr / cap) * (pr / cap));

    // Progress-aware tightness (combined quadratic + cubic ramp).
    let tightness = 1.0 + 2.4 * progress * progress + 1.2 * progress * progress * progress;
    score *= tightness;

    // Reward near-perfect fills.
    if pr == 0.0 {
        score -= 1000.0;
    } else if pr <= 5.0 {
        score -= 90.0 * (1.0 - 0.4 * progress);
    } else if pr <= 10.0 {
        score -= 40.0;
    }

    // 2-step lookahead with fine-grained chain fitting.
    if nx > 0.0 {
        if pr == nx {
            score -= 500.0;
        } else if nx < pr {
            let chain_left = pr - nx;
            let frac = nx / pr;
            score -= 200.0 * frac * frac;
            if chain_left <= 5.0 {
                score -= 100.0;
            } else if chain_left <= 10.0 {
                score -= 40.0;
            }
            if chain_left <= 42.0 {
                score -= 6.5 + 0.11 * chain_left;
            }
            let slack = chain_left / cap;
            if slack < 0.04 {
                score -= 8.5 * (1.0 - slack * 25.0) * (1.0 + progress);
            }
            // Reward chains that leave room for a third small item.
            if chain_left > 0.0 && chain_left < 0.08 * cap {
                score -= 3.5 * (1.0 - chain_left / (0.08 * cap)) * (0.4 + progress);
            }
            // Combined: reward broad usable chains (from best heuristic).
            let chain = 1.0 - slack.min(1.0);
            score -= 5.0 + 4.0 * (nx / cap) + 9.5 * chain * (1.0 - progress);
        } else {
            // Next item can't follow: dead space likely.
            let gap = nx - pr;
            score += gap * (2.0 + 6.5 * (1.0 - progress));
            if gap <= 3.0 {
                score -= 9.0 * (1.0 - progress);
            }
            // Extra penalty when gap is small-but-unusable late in stream.
            if gap <= 0.05 * cap && progress > 0.4 {
                score += 3.5 * (1.0 - gap / (0.05 * cap)) * progress;
            }
            // Near-miss gap amplification (from best heuristic).
            if gap <= 0.04 * cap {
                score += 3.5 * (1.0 - gap / (0.04 * cap)) * (0.5 + progress);
            }
        }
    }

    // Mean-residual comparison.
    let dev = mean_residual - pr;
    score -= 0.5 * dev;

    // Small residual band bonus.
    let dead_ratio = (pr / cap).max(0.0);
    if dead_ratio > 0.0 && dead_ratio < 0.12 {
        score -= 9.0 * (1.0 - dead_ratio / 0.12) * (0.4 + progress);
    }
    // Penalize big residuals, worse if next item can't use them.
    let unusable = if nx > 0.0 && pr > 0.0 && pr < nx { 1.0 } else { 0.55 };
    score += (10.5 + 3.2 * progress) * dead_ratio * dead_ratio * cap * (0.45 + progress) * unusable;

    // Mid-band waste penalty.
    if dead_ratio > 0.14 && dead_ratio < 0.34 {
        score += 13.0 * (dead_ratio - 0.14) * (0.6 + 0.8 * progress);
    }

    // Last-chance bin.
    if fitting_bins_count == 1 {
        score -= 150.0 * (0.5 + progress);
    } else if fitting_bins_count > 3 && dead_ratio < 0.12 {
        score -= 5.5 * (1.0 - dead_ratio * 8.0) * (0.5 + progress);
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let item_frac = (it / cap).min(1.0);
        let mut nb = cap * (1.3 + 1.1 * progress);
        nb -= 26.0 * scarcity * (1.0 - progress);
        nb -= 19.0 * item_frac * (1.0 - progress);
        // Prefer new bin for big items late in stream.
        if it >= 0.85 * cap && progress > 0.3 {
            nb -= 32.0 + 9.0 * progress;
        }
        // If next item fits exactly in the fresh residual, favor new bin.
        if nx > 0.0 && cap - it >= nx {
            nb -= 10.5 + 0.11 * (cap - it - nx);
        }
        // Few fitting bins: opening a bin is costly.
        if fitting_bins_count <= 2 {
            nb += 21.0 + 10.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 4 {
            nb -= 6.5 + 8.5 * progress;
        }
        // If mean residual can still host item + next, avoid new bin.
        if nx > 0.0 && mean_residual >= it + nx && progress < 0.6 {
            nb += 5.5 * (1.0 - progress);
        }
        if nx > it && mean_residual >= nx && progress < 0.6 {
            nb += 10.0 * (1.0 - progress);
        }
        // Very large dead space in open bins justifies a new bin.
        if dead_ratio > 0.6 {
            nb -= 100.0 * (dead_ratio - 0.6);
        }
        // Avoid new bin when mean residual nearly fits item + next tightly.
        if nx > 0.0 && mean_residual >= it + nx {
            let rem = mean_residual - it - nx;
            if rem < 0.08 * cap {
                nb += 7.0 * (1.0 - rem / (0.08 * cap)) * (0.5 + progress);
            }
        }
        // Avoid new bin when mean residual post-fit is a near-exact match for next.
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_pr = (mean_residual - it).max(0.0);
            if best_pr >= nx && best_pr - nx < 0.05 * cap {
                nb += 6.0 * (1.0 - (best_pr - nx) / (0.05 * cap)) * (0.5 + progress);
            }
        }
        // Favor new bin when fresh residual would be nearly dead space.
        if nx > 0.0 && cap - it < nx && cap - it > 0.0 {
            nb += 4.5 * (1.0 - progress) * ((nx - (cap - it)) / cap).min(0.3) * 10.0;
