            nb -= 5.0 * (1.0 - (cap - it - nx) / (0.05 * cap)) * (0.5 + progress);
        }
        // Many open bins with large mean residual -> avoid new bin.
        if open_bins_count > 6 && mean_residual > 0.4 * cap && progress < 0.6 {
            nb += 5.0 * ((mean_residual - 0.4 * cap) / cap) * (1.0 - progress)
                * ((open_bins_count as f64 - 6.0).min(8.0) / 8.0);
        }
        // Late stream with small item and fitting bins -> avoid new bin.
        if item_frac < 0.15 && progress > 0.55 && fitting_bins_count >= 1 {
            nb += 6.0 * progress * (1.0 - item_frac / 0.15);
        }
        // Combined additions (from best heuristic):
        // Avoid new bin when mean residual can host next item with small excess.
        if nx > 0.0 && mean_residual > nx {
            let excess = mean_residual - nx;
            if excess < 0.05 * cap && progress < 0.55 {
                nb += 5.0 * (1.0 - excess / (0.05 * cap)) * (1.0 - progress);
            }
        }
        // No fitting bins late: opening is required anyway.
        if fitting_bins_count == 0 && progress > 0.25 {
            nb += 9.0 + 7.0 * progress;
        }
        // Wide margin after item+next in fresh bin: mild cost.
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin < 0.15 * cap {
                nb -= 6.0 * (1.0 - margin / (0.15 * cap)) * (0.6 + 0.4 * progress);
            }
        }
        // Next item large: fresh bin helps chain it.
        if nx >= 0.5 * cap {
            nb -= 12.0 * progress + 6.0 * (1.0 - progress);
        }
        // Avoid new bin when mean residual fits item+next with leftover in a good band.
        if nx > 0.0 && fitting_bins_count >= 1 && mean_residual >= it + nx {
            let leftover = mean_residual - it - nx;
            if leftover < 0.1 * cap && progress > 0.45 {
                nb -= 5.0 * (1.0 - leftover / (0.1 * cap)) * progress;
            }
        }
        score = nb;
    } else {
        // Open-bin fill ratio bonus.
        let fill_ratio = 1.0 - res / cap;
        if fill_ratio > 0.65 {
            score -= 4.8 * (fill_ratio - 0.65) * 10.0 * (0.4 + progress);
        }
        // Near-exact next-item match in open bins.
        if nx > 0.0 && nx <= pr && pr > 0.0 {
            let gap = (pr - nx) / cap;
            if gap < 0.03 {
                score -= 7.5 * (1.0 - gap * 33.0);
            }
        }
        // Waste-band bonus for very low waste early (from best heuristic).
        let waste = pr / cap;
        if waste < 0.08 {
            score -= 48.0 * (1.0 - progress) * (0.08 - waste);
        }
        // Penalize leaving residual just below next item size.
        if nx > 0.0 && pr > 0.0 && pr < nx {
            let closeness = 1.0 - pr / nx;
            score += 3.0 * closeness * closeness * (0.6 + progress);
        }
    }

    // Slight open-bin pressure to consolidate.
    score -= 0.42 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: prefer residuals that future
    // items (sizes 1..=100, mean ~ item_size) can still pair into.
    // Class 0: perfectly full bin -> excellent, big reward.
    // Class 1: tiny dead space (1..=5) -> nearly full, still good.
    // Class 2: mid residual -> neutral-ish.
    let post = post_residual;
    let class = match post {
        0 => 0,
        1..=5 => 1,
        6..=15 => 2,
        16..=30 => 3,
        _ => 4,
    };
    score -= match class {
        0 => 60.0,
        1 => 35.0,
        2 => 10.0,
        3 => 0.0,
        _ => 5.0,
    };

    // Modulo coupling: residual that is a multiple of common item sizes
    // (10/20/25/50) is more reusable.
    if post > 0 && (post % 10 == 0 || post % 25 == 0) {
        score -= 8.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 45.0;
        } else if next_item_size <= post {
            // next item fits: residual quality depends on leftover after next
            let after_next = post - next_item_size;
            score -= 20.0 - (after_next as f64 * 0.15);
            if after_next == 0 {
                score -= 15.0;
            }
        } else {
            // next item cannot use this residual: penalize large wasted space
            score += ((next_item_size - post) as f64) * 0.25;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current fit is terrible (huge post_residual) or no real bin competes well.
    if bin_residual == bin_capacity {
        // New bin: post_residual = capacity - item_size; make it expensive
        // unless the item is large (small post residual) or stream is early.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * (1.0 - progress) + (open_bins_count as f64) * 0.5;
        if post <= 20 {
            score -= 55.0; // large item in fresh bin is fine
        }
    } else {
        // Reward tight fits in existing bins relative to mean residual.
