    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.3;

    // Small tie-breaker: prefer bins whose residual parity aligns with item size.
    if bin_residual % 2 == item_size % 2 {
        score -= 1.0;
    }

