}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are the worst outcome.
    // A residual that no realistic item (>=1) can use is pure waste; residual
    // just below the smallest plausible item band is heavily penalized.
    if post_residual > 0 {
        let dead = if post_residual < 10 {
            // gap too small for the typical item range: near-total waste
            60.0
        } else if post_residual < 25 {
            // awkward gap: usable only by very small items
            25.0
        } else if post_residual < 50 {
            8.0
        } else {
            0.0
        };
        score += dead;
    } else {
        // perfect fit: strong reward
        score -= 40.0;
    }

    // Reward tight fits relative to bin residual (low waste ratio)
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: when many bins are open, avoid spreading;
    // when few bins are open, opening a new one is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += 0.6 * pressure;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (a new bin costs a full slot).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item can use the post-residual, reward leaving it;
    // if the next item is larger than post_residual and this bin would leave a
    // near-dead gap, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 && post_residual < 15 {
            score += 15.0;
        }
    }

    // Mild nudge toward bins whose residual is close to the item (best-fit core)
    score += (bin_residual as f64 - item_size as f64) * 0.15;

    // New-bin candidate handling: prefer opening a new bin only when no open
    // bin offers a decent fit (residual usage poor) or when open count is low.
    if bin_residual == bin_capacity {
        // base cost of consuming a fresh bin
        score += 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        } else if mean_residual < item_size as f64 * 1.2 {
            score -= 25.0; // open bins are all tight anyway
        }
    }

    score
}

