        if fill_ratio > 0.8 {
            score -= 15.0; // big item: fresh bin is fine
        } else {
            score += 10.0 * (1.0 - fill_ratio); // small item in a fresh bin: wasteful
        }
    }

    // Slight progression bias: late in the stream, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (pr / bin_capacity as f64);

    score
}

