            nb += 10.0 * (1.0 - progress);
        }
        if waste > 0.6 {
            nb -= 100.0 * (waste - 0.6);
        }
        // Open-bin pressure: avoid new bin when mean residual is generous.
        if mean_residual >= it && progress > 0.5 {
            nb += 6.5 + 8.5 * progress;
        }
        if nx > 0.0 && mean_residual > nx + 8.0 && progress < 0.7 {
            nb += 8.5 * ((mean_residual - nx) / cap).min(0.5) * cap * 0.1;
        }
        if it / cap > 0.6 && nx > 0.0 && cap >= it + nx && cap - it - nx < 0.03 * cap {
            nb -= 5.5 * (1.0 - (cap - it - nx) / (0.03 * cap));
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_pr = (mean_residual - it).max(0.0);
            if best_pr > 0.0 && best_pr < 0.06 * cap && (cap - it) >= nx {
                nb -= 7.0 * (1.0 - best_pr / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if progress > 0.85 && mean_residual < 0.15 * cap {
            nb += 7.0 * progress * (1.0 - mean_residual / (0.15 * cap));
        }
        // Two-item packing margin — prefer new bin when fresh bin packs item+next nearly full.
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin < 0.05 * cap {
                nb -= 6.5 * (1.0 - margin / (0.05 * cap)) * (0.5 + progress);
            }
        }
        // Discourage new bin when mean residual can host item plus next.
        if nx > 0.0 && mean_residual >= it + nx && progress > 0.4 {
            let rem = mean_residual - it - nx;
            if rem < 0.08 * cap {
                nb += 5.0 * (1.0 - rem / (0.08 * cap)) * progress;
            }
        }
        // Many open bins with slack — avoid opening a new one.
        if open_bins_count > 6 && mean_residual > 0.35 * cap && progress < 0.6 {
            nb += 5.0 * ((mean_residual - 0.35 * cap) / cap) * (1.0 - progress)
                * ((open_bins_count as f64 - 6.0).min(8.0) / 8.0);
        }
        // Borrowed from best lineage: mean residual hosting item+next with tight leftover.
        if nx > 0.0 && fitting_bins_count >= 1 && mean_residual - it >= nx {
            let leftover = mean_residual - it - nx;
            if leftover < 0.1 * cap && progress > 0.45 {
                nb -= 5.0 * (1.0 - leftover / (0.1 * cap)) * progress;
            }
        }
        // Large next item: fresh bin less attractive.
        if nx > 0.0 && mean_residual < nx && progress > 0.55 && item_frac < 0.5 {
            nb += 3.5 * (nx - mean_residual).min(0.1 * cap) / (0.1 * cap) * progress;
        }
        score = nb;
    }

    // Slight open-bin pressure to consolidate.
    score -= 0.42 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item can use are heavily penalized.
    // Items are >= 1, but treat gaps below a small "usable threshold" as dead space.
    let dead_threshold: u32 = 10;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual) as f64;
    }

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Coupling with residual structure: penalize leaving a gap that the known
    // next item cannot use (wasted potential), reward if next item fits gap.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // gap remains usable by lookahead item
        } else if post_residual > 0 {
            score += 10.0; // gap too small for next item -> likely dead
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening a new bin
    // (new bin has bin_residual == bin_capacity, so it gets this penalty too,
    // pushing selection toward existing bins unless fit is terrible).
    if bin_residual == bin_capacity {
        score += 12.0 + 3.0 * open_bins_count as f64;
    } else {
        // Mild reward for using already-open bins, scaled by congestion.
        score -= 2.0 + 0.5 * open_bins_count as f64;
    }

    // Prefer bins whose residual is below average (consolidate small leftovers).
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 6.0 * (mean_residual - res) / bin_capacity as f64;
    } else {
        score += 4.0 * (res - mean_residual) / bin_capacity as f64;
    }

    // Stream progression: early on, allow more new bins (exploration);
    // later, be conservative and squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 15.0 * progress;
    } else {
        score -= 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { (step_index as f64 / total_items as f64).clamp(0.0, 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;
    let is_new_bin = (res - cap).abs() < 1e-9;
    let urgency = progress * progress * (3.0 - 2.0 * progress);

    // ---- NEW-BIN CANDIDATE: adopt lookahead-driven gating from best heuristic ----
    if is_new_bin {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let item_frac = (it / cap).min(1.0);
        let mut nb = cap * (1.35 + 1.15 * progress);
        nb -= 26.0 * scarcity * (1.0 - progress);
        nb -= 19.0 * item_frac * (1.0 - progress);
        if nx >= 0.5 * cap { nb -= 12.0 * progress + 6.0 * (1.0 - progress); }
        nb += 15.0 * progress * (1.0 - item_frac);
        if it >= cap - 1.0 { nb -= 32.0; }
        if nx > 0.0 && cap - it >= nx { nb -= 10.5 + 0.11 * (cap - it - nx); }
        if fitting_bins_count <= 2 { nb += 21.0 + 10.0 * (1.0 - progress); }
        if fitting_bins_count >= 4 { nb -= 6.5 + 8.5 * progress; }
        if nx > 0.0 && mean_residual > nx + 8.0 && progress < 0.7 {
            nb += 8.5 * ((mean_residual - nx) / cap).min(0.5) * cap * 0.1;
        }
        if mean_residual >= it && progress > 0.5 { nb += 6.5 + 8.5 * progress; }
        if nx > it && mean_residual >= nx && progress < 0.6 { nb += 10.0 * (1.0 - progress); }
        if it / cap > 0.6 && nx > 0.0 && cap >= it + nx && cap - it - nx < 0.03 * cap {
            nb -= 5.5 * (1.0 - (cap - it - nx) / (0.03 * cap));
        }
        if fitting_bins_count == 0 && progress > 0.25 { nb += 9.0 + 7.0 * progress; }
        if progress > 0.85 && mean_residual < 0.15 * cap {
            nb += 7.0 * progress * (1.0 - mean_residual / (0.15 * cap));
        }
        if open_bins_count > 10 && progress < 0.35 && item_frac < 0.3 {
            nb += 6.0 * (1.0 - progress) * (1.0 - item_frac / 0.3);
        }
        return nb;
    }

    // ---- EXISTING BIN SCORING (mutated parent core) ----
    let x = (pr / cap).max(0.0);
    let mut score = pr * (1.0 + 0.03 * x * x);
    // tightness ramp (stronger late)
    score *= 1.0 + 2.6 * progress * progress + 2.4 * progress * progress * progress;

    // Lookahead chain logic (borrowed, tightened)
    if nx > 0.0 {
        if pr < nx {
            let gap = nx - pr;
            score += gap * (2.0 + 6.5 * (1.0 - progress));
        } else {
            let chain_gap = pr - nx;
            let slack = chain_gap / cap;
            if chain_gap <= 42.0 { score -= 6.5 + 0.11 * chain_gap; }
            if slack < 0.04 { score -= 8.5 * (1.0 - slack * 25.0) * (1.0 + progress); }
            let chain = 1.0 - slack.min(1.0);
            score -= 5.0 + 4.0 * (nx / cap) + 9.5 * chain * (1.0 - progress);
        }
    }

    // Dead-space penalty (parent cubic, amplified and gated by lookahead)
    let unusable = if nx > 0.0 && pr > 0.0 && pr < nx { 1.0 } else { 0.55 };
    score += (10.5 + 3.2 * progress) * x * x * cap * (0.45 + progress) * unusable;

    // Near-exact fit rewards
    if x > 0.0 && x < 0.12 { score -= 9.0 * (1.0 - x / 0.12) * (0.4 + progress); }
    if pr == 0.0 { score -= 62.0; }
    else if pr <= 5.0 { score -= 31.0 * (1.0 - 0.4 * progress); }

    // Next item almost fits: small penalty to preserve option
    if nx > 0.0 && pr > 0.0 && pr < nx && (nx - pr) <= 0.04 * cap {
        score += 3.5 * (1.0 - (nx - pr) / (0.04 * cap)) * (0.5 + progress);
    }

    // Scarcity bonus
    if fitting_bins_count == 1 { score -= 1.5; }
    else if fitting_bins_count > 1 { score -= 0.3 / fitting_bins_count as f64; }

    // Fragmentation pressure via open bins
    let mr = (mean_residual / cap).max(0.0);
    score += 0.25 * (1.0 - mr) * (open_bins_count as f64).sqrt() * 0.1;
    score -= 0.42 * (open_bins_count as f64).ln().max(0.0);

    // Tightness tie-break kernel
    let tightness = (res - it) / cap;
    score += 0.15 * tightness * tightness;

    // Waste-band shaping (from best heuristic, smoothed)
    if x > 0.14 && x < 0.34 { score += 13.0 * (x - 0.14) * (0.6 + 0.8 * progress); }
    if fitting_bins_count > 3 && x < 0.12 { score -= 5.5 * (1.0 - x * 8.0) * (0.5 + progress); }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect-ish fits (low post residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tightness * tightness * tightness;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly (or nearly) matches the next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 45.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        // Exact match bonus for chaining two items perfectly.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving a residual that the next item can never use
        // (post_residual smaller than smallest possible item but nonzero).
        if post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
            score += 30.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average when the
    // stream is late (fewer chances to consolidate).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let rel = (post_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 20.0 * rel * (0.5 + progress);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is
    // large and would leave a useful residual in a fresh bin.
    if bin_residual == bin_capacity {
        score += 15.0;
        if item_size >= 50 {
            score -= 20.0;
        }
        // Late in the stream, opening fresh bins is more wasteful.
        score += 25.0 * progress;
    }

    // Mild penalty for very large residual waste (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
