    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;

    // Base: post residual with mild non-linear scaling.
    let mut score = pr * (1.0 + 0.03 * (pr / cap) * (pr / cap));

    // Progress-aware tightness (combined quadratic + cubic ramp).
    let tightness = 1.0 + 2.6 * progress * progress + 2.4 * progress * progress * progress;
    score *= tightness;

    // Reward near-perfect fills.
    if pr == 0.0 {
        score -= 1000.0;
    } else if pr <= 5.0 {
        score -= 90.0 * (1.0 - 0.4 * progress);
    } else if pr <= 10.0 {
        score -= 40.0;
    }

    // 2-step lookahead with fine-grained chain anticipation.
    if nx > 0.0 {
        if pr == nx {
            score -= 500.0;
        } else if nx < pr {
            let chain_left = pr - nx;
            let frac = nx / pr;
            score -= 200.0 * frac * frac;
            if chain_left <= 5.0 {
                score -= 100.0;
            } else if chain_left <= 10.0 {
                score -= 40.0;
            }
            if chain_left <= 42.0 {
                score -= 6.5 + 0.11 * chain_left;
            }
            let slack = chain_left / cap;
            if slack < 0.04 {
                score -= 8.5 * (1.0 - slack * 25.0) * (1.0 + progress);
            }
            // Second-order chain: does the item after next also chain?
            let chain2 = chain_left - nx;
            if chain2 > 0.0 && chain2 <= 0.05 * cap {
                score -= 5.0 * (1.0 - chain2 / (0.05 * cap)) * (0.5 + progress);
            }
        } else {
            let gap = nx - pr;
            score += gap * (2.0 + 6.5 * (1.0 - progress));
            if gap <= 3.0 {
                score -= 9.0 * (1.0 - progress);
            }
            // Small dead space that next item almost fits: mild penalty.
            if gap <= 0.04 * cap {
                score += 3.5 * (1.0 - gap / (0.04 * cap)) * (0.5 + progress);
            }
        }
    }

    // Mean-residual comparison.
    let dev = mean_residual - pr;
    score -= 0.5 * dev;

    // Small residual band bonus.
    let dead_ratio = (pr / cap).max(0.0);
    if dead_ratio > 0.0 && dead_ratio < 0.12 {
        score -= 9.0 * (1.0 - dead_ratio / 0.12) * (0.4 + progress);
    }
    let unusable = if nx > 0.0 && pr > 0.0 && pr < nx { 1.0 } else { 0.55 };
    score += (10.5 + 3.2 * progress) * dead_ratio * dead_ratio * cap * (0.45 + progress) * unusable;

    // Waste band penalties (from best heuristic lineage).
    if dead_ratio > 0.14 && dead_ratio < 0.34 {
        score += 13.0 * (dead_ratio - 0.14) * (0.6 + 0.8 * progress);
    }
    if dead_ratio < 0.08 {
        score -= 48.0 * (1.0 - progress) * (0.08 - dead_ratio);
    }
    if pr > 0.0 && pr < 10.0 {
        score += 41.0 * (1.0 - 0.5 * progress);
    }
    if nx > 0.0 && pr > 0.0 && pr < nx {
        let closeness = 1.0 - pr / nx;
        score += 3.0 * closeness * closeness * (0.6 + progress);
    }
    if nx > 0.0 && pr >= nx {
        let room = pr - nx;
        if room < 0.06 * cap {
            score -= 6.5 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
        }
        if room > 0.04 * cap && room < 0.18 * cap {
            score -= 2.2 * (1.0 - room / (0.18 * cap)) * (0.3 + progress);
        }
        if room < 0.5 * nx && progress > 0.6 {
            score -= 2.8 * (1.0 - room / (0.5 * nx)) * progress;
        }
    }
    let fill_ratio = 1.0 - res / cap;
    if fill_ratio > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
    }
    if fill_ratio > 0.92 && pr > 0.0 {
        score -= 2.0 * (fill_ratio - 0.92) * 10.0 * (0.5 + progress);
    }

    // Last-chance bin.
    if fitting_bins_count == 1 {
        score -= 150.0 * (0.5 + progress);
    } else if fitting_bins_count > 3 && dead_ratio < 0.12 {
        score -= 5.5 * (1.0 - dead_ratio * 8.0) * (0.5 + progress);
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let item_frac = (it / cap).min(1.0);
        let mut nb = cap * (1.3 + 1.1 * progress);
