            }
        }
        if progress > 0.85 && mean_residual < 0.15 * cap {
            nb += 7.0 * progress * (1.0 - mean_residual / (0.15 * cap));
        }
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin < 0.15 * cap {
                nb -= 6.0 * (1.0 - margin / (0.15 * cap)) * (0.6 + 0.4 * progress);
            }
        }
        if fitting_bins_count >= 2 && mean_residual >= it + nx && progress > 0.4 {
            let rem = mean_residual - it - nx;
            if rem < 0.05 * cap {
                nb -= 4.5 * (1.0 - rem / (0.05 * cap)) * progress;
            }
        }
        if open_bins_count > 8 && mean_residual < 0.1 * cap && progress > 0.5 {
            nb -= 4.0 * (1.0 - mean_residual / (0.1 * cap)) * progress;
        }
        score = nb;
    }

    // Slight open-bin pressure to consolidate.
    score -= 0.42 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical items are wasted.
    if post_residual < 10 {
        score -= 8.0; // perfect close-out bonus
    } else if post_residual < 25 {
        score += 6.0; // awkward dead zone
    }

    // Last-chance bin: strongly prefer filling it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: bonus if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // next item won't fit here; slight penalty proportional to leftover
            score += 2.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let poor_fit = if post_residual < 20 { 1.0 } else { 0.0 };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening a new bin is penalized normally, but less when bins are scarce
        // or late in the stream with awkward residual structure.
        score += 20.0;
        score -= 30.0 * pressure;
        score -= 10.0 * poor_fit * (0.5 + 0.5 * progress);
        score -= 2.0 * (open_bins_count as f64).sqrt().ln().max(0.0);
    }

    // Global residual balance: prefer bins whose residual is below the mean
    // (fill the emptier-relative bins first, keeping big holes for big items).
    let diff = mean_residual - bin_residual as f64;
    score += 0.05 * diff;

    // Mild time-horizon modulation: early on, be conservative (favor balanced
    // fills); late, be aggressive (favor closing bins out).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

