}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo classes over capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Reward exact-fit classes (residual in {0, small harmonics}).
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else if post_residual < eighth {
        score -= 60.0;
    } else if post_residual < quarter {
        score -= 25.0;
    }

    // Modulo-10 class of post_residual: residuals divisible by 10 pair well
    // with typical item sizes drawn from wide distributions.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 5.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: does next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= (next_item_size as f64) * 0.5;
            // harmonic bonus if next item exactly consumes residual
            if next_item_size == post_residual {
                score -= 80.0;
            }
        } else {
            // next item won't fit here: penalize proportionally to waste
            score += (next_item_size as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Tightness reward: item fills a large fraction of the bin residual.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 20.0;

    // Encourage consolidation early, discourage hoarding many open bins late.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + progress);

    // Slight pull toward bins near the mean residual (balance load).
    score += (pr - mean_residual).abs() * 0.05;

    // New-bin candidate: only attractive when current item is large relative
    // to capacity or no open bin fits well.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / cap;
        if big_item > 0.7 || fitting_bins_count == 0 {
            score -= 45.0;
        } else {
            score += 25.0;
        }
    }

    score
}

