    if fill_ratio > 0.92 && pr > 0.0 {
        score -= 2.5 * (fill_ratio - 0.92) * 10.0 * (0.5 + progress);
    }
    // Waste-band bonus when residual is nearly unusable.
    if waste > 0.08 && waste < 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.12 * cap {
        score += 3.0 * (1.0 - (pr - nx) / (0.12 * cap)) * (0.5 + progress);
    }
    // Low-waste reward scaled by remaining stream (from best lineage).
    if waste < 0.08 {
        score -= 54.0 * (1.0 - progress) * (0.08 - waste);
    }
    // Mid-band chain gap bonus.
    if nx > 0.0 && pr > nx && (pr - nx) <= 0.04 * cap {
        score -= 3.8 * (1.0 - (pr - nx) / (0.04 * cap)) * (1.0 - progress);
    }
    // Small residual with next item far above: dead-space penalty.
    if pr > 0.0 && nx > 0.0 && pr < 0.5 * nx && progress > 0.3 {
        score += 4.0 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
    }
    // NEW: penalize dead space more when the bin is already very full and next item cannot use leftover.
    if pr > 0.0 && nx > 0.0 && pr < nx && fill_ratio > 0.8 {
        score += 5.0 * (fill_ratio - 0.8) * 10.0 * (0.3 + progress);
    }
    // NEW: reward bins whose leftover after placing item is a near-exact fit for next item.
    if nx > 0.0 && pr >= nx && (pr - nx) < 0.02 * cap {
        score -= 4.5 * (1.0 - (pr - nx) / (0.02 * cap)) * (0.4 + progress);
    }

    // Last-chance bin.
    if fitting_bins_count == 1 {
        score -= 160.0 * (0.5 + progress);
    } else if fitting_bins_count > 3 && waste < 0.12 {
        score -= 6.0 * (1.0 - waste * 8.0) * (0.5 + progress);
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let item_frac = (it / cap).min(1.0);
        let mut nb = cap * (1.3 + 1.1 * progress);
        nb -= 26.0 * scarcity * (1.0 - progress);
        nb -= 19.0 * item_frac * (1.0 - progress);
        if it >= 0.85 * cap && progress > 0.3 {
            nb -= 34.0 + 9.0 * progress;
        }
        if nx > 0.0 && cap - it >= nx {
            nb -= 11.5 + 0.11 * (cap - it - nx);
        }
        if nx > 0.0 {
            let r1 = cap - it;
            if r1 >= nx && (r1 - nx) < 6.0 && (r1 - nx) > 0.0 {
                nb += 8.5 * (1.0 - progress);
            }
            if r1 < nx && r1 > 0.0 {
                nb += (1.0 + 2.0 * progress) * (nx - r1) * 0.55;
            }
        }
        if nx >= 0.5 * cap {
            nb -= 12.0 * progress + 6.0 * (1.0 - progress);
        }
        nb += 15.0 * progress * (1.0 - item_frac);
        if fitting_bins_count <= 2 {
            nb += 21.0 + 10.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 4 {
            nb -= 7.5 + 9.0 * progress;
        }
        if nx > 0.0 && mean_residual >= it + nx && progress < 0.6 {
            nb += 5.5 * (1.0 - progress);
        }
        if nx > it && mean_residual >= nx && progress < 0.6 {
            nb += 10.0 * (1.0 - progress);
        }
        if waste > 0.6 {
            nb -= 100.0 * (waste - 0.6);
        }
        // Open-bin pressure: avoid new bin when mean residual is generous.
        if mean_residual >= it && progress > 0.5 {
            nb += 6.5 + 8.5 * progress;
        }
        if nx > 0.0 && mean_residual > nx + 8.0 && progress < 0.7 {
            nb += 8.5 * ((mean_residual - nx) / cap).min(0.5) * cap * 0.1;
        }
        if it / cap > 0.6 && nx > 0.0 && cap >= it + nx && cap - it - nx < 0.03 * cap {
            nb -= 5.5 * (1.0 - (cap - it - nx) / (0.03 * cap));
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_pr = (mean_residual - it).max(0.0);
            if best_pr > 0.0 && best_pr < 0.06 * cap && (cap - it) >= nx {
                nb -= 7.0 * (1.0 - best_pr / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if progress > 0.85 && mean_residual < 0.15 * cap {
            nb += 7.0 * progress * (1.0 - mean_residual / (0.15 * cap));
        }
        // Two-item packing margin — prefer new bin when fresh bin packs item+next nearly full.
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin < 0.05 * cap {
                nb -= 7.5 * (1.0 - margin / (0.05 * cap)) * (0.5 + progress);
            }
        }
        // Discourage new bin when mean residual can host item plus next.
        if nx > 0.0 && mean_residual >= it + nx && progress > 0.4 {
            let rem = mean_residual - it - nx;
            if rem < 0.08 * cap {
                nb += 5.0 * (1.0 - rem / (0.08 * cap)) * progress;
            }
        }
        // Many open bins with slack — avoid opening a new one.
        if open_bins_count > 6 && mean_residual > 0.35 * cap && progress < 0.6 {
            nb += 5.0 * ((mean_residual - 0.35 * cap) / cap) * (1.0 - progress)
                * ((open_bins_count as f64 - 6.0).min(8.0) / 8.0);
        }
        // Borrowed from best lineage: mean residual hosting item+next with tight leftover.
        if nx > 0.0 && fitting_bins_count >= 1 && mean_residual - it >= nx {
            let leftover = mean_residual - it - nx;
            if leftover < 0.1 * cap && progress > 0.45 {
                nb -= 5.0 * (1.0 - leftover / (0.1 * cap)) * progress;
            }
        }
        // Large next item: fresh bin less attractive.
        if nx > 0.0 && mean_residual < nx && progress > 0.55 && item_frac < 0.5 {
            nb += 3.5 * (nx - mean_residual).min(0.1 * cap) / (0.1 * cap) * progress;
        }
        // Stronger consolidation pressure late in the stream.
        if progress > 0.6 && open_bins_count > 4 && mean_residual >= it {
            nb += 4.5 * (progress - 0.6) * 5.0 * ((mean_residual - it) / cap).min(0.3);
        }
        // Prefer new bin for tiny items early only if no bin fits well.
        if item_frac < 0.1 && fitting_bins_count >= 3 && progress < 0.4 {
            nb += 6.0 * (1.0 - progress);
        }
        // NEW: discourage new bin when an open bin's post-fit residual exactly matches next item.
        if nx > 0.0 && fitting_bins_count >= 1 && (mean_residual - it) >= nx {
            let lr = mean_residual - it - nx;
            if lr < 3.0 {
                nb += 6.0 * (1.0 - lr / 3.0) * (0.5 + progress);
            }
        }
        score = nb;
    }

    // Slight open-bin pressure to consolidate.
    score -= 0.42 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: penalize large post_residual, especially dead space
    // that cannot fit typical small items.
    let dead = if post_residual > 0 && post_residual < 10 { 1.0 } else { 0.0 };
    score += dead * 500.0;

    // Fractional tightness term
    score += (post_residual as f64 / bin_capacity as f64) * 50.0;

    // Lookahead: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 120.0 - (gap as f64) * 2.0;
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // next item can't follow here but fits elsewhere; mild penalty
        score += 20.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 300.0;
    }

    // Prefer fullest bins (best-fit bias) relative to mean residual
    score += (mean_residual - bin_residual as f64) * 1.5;

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well (this call would have high post_residual or be
    // a poor fit) and stream still has plenty of items to fill it.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Fresh bin: penalize when many bins already open (avoid fragmentation)
        score += open_bins_count as f64 * 8.0;
        // Penalize more early in the stream (plenty of time to fill existing bins)
        score += (1.0 - progress) * 150.0;
        // But discount if the item is large and would leave awkward residue elsewhere
        if item_size > bin_capacity / 2 {
            score -= 60.0;
        }
    }

    // Congestion term: when many bins fit the item, be pickier (raise scores
    // uniformly via small term so relative ordering dominated by fit quality)
    if fitting_bins_count > 2 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear shaping
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals slightly; late, punish dead space harder.
    let shape = 1.0 + 0.5 * progress - 1.2 * progress * progress + 0.7 * progress * progress * progress;
    score *= shape;

    // Cubic penalty for very small residuals (dead space) scaled by progress
    score += (norm_pr * norm_pr * norm_pr) * cap * (0.4 + 0.6 * progress);

    // Lookahead: reward if next item fits the post residual (smooth quadratic reward)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        score -= 8.0 * (1.0 - gap / cap).max(0.0) * (1.0 - gap / cap);
        // penalize if next item barely misses
        if next_item_size as f64 > pr {
            score += 6.0 * (next_item_size as f64 - pr) / cap;
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.5 + 0.5 * progress);
    }

    // Mild reward for consolidating when many bins are open
    score -= 1.5 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * (mean_residual - pr).max(0.0) / cap * 10.0;

    // New-bin candidate: make empty bins mildly unattractive unless residuals are tight
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo small divisors.
    // Residues that are "nice" (small multiples near typical item sizes) are penalized less.
    let pr = post_residual;
    let mod5 = pr % 5;
    let mod10 = pr % 10;
    let mod20 = pr % 20;

    // Dead-space penalty: post_residual too small to ever fit (min item size 1..100 unknown, use 10 as anchor).
    if pr > 0 && pr < 10 {
        score += 40.0; // unusable sliver
    }

    // Harmonic reward: post_residual divisible by common item classes (10, 20, 25, 50)
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else {
        if pr % 10 == 0 { score -= 12.0; }
        if pr % 20 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 6.0; }
        if pr % 50 == 0 { score -= 10.0; }
    }

    // Penalize residues in awkward classes (mod 5 == 1..4 unevenly, favor 0 and 5)
    score += match mod5 {
        0 => -4.0,
        1 => 6.0,
        2 => 3.0,
        3 => 3.0,
        _ => 1.0,
    } as f64;

    // Lookahead coupling: does next_item_size fit the post_residual exactly or well?
    if next_item_size > 0 {
        if next_item_size <= pr {
            let next_post = pr - next_item_size;
            if next_post == 0 {
                score -= 25.0; // chains into a perfect fit
            } else if next_post % 10 == 0 {
                score -= 10.0;
            } else {
                score += (next_post % 10) as f64 * 0.5;
            }
            // Bonus if next item only fits here (last-chance synergy)
            if fitting_bins_count == 1 && next_item_size <= pr {
                score -= 15.0;
            }
        } else {
            // Next item won't fit here: leftover class matters more
            score += 5.0 + mod10 as f64;
        }
    }

    // Last chance bin for current item: strong preference to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current item leaves a clean harmonic residual
    if bin_residual == bin_capacity {
        let clean = item_size % 10 == 0;
        if clean {
            score -= 5.0;
        } else {
            score += 20.0 + (item_size % 10) as f64 * 2.0;
        }
        // Prefer opening new bins early in stream when few bins open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Mild pressure to consolidate when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Tightness reward: filling a bin deeply is good
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= fill * 15.0;

    // Deviation from mean residual: prefer bins whose residual is close to item need
    let dev = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 5.0 * post_residual as f64;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.05 * pressure * (1.0 - progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item cannot use the dead space left behind, penalize.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 20.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let decent_fit_exists = fitting_bins_count > 0 && mean_residual > item_size as f64 * 1.2;
        if decent_fit_exists {
            score += 45.0; // discourage opening new bin
        } else {
            score -= 10.0; // encourage fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/next-fit coupling: next item fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-step closure
        } else if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
            score += 0.3 * slack_after_next as f64; // mild penalty for leftover slack
        } else {
            // next item won't fit here; penalize proportionally to overshoot
            let over = next_item_size - post_residual;
            score += 0.5 * over as f64;
        }
    } else {
        // last item: just minimize waste
        score -= 10.0;
    }

    // Reward tight fits of the current item (small post_residual is good,
    // already captured by base, but amplify near-perfect fits).
    if post_residual <= 10 {
        score -= 15.0;
    }

    // Compare against mean residual: prefer bins whose residual deviates
    // favorably (using a below-average residual bin keeps big holes intact).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 0.1 * (bin_residual as f64 - mean_residual);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when the
    // item is large relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 30.0;
        score -= large_item_bonus;
        // discourage hoarding many open bins early in the stream
        score += 0.5 * open_bins_count as f64 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fits (small post_residual), with non-linear sharpening.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Lookahead: reward if the next item can exactly/nearly fill the post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use this residual; penalize wasted residual proportionally.
            score += 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Penalize leaving dead space that no plausible item (min size 1..10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // unusable sliver
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into existing bins rather than spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 8.0 * (mean_residual / bin_capacity as f64) * progress;
        score -= 2.0 * open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    }

    // New-bin candidate handling: make empty bins attractive only when the fit
    // into existing bins would be poor or when residual is large relative to item.
    if bin_residual == bin_capacity {
        // New bin starts with large residual; penalize unless item is large.
        score += 15.0 * (1.0 - item_size as f64 / bin_capacity as f64);
        // If existing bins are mostly full (low mean residual), opening fresh is fine.
        score -= 20.0 * (1.0 - mean_residual / bin_capacity as f64);
        // Late in the stream, opening a bin for a good fresh fit is cheap.
        score -= 10.0 * progress;
        // If no open bin fits well (this call would be the only alternative), soften.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Mild tie-breaking: prefer bins with residual close to mean (balance load).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
