    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Smooth polynomial coupling of post_residual with progress:
    // early on, prefer tight fits less aggressively; later, punish waste more.
    let waste_term = (norm_pr * norm_pr) * (1.0 + 2.0 * progress);
    score += 30.0 * waste_term;

    // Cubic coupling: heavily penalize mid-range residuals late in stream.
    score += 12.0 * (norm_pr * norm_pr * norm_pr) * (progress + 0.2);

    // Reward filling bins nearly exactly, scaled by progress.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - norm_pr);
    }

    // Lookahead: if next item fits into post-residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 8.0 * (1.0 - progress);
        } else {
            score += 4.0 * (next_item_size as f64) / cap * (1.0 + progress);
        }
    }

    // Penalize contributing to residual dispersion relative to mean.
    score += 5.0 * (pr - mean_residual).abs() / cap;

    // Mild penalty for opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * (open_bins_count as f64).sqrt() + 10.0 * progress;
    }

    score
}

