        if cls == 0 {
            score -= 6.0; // perfectly divisible residual -> reusable
        } else if post_residual < 10 {
            score += 30.0; // dead space below smallest item class
        } else if cls <= 3 {
            score += 8.0; // awkward small class
        }
    } else {
        score -= 12.0; // perfect closure of the bin
    }

    // Compatibility: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // exact harmonic match: next item exactly fills residual
            if next_item_size == post_residual {
                score -= 15.0;
            }
        } else {
            score += 5.0; // next item cannot use this bin's leftover
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral baseline, slightly worse than a good fit,
    // better than dumping into a bin that creates dead space.
    if bin_residual == bin_capacity {
        score = 40.0 - 0.1 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 3.0; // big-item stream favors fresh bins
        }
    }

    // Progress pressure: early in stream, be pickier about residual waste.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (post_residual as f64 / bin_capacity as f64) * 6.0;

    // Mean residual coupling: if this bin is far below mean residual, it's a
    // good filler; if far above, deprioritize.
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    // Tight-fit reward: residual close to item size means near-perfect packing.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;
    let waste = (pr / cap).max(0.0);

    // Base: post residual with mild non-linear scaling.
    let mut score = pr * (1.0 + 0.03 * waste * waste);

    // Progress-aware tightness (combined quadratic + cubic ramp).
    let tightness = 1.0 + 2.4 * progress * progress + 2.0 * progress * progress * progress;
    score *= tightness;

    // Reward near-perfect fills (slightly strengthened early).
    if pr == 0.0 {
        score -= 1100.0;
    } else if pr <= 5.0 {
        score -= 95.0 * (1.0 - 0.4 * progress);
    } else if pr <= 10.0 {
        score -= 42.0;
    }

    // 2-step lookahead with fine-grained chain anticipation.
    if nx > 0.0 {
        if pr == nx {
            score -= 580.0;
        } else if nx < pr {
            let chain_left = pr - nx;
            let frac = nx / pr;
            score -= 220.0 * frac * frac;
            if chain_left <= 5.0 {
                score -= 105.0;
            } else if chain_left <= 10.0 {
                score -= 42.0;
            }
            if chain_left <= 42.0 {
                score -= 6.5 + 0.11 * chain_left;
            }
            let slack = chain_left / cap;
            if slack < 0.04 {
                score -= 9.5 * (1.0 - slack * 25.0) * (1.0 + progress);
            }
            let chain = 1.0 - slack.min(1.0);
            score -= 5.0 + 4.0 * (nx / cap) + 10.5 * chain * (1.0 - progress);
            // Second-order chain: does the item after next also chain?
            let chain2 = chain_left - nx;
            if chain2 > 0.0 && chain2 <= 0.05 * cap {
                score -= 6.5 * (1.0 - chain2 / (0.05 * cap)) * (0.5 + progress);
            } else if chain2 > 0.05 * cap && chain2 <= 0.15 * cap {
                score -= 2.0 * (1.0 - (chain2 - 0.05 * cap) / (0.10 * cap)) * progress;
            }
        } else {
            let gap = nx - pr;
            score += gap * (2.0 + 6.5 * (1.0 - progress));
            if gap <= 3.0 {
                score -= 9.0 * (1.0 - progress);
            }
            if gap <= 0.04 * cap {
                score += 3.5 * (1.0 - gap / (0.04 * cap)) * (0.5 + progress);
            }
        }
    }

    // Mean-residual comparison.
    let dev = mean_residual - pr;
    score -= 0.5 * dev;

    // Small residual band bonus.
    if waste > 0.0 && waste < 0.12 {
        score -= 9.0 * (1.0 - waste / 0.12) * (0.4 + progress);
    }
    let unusable = if nx > 0.0 && pr > 0.0 && pr < nx { 1.0 } else { 0.55 };
    score += (10.5 + 3.2 * progress) * waste * waste * cap * (0.45 + progress) * unusable;

    // Waste band penalties (from best heuristic lineage).
    if waste > 0.14 && waste < 0.34 {
        score += 13.0 * (waste - 0.14) * (0.6 + 0.8 * progress);
    }
    if pr > 0.0 && pr < 10.0 {
        score += 41.0 * (1.0 - 0.5 * progress);
    }
    if nx > 0.0 && pr > 0.0 && pr < nx {
        let closeness = 1.0 - pr / nx;
        score += 3.0 * closeness * closeness * (0.6 + progress);
    }
    if nx > 0.0 && pr >= nx {
        let room = pr - nx;
        if room < 0.06 * cap {
            score -= 6.5 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
        }
        if room > 0.04 * cap && room < 0.18 * cap {
            score -= 2.2 * (1.0 - room / (0.18 * cap)) * (0.3 + progress);
        }
    }
    let fill_ratio = 1.0 - res / cap;
    if fill_ratio > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
    }
    if fill_ratio > 0.65 && pr > 0.0 {
        score -= 4.8 * (fill_ratio - 0.65) * 10.0 * (0.4 + progress);
    }
    if fill_ratio > 0.92 && pr > 0.0 {
        score -= 2.0 * (fill_ratio - 0.92) * 10.0 * (0.5 + progress);
    }
    // Waste-band bonus when residual is nearly unusable.
    if waste > 0.08 && waste < 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.12 * cap {
        score += 3.0 * (1.0 - (pr - nx) / (0.12 * cap)) * (0.5 + progress);
    }
    // Low-waste reward scaled by remaining stream (from best lineage).
    if waste < 0.08 {
        score -= 48.0 * (1.0 - progress) * (0.08 - waste);
    }
    // Mid-band chain gap bonus.
    if nx > 0.0 && pr > nx && (pr - nx) <= 0.04 * cap {
        score -= 3.2 * (1.0 - (pr - nx) / (0.04 * cap)) * (1.0 - progress);
    }
    // Small residual with next item far above: dead-space penalty.
    if pr > 0.0 && nx > 0.0 && pr < 0.5 * nx && progress > 0.3 {
        score += 3.5 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
    }
    // Penalize dead space more when the bin is already very full and next item cannot use leftover.
    if pr > 0.0 && nx > 0.0 && pr < nx && fill_ratio > 0.8 {
        score += 4.5 * (fill_ratio - 0.8) * 10.0 * (0.3 + progress);
    }
    // NEW: strong penalty for leaving a residual that next item cannot use at high fill.
    if pr > 0.0 && nx > 0.0 && pr < nx && fill_ratio > 0.7 {
        score += 2.5 * (fill_ratio - 0.7) * 10.0 * (0.4 + progress);
    }

    // Last-chance bin.
    if fitting_bins_count == 1 {
        score -= 150.0 * (0.5 + progress);
    } else if fitting_bins_count > 3 && waste < 0.12 {
        score -= 5.5 * (1.0 - waste * 8.0) * (0.5 + progress);
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let item_frac = (it / cap).min(1.0);
        let mut nb = cap * (1.3 + 1.1 * progress);
        nb -= 26.0 * scarcity * (1.0 - progress);
        nb -= 19.0 * item_frac * (1.0 - progress);
        if it >= 0.85 * cap && progress > 0.3 {
            nb -= 32.0 + 9.0 * progress;
        }
        if nx > 0.0 && cap - it >= nx {
            nb -= 10.5 + 0.11 * (cap - it - nx);
        }
        if nx > 0.0 {
            let r1 = cap - it;
            if r1 >= nx && (r1 - nx) < 6.0 && (r1 - nx) > 0.0 {
                nb += 8.5 * (1.0 - progress);
            }
            if r1 < nx && r1 > 0.0 {
                nb += (1.0 + 2.0 * progress) * (nx - r1) * 0.55;
            }
        }
        if nx >= 0.5 * cap {
            nb -= 12.0 * progress + 6.0 * (1.0 - progress);
        }
        nb += 15.0 * progress * (1.0 - item_frac);
        if fitting_bins_count <= 2 {
            nb += 21.0 + 10.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 4 {
            nb -= 6.5 + 8.5 * progress;
        }
        if nx > 0.0 && mean_residual >= it + nx && progress < 0.6 {
            nb += 5.5 * (1.0 - progress);
        }
        if nx > it && mean_residual >= nx && progress < 0.6 {
            nb += 10.0 * (1.0 - progress);
        }
        if waste > 0.6 {
            nb -= 100.0 * (waste - 0.6);
        }
        // Open-bin pressure: avoid new bin when mean residual is generous.
        if mean_residual >= it && progress > 0.5 {
            nb += 6.5 + 8.5 * progress;
        }
        if nx > 0.0 && mean_residual > nx + 8.0 && progress < 0.7 {
            nb += 8.5 * ((mean_residual - nx) / cap).min(0.5) * cap * 0.1;
        }
        if it / cap > 0.6 && nx > 0.0 && cap >= it + nx && cap - it - nx < 0.03 * cap {
            nb -= 5.5 * (1.0 - (cap - it - nx) / (0.03 * cap));
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_pr = (mean_residual - it).max(0.0);
            if best_pr > 0.0 && best_pr < 0.06 * cap && (cap - it) >= nx {
                nb -= 7.0 * (1.0 - best_pr / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if progress > 0.85 && mean_residual < 0.15 * cap {
            nb += 7.0 * progress * (1.0 - mean_residual / (0.15 * cap));
        }
        // Two-item packing margin — prefer new bin when fresh bin packs item+next nearly full.
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin < 0.05 * cap {
                nb -= 6.5 * (1.0 - margin / (0.05 * cap)) * (0.5 + progress);
            }
        }
        // Discourage new bin when mean residual can host item plus next.
        if nx > 0.0 && mean_residual >= it + nx && progress > 0.4 {
            let rem = mean_residual - it - nx;
            if rem < 0.08 * cap {
                nb += 5.0 * (1.0 - rem / (0.08 * cap)) * progress;
            }
        }
        // Many open bins with slack — avoid opening a new one.
        if open_bins_count > 6 && mean_residual > 0.35 * cap && progress < 0.6 {
            nb += 5.0 * ((mean_residual - 0.35 * cap) / cap) * (1.0 - progress)
                * ((open_bins_count as f64 - 6.0).min(8.0) / 8.0);
        }
        // Borrowed from best lineage: mean residual hosting item+next with tight leftover.
        if nx > 0.0 && fitting_bins_count >= 1 && mean_residual - it >= nx {
            let leftover = mean_residual - it - nx;
            if leftover < 0.1 * cap && progress > 0.45 {
                nb -= 5.0 * (1.0 - leftover / (0.1 * cap)) * progress;
            }
        }
        // Large next item: fresh bin less attractive.
        if nx > 0.0 && mean_residual < nx && progress > 0.55 && item_frac < 0.5 {
            nb += 3.5 * (nx - mean_residual).min(0.1 * cap) / (0.1 * cap) * progress;
        }
        // Stronger consolidation pressure late in the stream.
        if progress > 0.6 && open_bins_count > 4 && mean_residual >= it {
            nb += 4.0 * (progress - 0.6) * 5.0 * ((mean_residual - it) / cap).min(0.3);
        }
        // Prefer new bin for tiny items early only if no bin fits well.
        if item_frac < 0.1 && fitting_bins_count >= 3 && progress < 0.4 {
            nb += 6.0 * (1.0 - progress);
        }
        // NEW: avoid new bin when any open bin would end with near-zero residual.
        if nx > 0.0 && mean_residual >= it && (mean_residual - it) < 0.03 * cap {
            nb += 8.0 * (1.0 - (mean_residual - it) / (0.03 * cap)) * (0.5 + progress);
        }
        score = nb;
    }

    // Slight open-bin pressure to consolidate.
    score -= 0.42 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in the "unusable gap" zone
    // (1..10, too small for the minimum item) is heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    }
    // Perfect fit is maximally rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits relative to bin capacity (low waste ratio).
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Reward using bins that are already fairly full (residual close to item).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // opening a new bin (residual == capacity) should be penalized more
    // when open_bins_count is already high.
    if bin_residual == bin_capacity {
        score += 8.0 + (open_bins_count as f64) * 1.5;
    } else {
        score -= 5.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual,
    // reward this placement strongly (chained packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use the leftover: mild penalty for stranded space.
        score += 6.0;
    }

    // Mean-residual coupling: prefer bins below the mean residual
    // (i.e., filling the emptier bins less aggressively, keeping
    // large gaps available for large future items).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Early in the stream, be slightly more willing to open bins
    // (better global structure); late, conserve bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= progress * 6.0;
    }

    score
}

