    // (keeps residuals homogeneous), penalize outliers.
    let pr = post_residual as f64;
    let dev = (pr - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when a decent existing fit exists.
    if bin_residual == bin_capacity {
