        if nx > 0.0 && mean_residual < nx && progress > 0.55 && item_frac < 0.5 {
            nb += 3.5 * (nx - mean_residual).min(0.1 * cap) / (0.1 * cap) * progress;
        }
        // Stronger consolidation pressure late in the stream.
        if progress > 0.6 && open_bins_count > 4 && mean_residual >= it {
            nb += 4.0 * (progress - 0.6) * 5.0 * ((mean_residual - it) / cap).min(0.3);
        }
        // Prefer new bin for tiny items early only if no bin fits well.
        if item_frac < 0.1 && fitting_bins_count >= 3 && progress < 0.4 {
            nb += 6.0 * (1.0 - progress);
        }
        // NEW: fresh-bin two-item margin over a wider band, weighted by progress.
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin >= 0.05 * cap && margin < 0.15 * cap && progress > 0.3 {
                nb -= 5.0 * (1.0 - margin / (0.15 * cap)) * (0.5 + progress);
            }
        }
        // NEW: avoid new bin if the best open residual already yields a near-perfect fill.
        if fitting_bins_count >= 1 && mean_residual >= it {
            let best_pr = mean_residual - it;
            if best_pr <= 3.0 {
                nb += 12.0 * (1.0 - best_pr / 3.0) * (0.5 + progress);
            }
        }
        score = nb;
    }

    // Slight open-bin pressure to consolidate.
    score -= 0.42 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
