pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;

    // Base: minimize wasted residual, with non-linear polynomial shaping
    let mut score = pr_norm * pr_norm * (1.0 + 2.0 * progress) + pr_norm;

    // Reward tight fits: quadratic coupling of item size with post residual
