    score += dead * (0.5 + progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 5.0 + 4.0 * progress;
    }

    // Coupling with mean residual: prefer bins that reduce dispersion
    score += 0.5 * ((pr - mean_residual) / cap).powi(2);

    // Lookahead: if next item fits exactly into post_residual, reward heavily
