        let nxt = next_item_size as f64;
        if nxt <= pr {
            let snug = 1.0 - ((pr - nxt) / cap).abs();
            score -= 2.0 * snug * snug * (1.0 + progress);
        } else {
            score += 0.8 * (1.0 - pr_norm);
        }
