    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo common item sizes
    let capacity_frac = post_residual as f64 / bin_capacity as f64;

    // Penalize "awkward" residuals that few item sizes can use well.
    // Dead space classes: residual in (0,10) is nearly unusable (min item 1, but small items rare).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Modulo logic: residuals divisible by common small sizes (5, 10, 20, 25) are reusable.
    let reusable = (post_residual % 10 == 0) as f64
        + (post_residual % 5 == 0 && post_residual % 10 != 0) as f64 * 0.5
        + (post_residual % 25 == 0) as f64 * 0.5
        + (post_residual % 20 == 0) as f64 * 0.5;
    score -= 6.0 * reusable;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: does the next item fit exactly in the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // chain fit: excellent
