                score += 8.0;
            } else if slack % 10 == 0 {
                score -= 5.0;
            }
            score += slack * 0.15;
        } else {
            // next item cannot follow into this bin: mildly penalize wasting a good residual
            score += 4.0 * capacity_frac;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: baseline cost of opening a bin; prefer it only when
    // remaining open bins are fragmented (high mean residual spread).
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score = 45.0 + capacity_frac * 0.0
            - if mean_residual < 20.0 { 20.0 } else { 0.0 }
            + fragmentation * 0.2;
