        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
    }

    // Mild global pressure: many open bins -> prefer tight packing
    score += open_bins_count as f64 * 0.3;

    // Fractional threshold shaping: reward filling bins past half capacity
    if bin_residual as f64 <= bin_capacity as f64 * 0.5 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    score
}

