pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (unusable gaps).
    if post_residual > 0 {
        let dead_threshold = 10.0; // smallest item is 1..100, treat <10 as near-dead
        if (post_residual as f64) < dead_threshold {
            score += 60.0;
        } else if post_residual <= 15 {
            score += 25.0;
        } else if post_residual <= 25 {
            score += 8.0;
        } else {
            // reward leaving large, flexible residuals
            score -= (post_residual as f64) * 0.15;
        }
    } else {
        // perfect fit: strong reward
        score -= 40.0;
    }

    // Bonus if the leftover can exactly fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 20.0;
        if post_residual <= 10 {
            score -= 10.0; // still fine to fill nearly fully
        }
    } else if fitting_bins_count > 1 {
        // many options: prefer tight fits, discourage wasting a big residual
        score += (post_residual as f64) * 0.05;
    }

    // Open-bin pressure: many open bins -> favor consolidating into existing
    // bins rather than opening new ones.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    score -= open_pressure;

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Penalize the empty bin moderately by default.
    if bin_residual == bin_capacity {
        // base penalty so existing bins usually win
        score += 35.0;
        // but if open bins are fragmented (high mean residual spread) and many
        // bins are open, a fresh bin becomes more attractive
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: must open
        }
        if open_bins_count > 4 && mean_residual < 20.0 {
            score -= 25.0 * progress.max(0.5);
        }
        // large upcoming item favors a fresh empty bin
        if next_item_size >= 70 {
            score -= 15.0;
        }
    } else {
        // placing into an existing bin with a huge residual wastes capacity
        if post_residual >= 70 && item_size <= 20 {
            score += 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits strongly (non-linear).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let fit_ratio = post_residual as f64 / bin_capacity as f64;
        score += 200.0 * fit_ratio * fit_ratio;
    }

    // 2-step lookahead: reward when the next item fits the post-residual exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score += 0.5 * slack;
            // Bonus if next item fills bin completely after this placement.
            if post_residual == next_item_size {
                score -= 200.0;
            }
        } else {
            // Next item cannot use leftover; penalize dead space relative to mean residual.
            score += 2.0 * (post_residual as f64 - mean_residual).abs();
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably.
    if bin_residual == bin_capacity {
        score += 50.0;
        if fitting_bins_count > 0 && post_residual as f64 <= mean_residual {
            score += 100.0;
        }
        // Prefer new bin only if next item is large and would waste current bins.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 30.0;
        }
    }

    // Mild preference for tighter bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit here; slight penalty for wasting large residual.
            score += 3.0;
        }
    }

    // New-bin candidate handling: only prefer a fresh bin when the item fits
    // poorly everywhere else (large post_residual relative to capacity).
    if bin_residual == bin_capacity {
        let waste = post_residual as f64 / bin_capacity as f64;
        if waste > 0.5 {
            score -= 10.0 * waste; // opening a new bin is fine for big items
        } else {
            score += 30.0; // discourage opening bins for small items
        }
    }

    // Time horizon: early in the stream, be conservative with open bins;
    // later, consolidate to avoid bin proliferation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64).sqrt();

    // Prefer bins whose residual is close to the global mean residual (balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild preference for filling fuller bins overall.
    score -= 0.1 * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;

    // Base: penalize wasted space, but weight waste non-linearly by stream progress.
    let mut score = pr_norm * (1.0 + 1.5 * pr_norm * pr_norm);

    // Smooth progress coupling: waste matters more later in the stream.
    score += 2.0 * progress * pr_norm * pr_norm;

    // Reward tight fits (small post_residual) with a smooth saturating bonus.
    score -= (1.0 - pr_norm).powi(3) * (1.0 + fit_ratio);

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 3.0 * (1.0 + progress);
    } else {
        // Mild penalty when many bins fit: prefer consolidating into fewest bins.
        score += 0.15 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Dead-space penalty: post_residual too small for typical future items.
    let dead = ((12.0 - pr_norm * cap.min(100.0) / 10.0).max(0.0)) / 10.0;
    score += 0.8 * dead * (1.0 + progress);

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            // Perfect lookahead fit is very attractive.
            score -= 1.2 * (1.0 - gap / cap).max(0.0) * (1.0 - (gap / cap).abs() * 0.5);
        } else {
            score += 0.5 * (-gap / cap);
        }
    }

    // Prefer fuller bins relative to mean residual across open bins.
    score += 0.3 * (mean_residual - pr).max(0.0) / cap;

    // New-bin candidate: penalize opening a bin unless current bin would be badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = 1.0 - (pr_norm.min(1.0));
        score += 1.0 + 2.0 * (1.0 - fragmentation) + progress * 0.5;
    }

    // Count pressure: many open bins -> discourage spreading.
    score += 0.05 * open_bins_count as f64 / (total_items.max(1) as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residuals divisible by common item
    // sizes (5, 10, 20, 25) are reusable, odd/prime leftovers are dead space.
    let residual = post_residual;
    if residual == 0 {
        score -= 500.0; // perfect fit, always best
    } else {
        let class_bonus: f64 = if residual % 25 == 0 {
            40.0
        } else if residual % 20 == 0 {
            30.0
        } else if residual % 10 == 0 {
            20.0
        } else if residual % 5 == 0 {
            10.0
        } else {
            -15.0 // prime-ish leftover, hard to reuse
        };
        score -= class_bonus;

        // Small leftovers (<10) are dead space given min item size 1..100 unknown;
        // penalize tiny unusable gaps but keep perfect fits dominant.
        if residual < 5 {
            score += 25.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward; if next item is close, mild reward.
    if next_item_size > 0 {
        if next_item_size == residual {
            score -= 120.0;
        } else if next_item_size <= residual {
            score -= 20.0 * (1.0 - (residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: mild penalty proportional to overflow
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer opening a new bin only when all open fits would be very poor
    // (large post_residual fragmentation) or late in stream with many bins.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 60.0;
        // early in stream, new bins are cheap to open
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 40.0 * (1.0 - progress);
        // if many bins open and mean residual is high, opening new bin is worse
        score += (open_bins_count as f64).sqrt() * 4.0;
        if mean_residual > 30.0 {
            score += 15.0;
        }
    }

    // Prefer tighter bins overall: reward small bin_residual (best-fit flavor)
    score -= (bin_capacity - bin_residual) as f64 * 0.15;

    // Modulo class of item size: large items (harmonic class near capacity)
    // should go into bins where they leave class-aligned leftovers.
    let item_class = item_size % 10;
    if item_class == 0 && residual % 10 == 0 {
        score -= 12.0;
    }

    score
