            let chain = 1.0 - slack.min(1.0);
            score -= 5.0 + 4.0 * (nx / cap) + 9.5 * chain * (1.0 - progress);
            // Second-order chain: does the item after next also chain?
            let chain2 = chain_left - nx;
            if chain2 > 0.0 && chain2 <= 0.05 * cap {
                score -= 5.5 * (1.0 - chain2 / (0.05 * cap)) * (0.5 + progress);
            }
            // NEW: triple-chain anticipation — leftover after two next-items.
            let chain3 = chain_left - 2.0 * nx;
            if chain3 > 0.0 && chain3 <= 0.03 * cap {
                score -= 4.0 * (1.0 - chain3 / (0.03 * cap)) * (0.4 + progress);
            }
        } else {
            let gap = nx - pr;
            score += gap * (2.0 + 6.5 * (1.0 - progress));
            if gap <= 3.0 {
