    if fill_ratio > 0.65 && pr > 0.0 {
        score -= 4.8 * (fill_ratio - 0.65) * 10.0 * (0.4 + progress);
    }
    if fill_ratio > 0.92 && pr > 0.0 {
        score -= 2.0 * (fill_ratio - 0.92) * 10.0 * (0.5 + progress);
    }
    // Waste-band bonus when residual is nearly unusable.
    if waste > 0.08 && waste < 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.12 * cap {
        score += 3.0 * (1.0 - (pr - nx) / (0.12 * cap)) * (0.5 + progress);
    }
    // Low-waste reward scaled by remaining stream (from best lineage).
    if waste < 0.08 {
        score -= 48.0 * (1.0 - progress) * (0.08 - waste);
    }
    // Mid-band chain gap bonus.
    if nx > 0.0 && pr > nx && (pr - nx) <= 0.04 * cap {
        score -= 3.2 * (1.0 - (pr - nx) / (0.04 * cap)) * (1.0 - progress);
    }
    // Small residual with next item far above: dead-space penalty.
    if pr > 0.0 && nx > 0.0 && pr < 0.5 * nx && progress > 0.3 {
        score += 3.5 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
    }
    // Penalize dead space more when the bin is already very full and next item cannot use leftover.
    if pr > 0.0 && nx > 0.0 && pr < nx && fill_ratio > 0.8 {
        score += 4.5 * (fill_ratio - 0.8) * 10.0 * (0.3 + progress);
    }
    // NEW: exact-fit reward scaled by remaining stream length.
