            }
        }
        score = nb;
    }

    // Slight open-bin pressure to consolidate.
    score -= 0.42 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual relative to item size).
    let fit_ratio = post_residual as f64 / (bin_residual.max(1) as f64);
    score += fit_ratio * 60.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Penalize leaving dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 0.0; // tiny residual is fine (dead space small)
    } else if post_residual >= 10 && post_residual < 30 {
        score -= 5.0; // medium residual reusable
    }

    // Lookahead coupling: if next item fits into post_residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        // extra reward if next item fills bin almost exactly
        let nr = post_residual - next_item_size;
        if nr < 10 {
            score -= 20.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item won't fit here; slight penalty for awkward residual
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the fit
    // in existing bins is bad. New bin has residual == capacity.
    if bin_residual == bin_capacity {
        let base_penalty = 70.0;
        // More open bins => prefer packing into them.
        let crowding = (open_bins_count as f64).ln().max(0.0) * 6.0;
        // Late in stream, opening bins is cheaper to churn.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let time_adj = -progress * 15.0;
        // If many bins fit the item, opening new bin is wasteful.
        let waste_adj = (fitting_bins_count as f64) * 12.0;
        score += base_penalty + crowding + time_adj + waste_adj;
        // Large items relative to capacity justify a fresh bin.
        score -= (item_size as f64 / bin_capacity as f64) * 40.0;
    }

    // Global residual state: high mean residual means slack exists; prefer
    // consuming bins with residual above mean (reduce variance).
    if (bin_residual as f64) > mean_residual && bin_residual != bin_capacity {
        score -= 10.0;
    } else if (bin_residual as f64) < mean_residual {
        score += 5.0;
    }

    // Mild preference for bins with larger residuals generally (best-fit
    // counterweight: keeps small residuals for small future items).
    score -= (bin_residual as f64) * 0.15;

    score
}

