    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: minimize wasted space, with a non-linear penalty on small residuals
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, tightening residual space matters more
    let coupling = norm_post * (1.0 - progress) * (1.0 - progress)
                 + 0.5 * norm_post.powi(3) * progress;
    score += 20.0 * coupling;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 15.0 * tightness * (1.0 + progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let gap = post - next_item_size as f64;
        if gap > 0.0 {
