            let best_pr = (mean_residual - it).max(0.0);
            if best_pr > 0.0 && best_pr < 0.06 * cap && (cap - it) >= nx {
                nb -= 7.0 * (1.0 - best_pr / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if progress > 0.85 && mean_residual < 0.15 * cap {
            nb += 7.0 * progress * (1.0 - mean_residual / (0.15 * cap));
        }
        // Two-item packing margin.
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin < 0.05 * cap {
                nb -= 6.5 * (1.0 - margin / (0.05 * cap)) * (0.5 + progress);
            }
        }
        if nx > 0.0 && mean_residual >= it + nx && progress > 0.4 {
            let rem = mean_residual - it - nx;
            if rem < 0.08 * cap {
                nb += 5.0 * (1.0 - rem / (0.08 * cap)) * progress;
            }
        }
        if open_bins_count > 6 && mean_residual > 0.35 * cap && progress < 0.6 {
            nb += 5.0 * ((mean_residual - 0.35 * cap) / cap) * (1.0 - progress)
                * ((open_bins_count as f64 - 6.0).min(8.0) / 8.0);
        }
        if nx > 0.0 && fitting_bins_count >= 1 && mean_residual - it >= nx {
            let leftover = mean_residual - it - nx;
            if leftover < 0.1 * cap && progress > 0.45 {
                nb -= 5.0 * (1.0 - leftover / (0.1 * cap)) * progress;
            }
        }
        if nx > 0.0 && mean_residual < nx && progress > 0.55 && item_frac < 0.5 {
            nb += 3.5 * (nx - mean_residual).min(0.1 * cap) / (0.1 * cap) * progress;
        }
        // Stronger consolidation pressure late in the stream.
        if progress > 0.6 && open_bins_count > 4 && mean_residual >= it {
            nb += 4.0 * (progress - 0.6) * 5.0 * ((mean_residual - it) / cap).min(0.3);
        }
        // Prefer new bin for tiny items early only if no bin fits well.
        if item_frac < 0.1 && fitting_bins_count >= 3 && progress < 0.4 {
            nb += 6.0 * (1.0 - progress);
        }
        // NEW: two-item margin widened with progress — fresh bins that pack item+next almost full are very attractive.
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin < 0.12 * cap {
                nb -= 4.0 * (1.0 - margin / (0.12 * cap)) * (0.3 + 0.7 * progress);
            }
        }
        // NEW: avoid new bin when mean residual can host item+next with small leftover.
        if nx > 0.0 && mean_residual >= it + nx {
            let rem = mean_residual - it - nx;
            if rem < 0.05 * cap {
                nb += 6.0 * (1.0 - rem / (0.05 * cap)) * (0.4 + progress);
            }
        }
        // NEW: avoid new bin when open bins are plentiful and slack is generous.
        if open_bins_count > 8 && mean_residual > 0.45 * cap {
            nb += 4.5 * ((mean_residual - 0.45 * cap) / cap).min(0.3) * 10.0 * ((open_bins_count as f64 - 8.0).min(6.0) / 6.0) * (0.5 + progress);
        }
        score = nb;
    }

    // Slight open-bin pressure to consolidate.
    score -= 0.42 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that pair well with common item sizes
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit gets a huge reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty: residuals too small for the smallest plausible item (<=5)
        if post_residual <= 5 {
            score -= 200.0; // small dead space is actually great (near-full bin)
        } else {
            // penalize residuals that are "awkward" — not expressible as a sum of
            // typical item sizes; use modulo classes on capacity fractions
            let quarter = (bin_capacity / 4) as f64;
            let residue_mod = (post_residual % 10) as f64;
            score += residue_mod * 1.5; // misalignment with decile classes

            // reward residuals in "good" harmonic classes: multiples of 10, 20, 25
            if post_residual % 10 == 0 {
                score -= 15.0;
            }
            if post_residual % 25 == 0 {
                score -= 10.0;
            }
            // penalize the worst class: residual just above a small item size
            // (e.g. 11..19 wastes capacity relative to 10)
            if (11..=19).contains(&post_residual) {
                score += 20.0;
            }
            if (21..=24).contains(&post_residual) || (26..=29).contains(&post_residual) {
                score += 8.0;
            }
        }
    }

    // Lookahead coupling: does post_residual accommodate next_item_size exactly or well?
    if next_item_size > 0 && post_residual > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 300.0; // chains perfectly
        } else if next_item_size < post_residual {
            let chain_waste = (post_residual - next_item_size) as f64;
            // reward chains whose leftover is again in a good class
            let chain_bonus = 40.0 * (1.0 - chain_waste / cap);
            score -= chain_bonus;
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // next item cannot follow here; residual is terminal — mild penalty
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 50.0;
    } else if fitting_bins_count > 1 {
        // when many bins fit, prefer tighter fits (post_residual already does this)
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: only attractive when open bins would leave terrible waste
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else {
            (mean_residual - pr).max(0.0)
        };
        // base cost of opening a new bin, discounted late in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = cap * 0.9 - progress * 30.0;
        // if next item is large, a fresh bin may be wise
        if next_item_size >= bin_capacity / 2 {
            new_bin_score -= 40.0;
        }
        // if the best existing fit would strand >40% of capacity, new bin competitive
        if post_residual > 0 && pr > 0.4 * cap && fitting_bins_count > 0 {
            new_bin_score -= 25.0;
        }
        score = score.min(new_bin_score + pressure * 0.1);
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins first)
    score += (mean_residual - pr) * 0.05;

    // Mild exploration term via integer-division threshold on item class
    let item_class = item_size / 10;
    if post_residual >= item_size && post_residual < item_size + item_class {
        score -= 3.0; // near-exact class fill
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;

    let mut score = pr * (1.0 + 0.03 * (pr / cap) * (pr / cap));

    let tightness = 1.0 + 2.6 * progress * progress + 2.4 * progress * progress * progress;
    score *= tightness;

    if pr == 0.0 {
        score -= 1000.0;
    } else if pr <= 5.0 {
        score -= 90.0 * (1.0 - 0.4 * progress);
    } else if pr <= 10.0 {
        score -= 40.0;
    }

    if nx > 0.0 {
        if pr == nx {
            score -= 500.0;
        } else if nx < pr {
            let chain_left = pr - nx;
            let frac = nx / pr;
            score -= 200.0 * frac * frac;
            if chain_left <= 5.0 {
                score -= 100.0;
            } else if chain_left <= 10.0 {
                score -= 40.0;
            }
            if chain_left <= 42.0 {
                score -= 6.5 + 0.11 * chain_left;
            }
            let slack = chain_left / cap;
            if slack < 0.04 {
                score -= 8.5 * (1.0 - slack * 25.0) * (1.0 + progress);
            }
            let chain = 1.0 - slack.min(1.0);
            score -= 5.0 + 4.0 * (nx / cap) + 9.5 * chain * (1.0 - progress);
            let chain2 = chain_left - nx;
            if chain2 > 0.0 && chain2 <= 0.05 * cap {
                score -= 5.0 * (1.0 - chain2 / (0.05 * cap)) * (0.5 + progress);
            }
        } else {
            let gap = nx - pr;
            score += gap * (2.0 + 6.5 * (1.0 - progress));
            if gap <= 3.0 {
                score -= 9.0 * (1.0 - progress);
            }
            if gap <= 0.04 * cap {
                score += 3.5 * (1.0 - gap / (0.04 * cap)) * (0.5 + progress);
            }
        }
    }

    let dev = mean_residual - pr;
    score -= 0.5 * dev;

    let dead_ratio = (pr / cap).max(0.0);
    if dead_ratio > 0.0 && dead_ratio < 0.12 {
        score -= 9.0 * (1.0 - dead_ratio / 0.12) * (0.4 + progress);
    }
    let unusable = if nx > 0.0 && pr > 0.0 && pr < nx { 1.0 } else { 0.55 };
    score += (10.5 + 3.2 * progress) * dead_ratio * dead_ratio * cap * (0.45 + progress) * unusable;

    if dead_ratio > 0.14 && dead_ratio < 0.34 {
        score += 13.0 * (dead_ratio - 0.14) * (0.6 + 0.8 * progress);
    }
    if pr > 0.0 && pr < 10.0 {
        score += 41.0 * (1.0 - 0.5 * progress);
    }
    if nx > 0.0 && pr > 0.0 && pr < nx {
        let closeness = 1.0 - pr / nx;
        score += 3.0 * closeness * closeness * (0.6 + progress);
        if nx - pr > 0.1 * cap && dead_ratio > 0.25 {
            score += 5.0 * (dead_ratio - 0.25) * 10.0 * (0.4 + progress);
        }
    }
    if nx > 0.0 && pr >= nx {
        let room = pr - nx;
        if room < 0.06 * cap {
            score -= 6.5 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
        }
        if room > 0.04 * cap && room < 0.18 * cap {
            score -= 2.2 * (1.0 - room / (0.18 * cap)) * (0.3 + progress);
        }
    }
    let fill_ratio = 1.0 - res / cap;
    if fill_ratio > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
    }
    if fill_ratio > 0.92 && pr > 0.0 {
        score -= 2.0 * (fill_ratio - 0.92) * 10.0 * (0.5 + progress);
    }
    // Fine-grained residual band: reward near-exact chain fits.
    if nx > 0.0 && pr >= nx && (pr - nx) <= 0.04 * cap {
        score -= 3.2 * (1.0 - (pr - nx) / (0.04 * cap)) * (1.0 - progress);
    }
    if pr > 0.0 && nx > 0.0 && pr < 0.5 * nx && progress > 0.3 {
        score += 3.5 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
    }

    if fitting_bins_count == 1 {
        score -= 150.0 * (0.5 + progress);
    } else if fitting_bins_count > 3 && dead_ratio < 0.12 {
        score -= 5.5 * (1.0 - dead_ratio * 8.0) * (0.5 + progress);
    }

    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let item_frac = (it / cap).min(1.0);
        let mut nb = cap * (1.3 + 1.1 * progress);
        nb -= 26.0 * scarcity * (1.0 - progress);
        nb -= 19.0 * item_frac * (1.0 - progress);
        if it >= 0.85 * cap && progress > 0.3 {
            nb -= 32.0 + 9.0 * progress;
        }
        if nx > 0.0 && cap - it >= nx {
            nb -= 10.5 + 0.11 * (cap - it - nx);
        }
        if nx > 0.0 {
            let r1 = cap - it;
            if r1 >= nx && (r1 - nx) < 6.0 && (r1 - nx) > 0.0 {
                nb += 8.5 * (1.0 - progress);
            }
            if r1 < nx && r1 > 0.0 {
                nb += (1.0 + 2.0 * progress) * (nx - r1) * 0.55;
            }
            if r1 >= nx && (r1 - nx) > 0.25 * cap && progress > 0.45 {
                nb += 4.5 * ((r1 - nx) / cap).min(0.5) * progress;
            }
        }
        if nx >= 0.5 * cap {
            nb -= 12.0 * progress + 6.0 * (1.0 - progress);
        }
        nb += 15.0 * progress * (1.0 - item_frac);
        if fitting_bins_count <= 2 {
            nb += 21.0 + 10.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 4 {
            nb -= 6.5 + 8.5 * progress;
        }
        if nx > 0.0 && mean_residual >= it + nx && progress < 0.6 {
            nb += 5.5 * (1.0 - progress);
        }
        if nx > it && mean_residual >= nx && progress < 0.6 {
            nb += 10.0 * (1.0 - progress);
        }
        if dead_ratio > 0.6 {
            nb -= 100.0 * (dead_ratio - 0.6);
        }
        if mean_residual >= it && progress > 0.5 {
            nb += 6.5 + 8.5 * progress;
        }
        if nx > 0.0 && mean_residual > nx + 8.0 && progress < 0.7 {
            nb += 8.5 * ((mean_residual - nx) / cap).min(0.5) * cap * 0.1;
        }
        if it / cap > 0.6 && nx > 0.0 && cap >= it + nx && cap - it - nx < 0.03 * cap {
            nb -= 5.5 * (1.0 - (cap - it - nx) / (0.03 * cap));
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_pr = (mean_residual - it).max(0.0);
            if best_pr > 0.0 && best_pr < 0.06 * cap && (cap - it) >= nx {
                nb -= 7.0 * (1.0 - best_pr / (0.06 * cap)) * (0.5 + progress);
            }
            let best_post = (mean_residual - it).max(0.0);
            if best_post >= nx && best_post - nx > 0.18 * cap && progress > 0.35 {
                nb -= 6.0 * ((best_post - nx) / cap).min(0.4) * (0.4 + progress);
            }
        }
        if progress > 0.85 && mean_residual < 0.15 * cap {
            nb += 7.0 * progress * (1.0 - mean_residual / (0.15 * cap));
        }
        if item_frac > 0.45 && item_frac < 0.75 && progress > 0.5 {
            nb -= 5.0 * (item_frac - 0.45) * progress;
        }
        if item_frac < 0.15 && progress > 0.55 && fitting_bins_count >= 1 {
            nb += 6.0 * progress * (1.0 - item_frac / 0.15);
        }
        if open_bins_count > 10 && progress < 0.35 && item_frac < 0.3 {
            nb += 6.0 * (1.0 - progress) * (1.0 - item_frac / 0.3);
        }
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin < 0.15 * cap {
                nb -= 6.0 * (1.0 - margin / (0.15 * cap)) * (0.6 + 0.4 * progress);
            }
        }
        if nx > 0.0 && fitting_bins_count >= 1 && mean_residual >= it + nx {
            let leftover = mean_residual - it - nx;
            if leftover < 0.1 * cap && progress > 0.45 {
                nb -= 5.0 * (1.0 - leftover / (0.1 * cap)) * progress;
            }
        }
        score = nb;
    }

    score -= 0.42 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is smaller than the smallest plausible item (>=1),
    // but practically we treat gaps below ~10 as nearly useless and gaps
    // below 20 as risky.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 60.0; // almost certainly wasted space
    } else if pr < 20.0 {
        score += 25.0; // risky small gap
    } else if pr == 0.0 {
        score -= 40.0; // perfect fit: reward strongly
    } else {
        // Smooth quadratic penalty on leftover to prefer tight fits
        score += 0.08 * pr * pr / bin_capacity as f64;
    }

    // Reward filling bins that are already substantially loaded
    // (encourage closing bins out rather than spreading across many).
    let fill_ratio = (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: with many open bins, prefer reusing existing ones
    // over opening new bins; the new-bin candidate will get this penalty too
    // but the extra term below hits it harder.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bonus: if this is the only bin that fits the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 55.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // reward this placement (chaining); if next item cannot use the gap,
    // slight penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 10.0;
        }
    }

    // New-bin candidate handling: an empty bin has post_residual == bin_residual == capacity.
    // Opening a new bin is only desirable when existing bins would leave bad gaps.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin grows with stream progression
        // (early on, spreading is fine; late, consolidation matters).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 40.0 * progress;

        // If the item is large, a fresh bin is natural; soften the penalty.
        if item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
        // If many bins can fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 2 {
            score += 30.0;
        }
    }

    // Mild deviation from mean residual: prefer bins whose residual is
    // below average (more loaded) to balance toward fewer open bins.
    score += 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
