    }
    if nx > 0.0 && pr > 0.0 && pr < nx {
        let closeness = 1.0 - pr / nx;
        score += 3.0 * closeness * closeness * (0.6 + progress);
    }
    if nx > 0.0 && pr >= nx {
        let room = pr - nx;
        if room < 0.06 * cap {
            score -= 6.5 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
        }
        if room > 0.04 * cap && room < 0.18 * cap {
            score -= 2.2 * (1.0 - room / (0.18 * cap)) * (0.3 + progress);
        }
    }
    let fill_ratio = 1.0 - res / cap;
    if fill_ratio > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
    }
    if fill_ratio > 0.65 && pr > 0.0 {
        score -= 4.8 * (fill_ratio - 0.65) * 10.0 * (0.4 + progress);
    }
    if fill_ratio > 0.92 && pr > 0.0 {
        score -= 2.0 * (fill_ratio - 0.92) * 10.0 * (0.5 + progress);
    }
    if waste > 0.08 && waste < 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.12 * cap {
        score += 3.0 * (1.0 - (pr - nx) / (0.12 * cap)) * (0.5 + progress);
    }
    if waste < 0.08 {
        score -= 48.0 * (1.0 - progress) * (0.08 - waste);
    }
    if nx > 0.0 && pr > nx && (pr - nx) <= 0.04 * cap {
        score -= 3.2 * (1.0 - (pr - nx) / (0.04 * cap)) * (1.0 - progress);
    }
    if pr > 0.0 && nx > 0.0 && pr < 0.5 * nx && progress > 0.3 {
        score += 3.5 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
    }
    if pr > 0.0 && nx > 0.0 && pr < nx && fill_ratio > 0.8 {
        score += 4.5 * (fill_ratio - 0.8) * 10.0 * (0.3 + progress);
    }

    if fitting_bins_count == 1 {
        score -= 150.0 * (0.5 + progress);
    } else if fitting_bins_count > 3 && waste < 0.12 {
        score -= 5.5 * (1.0 - waste * 8.0) * (0.5 + progress);
    }

    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let item_frac = (it / cap).min(1.0);
        let mut nb = cap * (1.3 + 1.1 * progress);
        nb -= 26.0 * scarcity * (1.0 - progress);
        nb -= 19.0 * item_frac * (1.0 - progress);
        if it >= 0.85 * cap && progress > 0.3 {
            nb -= 32.0 + 9.0 * progress;
        }
        if nx > 0.0 && cap - it >= nx {
            nb -= 10.5 + 0.11 * (cap - it - nx);
        }
        if nx > 0.0 {
            let r1 = cap - it;
            if r1 >= nx && (r1 - nx) < 6.0 && (r1 - nx) > 0.0 {
                nb += 8.5 * (1.0 - progress);
            }
            if r1 < nx && r1 > 0.0 {
                nb += (1.0 + 2.0 * progress) * (nx - r1) * 0.55;
            }
        }
        if nx >= 0.5 * cap {
            nb -= 12.0 * progress + 6.0 * (1.0 - progress);
        }
        nb += 15.0 * progress * (1.0 - item_frac);
        if fitting_bins_count <= 2 {
            nb += 21.0 + 10.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 4 {
            nb -= 6.5 + 8.5 * progress;
        }
        if nx > 0.0 && mean_residual >= it + nx && progress < 0.6 {
            nb += 5.5 * (1.0 - progress);
        }
        if nx > it && mean_residual >= nx && progress < 0.6 {
            nb += 10.0 * (1.0 - progress);
        }
        if waste > 0.6 {
            nb -= 100.0 * (waste - 0.6);
        }
        if mean_residual >= it && progress > 0.5 {
            nb += 6.5 + 8.5 * progress;
        }
        if nx > 0.0 && mean_residual > nx + 8.0 && progress < 0.7 {
            nb += 8.5 * ((mean_residual - nx) / cap).min(0.5) * cap * 0.1;
        }
        if it / cap > 0.6 && nx > 0.0 && cap >= it + nx && cap - it - nx < 0.03 * cap {
            nb -= 5.5 * (1.0 - (cap - it - nx) / (0.03 * cap));
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_pr = (mean_residual - it).max(0.0);
            if best_pr > 0.0 && best_pr < 0.06 * cap && (cap - it) >= nx {
                nb -= 7.0 * (1.0 - best_pr / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if progress > 0.85 && mean_residual < 0.15 * cap {
            nb += 7.0 * progress * (1.0 - mean_residual / (0.15 * cap));
        }
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin < 0.05 * cap {
                nb -= 6.5 * (1.0 - margin / (0.05 * cap)) * (0.5 + progress);
            }
        }
        if nx > 0.0 && mean_residual >= it + nx && progress > 0.4 {
            let rem = mean_residual - it - nx;
            if rem < 0.08 * cap {
                nb += 5.0 * (1.0 - rem / (0.08 * cap)) * progress;
            }
        }
        if open_bins_count > 6 && mean_residual > 0.35 * cap && progress < 0.6 {
            nb += 5.0 * ((mean_residual - 0.35 * cap) / cap) * (1.0 - progress)
                * ((open_bins_count as f64 - 6.0).min(8.0) / 8.0);
        }
        if nx > 0.0 && fitting_bins_count >= 1 && mean_residual - it >= nx {
            let leftover = mean_residual - it - nx;
            if leftover < 0.1 * cap && progress > 0.45 {
                nb -= 5.0 * (1.0 - leftover / (0.1 * cap)) * progress;
            }
        }
        if nx > 0.0 && mean_residual < nx && progress > 0.55 && item_frac < 0.5 {
            nb += 3.5 * (nx - mean_residual).min(0.1 * cap) / (0.1 * cap) * progress;
        }
        if progress > 0.6 && open_bins_count > 4 && mean_residual >= it {
            nb += 4.0 * (progress - 0.6) * 5.0 * ((mean_residual - it) / cap).min(0.3);
        }
        if item_frac < 0.1 && fitting_bins_count >= 3 && progress < 0.4 {
            nb += 6.0 * (1.0 - progress);
        }
        // MUTATION: stronger two-item tightness — fresh bin very attractive when item+next nearly fill it.
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin < 0.02 * cap {
                nb -= 9.0 * (1.0 - margin / (0.02 * cap)) * (0.4 + progress);
            }
        }
        // MUTATION: discourage new bin when some open bin would end with near-zero residual.
        if nx > 0.0 && fitting_bins_count >= 1 && mean_residual >= it {
            let best_post = (mean_residual - it).max(0.0);
            if best_post > 0.0 && best_post < 0.03 * cap {
                nb += 6.0 * (1.0 - best_post / (0.03 * cap)) * (0.5 + progress);
            }
        }
        // MUTATION: late-stream consolidation — new bins heavily discouraged when many bins hold slack.
        if progress > 0.7 && open_bins_count > 5 && mean_residual > 0.25 * cap {
            nb += 6.0 * (progress - 0.7) * 10.0 * ((mean_residual - 0.25 * cap) / cap)
                * ((open_bins_count as f64 - 5.0).min(6.0) / 6.0);
        }
        // MUTATION: small items early — prefer existing bins to preserve fresh capacity.
        if item_frac < 0.15 && progress < 0.5 && fitting_bins_count >= 2 {
            nb += 5.0 * (1.0 - item_frac / 0.15) * (1.0 - progress);
        }
        score = nb;
    }

    score -= 0.42 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), but penalize very tiny dead space less than mid-range waste
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Lookahead: if next item fits exactly into post_residual, strongly reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (next_item_size as u32) == post_residual {
            score -= 45.0; // perfect 2-chain
        } else if next_item_size < post_residual {
            let slack = pr - nxt;
            score -= 20.0 * (1.0 - slack / cap);
            score += 0.15 * slack; // mild penalty for leftover slack after chain
        } else {
            // next item cannot fit here; waste becomes dead unless small
            if pr < 10.0 {
                score -= 8.0; // negligible dead space
            } else {
                score += 0.3 * (pr - 10.0).min(30.0); // penalize unusable mid waste
            }
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are precious; filling them is good
    let dev = mean_residual - bin_residual as f64;
    score += 0.1 * dev;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless current bin fit is terrible
    if bin_residual == bin_capacity {
        score += cap * 0.5 + 20.0;
        // but allow new bin if item is huge and would leave bad residual anywhere
        if item_size as f64 > 0.8 * cap {
            score -= 60.0;
        }
    }

    // Slight preference to keep many bins balanced early in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * (1.0 - progress) * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize residual relative to item size.
    if item_size > 0 {
        score -= (item_size as f64) * (1.0 - (post_residual as f64) / (bin_capacity as f64));
    }

    // Dead-space penalty: small post-residuals that can't fit typical items are bad,
    // but zero residual is perfect.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item would still fit in the post-residual, reward;
    // if placing here blocks the next item while another bin could take both, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if bin_residual >= next_item_size && next_item_size > post_residual {
            score += 6.0;
        }
        // If next item exactly fills post residual, big reward (perfect chain).
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Time horizon: early in stream, be conservative (keep bins flexible);
    // late in stream, prefer filling bins aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.5;

    // Global state: many open bins with high mean residual -> encourage consolidation.
    if open_bins_count > 2 && mean_residual > (item_size as f64) {
        score -= 4.0;
    }

    // New-bin candidate: opening a new bin is only attractive when no open bin fits well.
    // Penalize new bins mildly, more so when fitting bins exist and residual is small.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score = waste + 10.0;
        if fitting_bins_count >= 1 {
            score += 30.0;
        }
        // Late in stream, opening new bins is cheaper than fragmenting old ones.
        score -= progress * 15.0;
        // If next item is huge, a fresh bin is valuable.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
