}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + progress * norm_pr * (1.0 - progress));

    // Reward tight fits (low post_residual), increasingly as stream advances
    let mut score = poly * (1.0 + 2.0 * progress);

    // Penalize dead space that can't hold the next item (smooth interaction)
    let waste = (pr - norm_next * cap).max(0.0) / cap;
    score += waste * waste * 4.0;

    // Last-chance bonus: strongly prefer the only bin that fits
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64) * 0.05 * (1.0 - progress);

    // Penalize deviating from mean residual (balance bins smoothly)
    score += ((pr - mean_residual) / cap).abs() * 0.5;

    // New-bin candidate: prefer it only when post_residual is large
    if bin_residual == bin_capacity {
        score = pr + 20.0 * (1.0 - norm_item);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
