pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls on "nice"
    // capacity fractions (1/4, 1/3, 1/2 of capacity) are more reusable.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;

    if post_residual == 0 {
        score -= 60.0; // perfect closure is always best
    } else {
        // Penalize tiny dead space (< quarter) strongly: unusable slivers.
        if post_residual < quarter {
            score += 35.0;
            // harmonic penalty: residue mod quarter near zero means it
            // could still combine with small items; mod-far is worse.
            let m = post_residual % (quarter.max(1));
            if m == 0 { score -= 10.0; }
        } else {
            // Reward residuals that align with common item-compatible classes
            if post_residual == quarter || post_residual == third
                || post_residual == half || post_residual == bin_capacity {
                score -= 25.0;
            }
            // Integer-division threshold: residual in [quarter, half) is a
            // healthy mid-class; in [half, cap) is excellent.
            if post_residual / quarter >= 2 { score -= 12.0; }
            if post_residual / quarter >= 3 { score -= 8.0; }
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0;
        if next_item_size == post_residual { score -= 22.0; }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here: mild penalty scaled by waste
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when current item is large
    // relative to capacity (would leave open bins with big residuals anyway),
    // or when many bins are already open and this fit is tight.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // Large items justify fresh bins.
        if item_size > half { score -= 30.0; }
        if item_size > 3 * quarter { score -= 15.0; }
        // If no open bin is a good fit (all would leave slivers), new bin ok.
        if mean_residual < item_size as f64 * 1.1 && open_bins_count > 0 {
            score -= 20.0;
        }
        // Late in the stream, avoid bin proliferation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        // Modulo harmonic: item in the top octile of capacity packs cleanly
        // into a fresh bin.
        if item_size % quarter == 0 && item_size >= quarter { score -= 10.0; }
    }

    // Slight preference for tighter existing bins as more bins accumulate.
    score += (open_bins_count as f64) * (post_residual as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space): residuals that are too small
    // to be useful for future items but nonzero.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += (25 - post_residual) as f64 * 1.5;
    }

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Open bins pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 2.0 * (0.5 + progress);

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (consolidating space into tighter bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;
    let waste = (pr / cap).max(0.0);

    // Base: post residual with mild non-linear scaling.
    let mut score = pr * (1.0 + 0.03 * waste * waste);

    // Progress-aware tightness (combined quadratic + cubic ramp).
    let tightness = 1.0 + 2.6 * progress * progress + 2.3 * progress * progress * progress;
    score *= tightness;

    // Reward near-perfect fills (slightly strengthened early).
    if pr == 0.0 {
        score -= 1050.0;
    } else if pr <= 5.0 {
        score -= 95.0 * (1.0 - 0.4 * progress);
    } else if pr <= 10.0 {
        score -= 42.0;
    }

    // 2-step lookahead with fine-grained chain anticipation.
    if nx > 0.0 {
        if pr == nx {
            score -= 540.0;
        } else if nx < pr {
            let chain_left = pr - nx;
            let frac = nx / pr;
            score -= 210.0 * frac * frac;
            if chain_left <= 5.0 {
                score -= 105.0;
            } else if chain_left <= 10.0 {
                score -= 42.0;
            }
            if chain_left <= 42.0 {
                score -= 6.5 + 0.11 * chain_left;
            }
            let slack = chain_left / cap;
            if slack < 0.04 {
                score -= 9.0 * (1.0 - slack * 25.0) * (1.0 + progress);
            }
            if slack < 0.02 {
                score -= 4.0 * (1.0 - slack * 50.0) * (0.6 + progress);
            }
            let chain = 1.0 - slack.min(1.0);
            score -= 5.0 + 4.0 * (nx / cap) + 9.5 * chain * (1.0 - progress);
            // Second-order chain: does the item after next also chain?
            let chain2 = chain_left - nx;
            if chain2 > 0.0 && chain2 <= 0.05 * cap {
                score -= 5.5 * (1.0 - chain2 / (0.05 * cap)) * (0.5 + progress);
            }
        } else {
            let gap = nx - pr;
            score += gap * (2.0 + 6.5 * (1.0 - progress));
            if gap <= 3.0 {
                score -= 9.0 * (1.0 - progress);
            }
            if gap <= 0.04 * cap {
                score += 3.5 * (1.0 - gap / (0.04 * cap)) * (0.5 + progress);
            }
        }
    }

    // Mean-residual comparison (combined with residual deviation).
    let dev = mean_residual - pr;
    score -= 0.5 * dev;
    if dev > -5.0 && dev < 15.0 && pr > 0.0 {
        score -= 4.2;
    }

    // Small residual band bonus.
    if waste > 0.0 && waste < 0.12 {
        score -= 9.0 * (1.0 - waste / 0.12) * (0.4 + progress);
    }
    let unusable = if nx > 0.0 && pr > 0.0 && pr < nx { 1.0 } else { 0.55 };
    score += (10.5 + 3.2 * progress) * waste * waste * cap * (0.45 + progress) * unusable;

    // Waste band penalties (from best heuristic lineage).
    if waste > 0.14 && waste < 0.34 {
        score += 13.0 * (waste - 0.14) * (0.6 + 0.8 * progress);
    }
    if pr > 0.0 && pr < 10.0 {
        score += 41.0 * (1.0 - 0.5 * progress);
    }
    if pr > 0.0 && pr.sqrt() < 2.6 {
        score -= 3.5 * (1.0 - progress);
    }
    if nx > 0.0 && pr > 0.0 && pr < nx {
        let closeness = 1.0 - pr / nx;
        score += 3.0 * closeness * closeness * (0.6 + progress);
        if nx - pr <= 3.0 {
            score -= 9.0 * (1.0 - progress);
        }
    }
    if nx > 0.0 && pr >= nx {
        let room = pr - nx;
        if room < 0.06 * cap {
            score -= 6.5 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
        }
        if room > 0.04 * cap && room < 0.18 * cap {
            score -= 2.2 * (1.0 - room / (0.18 * cap)) * (0.3 + progress);
        }
        if room < 0.02 * cap {
            score -= 4.0 * (1.0 - room / (0.02 * cap)) * (0.4 + progress);
        }
    }
    let fill_ratio = 1.0 - res / cap;
    if fill_ratio > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
    }
    if fill_ratio > 0.65 && pr > 0.0 {
        score -= 4.8 * (fill_ratio - 0.65) * 10.0 * (0.4 + progress);
    }
    if fill_ratio > 0.92 && pr > 0.0 {
        score -= 2.0 * (fill_ratio - 0.92) * 10.0 * (0.5 + progress);
    }
    // Waste-band bonus when residual is nearly unusable.
    if waste > 0.08 && waste < 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.12 * cap {
        score += 3.0 * (1.0 - (pr - nx) / (0.12 * cap)) * (0.5 + progress);
    }
    // Low-waste reward scaled by remaining stream (from best lineage).
    if waste < 0.08 {
        score -= 48.0 * (1.0 - progress) * (0.08 - waste);
    }
    // Mid-band chain gap bonus.
    if nx > 0.0 && pr > nx && (pr - nx) <= 0.04 * cap {
        score -= 3.2 * (1.0 - (pr - nx) / (0.04 * cap)) * (1.0 - progress);
    }
    // Small residual with next item far above: dead-space penalty.
    if pr > 0.0 && nx > 0.0 && pr < 0.5 * nx && progress > 0.3 {
        score += 3.5 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
    }
    // Penalize dead space more when the bin is already very full and next item cannot use leftover.
    if pr > 0.0 && nx > 0.0 && pr < nx && fill_ratio > 0.8 {
        score += 4.5 * (fill_ratio - 0.8) * 10.0 * (0.3 + progress);
    }
    // Dead-space penalty when waste is large and next item overshoots.
    if pr > 0.0 && nx > 0.0 && pr < nx && (nx - pr) > 0.1 * cap && waste > 0.25 {
        score += 5.0 * (waste - 0.25) * 10.0 * (0.4 + progress);
    }

    // Last-chance bin.
    if fitting_bins_count == 1 {
        score -= 150.0 * (0.5 + progress);
    } else if fitting_bins_count > 3 && waste < 0.12 {
        score -= 5.5 * (1.0 - waste * 8.0) * (0.5 + progress);
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let item_frac = (it / cap).min(1.0);
        let mut nb = cap * (1.3 + 1.1 * progress);
        nb -= 26.0 * scarcity * (1.0 - progress);
        nb -= 19.0 * item_frac * (1.0 - progress);
        if it >= 0.85 * cap && progress > 0.3 {
            nb -= 32.0 + 9.0 * progress;
        }
        if nx > 0.0 && cap - it >= nx {
            nb -= 10.5 + 0.11 * (cap - it - nx);
        }
        if nx > 0.0 {
            let r1 = cap - it;
            if r1 >= nx && (r1 - nx) < 6.0 && (r1 - nx) > 0.0 {
                nb += 8.5 * (1.0 - progress);
            }
            if r1 < nx && r1 > 0.0 {
                nb += (1.0 + 2.0 * progress) * (nx - r1) * 0.55;
            }
            if r1 >= nx && (r1 - nx) > 0.25 * cap && progress > 0.45 {
                nb += 4.5 * ((r1 - nx) / cap).min(0.5) * progress;
            }
        }
        if nx >= 0.5 * cap {
            nb -= 12.0 * progress + 6.0 * (1.0 - progress);
        }
        nb += 15.0 * progress * (1.0 - item_frac);
        if fitting_bins_count <= 2 {
            nb += 21.0 + 10.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 4 {
            nb -= 6.5 + 8.5 * progress;
        }
        if nx > 0.0 && mean_residual >= it + nx && progress < 0.6 {
            nb += 5.5 * (1.0 - progress);
        }
        if nx > it && mean_residual >= nx && progress < 0.6 {
            nb += 10.0 * (1.0 - progress);
        }
        if waste > 0.6 {
            nb -= 100.0 * (waste - 0.6);
        }
        // Open-bin pressure: avoid new bin when mean residual is generous.
        if mean_residual >= it && progress > 0.5 {
            nb += 6.5 + 8.5 * progress;
        }
        if nx > 0.0 && mean_residual > nx + 8.0 && progress < 0.7 {
            nb += 8.5 * ((mean_residual - nx) / cap).min(0.5) * cap * 0.1;
        }
        if it / cap > 0.6 && nx > 0.0 && cap >= it + nx && cap - it - nx < 0.03 * cap {
            nb -= 5.5 * (1.0 - (cap - it - nx) / (0.03 * cap));
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_pr = (mean_residual - it).max(0.0);
            if best_pr > 0.0 && best_pr < 0.06 * cap && (cap - it) >= nx {
                nb -= 7.0 * (1.0 - best_pr / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if progress > 0.85 && mean_residual < 0.15 * cap {
            nb += 7.0 * progress * (1.0 - mean_residual / (0.15 * cap));
        }
        // Two-item packing margin — prefer new bin when fresh bin packs item+next nearly full.
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin < 0.08 * cap {
                nb -= 6.0 * (1.0 - margin / (0.08 * cap)) * (0.6 + 0.4 * progress);
            }
        }
        // Discourage new bin when mean residual can host item plus next.
        if nx > 0.0 && mean_residual >= it + nx && progress > 0.4 {
            let rem = mean_residual - it - nx;
            if rem < 0.08 * cap {
                nb += 5.0 * (1.0 - rem / (0.08 * cap)) * progress;
            }
        }
        // Many open bins with slack — avoid opening a new one.
        if open_bins_count > 6 && mean_residual > 0.35 * cap && progress < 0.6 {
            nb += 5.0 * ((mean_residual - 0.35 * cap) / cap) * (1.0 - progress)
                * ((open_bins_count as f64 - 6.0).min(8.0) / 8.0);
        }
        // Borrowed from best lineage: mean residual hosting item+next with tight leftover.
        if nx > 0.0 && fitting_bins_count >= 1 && mean_residual - it >= nx {
            let leftover = mean_residual - it - nx;
            if leftover < 0.1 * cap && progress > 0.45 {
                nb -= 5.0 * (1.0 - leftover / (0.1 * cap)) * progress;
            }
        }
        // Large next item: fresh bin less attractive.
        if nx > 0.0 && mean_residual < nx && progress > 0.55 && item_frac < 0.5 {
            nb += 3.5 * (nx - mean_residual).min(0.1 * cap) / (0.1 * cap) * progress;
        }
        // Stronger consolidation pressure late in the stream.
        if progress > 0.6 && open_bins_count > 4 && mean_residual >= it {
            nb += 4.0 * (progress - 0.6) * 5.0 * ((mean_residual - it) / cap).min(0.3);
        }
        // Prefer new bin for tiny items early only if no bin fits well.
        if item_frac < 0.1 && fitting_bins_count >= 3 && progress < 0.4 {
            nb += 6.0 * (1.0 - progress);
        }
        // Small item late with fitting bins: prefer consolidation.
        if item_frac < 0.15 && progress > 0.55 && fitting_bins_count >= 1 {
            nb += 6.0 * progress * (1.0 - item_frac / 0.15);
        }
        // Many open bins with small items early: prefer consolidation.
        if open_bins_count > 10 && progress < 0.35 && item_frac < 0.3 {
            nb += 6.0 * (1.0 - progress) * (1.0 - item_frac / 0.3);
        }
        // Best left chain near-tight: prefer using existing bin.
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_left = mean_residual - it;
            if best_left >= nx && (best_left - nx) < 12.0 {
                nb += 4.0 * (1.0 - (best_left - nx) / 12.0) * (0.5 + progress);
            }
        }
        // No fitting bins at all: fresh bin attractive.
        if fitting_bins_count == 0 && progress > 0.25 {
            nb += 9.0 + 7.0 * progress;
        }
        // Item+next exceeds capacity but mean residual hosts next: consolidate.
        if nx > 0.0 && it + nx > cap && mean_residual >= nx {
            nb += 6.0 * (1.0 - progress);
        }
        // Mean residual hosts item+next with slack: prefer existing bin.
        if nx > 0.0 && mean_residual >= it + nx && progress < 0.6 {
            nb -= 5.5 * (1.0 - progress) * ((mean_residual - it - nx) / cap).min(0.3) * 10.0;
        }
        score = nb;
    }

    // Slight open-bin pressure to consolidate.
    score -= 0.42 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= (1.0 - gap / bin_capacity as f64) * 300.0;
        // exact chain fit
        if gap == 0.0 {
            score -= 500.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // dead space relative to the lookahead item
        score += (next_item_size - post_residual) as f64 * 2.0;
    }

    // Penalize wasting a large residual on a small item
    let waste = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += waste * 150.0;

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // Relative-to-mean residual: prefer bins with below-average residual (denser bins)
    score += (post_residual as f64 - mean_residual) * 1.5;

    // New-bin candidate: penalize opening a new bin unless it enables a strong chain
    if bin_residual == bin_capacity {
        let mut bonus = 0.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            bonus = 50.0;
        }
        score += 120.0 - bonus;
    }

    // Early stream: be slightly more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot fit a typical next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 * (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 {
        // Reward leaving room exactly for the lookahead item.
        score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer fuller bins relative to the fleet's mean residual.
    score += 0.35 * (mean_residual - bin_residual as f64);

    // Mild penalty for spreading across many open bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: only attractive when the item barely fits anywhere
    // or open bins would waste a lot of space.
    if bin_residual == bin_capacity {
        let waste_if_forced = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 30.0 * waste_if_forced - 10.0 * (1.0 - progress);
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 6.0; // room to pair with lookahead item in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
