        } else if nx < pr {
            let chain_left = pr - nx;
            let frac = nx / pr;
            score -= 215.0 * frac * frac;
            if chain_left <= 5.0 {
                score -= 108.0;
            } else if chain_left <= 10.0 {
                score -= 44.0;
            }
            if chain_left <= 42.0 {
                score -= 6.5 + 0.11 * chain_left;
            }
            let slack = chain_left / cap;
            if slack < 0.04 {
