pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap;
    let poly = prn * prn * (1.0 - progress) * (1.0 - progress)
             - prn * prn * prn * progress;
    score += 8.0 * poly;

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        let gap = (next_item_size as f64 - pr) / cap;
        score += 6.0 * gap * gap * cap;
    } else if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 4.0 * (next_item_size as f64 / cap);
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 * (item_size as f64 / cap);
    }

    // Mild penalty when bin is much tighter than the mean residual (fragmentation)
    let dev = (mean_residual - pr) / cap;
    score += 3.0 * dev * dev;

    // Prefer tight fits overall (quadratic in fill ratio)
    let fill = (bin_residual as f64 - pr) / cap;
    score -= 5.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 10.0;
    }

    // Tiny dead space (1..9) is nearly unusable: heavy penalty
    if post_residual > 0 && post_residual < 10 {
        score += 18.0 - post_residual as f64;
    }

    // Harmonic class: post_residual mod 10; low residues are awkward leftovers
    let class = (post_residual % 10) as f64;
    score += class * 0.5;

    // Integer-division thresholds on post_residual: mid-size leftovers are valuable
    let third = post_residual / 33;
    score -= third as f64 * 3.0;

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 7.0;
    }

    // Lookahead (k=2): reward if next item fits into resulting residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size as u32 <= post_residual {
            score -= 6.0;
            // extra reward for near-exact two-item packing
            let gap = post_residual as f64 - nxt;
            if gap < 10.0 { score -= 4.0 - gap * 0.3; }
        } else {
            // next item won't fit: penalize proportionally to the overshoot
            score += (nxt - post_residual as f64).min(40.0) * 0.25;
        }
    }

    // Stream progression: late in stream, be more frugal with existing space
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 3.0;

    // Global pressure: many open bins with high mean residual -> fill them
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.06;

    // New-bin candidate (empty bin): baseline high so open bins are preferred,
    // but attractive when the fit into existing bins is bad
    if bin_residual == bin_capacity {
        score = cap * 0.55 + item_size as f64 * 0.25;
        // opening a bin when the item fits nowhere else is reasonable
        if fitting_bins_count == 1 { score += 5.0; }
        // if next item is huge, a fresh bin can still host it afterwards
        if next_item_size > 0 && next_item_size as u32 <= bin_capacity && next_item_size as u32 > post_residual {
            score -= 4.0;
        }
        // late stream: discourage spawning bins
        score += progress * 6.0;
    }

    score
}

