        if mean_residual < 0.08 * cap && progress > 0.5 {
            nb += 5.0 * (1.0 - mean_residual / (0.08 * cap)) * progress;
        }
        score = nb;
    }

    // Slight open-bin pressure to consolidate.
    score -= 0.42 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fill is maximally rewarded.
        score -= 60.0;
    }

    // Moderate leftovers are fine if they can host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Leftover too small for the next item: penalize mildly.
        score += 6.0 * (next_item_size - post_residual).min(20) as f64 / 10.0;
    }

    // Last chance: only bin that fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 1.5 * open_bins_count as f64;

    // Prefer bins tighter than the mean residual (good fit).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Progress: early in stream, be more selective about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    // New-bin candidate: neutral-ish baseline; only attractive when no
    // open bin offers a decent fit (its raw post_residual = capacity - item
    // is large, so it naturally loses unless dead-space penalties dominate).
    if bin_residual == bin_capacity {
        score += 15.0;
        // Late in the stream, opening a fresh bin for a big item is fine.
        if item_size >= 50 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward bins whose post-residual matches the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - gap / bin_capacity as f64);
    }
    // Penalize post-residuals that are small but unusable (dead space)
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 8.0;
    }

    // Relative-to-mean residual coupling: prefer bins tighter than the mean
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= 0.5 * (mean_residual - resid_f);
    } else {
        score += 0.3 * (resid_f - mean_residual);
    }

    // Last-chance bonus: only bin that fits -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only open a new bin when no good fit exists
    if bin_residual == bin_capacity {
        let tight_exists = mean_residual < (bin_capacity as f64 - item_size as f64) * 0.9;
        if tight_exists {
            score += 20.0;
        } else {
            score += 2.0;
        }
    }

    // Prefer filling bins more fully as the stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;
    let waste = (pr / cap).max(0.0);

    // Base: post residual with mild non-linear scaling.
    let mut score = pr * (1.0 + 0.03 * waste * waste);

    // Progress-aware tightness (combined quadratic + cubic ramp).
    let tightness = 1.0 + 2.6 * progress * progress + 2.2 * progress * progress * progress;
    score *= tightness;

    // Reward near-perfect fills (slightly strengthened early).
    if pr == 0.0 {
        score -= 1080.0;
    } else if pr <= 5.0 {
        score -= 98.0 * (1.0 - 0.4 * progress);
    } else if pr <= 10.0 {
        score -= 44.0;
    }

    // 2-step lookahead with fine-grained chain anticipation.
    if nx > 0.0 {
        if pr == nx {
            score -= 560.0;
        } else if nx < pr {
            let chain_left = pr - nx;
            let frac = nx / pr;
            score -= 215.0 * frac * frac;
            if chain_left <= 5.0 {
                score -= 108.0;
            } else if chain_left <= 10.0 {
                score -= 44.0;
            }
            if chain_left <= 42.0 {
                score -= 6.5 + 0.11 * chain_left;
            }
            let slack = chain_left / cap;
            if slack < 0.04 {
                score -= 9.5 * (1.0 - slack * 25.0) * (1.0 + progress);
            }
            let chain = 1.0 - slack.min(1.0);
            score -= 5.0 + 4.0 * (nx / cap) + 9.5 * chain * (1.0 - progress);
            let chain2 = chain_left - nx;
            if chain2 > 0.0 && chain2 <= 0.05 * cap {
                score -= 5.5 * (1.0 - chain2 / (0.05 * cap)) * (0.5 + progress);
            }
        } else {
            let gap = nx - pr;
            score += gap * (2.0 + 6.5 * (1.0 - progress));
            if gap <= 3.0 {
                score -= 9.0 * (1.0 - progress);
            }
            if gap <= 0.04 * cap {
                score += 3.5 * (1.0 - gap / (0.04 * cap)) * (0.5 + progress);
            }
        }
    }

    // Mean-residual comparison.
    let dev = mean_residual - pr;
    score -= 0.5 * dev;

    // Small residual band bonus.
    if waste > 0.0 && waste < 0.12 {
        score -= 9.0 * (1.0 - waste / 0.12) * (0.4 + progress);
    }
    let unusable = if nx > 0.0 && pr > 0.0 && pr < nx { 1.0 } else { 0.55 };
    score += (10.5 + 3.2 * progress) * waste * waste * cap * (0.45 + progress) * unusable;

    // Waste band penalties.
    if waste > 0.14 && waste < 0.34 {
        score += 13.0 * (waste - 0.14) * (0.6 + 0.8 * progress);
    }
    if pr > 0.0 && pr < 10.0 {
        score += 41.0 * (1.0 - 0.5 * progress);
    }
    if nx > 0.0 && pr > 0.0 && pr < nx {
        let closeness = 1.0 - pr / nx;
        score += 3.0 * closeness * closeness * (0.6 + progress);
    }
    if nx > 0.0 && pr >= nx {
        let room = pr - nx;
        if room < 0.06 * cap {
            score -= 6.5 * (1.0 - room / (0.06 * cap)) * (0.5 + progress);
        }
        if room > 0.04 * cap && room < 0.18 * cap {
            score -= 2.2 * (1.0 - room / (0.18 * cap)) * (0.3 + progress);
        }
    }
    let fill_ratio = 1.0 - res / cap;
    if fill_ratio > 0.85 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 3.0 * (fill_ratio - 0.85) * 10.0 * progress;
    }
    if fill_ratio > 0.65 && pr > 0.0 {
        score -= 4.8 * (fill_ratio - 0.65) * 10.0 * (0.4 + progress);
    }
    if fill_ratio > 0.92 && pr > 0.0 {
        score -= 2.0 * (fill_ratio - 0.92) * 10.0 * (0.5 + progress);
    }
    if waste > 0.08 && waste < 0.2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.12 * cap {
        score += 3.0 * (1.0 - (pr - nx) / (0.12 * cap)) * (0.5 + progress);
    }
    // Low-waste reward scaled by remaining stream.
    if waste < 0.08 {
        score -= 52.0 * (1.0 - progress) * (0.08 - waste);
    }
    if nx > 0.0 && pr > nx && (pr - nx) <= 0.04 * cap {
        score -= 3.2 * (1.0 - (pr - nx) / (0.04 * cap)) * (1.0 - progress);
    }
    if pr > 0.0 && nx > 0.0 && pr < 0.5 * nx && progress > 0.3 {
        score += 3.5 * (1.0 - pr / (0.5 * nx)) * (0.5 + progress);
    }
    if pr > 0.0 && nx > 0.0 && pr < nx && fill_ratio > 0.8 {
        score += 4.5 * (fill_ratio - 0.8) * 10.0 * (0.3 + progress);
    }
    // Two-item chain reward — item+next nearly fills this bin exactly.
    if nx > 0.0 && pr >= nx {
        let room = pr - nx;
        if room > 0.0 && room < 3.0 {
            score -= 14.0 * (1.0 - room / 3.0) * (0.6 + progress);
        }
    }
    // Exact two-item fill reward (item+next exactly fills residual).
    if nx > 0.0 && pr > 0.0 && res >= it + nx && (res - it - nx) < 0.02 * cap {
        score -= 9.0 * (1.0 - (res - it - nx) / (0.02 * cap)) * (0.5 + progress);
    }
    // Penalize bins whose residual cannot host the next item (dead space),
    // with a sharper ramp for large dead gaps.
    if nx > 0.0 && pr > 0.0 && pr < nx {
        let dead = nx - pr;
        score += 2.5 * dead * (0.4 + progress);
        if dead > 0.1 * cap {
            score += 6.0 * (dead / cap) * (0.6 + 0.6 * progress);
        }
        // Extra: if NO other bin can host the next item either, this dead space is forgivable.
        if fitting_bins_count <= 1 {
            score -= 3.0 * dead * (0.4 + progress);
        }
    }

    // Last-chance bin.
    if fitting_bins_count == 1 {
        score -= 155.0 * (0.5 + progress);
    } else if fitting_bins_count > 3 && waste < 0.12 {
        score -= 5.5 * (1.0 - waste * 8.0) * (0.5 + progress);
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let item_frac = (it / cap).min(1.0);
        let mut nb = cap * (1.3 + 1.1 * progress);
        nb -= 26.0 * scarcity * (1.0 - progress);
        nb -= 19.0 * item_frac * (1.0 - progress);
        if it >= 0.85 * cap && progress > 0.3 {
            nb -= 32.0 + 9.0 * progress;
        }
        if nx > 0.0 && cap - it >= nx {
            nb -= 10.5 + 0.11 * (cap - it - nx);
        }
        if nx > 0.0 {
            let r1 = cap - it;
            if r1 >= nx && (r1 - nx) < 6.0 && (r1 - nx) > 0.0 {
                nb += 8.5 * (1.0 - progress);
            }
            if r1 < nx && r1 > 0.0 {
                nb += (1.0 + 2.0 * progress) * (nx - r1) * 0.55;
            }
        }
        if nx >= 0.5 * cap {
            nb -= 12.0 * progress + 6.0 * (1.0 - progress);
        }
        nb += 15.0 * progress * (1.0 - item_frac);
        if fitting_bins_count <= 2 {
            nb += 21.0 + 10.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 4 {
            nb -= 6.5 + 8.5 * progress;
        }
        if nx > 0.0 && mean_residual >= it + nx && progress < 0.6 {
            nb += 5.5 * (1.0 - progress);
        }
        if nx > it && mean_residual >= nx && progress < 0.6 {
            nb += 10.0 * (1.0 - progress);
        }
        if waste > 0.6 {
            nb -= 100.0 * (waste - 0.6);
        }
        if mean_residual >= it && progress > 0.5 {
            nb += 6.5 + 8.5 * progress;
        }
        if nx > 0.0 && mean_residual > nx + 8.0 && progress < 0.7 {
            nb += 8.5 * ((mean_residual - nx) / cap).min(0.5) * cap * 0.1;
        }
        if it / cap > 0.6 && nx > 0.0 && cap >= it + nx && cap - it - nx < 0.03 * cap {
            nb -= 5.5 * (1.0 - (cap - it - nx) / (0.03 * cap));
        }
        if nx > 0.0 && fitting_bins_count >= 1 {
            let best_pr = (mean_residual - it).max(0.0);
            if best_pr > 0.0 && best_pr < 0.06 * cap && (cap - it) >= nx {
                nb -= 7.0 * (1.0 - best_pr / (0.06 * cap)) * (0.5 + progress);
            }
        }
        if progress > 0.85 && mean_residual < 0.15 * cap {
            nb += 7.0 * progress * (1.0 - mean_residual / (0.15 * cap));
        }
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin < 0.05 * cap {
                nb -= 6.5 * (1.0 - margin / (0.05 * cap)) * (0.5 + progress);
            }
        }
        if nx > 0.0 && mean_residual >= it + nx && progress > 0.4 {
            let rem = mean_residual - it - nx;
            if rem < 0.08 * cap {
                nb += 5.0 * (1.0 - rem / (0.08 * cap)) * progress;
            }
        }
        if open_bins_count > 6 && mean_residual > 0.35 * cap && progress < 0.6 {
            nb += 5.0 * ((mean_residual - 0.35 * cap) / cap) * (1.0 - progress)
                * ((open_bins_count as f64 - 6.0).min(8.0) / 8.0);
        }
        if nx > 0.0 && fitting_bins_count >= 1 && mean_residual - it >= nx {
            let leftover = mean_residual - it - nx;
            if leftover < 0.1 * cap && progress > 0.45 {
                nb -= 5.0 * (1.0 - leftover / (0.1 * cap)) * progress;
            }
        }
        if nx > 0.0 && mean_residual < nx && progress > 0.55 && item_frac < 0.5 {
            nb += 3.5 * (nx - mean_residual).min(0.1 * cap) / (0.1 * cap) * progress;
        }
        if progress > 0.6 && open_bins_count > 4 && mean_residual >= it {
            nb += 4.0 * (progress - 0.6) * 5.0 * ((mean_residual - it) / cap).min(0.3);
        }
        if item_frac < 0.1 && fitting_bins_count >= 3 && progress < 0.4 {
            nb += 6.0 * (1.0 - progress);
        }
        // Two-item margin reward for fresh bin across wider band.
        if nx > 0.0 && cap >= it + nx {
            let margin = cap - it - nx;
            if margin >= 0.05 * cap && margin < 0.12 * cap && progress > 0.3 {
                nb -= 4.0 * (1.0 - margin / (0.12 * cap)) * progress;
            }
        }
        // Avoid new bin when several bins can host item+next tightly.
        if nx > 0.0 && fitting_bins_count >= 2 && mean_residual >= it + nx {
            nb += 4.0 * (1.0 - progress);
        }
        // Exact two-item fill in a fresh bin — strong reward.
        if nx > 0.0 && cap >= it + nx && cap - it - nx < 0.02 * cap {
            nb -= 9.0 * (1.0 - (cap - it - nx) / (0.02 * cap)) * (0.5 + progress);
        }
        // Penalize fresh bin when mean residual is already very tight (consolidate instead).
        if mean_residual < 0.08 * cap && progress > 0.5 {
            nb += 5.0 * (1.0 - mean_residual / (0.08 * cap)) * progress;
        }
        // NEW: prefer opening a fresh bin over dumping into a bin that would leave
        // dead space smaller than the next item (dead-space trade-off).
        if nx > 0.0 && fitting_bins_count >= 1 && mean_residual < it + nx && mean_residual >= it {
            let dead = it + nx - mean_residual;
            if dead < 0.07 * cap {
                nb -= 7.5 * (1.0 - dead / (0.07 * cap)) * (0.5 + progress);
            }
        }
        // NEW: fresh-bin discount late in the stream when many bins are open
        // (closing out the stream with fewer, tighter bins).
        if progress > 0.7 && open_bins_count > 5 {
            nb -= 3.0 * (progress - 0.7) * 10.0 * ((open_bins_count as f64 - 5.0).min(6.0) / 6.0);
        }
        score = nb;
    }

    // Slight open-bin pressure to consolidate.
    score -= 0.42 * (open_bins_count as f64).ln().max(0.0);

    score
}

