    }

    // Last-chance bonus: sole fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Mild consolidation pressure against many open bins.
    score -= 0.42 * (open_bins_count as f64).ln().max(0.0);

    score
}

