        if nx > 0.0 && mean_residual >= it + nx && progress > 0.4 {
            let rem = mean_residual - it - nx;
            if rem < 0.08 * cap {
                nb += 5.0 * (1.0 - rem / (0.08 * cap)) * progress;
            }
        }
        if open_bins_count > 6 && mean_residual > 0.35 * cap && progress < 0.6 {
            nb += 5.0 * ((mean_residual - 0.35 * cap) / cap) * (1.0 - progress) * ((open_bins_count as f64 - 6.0).min(8.0) / 8.0);
        }
        if nx > 0.0 && fitting_bins_count >= 1 && mean_residual - it >= nx {
            let leftover = mean_residual - it - nx;
            if leftover < 0.1 * cap && progress > 0.45 {
                nb -= 5.0 * (1.0 - leftover / (0.1 * cap)) * progress;
            }
        }
        if nx > 0.0 && mean_residual < nx && progress > 0.55 && item_frac < 0.5 {
            nb += 3.5 * (nx - mean_residual).min(0.1 * cap) / (0.1 * cap) * progress;
        }
        if nx > 0.0 && fitting_bins_count >= 1 && mean_residual < it + nx && mean_residual >= it {
            let dead = it + nx - mean_residual;
            if dead < 0.07 * cap {
                nb -= 7.5 * (1.0 - dead / (0.07 * cap)) * (0.5 + progress);
            }
        }
        if progress > 0.7 && open_bins_count > 5 {
            nb -= 3.0 * (progress - 0.7) * 10.0 * ((open_bins_count as f64 - 5.0).min(6.0) / 6.0);
        }
        if item_frac < 0.1 && fitting_bins_count >= 3 && progress < 0.4 {
            nb += 6.0 * (1.0 - progress);
        }
        if mean_residual < 0.08 * cap && progress > 0.5 {
            nb += 5.0 * (1.0 - mean_residual / (0.08 * cap)) * progress;
        }
        score = nb;
    } else {
        score -= 0.42 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize leaving small, hard-to-use dead space (< ~20).
    if post_residual > 0 && post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, using it avoids a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: penalize if the next item would fit better in this bin's post-residual
    // than in the mean available space (i.e., don't waste a good future spot).
    if next_item_size > 0 {
        if (next_item_size as f64) <= post_residual as f64 {
            // next item can chain into this bin: reward moderate leftover that still fits it
            score -= 8.0;
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * next_fit * next_fit;
        } else {
            // leftover too small for next item: penalize proportionally to wasted potential
            let waste = 1.0 - post_residual as f64 / (next_item_size as f64);
            score += 12.0 * waste.max(0.0);
        }
    }

    // New-bin candidate logic: an empty bin should only win when it's genuinely better.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by stream progress and open-bin pressure.
        let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 + 15.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;

        // If no existing bin fits well (large fit_ratio everywhere), opening new is fine.
        if fit_ratio >= 1.0 {
            score -= 35.0;
        }
        // If next item is large, a fresh bin preserves flexibility.
        if next_item_size >= item_size && next_item_size > 0 {
            score -= 10.0;
        }
    }

    // Global-state coupling: prefer bins whose residual is above the mean residual
    // when we can fill them well (keeps small residuals for small items).
    if bin_residual != bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.05 * diff;
    }

    // Mild time-horizon term: early in the stream, be slightly more conservative
    // about creating tiny residuals (long future to suffer from them).
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 20 {
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // early on, mild penalty for waste; late, stronger penalty
    let coupling = norm_pr * (1.0 - progress) * (1.0 - progress)
        - norm_pr * progress * progress;
    score += 40.0 * coupling;

    // Reward bins whose leftover could fit the lookahead item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 6.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize opening new bins when good open bins exist
    if bin_residual == bin_capacity {
        score += 25.0 + 15.0 * progress;
    }

    // Slight preference for bins below mean residual (tighter bins)
    score += 0.3 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class analysis of post_residual ---
    // Dead space is most painful when it falls into "unreachable" residue classes.
    // Class 1: post_residual == 0 -> perfect fit, huge reward.
    if post_residual == 0 {
        score -= 60.0;
    }
    // Class 2: post_residual < 10 (below minimum item size) -> dead space, penalize.
    else if post_residual < 10 {
        score += 25.0;
    }
    // Class 3: post_residual is a multiple of 10 -> aligns with typical item sizes,
    // reusable by future items.
    else if post_residual % 10 == 0 {
        score -= 12.0;
    }
    // Class 4: post_residual in awkward mid-band (11..=19) -> likely dead.
    else if post_residual < 20 {
        score += 15.0;
    }

    // Integer-division threshold coupling: how well does post_residual
    // "cover" the next item's harmonic class?
    if next_item_size > 0 && post_residual >= next_item_size {
        // Next item fits here: reward proportional to tightness of that fit.
        let lookahead_tightness = (post_residual - next_item_size) as f64;
        score -= 20.0 - 0.25 * lookahead_tightness;
        // Bonus if post_residual is an exact harmonic multiple of next item.
        if post_residual % next_item_size == 0 {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize by how far off we are,
        // scaled by the item's residue class relative to 10.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.5 * gap;
        if next_item_size % 10 == 0 && post_residual < next_item_size {
            score += 5.0; // round-sized next item is common; this bin becomes waste
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin has full residual. Opening a new
    // bin is only sensible when the fit here is bad or post_residual is dead space.
    if bin_residual == bin_capacity {
        // Mild penalty so we prefer reusing open bins with good fits,
        // but a strong perfect fit in an existing bin beats opening.
        score += 10.0;
        // If the stream is early, opening bins is cheaper (bins stay open longer).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 8.0 * (1.0 - progress);
        // If many open bins exist, discourage adding more.
        score += 0.4 * open_bins_count as f64;
    }

    // Coupling with mean residual: prefer bins whose post_residual moves the
    // bin toward the mean (consolidating usable space).
    let post_f = post_residual as f64;
    let drift = (post_f - mean_residual).abs();
    score += 0.08 * drift;

    // Small progression-aware tightening: late in the stream, waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible future item are pure waste.
    let dead_threshold = 20u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 + (dead_threshold - post_residual) as f64 * 3.0;
    }

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward fits that leave room for the lookahead item (k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 + (next_item_size as f64) * 0.2;
        } else {
            // Lookahead won't fit here; mild penalty unless bin becomes empty.
            score += 10.0;
        }
    }

    // Tightness reward: the closer the fill to capacity, the better.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 40.0;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: penalize adding to bins when many bins are open,
    // encouraging consolidation rather than sprawl.
    score += open_bins_count as f64 * 0.15;

    // Mean residual coupling: prefer bins whose residual is below average
    // (fill the emptier-than-average gaps? no — prefer filling bins that
    // deviate most, i.e. the tightest bins, to close them out).
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 8.0;
    } else {
        score += (res - mean_residual) * 0.1;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // early in the stream or when no bin offers a decent fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base cost of a new bin grows with progress (sunk bins are costly).
        let mut new_bin_cost = 45.0 + progress * 30.0;
        // If several bins fit, discourage opening a new one.
        if fitting_bins_count >= 1 {
            new_bin_cost += fitting_bins_count as f64 * 5.0;
        }
        // Large items relative to typical residual benefit from fresh bins.
        if item_size as f64 > mean_residual {
            new_bin_cost -= 20.0;
        }
        score += new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits strongly (dead-space penalty is convex).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: if the next item fits into the post-residual,
    // reward this bin (chain placement); otherwise penalize residual that
    // neither fits the next item nor is likely reusable.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 18.0 * chain_tightness;
        } else {
            // Next item won't fit here: dead space unless residual is tiny.
            let dead = post_residual as f64;
            if dead < 10.0 {
                score -= 12.0; // tiny waste is fine, effectively a perfect fit
            } else {
                score += 8.0 + 0.25 * (dead - 10.0);
            }
        }
    }

    // Relative-to-mean coupling: bins with residual well below mean are
    // "nearly full" — prefer filling them (waste-minimization).
    let res = post_residual as f64;
    let mean_gap = res - mean_residual;
    score += 0.10 * mean_gap;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: neutral-ish baseline; only attractive when the fit
    // elsewhere would be poor. Penalize slightly so we consolidate by default.
    if bin_residual == bin_capacity {
        score += 10.0;
        // But if item is large and mean residual can't host it well, allow it.
        if fit_ratio < 0.5 && mean_residual < item_size as f64 {
            score -= 25.0;
        }
    }

    // Slight late-stream consolidation pressure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (wasted capacity).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0 + 0.25 * (next_item_size - post_residual) as f64;
    }

    // Reward exact pairing: post_residual that fits next item perfectly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin, but allow it when all
    // open bins would leave large unusable gaps or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 14.0 + 10.0 * progress;
        // If mean residual of open bins is large, packing into them is fine;
        // if small, opening a fresh bin is more attractive.
        new_bin_penalty -= 0.08 * mean_residual;
        // If next item is huge, a fresh bin gives flexibility.
        if next_item_size >= 60 {
            new_bin_penalty -= 4.0;
        }
        score += new_bin_penalty.max(1.0);
    }

    // Mild penalty for bins whose residual deviates far from the mean
    // (keeps the pool of residuals homogeneous for future fits).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    // Slight late-stream pressure: consolidate more aggressively as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (bin_residual < item_size + 20) as i32 as f64;

    // Tie-break toward fewer open bins (favor filling existing bins).
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + 2.0 * progress * progress + 1.5 * progress);

    let mut score = poly * cap;

    // Penalize dead space asymmetrically: small residuals are less useful late
    let dead = if norm_pr < 0.2 { (0.2 - norm_pr) * (0.2 - norm_pr) * cap * (1.0 + progress) } else { 0.0 };
    score += dead;

    // Reward tight fits smoothly
    let fit = (item_size as f64) / cap;
    score -= fit * fit * cap * 0.5;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 25.0 * progress;
    }

    // Lookahead: penalize if next item cannot fit into post_residual
    if next_item_size > 0 && (next_item_size as f64) > pr {
        score += (next_item_size as f64 - pr) * (0.3 + 0.4 * progress);
    } else if next_item_size > 0 {
        score -= 3.0;
    }

    // New-bin candidate: mild penalty that grows with progress so late stream prefers filling open bins
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * progress + 0.5 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins)
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward post_residual near zero.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Harmonic classes: post_residual divisible by 5/10 is more reusable
    // by future items (typical sizes cluster in multiples of 5/10).
    if post_residual % 10 == 0 {
        score -= 25.0;
    } else if post_residual % 5 == 0 {
        score -= 12.0;
    } else {
        // Odd dead space is less likely to be filled later.
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual
    // (or into the same harmonic class), strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            let lookahead_waste = post_residual - next_item_size;
            if lookahead_waste % 5 == 0 {
                score -= 30.0 - (lookahead_waste as f64) * 0.5;
            } else {
                score -= 10.0 - (lookahead_waste as f64) * 0.3;
            }
        } else {
            // Next item cannot use this bin's leftover: mild penalty.
            score += 20.0;
        }
    } else {
        // Last item in stream: only tightness matters, close bins greedily.
        score += post_residual as f64 * 2.0;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Relative fill fraction: prefer bins where the item occupies a large share.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 30.0;

    // Prefer bins with residual below the mean (concentrate packing).
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    // New-bin candidate handling: only attractive early in the stream or
    // when the item is huge and no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 > 0.6 * bin_capacity as f64;
        let poor_fit = post_residual as f64 > 0.35 * bin_capacity as f64;
        if big_item && poor_fit {
            score -= 35.0; // fresh bin better than wasting a full bin's space
        } else if progress < 0.2 && poor_fit {
            score -= 10.0;
        } else {
            score += 45.0; // generally discourage opening new bins
        }
    }

    // Mild penalty for excessive fragmentation (integer-division thresholds).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }
    if post_residual / 10 >= 5 {
        // Bin left more than half empty: suspicious placement.
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are wasted capacity.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 120.0; // unusable tiny gap (min item size 1..100 => small gaps still usable, but low)
        }
        // Non-linear penalty: dead space hurts more when it can't fit a typical item.
        let dead = post_residual as f64;
        score += (dead * dead) / (bin_capacity as f64 * 2.0);
    } else {
        score -= 30.0; // perfect fit reward
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: penalize opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if existing residuals are poor fits.
        score += 25.0 + open_bins_count as f64 * 3.0;
        if mean_residual < item_size as f64 {
            score -= 20.0; // no open bin can hold future load well
        }
    } else {
        score -= open_bins_count as f64 * 0.5;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Late-stream tightness: as stream progresses, be greedier about filling bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    // Prefer bins whose residual is close to item size (tight fit).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post-residual,
    // this is a perfect chaining placement — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but leaves a third-level residual; prefer tight chains.
            let chain_residual = post_residual - next_item_size;
            score -= 400.0 - (chain_residual as f64) * 2.0;
        } else {
            // Next item cannot use this bin's leftover space: penalize dead space
            // proportionally to how small the leftover is (unusable sliver).
            let r = post_residual as f64;
            let n = next_item_size as f64;
            if r < n {
                score += (n - r).min(r) * 1.5;
            }
        }
    }

    // Compare post_residual against mean residual: leaving a residual close to
    // the mean keeps flexibility across open bins; extremes are penalized.
    let mr = if mean_residual.is_finite() { mean_residual } else { 0.0 };
    let dev = (post_residual as f64 - mr).abs();
    score += dev * 0.3;

    // Penalize very small post-residuals that are not zero (dead space slivers),
    // unless the next item can still fit (already rewarded above).
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * 3.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible (large post_residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0 + pr * 0.5;
    }

    // New-bin candidate: opening a fresh bin should only win when the fit into
    // existing bins would be poor. Give it a moderate baseline score.
    if bin_residual == bin_capacity {
        score += 60.0;
        // If the next item is large, a fresh bin preserves room for it.
        if next_item_size > 0 && (next_item_size as f64) > pr.max(0.0) {
            score -= 20.0;
        }
    }

    // Late in the stream, tighten packing (less tolerance for slack).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * (0.1 + 0.2 * progress);

    // Many open bins: prefer consolidating into existing ones.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on post_residual relative to capacity.
    let frac_waste = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * frac_waste * frac_waste;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that blocks the lookahead item: penalize.
        score += 10.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize opening a new bin when several bins already fit the item well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // New bins are cheaper early, expensive late (fewer chances to fill them).
        score += 15.0 + 25.0 * progress;
        if fitting_bins_count > 0 {
            score += 8.0 * fitting_bins_count as f64;
        }
        // Opening a bin is more attractive if mean residual is high (existing bins fragmented).
        score -= (mean_residual / bin_capacity as f64).clamp(0.0, 1.0) * 10.0;
        // Large items prefer a fresh bin to avoid fragmenting partial bins.
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Mild penalty for using a bin that deviates strongly from mean residual
    // (keeps residual distribution balanced for future items).
    let dev = (bin_residual as f64 - mean_residual).abs() / bin_capacity as f64;
    score += 4.0 * dev;

    // Prefer filling bins that are already mostly full (reduce open bin count).
    let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 10.0 * fill * fill;

    // Time horizon: as stream ends, consolidate aggressively.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 15.0 * progress * fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr;

    // Smooth non-linear coupling: post_residual penalized more as stream progresses
    score += norm_post * norm_post * (1.0 + 40.0 * progress) * cap * 0.1;

    // Reward tight fits, amplified later in the stream (smooth sigmoid-ish term)
    let tightness = 1.0 - norm_post;
    score -= tightness * tightness * (10.0 + 60.0 * progress * progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0) / cap;
        score += gap * gap * 25.0 * (0.5 + progress);
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 40.0 * progress;
    }

    // Mild penalty for scattering across many bins relative to mean residual
    score += 0.05 * open_bins_count as f64 * (mean_residual - pr).abs() / cap;

    // New-bin candidate: keep it neutral-to-slightly-worse unless post_residual is large
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - norm_item) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in low multiples of a base unit is bad
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Fraction of capacity wasted after placement
    let waste_frac = pr / cap;
    score += 40.0 * waste_frac * waste_frac;

    // Harmonic class penalty: post_residual in awkward small bands (1..=15) is nearly dead space
    if post_residual > 0 && post_residual <= 15 {
        score += 25.0 - 1.5 * post_residual as f64;
    }

    // Modulo-10 class: residuals that are multiples of 10 pair well with typical item sizes
    if post_residual % 10 == 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 2.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let nxt = next_item_size as f64;
            // reward proportional to how much of the leftover the next item consumes
            score -= 10.0 * (nxt / pr).min(1.0);
            // harmonic class of leftover after hypothetical next placement
            let pr2 = (post_residual - next_item_size) as f64;
            if pr2 > 0.0 && pr2 <= 10.0 {
                score += 8.0;
            }
        } else {
            // next item cannot use this leftover: penalize small leftovers more
            score += 5.0 * waste_frac;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Many open bins: prefer consolidating into tighter fits
    if open_bins_count > 3 {
        score -= 3.0 * (1.0 - (bin_residual as f64 / mean_residual.max(1.0)).min(2.0) * 0.5);
    }

    // Early stream: mild preference for tight fits to build good structure
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 4.0 * (1.0 - waste_frac);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a bin, reduced when many items remain and current bins are fragmented
        let mut nb = 22.0;
        if fitting_bins_count == 0 {
            nb -= 40.0; // must open new bin anyway
        }
        if post_residual as f64 > mean_residual + 20.0 {
            nb -= 8.0;
        }
        score += nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 3.0 } else if post_residual < 20 { 2.0 } else { 0.0 };
        score += dead * post_residual as f64;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: favor bins whose post_residual can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = post_residual as f64 - item_size as f64;
        // Prefer new bin only if best existing placement leaves a large dead gap.
        score += 40.0 - mean_residual * 0.2 - progress * 10.0;
        let _ = tight;
    }

    // Mild preference for filling fuller bins (relative residual ordering).
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match with next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
        // Perfect match bonus: post residual exactly fits the next item.
        if post_residual == next_item_size {
            score -= 80.0;
        }
        // Post residual can still fit next item: mild reward.
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            // Dead space for the next item: penalize proportionally.
            score += 10.0 + 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Penalize small unusable residuals (dead space), unless it's a perfect tight fit.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 40.0; // perfect closure
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score -= 0.4 * (mean_residual - post_residual as f64);

    // New-bin candidate: make it attractive only when open bins are poor fits.
    if bin_residual == bin_capacity {
        score -= 20.0 + 0.2 * mean_residual;
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        if fitting_bins_count > 0 {
            score += 35.0; // discourage opening new bin when fits exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
