pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio discount.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 2.5 * fill * (bin_residual as f64 / bin_capacity as f64);

    // Penalize dead space: small post_residual is good, but leaving a sliver
    // (< 10) that nothing can use is worse than a clean zero.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 8.0 * (10.0 - pr) / 10.0;
    }
    if pr == 0.0 {
        score -= 12.0; // perfect closure
    }

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 3.0; // next item won't reuse this bin's remainder
        }
    } else {
        // Last item: strongly prefer closing bins.
        score -= 20.0 * (1.0 - post_residual / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when the fit elsewhere is poor or
    // the item is large and nothing tight exists.
    if bin_residual == bin_capacity {
        // Baseline penalty so a new bin is chosen only for good reason.
        score += 15.0;
        // Large items keep future flexibility in a fresh bin.
        score -= 10.0 * fill;
        // If mean residual is large, we should use existing space instead.
        score += 0.15 * mean_residual;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // If the current item leaves a large remainder that no next item uses,
        // a fresh bin is fine (its post_residual equals capacity - item).
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 4.0;
        }
    }

    // Mild diversity pressure: many open bins -> prefer filling existing ones.
    if open_bins_count > 3 {
        score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, penalize large post-residual quadratically.
    let mut score = pr + 60.0 * norm_pr * norm_pr * cap;

    // Non-linear coupling with stream progress: later in the stream,
    // dead space matters more (fewer future chances to fill it).
    let progress_pressure = 1.0 + 2.0 * t * t;
    score *= progress_pressure;

    // Smooth reward for exact-ish fits (post_residual near 0 or near a
    // plausible next-item size) via a cosine bump.
    let bump = (std::f64::consts::PI * norm_pr).cos();
    score -= 12.0 * bump.max(0.0) * (1.0 - norm_pr);

    // Lookahead coupling: reward residual that can host the next item,
    // penalize residuals just barely too small for it (smooth kernel).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = (pr - ni) / cap;
        let sigma = 0.06;
        let kernel = (-0.5 * (gap / sigma) * (gap / sigma)).exp();
        if pr >= ni {
            score -= 18.0 * kernel;
        } else {
            score += 18.0 * kernel;
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    // rather than opening a new one, scaled smoothly by progress.
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * t);
    }

    // Mild penalty for scattering across many open bins.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Deviation from mean residual: prefer bins that are either much
    // fuller (consolidation) with a smooth quadratic term.
    let dev = mean_residual - pr;
    score += 0.05 * dev * dev / cap;

    // New-bin candidate: make empty bins moderately attractive only when
    // the item leaves a very large residual in any existing bin.
    if bin_residual == bin_capacity {
        score = pr + 30.0 * (1.0 - t) - 20.0 * t * norm_pr;
        if fitting_bins_count == 0 { score -= 40.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.88;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold anything useful
    // (assuming items >= 10 in classic regime; scale with capacity) are pure waste.
    let dead_threshold = (bin_capacity as f64 * 0.10).max(10.0);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Perfect-ish fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if (post_residual as f64) < dead_threshold {
        score -= 15.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Creating a gap just smaller than the next item is doubly bad.
        score += 10.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin, especially when many bins are already open.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0 + 0.5 * open_bins_count as f64;
    }

    // Open-bin pressure: with many open bins, favor filling existing ones
    // over opening new bins; make the fresh-bin candidate less attractive.
    score += 0.8 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Fresh-bin candidate: only attractive when the item fits poorly everywhere
    // (large post_residual elsewhere) or few bins are open.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 20.0 * open_bins_count as f64 - 10.0 * progress;
        // If next item is large, a fresh bin gives flexibility.
        if next_item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Mild bonus for tightening the mean residual spread (fill below-average bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward exact packing.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // can exactly accommodate the next item (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // Reward leftover space that still fits the next item,
            // scaled by how snugly the next item nests.
            let snug = (post_residual - next_item_size) as f64;
            score -= 150.0 - snug * 1.5;
        } else {
            // Penalize dead space that the next item cannot use.
            score += (next_item_size - post_residual) as f64 * 0.75;
        }
    }

    // Penalize large unusable gaps relative to capacity.
    if post_residual > 0 && post_residual < 10 {
        score -= 50.0; // near-perfect fill
    } else if post_residual > bin_capacity as u32 / 2 {
        score += 30.0; // wasteful half-empty bin
    }

    // Contextual pressure: when few bins fit the item, prefer using them
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    // (best-fit style) but avoid over-fragmenting when many bins are open.
    let mr = mean_residual;
    if (post_residual as f64) < mr {
        score -= (mr - post_residual as f64).min(50.0) * 0.8;
    } else {
        score += (post_residual as f64 - mr).min(50.0) * 0.4;
    }

    // Early in the stream, allow opening bins more freely; later,
    // consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless item is large and lookahead
        // suggests a good companion item.
        score += 60.0;
        if next_item_size > 0 && (bin_capacity as u32 - item_size).saturating_sub(next_item_size) <= 10 {
            score -= 120.0; // new bin would pair well with next item
        }
        if progress > 0.7 {
            score += 40.0; // late stream: discourage new bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that cannot fit typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: favor bins whose leftover can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            score += 8.0 * (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Prefer fuller bins relative to the mean residual
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Time horizon: later in stream, be more conservative about new bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
    }

    // Mild penalty for many open bins
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Smooth non-linear penalty for small post-residuals (dead space), stronger late in stream
    let norm_post = post / cap;
    let dead = (1.0 - norm_post).powi(3);
    score -= dead * 12.0 * (0.5 + 0.5 * progress);

    // Reward tight fits (post_residual near zero) with smooth decay
    score -= (-post / 8.0).exp() * 10.0;

    // Penalize leaving a residual that is too small for typical future items
    let small_gap = (norm_post * 4.0 - 1.0).powi(2);
    score += small_gap * 6.0;

    // Lookahead coupling: reward if next item fits in post residual (smooth)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fits = (post - ns).max(0.0) / cap;
        let bonus = (-((post - ns).abs()) / 15.0).exp();
        score -= bonus * 8.0;
        score += fits * 2.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild preference for filling bins when many bins are open
    score -= (item_size as f64 / cap) * (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Interaction: stream progress with mean residual (pack tighter as stream ends)
    score += (mean_residual / cap) * progress * 5.0;

    // New-bin candidate: penalize opening a bin unless residual is tiny
    if bin_residual == bin_capacity {
        score += 25.0 - 20.0 * (1.0 - item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 classes capture "usable" dead space
    let pr = post_residual as i64;
    let class = pr % 10;
    // Residuals in {0} are perfect; small odd leftovers are bad
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr < 10 {
        score += 25.0; // dead space too small for any item (min size 1..~10)
    } else {
        // reward post_residual that matches a plausible next-item class
        if next_item_size > 0 && (pr as u32) >= next_item_size {
            let gap = pr - next_item_size as i64;
            if gap == 0 {
                score -= 45.0; // exactly fits lookahead item
            } else if gap < 10 {
                score -= 15.0; // near-perfect chain
            } else {
                score -= (20.0f64 / (gap as f64).sqrt()).min(10.0);
            }
        } else if next_item_size > 0 {
            // next item cannot fit here anyway; mildly penalize large leftovers
            score += (pr as f64) * 0.05;
        }
        // mod-class shaping: even decade residuals are friendlier
        match class {
            0 => score -= 8.0,
            5 => score -= 3.0,
            _ => score += (class as f64) * 0.4,
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening new bins when many bins fit the item (fragmentation risk)
    if fitting_bins_count > 1 {
        score += 4.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate: only attractive when open bins are crowded or item huge
    if bin_residual == bin_capacity {
        let crowding = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 1.0 };
        let pressure = 1.0 - crowding; // high when residuals are small
        let big_item = (item_size as f64 / bin_capacity as f64).powi(2);
        let late = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 - 55.0 * pressure - 25.0 * big_item - 10.0 * late;
        // discourage new bin if lookahead also fits comfortably after placement
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 12.0;
        }
    }

    // Slight global pressure: prefer filling bins when mean residual is low
    score += 0.05 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += 0.35 * open_bins_count as f64;

    // Slight preference toward bins tighter than average.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 0 && post_residual < 10;
        if poor_fit {
            score -= 50.0; // prefer fresh bin over creating dead space
        } else {
            score += 30.0; // discourage opening bins unnecessarily
        }
    }

    // Late-stream urgency: consolidate as the stream ends.
    let progress = step_index as f64 / total_items as f64;
    score -= 10.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 1.0 {
            score -= 500.0;
        } else if post_residual as f64 >= nxt {
            // next item still fits here: mild reward proportional to how well it fits after.
            let second_post = post_residual as f64 - nxt;
            score -= 50.0 * (1.0 - second_post / bin_capacity as f64);
        } else {
            // next item won't fit in this bin afterwards: penalize tight-but-not-perfect fits.
            score += 30.0 * (nxt - post_residual as f64).min(80.0) / 80.0;
        }
    }

    // Prefer tight fit relative to mean residual: bins with residual close to item_size are good.
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.5 * fit_gap;

    // Compare post_residual to mean residual: leaving less than average is good.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin unless current bins would be badly fragmented.
    if bin_residual == bin_capacity {
        // New bin: score = full capacity minus item; only attractive when open bins are too full on average.
        score = bin_capacity as f64 - item_size as f64;
        score += 40.0 * (mean_residual / bin_capacity as f64);
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 20.0; // new bin can chain with next item
        }
        if fitting_bins_count == 1 {
            score += 200.0; // don't abandon the last fitting bin
        }
        if post_residual == 0 {
            score -= 100.0; // perfect fit in fresh bin (item == capacity)
        }
    }

    // Slight pressure to consolidate early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: penalize if next item cannot fit into post residual
    if next_item_size > 0 {
        if (post_residual as u32) < next_item_size {
            score += 25.0 + (next_item_size as f64 - post_residual as f64) * 0.5;
        } else {
            score -= 8.0; // chain-friendly placement
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Tight fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    // Penalize opening a new bin when open bins have plenty of space
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 30.0 + pressure * 40.0 + (open_bins_count as f64) * 2.0;
    } else {
        // Reward using bins whose residual deviates favorably from mean
        let dev = bin_residual as f64 - mean_residual;
        score += dev * 0.15;
    }

    // Time horizon: early on, be more conservative about wasting space
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: non-linear polynomial in normalized post-residual
    let mut score = 3.0 * x - 2.5 * x * x + 1.2 * x * x * x;

    // Stream-progress coupling: later in stream, penalize residual more sharply
    score += 0.8 * x * (1.0 + progress) + 0.6 * progress * x * x;

    // Dead-space penalty: tiny residuals that likely become unusable
    let dead = if pr < 10.0 { (10.0 - pr) / 10.0 } else { 0.0 };
    score -= 1.5 * dead * (1.0 - progress);

    // Lookahead coupling: reward if next item fits the post-residual
    if next_item_size > 0 {
        let fits_next = if (pr >= next_item_size as f64) { 1.0 } else { 0.0 };
        score -= 2.0 * fits_next * (1.0 - progress);
        // penalize if post-residual is just barely too small for next item
        let gap = (next_item_size as f64 - pr).abs();
        score += 0.3 * (gap / cap) * (1.0 - fits_next);
    }

    // Last-chance bonus: only bin that fits -> strong reward
    if fitting_bins_count == 1 {
        score -= 3.0;
    }

    // Mean-residual context: prefer bins close to mean (balanced packing)
    score += 0.4 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: penalize opening a new bin, more so early and when alternatives exist
    if bin_residual == bin_capacity {
        score += 4.0 + 2.0 * (1.0 - progress) + 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals that are "useful" for common
    // future item sizes deserve a reward (subtraction), dead space a penalty.
    let pr = post_residual;
    let useful = |r: u32| -> bool {
        // residual classes that pair well with typical small/medium items
        (r >= 20 && r <= 50) || (r >= 60 && r <= 90) || r == 0
    };
    if pr == 0 {
        score -= 60.0; // perfect fit: strongly favored
    } else if useful(pr) {
        score -= 12.0;
    } else {
        score += 10.0; // awkward dead space (e.g. r in 1..20 or 51..59)
    }

    // Modulo-harmonic bonus: residuals divisible by common size steps
    // (multiples of 10 / 5) are more reusable.
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    } else if pr % 5 == 0 && pr > 0 {
        score -= 2.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this bin is a great choice; if next item just barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            let gap = pr - next_item_size;
            if gap <= 10 {
                score -= 15.0;
            } else if gap <= 30 {
                score -= 5.0;
            } else {
                score += gap as f64 * 0.1;
            }
        } else {
            // next item won't fit here regardless; slight penalty for wasting
            // a large residual on the current item.
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: opening a fresh bin should only win when current
    // fits are terrible. Give the empty bin a baseline handicap that shrinks
    // as the stream matures (early on, packing into open bins is cheap).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 + 20.0 * (1.0 - progress);
        // if many bins already open, discourage fragmentation further
        score += open_bins_count as f64 * 0.5;
    }

    // Mild preference for tighter bins overall (best-fit flavor).
    score += (mean_residual - bin_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are worthless.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        // Perfect fill is best; tiny dead space is heavily penalized.
        score -= 60.0 * (1.0 - (post_residual as f64 / dead_threshold as f64));
    } else {
        // Prefer small but usable residuals, mildly.
        score += 0.15 * (post_residual as f64).powf(1.3) / 10.0;
    }

    // Reward tight fits (post_residual much smaller than residual).
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 25.0 * tightness;

    // Lookahead: if next item fits the post-residual exactly or well, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_tight = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 20.0 * next_tight;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the gap: penalize.
        score += 8.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if current fit is bad or bin count is low.
        score += 30.0 + 2.0 * open_bins_count as f64;
        if post_residual == bin_capacity {
            // empty new bin: residual equals capacity
            score -= 0.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Slight preference to balance residuals toward the mean.
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item can't use the leftover; penalize dead space
        score += 10.0 + post_residual as f64 * 0.3;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Compare post_residual against mean residual: prefer bins with high residual usage
    score += (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize so it's only chosen when fits are terrible
    if bin_residual == bin_capacity {
        score += 40.0;
    }

    // Late in stream: prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Penalize unusable dead space: residuals smaller than the minimum item size (1)
    // are perfect; residuals just above typical small sizes are wasted.
    if post_residual > 0 {
        if post_residual < 10 {
            score -= 8.0; // tiny dead space is fine
        } else {
            score += (post_residual as f64).log2() * 1.5;
        }
    }

    // Exact fit reward
    if post_residual == 0 {
        score -= 12.0;
    }

    // Lookahead: reward if next item fits the post residual exactly or well
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= (10.0 - gap.min(10.0)) * 0.9; // chained fit bonus
        } else if next_item_size > bin_residual {
            // next item won't fit this bin anyway; mild bonus for keeping space
            score -= 1.0;
        } else {
            score += nxt * 0.05; // next item would leave more dead space here
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0;
    }

    // Prefer tighter bins relative to the mean residual of open bins
    let dev = mean_residual - post;
    score += dev * 0.3;

    // Time horizon: early in the stream, be more selective (avoid fragmenting);
    // late in the stream, fill aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 3.0;

    // If many bins are open, prefer consolidating into existing ones
    // over opening new bins; make the new-bin candidate less attractive.
    if bin_residual == bin_capacity {
        score += 4.0 + open_bins_count as f64 * 0.5;
        if item_size > 70 {
            score -= 3.0; // big items justify fresh bins
        }
    }

    // Mild reward for high fill ratio of this placement
    score -= (item_size as f64 / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 - progress) + pr_norm * (1.0 - pr_norm) * progress;
    score += 12.0 * poly;

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += (next_item_size as f64 - pr) * (0.5 + progress);
    } else if next_item_size > 0 && pr >= next_item_size as f64 {
        score -= (next_item_size as f64 / cap) * (1.0 - progress) * 4.0;
    }

    // Last-chance bonus: strongly prefer the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - pr_norm);
    }

    // New-bin candidate: mildly discourage unless residuals are tight
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * (mean_residual / cap).max(0.0) * (1.0 - progress);
    }

    // Prefer bins tighter than the mean residual (best-fit flavor, smooth)
    score += (pr - mean_residual).abs() * 0.3 * (1.0 + progress);

    // Reward filling bins nearly completely via smooth saturating term
    score -= 8.0 * (1.0 - pr_norm).powi(3);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in small residues is costly.
    if post_residual > 0 {
        let r = post_residual;
        if r < 10 {
            score += 25.0; // unusable sliver
        } else if r < 20 {
            score += 12.0;
        } else if r < 30 {
            score += 5.0;
        }
        // modulo-10 harmonic classes: residues divisible by 10 align with item granularity
        if r % 10 == 0 {
            score -= 4.0;
        } else if r % 5 == 0 {
            score -= 2.0;
        }
    } else {
        // perfect fit
        score -= 30.0;
    }

    // Lookahead coupling: reward if next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.25 * (next_item_size as f64);
            // exact modulo match: post_residual == next_item_size -> perfect chain
            if post_residual == next_item_size {
                score -= 15.0;
            }
        } else {
            score += 6.0; // next item cannot follow here
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a bin unless current bins are crowded
    if bin_residual == bin_capacity {
        score += 15.0
            + 0.5 * (open_bins_count as f64)
            - 0.3 * mean_residual;
        // late in stream, prefer closing out existing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Prefer filling bins that are already partially used (tight packing)
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    // Mean-residual deviation: prefer bins below mean residual (more filled)
    score += 0.2 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0;
    }
    // Zero residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a new empty bin is candidate.
    if bin_residual == bin_capacity {
        // New bin candidate: base cost plus pressure from number of open bins.
        score = bin_capacity as f64 + open_bins_count as f64 * 3.0;
        // If the next item would fit nicely in current mean residual, prefer existing bins.
        if next_item_size > 0 && mean_residual >= next_item_size as f64 {
            score += 15.0;
        }
        // Early in stream, opening new bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    } else {
        // Prefer bins whose residual is close to item size (tight packing).
        score -= (bin_residual as f64 - item_size as f64).abs() * 0.5;
        // Reward bins below mean residual (denser bins get used first).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
        // Lookahead: if next item fits exactly in post_residual, bonus.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual matches next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let gap = (pr - nxt).abs();
        if nxt <= pr {
            // Next item fits perfectly in the residual left behind: strong reward.
            score -= (bin_capacity as f64 - gap) * 0.8;
            // Extra bonus for exact/near-exact match.
            if gap <= 3.0 { score -= 30.0; }
        } else {
            // Next item cannot use this residual: penalize wasted dead space.
            score += gap * 0.35;
        }
    }

    // Prefer tight fits now (small post-residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 15.0;

    // Compare against mean residual: bins much tighter than average are precious,
    // avoid wasting them; bins looser than average are better targets.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= dev * 0.25;
    } else {
        score += (-dev) * 0.15;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, unless the current item
    // leaves a perfect slot for the next item in a fresh bin.
    if bin_residual == bin_capacity {
        let base_penalty = 20.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && (bin_capacity as u32 - item_size) == next_item_size {
            score -= 60.0; // opening a fresh bin creates an exact slot next step
        } else if next_item_size > 0 && next_item_size as f64 > (bin_capacity - item_size) as f64 {
            score -= 5.0; // fresh bin still leaves a usable big residual
        } else {
            score += base_penalty;
        }
    }

    // Late in the stream, consolidate: avoid spreading across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post-residual penalty so near-perfect
    // placements dominate.
    let pr = post_residual as f64;
    score += 0.6 * pr * pr / bin_capacity as f64;

    // Lookahead: strongly reward bins whose post-residual can host the next item
    // (chained placements), penalize leaving a gap just smaller than next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Extra reward if next item nearly fills the leftover exactly.
        let gap = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // Dead space: leftover too small for the next item.
        score += 4.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using
    // it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Reward using bins that are already relatively full (small residual before
    // placement), encouraging consolidation into nearly-full bins.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 5.0 * fill_ratio;

    // Penalize scattering across many open bins: prefer filling existing bins
    // when the mean residual is large.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);
    score -= 0.02 * mean_residual;

    // Time horizon: early in the stream, be more liberal about opening bins
    // (long future to exploit); late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 8.0 * (1.0 - progress) * (pr / bin_capacity as f64);
    score -= 6.0 * progress * fill_ratio;

    // New-bin candidate: make an empty bin moderately attractive only when the
    // item is large relative to residual fits elsewhere; default slightly worse
    // than a decent tight fit.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Large items justify opening fresh bins more readily.
        score -= 0.12 * item_size as f64;
        // If nothing else fits well, allow the new bin.
        if fitting_bins_count <= 1 {
            score -= 18.0;
        }
    }

    // Small penalty proportional to item size to prefer placing larger items
    // into tighter bins first.
    score += 0.03 * item_size as f64 * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, small residuals matter more (dead space accumulates)
    let progress_coupling = 1.0 + 0.8 * progress * progress + 0.4 * progress * norm_pr;
    score *= progress_coupling;

    // Penalize residuals that can't hold the lookahead item (smooth logistic-style penalty)
    if next_item_size > 0 {
        let fits_next = pr >= next_item_size as f64;
        let gap = (pr - next_item_size as f64).abs();
        let penalty = if fits_next { -0.15 * gap / cap } else { 0.25 * (1.0 + gap / cap) };
        score += penalty * cap * (0.5 + 0.5 * progress);
    }

    // Last-chance bonus: smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 3.0 * (1.0 + progress);
    }

    // Mild bonus for bins tighter than the mean residual (smooth)
    score -= 0.1 * (mean_residual - pr).max(0.0) / cap;

    // Mild penalty for spreading across many open bins
    score += 0.02 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: neutral baseline with slight preference early, penalty late
    if bin_residual == bin_capacity {
        score = cap * (1.0 - 0.6 * progress) + 0.3 * cap * norm_pr;
        if fitting_bins_count <= 1 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit reward: post_residual in {0} or a "harmonic" small divisor class.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Reward residuals that are harmonic divisions of capacity (25, 20, 50, 10...)
        for h in [0u32, 10, 20, 25, 50] {
            if post_residual == h {
                score -= 40.0;
            }
        }
        // Penalize dead space: residuals too small to hold typical future items.
        let min_item = 1.0f64.min(cap);
        if pr < 10.0 {
            score += (10.0 - pr) * 3.0;
        }
        // Quadratic dead-space penalty scaled by how full the bin already is.
        let fill = 1.0 - pr / cap;
        score += pr * pr / cap * 0.15 * fill;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / cap);
        } else {
            // Next item cannot follow here; penalize more if post residual is large wasted gap.
            score += pr * 0.2;
        }
        // Harmonic pairing: next_item in same modulo class as item_size (e.g., complements to 100)
        if item_size + next_item_size == bin_capacity && post_residual == 0 {
            score -= 500.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        // Neutral base; add pressure when many open bins already exist with slack.
        score += open_bins_count as f64 * 2.0;
        // Opening a new bin is bad if the mean residual across open bins is large.
        score += mean_residual * 1.5;
        // Early in stream, new bins are cheaper; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 50.0;
    }

    // Mild preference for tighter bins among equals (post_residual already encodes this,
    // but add tie-break via bin_residual distance to capacity).
    score += (bin_capacity - bin_residual) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

