    score += (bin_residual as f64 - mean_residual).abs() * 0.1;

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 25.0;
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 35.0; // opening a new bin is justified when nothing fits well
        }
    }

    // Slight preference for using fuller bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward if next item fits into the post-residual exactly.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            // Next item fits: reward proportional to how snug the 2-step fit is.
            let two_step_waste = (post_residual - next_item_size) as f64;
            score -= 60.0 - 2.0 * two_step_waste;
            // Perfect 2-step fill bonus.
            if post_residual == next_item_size {
                score -= 40.0;
            }
        } else {
            // Next item does NOT fit in this bin's remainder: penalize leaving
            // a remainder that is too small to be useful (dead space).
            let dead = (nxt - post) / nxt;
            score += 25.0 * dead;
        }
        // Relative-to-mean coupling: bins below mean residual are tighter; prefer
        // placing into tighter bins when lookahead is favorable.
        score -= (mean_residual - post) * 0.3;
    } else {
        // Last item: just minimize waste.
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize wasting space in a nearly-full bin when item barely fits
    // (very small post residual is good, but zero residual is excellent).
    if post_residual == 0 {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // remaining open bins have poor fits. Make new bin moderately unattractive.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 - 20.0 * progress;
        // If many bins fit the item, opening a new bin is clearly worse.
        if fitting_bins_count > 1 {
            score += 30.0;
        }
        // If next item is large, a fresh bin preserves flexibility.
        if next_item_size > 60 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of the bin after placement.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 6.0 * fill * fill;

    // Penalize dead space: small post_residuals that cannot hold typical items
    // (min item size assumed 1, but dead space below next item is risky).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Lookahead synergy: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }
    // Soft lookahead: reward if next item still fits in this bin after placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Relative tightness vs. mean residual: prefer bins with less residual than average.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Penalize opening new bins when several open bins can fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 + 5.0 * (1.0 - progress) * (open_bins_count as f64).ln();
    }

    // Mild fragmentation penalty: squared post-residual (smaller leftovers favored).
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);

    // Early-stream exploration: slight preference for spreading items early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * (1.0 - progress) * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr * (1.0 + 0.5 * progress * progress);
    // penalize large wasted residual smoothly
    score += 20.0 * norm_pr * norm_pr * (1.0 + progress);
    // reward tight fits: subtract when post_residual small relative to item
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * (1.0 + progress);
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * progress;
    }
    // lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - (next_item_size as f64 / cap));
    } else if next_item_size > 0 {
        score += 4.0 * progress;
    }
    // crowding penalty
    score += 0.5 * open_bins_count as f64 * progress;
    // deviation from mean residual
    score += 0.3 * (pr - mean_residual).abs();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction band it lands in.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let post = post_residual;
    let next = next_item_size;

    // Dead-space penalty grows superlinearly in the smallest band (residual < quarter).
    if post < quarter {
        score += (quarter - post) as f64 * 2.0;
    } else if post < half {
        score += (half - post) as f64 * 0.5;
    }

    // Harmonic reward: if the lookahead item fits exactly into the post-residual,
    // strongly favor this bin (perfect pairing).
    if next > 0 && post >= next {
        let slack = post - next;
        if slack == 0 {
            score -= 30.0;
        } else if slack < quarter {
            score -= 12.0;
        } else {
            score -= 4.0;
        }
    } else if next > 0 && post < next {
        // Lookahead item cannot use this residual: penalize small leftovers more.
        if post < quarter {
            score += 8.0;
        } else {
            score += 2.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive early in the stream or when the item
    // leaves a large residual class in a fresh bin. Penalize opening new bins
    // when good open bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 + 20.0 * progress;
        if next > 0 && next > post {
            score -= 3.0; // fresh bin guarantees fit for lookahead too
        }
    }

    // Mild pressure toward tightest overall fit relative to mean residual.
    score += (mean_residual - post as f64).abs() * 0.1;

    // Modulo-class tiebreak: prefer post-residuals that are harmonic multiples
    // of common item sizes (multiples of 10 or 20), making future packing easier.
    if post % 10 == 0 {
        score -= 2.0;
    }
    if post % 20 == 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space avoidance: penalize small nonzero leftover gaps that
    // are likely unusable for future items (items >= 1, gap < ~10 is trash).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual >= 10 && post_residual < 25 {
        // Medium-small gaps: moderate penalty scaled by how few bins fit the item
        // (last-chance bins get a discount to avoid opening new bins unnecessarily).
        let last_chance_bonus = if fitting_bins_count == 1 { 15.0 } else { 0.0 };
        score += 18.0 + last_chance_bonus;
    }

    // Reward bins whose residual tightly matches the item (waste = residual - item).
    let waste = (bin_residual as f64 - item_size as f64).max(0.0);
    score += waste * 0.35;

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            score -= 25.0;
        } else {
            // Next item won't fit here: penalize proportionally to wasted residual.
            score += post_residual as f64 * 0.5;
        }
    }

    // New-bin candidate handling: opening a new bin should only win when no
    // decent fit exists. Penalize the fresh bin more as open_bins_count is low
    // (consolidation pressure) and less when the stream is late and mean residual
    // across open bins is small (open bins nearly full anyway).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let consolidation = (open_bins_count as f64).max(1.0).ln() * 30.0;
        let open_bins_starving = (mean_residual < 15.0) as i32 as f64 * 40.0;
        let late_stream = progress * 20.0;
        score += 55.0 + consolidation + open_bins_starving + late_stream;
    }

    // Open-bins pressure: mildly favor bins that reduce fragmentation relative
    // to the mean residual (place into bins with below-average residual).
    score += (bin_residual as f64 - mean_residual) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Post-residual can fit next item: strongly reward tight chains.
            let chain_tightness = (next_item_size as f64 / post_residual as f64).min(1.0);
            score -= 25.0 + 20.0 * chain_tightness;
        } else {
            // Post-residual cannot host next item: penalize dead space, worse for large waste.
            let dead = (next_item_size - post_residual) as f64;
            score += 5.0 + dead * 0.3;
        }
    } else {
        // Last item: pure tightness fit.
        score -= 10.0;
    }

    // Penalize residuals far from useful sizes; reward very tight fits.
    if post_residual == 0 {
        score -= 15.0; // perfect fill
    } else if post_residual < 10 {
        score -= 5.0; // near-perfect, unusable sliver is fine
    }

    // Relative-to-mean coupling: bins tighter than average are better to fill.
    score -= (mean_residual - bin_residual as f64) * 0.15;

    // Last-chance bonus: if this is the only fitting bin, prefer using it over a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: make empty bins less attractive unless nothing else works well.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Late in the stream, opening new bins is more wasteful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // But if the next item is huge and current item small, a fresh bin is reasonable.
        if next_item_size >= 70 && item_size <= 20 {
            score -= 25.0;
        }
    }

    // Slight preference to keep the number of open bins low.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, so subtract a bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness;

    // Penalize dead space that cannot fit a typical future item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += 5.0; // next item won't fit here; bin likely closes
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are mostly too small (fragmented state) or late in stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / (bin_capacity as f64);
        // Early on with roomy residuals, prefer reusing bins: penalize new bin.
        score += 10.0 + 15.0 * (1.0 - progress);
        if fragmentation < 0.25 {
            score += 10.0; // very fragmented: new bin more acceptable
        }
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 5.0; // fresh bin can host next item too
        }
    }

    // Slight preference for filling bins with larger residuals among equals
    // (reduces number of near-empty bins floating around).
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    // Mild scaling with open bin count: many open bins -> favor consolidation.
    score += 0.3 * open_bins_count as f64;

    // Small progress term to break ties deterministically over time.
    score += 0.001 * (step_index as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Base: prefer small post residual, with non-linear shaping
    let mut score = pr * (1.0 + 0.35 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early stream -> tolerate larger residuals; late stream -> penalize them more
    let coupling = 1.0 + 0.8 * progress * progress + 0.5 * progress * norm_pr;
    score *= coupling;

    // Reward tight fits via a smooth bump around post_residual near 0
    score -= 12.0 * (-pr / (0.15 * cap)).exp();

    // Lookahead: reward if next item fits the post residual (smooth kernel)
    if next > 0.0 {
        let gap = (pr - next).abs();
        score -= 6.0 * (-gap / (0.25 * cap)).exp();
    } else {
        // last item: strongly prefer filling bins
        score -= 15.0 * (-pr / (0.1 * cap)).exp();
    }

    // Last-chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - norm_pr);
    }

    // Prefer bins with residual below the mean (compact bins), smooth quadratic
    let dev = (pr as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Slight penalty for opening new bins when many bins are already open, scaled by progress
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity fractions
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Penalize dead space super-linearly, especially small unusable slivers
    if post > 0 {
        // class boundaries: post in (0,10] worst, (10,20], (20,50], >50
        if post <= 10 {
            score += 45.0;
        } else if post <= 20 {
            score += 18.0;
        } else if post <= 50 {
            score += 6.0;
        } else {
            score -= 4.0;
        }
        // modulo harmonic: post % 10 == 0 means item sizes align with capacity grid
        if post_residual % 10 == 0 {
            score -= 5.0;
        }
        // exact fill reward
        if post_residual == 0 {
            score -= 30.0;
        }
    }

    // Lookahead coupling: if next item fits the post residual exactly or well, reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 25.0;
        } else if gap <= 10 {
            score -= 12.0;
        } else {
            score -= 3.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use this bin's leftover: penalize proportional to sliver
        score += 8.0 + (10.0 - frac * 10.0).max(0.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate: only attractive when open bins have poor residuals
    if bin_residual == bin_capacity {
        let urgency = (mean_residual / cap - 0.5).max(0.0); // high mean residual => keep using open bins
        score += 15.0 + 60.0 * urgency;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // mild preference for tighter bins
        score += (bin_residual as f64) * 0.05;
    }

    // Stream progression: later in stream, be greedier about closing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10, min item size) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps too small for the next item are also likely dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }
    // Reward tight fits (perfect fills get strong bonus).
    let tightness = (bin_residual - post_residual) as f64 / bin_residual.max(1) as f64;
    score -= tightness * 25.0;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins already exist.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to existing open bins and mean residual.
        score += 30.0 + open_bins_count as f64 * 4.0 + mean_residual * 0.5;
        // If only one fitting bin exists, strongly prefer using it over a new bin.
        if fitting_bins_count == 1 {
            score += 50.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 15.0;
    } else {
        // Slight reward for using an existing bin when it's the last chance.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // Mild preference for bins below mean residual (balancing load).
    score += (post_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins that become exactly full.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when the next item fits into post_residual.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            // Next item fits: reward proportional to how snugly it fits.
            let snug = 1.0 - (post - nxt) / bin_capacity as f64;
            score -= 30.0 + 40.0 * snug;
            // Chain bonus: next item nearly fills the bin after this placement.
            let chain_post = post - nxt;
            if chain_post <= 5.0 {
                score -= 50.0;
            }
        } else {
            // Next item won't fit here: penalize leaving medium dead space,
            // but mild penalty if post_residual is tiny (near-full bin is fine).
            if post_residual > 10 {
                score += 20.0 + 0.3 * (post - nxt).abs();
            }
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual.
    let post = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.5 * (post - mean_residual);
    }

    // Last-chance bin: strongly favor using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Penalize opening a new bin when open bins exist that fit decently.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // New bin is only attractive if item is large relative to mean residual.
        let item_frac = item_size as f64 / bin_capacity as f64;
        score += 60.0 * (1.0 - item_frac);
    }

    // Late-stream bias: consolidate more aggressively as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post * 0.2);

    // Small penalty for very large unusable gaps (dead space).
    if post > 0 && post < 10 {
        score -= 15.0; // tiny gap is effectively dead anyway; slight reward to fill
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
