    // New-bin candidate: penalize mildly unless current fit is poor
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - norm_item) - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "usable"
    // classes (multiples of small divisors of capacity) are rewarded.
    let cap = bin_capacity;
    let pr = post_residual;

    // Perfect fit: zero residual is ideal.
    if pr == 0 {
        score -= 1000.0;
        return score;
    }

    // Residual divisible by 10, 20, 25, 50 -> leaves reusable chunks.
    if pr % 50 == 0 { score -= 60.0; }
    else if pr % 25 == 0 { score -= 40.0; }
    else if pr % 20 == 0 { score -= 30.0; }
    else if pr % 10 == 0 { score -= 20.0; }

    // Dead-space penalty: tiny unusable residuals (below min item size 1 is
    // unknown, so treat <=5 as near-dead) are heavily penalized.
    if pr <= 5 {
        score += 35.0;
    } else if pr <= 10 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly reward; if it cannot fit anywhere else, penalize waste.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 80.0;
        } else if next_item_size <= pr {
            // fraction of post_residual consumed by next item
            let fill = next_item_size as f64 / pr as f64;
            score -= 25.0 * fill;
        } else {
            // next item won't fit here; penalize proportionally to overshoot
            let over = (next_item_size - pr) as f64;
            score += 0.3 * over;
        }
    }

    // Last-chance bin logic: if this is the only fitting bin, avoid forcing
    // a new bin unless the fit is truly bad.
    if fitting_bins_count == 1 && bin_residual != cap {
        score -= 45.0;
    }

    // Prefer tighter bins: relative tightness of the current fit.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // Slight preference for filling existing bins vs opening new ones as the
    // stream progresses (early on, keep flexibility).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == cap {
        // New-bin candidate: penalize early, allow later when mean residual
        // of open bins is small (they are mostly full).
        score += 55.0 - 40.0 * progress;
        if mean_residual < (item_size as f64) * 1.2 {
            score -= 30.0;
        }
    } else {
        score -= 10.0 * progress;
    }

    // Mean-residual harmony: bins close to the mean residual are "typical"
    // targets; extreme residuals are penalized mildly.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Integer-division threshold: residual in the band (50, 60] is a sweet
    // spot for typical item sizes.
    if pr > 50 && pr <= 60 {
        score -= 12.0;
    } else if pr > 80 {
        score += 8.0; // wasteful large residual left behind
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harsh penalty for small unusable gaps (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Reward very tight fits (post_residual near 0)
    if post_residual <= 3 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when open bins exist, scaled by pressure
    if bin_residual == bin_capacity {
        score = 100.0 + 8.0 * open_bins_count as f64;
        // But if this bin is the only fit, new bin is fine
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Slight preference for bins below mean residual (consolidate emptier bins)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Lookahead: if next item fits into the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 10.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Open bins pressure: mild penalty per open bin when placing in an existing bin
    if bin_residual != bin_capacity {
        score -= 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post residual (tight fit).
    score = post_residual as f64;

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 50.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
