            }
        }
    }

    // Relative to mean residual: bins below mean residual are "denser" -> prefer filling them.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last chance bin: if this is the only fitting bin, strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, mild penalty to encourage discrimination by fit quality.
        score += 5.0;
    }

    // New-bin candidate handling: only attractive when no good option exists.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Penalize opening a new bin; relax slightly as stream progresses or when item is large.
        let mut new_bin_penalty = 90.0 + 40.0 * (1.0 - progress);
        if item_size > bin_capacity / 2 {
            new_bin_penalty -= 30.0;
        }
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > bin_capacity / 2 {
            new_bin_penalty -= 25.0;
        }
        score += new_bin_penalty.max(10.0);
    }

    // Slight penalty for wasting a mostly-empty bin when many bins are open.
    if open_bins_count > 4 && bin_residual as f64 > mean_residual * 1.5 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below the
