        // opening a new bin is fine if item is big and would leave bad remainder
        if item_size >= 60 {
            score -= 8.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into existing bins (penalize spreading).
    if bin_residual != bin_capacity {
        let spread = mean_residual - post_residual as f64;
        if spread > 0.0 {
            score -= 2.0 * spread / bin_capacity as f64;
        }
        // Prefer fuller bins relative to the average open bin.
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 1.5;
        }
    }

    // Time horizon: early in the stream, be conservative with new bins;
    // late in the stream, tightness matters more than bin count.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Small penalty for creating awkward remainders (just above typical small items)
    if post_residual >= 21 && post_residual <= 30 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
