    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward; if next item would leave this bin's leftover dead,
    // penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let leftover2 = post_residual - next_item_size;
            score -= 15.0 - 0.2 * leftover2 as f64;
            if leftover2 % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // next item cannot use the leftover: dead-space risk grows
            // when post_residual is small relative to min plausible item.
            let dead = (post_residual as f64) / cap;
            score += 10.0 * (1.0 - dead);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid wasting it
    // on a bad fit; prefer opening a new bin for large leftovers.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }
    if post_residual >= 50 && fitting_bins_count > 1 {
        // plenty of alternatives; keep large-residual bins flexible
        score += 3.0;
    }

    // Capacity-fraction thresholds: bins filled past 70% or 90% are good.
    if fill >= 0.9 {
        score -= 10.0;
    } else if fill >= 0.7 {
        score -= 5.0;
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fill;

    // Many open bins with high mean residual: discourage spreading.
    if open_bins_count > 4 && (post_residual as f64) > mean_residual {
        score += 2.0;
    } else if (post_residual as f64) < mean_residual {
        score -= 2.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score = cap * 0.5 + 25.0 - (fitting_bins_count as f64) * 2.0;
        if next_item_size > 0 && next_item_size >= 70 {
            score -= 15.0; // big next item: fresh bin useful
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the next item are wasted.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward residuals that can still host the next item, more so when snug.
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - 0.15 * slack;
        } else {
            // Unusable gap: penalize proportionally to how close it is to being useful.
            let gap = next_item_size - post_residual;
            score += 10.0 + 0.5 * gap as f64;
        }
    }

    // Reward very tight fits (post_residual near zero is perfect packing).
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Compare against mean residual: bins with residual far below mean are "dregs";
    // filling them first cleans up the pool.
    if (bin_residual as f64) < mean_residual {
        score -= 0.5 * (mean_residual - bin_residual as f64);
    } else {
        score += 0.3 * (bin_residual as f64 - mean_residual);
    }

    // New-bin candidate: only attractive when the item is large and no good fit exists.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative, must open
        } else if large_item > 0.6 && fitting_bins_count <= 2 {
            score -= 5.0; // big item, weak alternatives
        } else {
            score += 15.0 + 2.0 * open_bins_count as f64; // discourage proliferation
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect or near-perfect matches
    // where the next item exactly fills the post residual.
    if next_item_size > 0 {
        let next_fits = next_item_size <= post_residual;
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if next_fits {
            // Reward tight two-step chains strongly (subtracted from score).
            score -= 18.0 * (1.0 - gap / bin_capacity as f64);
            // Exact chain (post_residual == next_item_size) is ideal.
            if gap == 0.0 {
                score -= 25.0;
            }
        } else {
            // Post-residual too small for the next item: penalize dead space
            // proportionally to how stranded the leftover becomes.
            score += 6.0 + 0.25 * gap;
        }
    }

    // Compare post residual against the mean residual across open bins:
    // leaving less than average residual means this bin is being packed tighter.
    let mean_gap = mean_residual - post_residual as f64;
    score -= 0.5 * mean_gap;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize wasteful low-fill placements relative to capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Mild penalty for opening a brand-new bin while good open bins exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 8.0;
        // But allow a new bin if the item is huge and would leave bad residue elsewhere.
        if item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    }

    // Late-stream consolidation: prefer existing bins as the stream nears its end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 6.0 * progress;
    }

    score
}
